window.MINSO_CATS_DATA = [["mp_1", "제1편 총론"], ["mp_2", "제2편 소송의 주체"], ["mp_3", "제3편 제1심의 소송절차"], ["mp_4", "제4편 소송의 종료"], ["mp_5", "제5편 상소심절차"], ["mp_6", "제6편 병합소송"]];
window.MINSO_UNITS = [["민소001", "민사소송과 신의성실의 원칙", "<div class=\"cs-callout\"><div class=\"cs-h\">Ⅰ. 의의 및 적용범위</div><div class=\"cs-li\" style=\"margin-left:0px\">: 당사자·소송관계인은 상대방 신뢰를 저버리지 않게 성실히 소송수행해야 한다는 원칙(§1②)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例 : <span class=\"cs-neg-tag\"><strong>[부제소합의 위반 제소]</strong></span><span class=\"cs-x\"><strong>(X)</strong></span> — 권리보호이익 X, 신의칙 위배(<span class=\"cs-u\">선택적 적용설</span>)</div><div class=\"cs-h\">Ⅱ. 발현형태</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송상태의 부당형성 금지</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">: 일방이 상대방에 불리한 소송상태를 만들어 부당히 이용하는 행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ★ <span class=\"cs-neg-tag\">[관할만 발생시킬 목적으로 <strong>본래 제소할 의사 없는 청구를 병합</strong>한 것이 명백한 경우]</span> 관련재판적 적용 <span class=\"cs-x\"><strong>(X)</strong></span> — 관할선택권 남용으로 신의칙 위반</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>선행행위와 모순되는 거동금지</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">: 선행행위를 신뢰케 한 후 모순되는 후행행위는 신의칙상 불허</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">★<span class=\"cs-neg-tag\"> [<strong>추완항소</strong> 신청 후 상고이유로 부적법 주장]</span><span class=\"cs-x\"><strong>(X)</strong></span> — 신의칙상 불허</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">★<span class=\"cs-neg-tag\"> [<strong>소송상 합의(부제소특약)</strong>에 반하는 제소]</span> <span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[<strong>부적법 표시정정</strong></span>을 1심법원이 받아들임+피고의 명시적 동의로 본안판결선고] 시 <span class=\"cs-neg-tag\">뒤늦게 표시정정 부적법을 문제삼는 것</span><span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송상 권능의 실효</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(1) 적용요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-def\"><span class=\"cs-u\"><strong>실효의 원칙</strong></span></span> = ① 권리자가 장기간 권리를 행사하지 않아 2) ② 상대방이 정당한 신뢰를 갖게 된 경우 ③ 그 후 권리행사는 신의칙상 허용 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(2) 소권의 실효 여부</strong>  (判例)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[<strong>면직 후</strong> 이의없이 퇴직금·보상금 수령 후 <span class=\"cs-u\"><strong>10년</strong></span><strong> 뒤 무효확인청구</strong>]</span> <span class=\"cs-x\"><strong>(X)</strong></span>→ 실효 <span class=\"cs-red\"><strong>O</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">★<span class=\"cs-fact-tag\">[<strong>상대방 주소 허위기재로 자백간주 판결 편취</strong>시]</span> 상대방이 이를 알고도 장기간 항소 X → 실효 <span class=\"cs-red\"><strong>O</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소권의 남용</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">: 소송 외 목적추구 위한 소송상의 권능행사</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">★ <span class=\"cs-fact-tag\"><strong>[명시적 일부청구]</strong></span> 일부청구, 잔부청구 = 별개소송물, 중복소제기 X</div><div class=\"cs-li\" style=\"margin-left:48px\">but <span class=\"cs-fact-tag\"><strong>[전소 청구취지 확장가능함에도 별소로 잔부청구]</strong></span>는 소권남용, 부적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">★ <span class=\"cs-fact-tag\"><strong>[법인격 남용]</strong></span> 채무면탈 목적 실질동일한 신설회사 설립 후 별개 법인격 주장→ 신의칙 위반, 법인격남용</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">★ <span class=\"cs-fact-tag\"><strong>[소권남용: 청구가 이유없음이 명백한 소 반복제기]</strong></span> <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§219의2</strong></span></span> 신설 → 법원이 결정으로 과태료 처분 가능 규정</div><div class=\"cs-h\">Ⅲ. 신의칙 위반여부의 조사 및 효과</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例: 신의칙 위반여부 = <span class=\"cs-red\"><strong>직권조사사항</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>[소 제기]</strong>가 신의칙 위반 → 부적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>[개개의 소송행위]</strong>가 신의칙 위반 → 무효로 배척</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>[신의칙 위반을 간과한 판결]</strong>:  <span class=\"cs-u\">확정 </span><span class=\"cs-u\"><strong>전</strong></span><span class=\"cs-u\"> 상소</span>로만 구제 가능(확정 <strong>후</strong> <span class=\"cs-u\">재심사유 X</span>)</div></div><div class=\"cs-h\">제2편 소송의 주체</div>", ["★"], 1, "mp_1"], ["민소002", "재판권", "<div class=\"cs-h\">Ⅰ. 재판권의 인적범위  (判例)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\"><strong>외국국가에 대한 국제 재판권의 인정여부</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(1) 외국국가에 대한 국내재판권의 면제범위(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">종래 : <span class=\"cs-u\"><strong>[절대적 면제론]</strong></span> 외국국가를 피고로 한 재판권 전면 불가</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">→ <strong>변경 : </strong><span class=\"cs-u\"><strong>[상대적 면제론]</strong></span></div><div class=\"cs-li\" style=\"margin-left:48px\"><span class=\"cs-red\"><strong>① 주권적 행위는 면제</strong></span> 원칙 <span class=\"cs-red\">↔</span> <span class=\"cs-green\"><strong>② 사법적 행위는 재판권 O</strong></span> but <span class=\"cs-red\">주권적 활동과 밀접관련·부당간섭 우려되는 특별한 사정 있을 시 면제 </span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(2) </strong><span class=\"cs-fact-tag\"><strong>국가가 국내부동산을 점유하는 경우 국내재판권 인정 여부</strong></span><strong>(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-green\"><strong>원칙 : 재판권 O</strong></span> — 부동산 점유 주체가 외국이라는 이유만으로 당연면제 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-red\">↔ <span class=\"cs-u\"><strong>[공관지역 점유</strong></span><strong>]<span class=\"cs-x\"><strong>(X)</strong></span></strong></span> <strong> :</strong> 주권적 활동과 밀접관련, 외교공관 직무수행 방해우려시 재판권 행사 제한</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(3) </strong><span class=\"cs-fact-tag\"><strong>외국국가에 대한 공관지역의 </strong><span class=\"cs-u\"><strong>건물철거&amp;토지인도청구</strong></span><strong> 및 </strong><span class=\"cs-u\"><strong>부당이득반환청구</strong></span><strong> 적부</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-red\"><strong>[건물철거·토지인도청구]: <span class=\"cs-x\"><strong>(X)</strong></span></strong></span> — 직무수행에 직간접 영향 → 재판권 X (소각하)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-green\"><strong>[부당이득반환청구]: <span class=\"cs-o\"><strong>(O)</strong></span></strong></span>  — 공관지역 점유·직무수행에 영향 X → 재판권 O</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\"><strong>외국을 피고로 한 추심금 소송에 대한 재판권</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 외국을 제3채무자로 한 추심명령에 <span class=\"cs-green\"><strong>재판권 행사 가능한 경우</strong></span><strong>, </strong>②  해당국가가 강제집행대상됨에 <span class=\"cs-green\"><strong>명시적 동의(or 재판권면제주장 포기)한 경우</strong></span><strong>에만</strong><span class=\"cs-green\"><strong> O</strong></span></div><div class=\"cs-h\">Ⅱ. 재판권의 물적범위 - 국제재판관할권</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>결정기준</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>국제사법§2①</strong></span></span>: 대한민국과 <span class=\"cs-red\"><strong>실질적 관련성</strong></span><span class=\"cs-o\"><strong>(O)</strong></span> 기준</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>동법§2②</strong></span></span>: 국제사법에 규정 없으면 ① 국내법 관할규정 참작하여 판단 + ② 국제재판관할 특수성 고려</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>개정 국제사법의 국제재판관할에 관한 규정 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§3이하</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>국내법 관할규정 참작</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(1) 토지관할과 관련재판적 인정    </strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 판례가 국제재판관할에서도 관련재판적 인정 → ② 개정 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>국제사법§6①</strong></span></span>(객관적 병합)·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§6②</strong></span></span>(주관적 병합)으로 입법 반영</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(2) 국제재판관할의 합의</strong> - 합의관할 판단기준 적용</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">개정 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>국제사법§8①</strong></span></span>에서 엄격 요건 하 합의관할 인정, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§8③</strong></span></span>에서 전속적 합의로 추정</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(3) 변론관할 인정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 판례가 국제재판관할에서 변론관할 인정 → ② 개정 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>국제사법§9</strong></span></span>로 입법 반영</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>국제재판관할의 특수성 고려 - </strong><span class=\"cs-red\"><strong>실질적 관련성 판단</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 당사자 공평·재판적정·신속경제의 기본이념 + ② 개인적 이익·법원(국가)이익 고려 + ③ 실질적 관련성(법정지-당사자 간 / 법정지-분쟁사안 간)을 객관적 기준으로 합리적 판단</div><div class=\"cs-h\">Ⅲ. 재판권 흠결의 효과</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>민사재판권</strong> 존재 여부 = <span class=\"cs-red\"><strong>소송요건·직권조사사항 </strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>[재판권 없음 명백]</strong>: 소장각하명령 <span class=\"cs-red\">↔</span>  [<strong>불명확]</strong>: 변론 후 소각하판결</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>[재판권 흠결 간과판결]</strong>: <strong>무효</strong>(확정 전 상소, 후 재심 모두 부적법)</div>", ["★"], 1, "mp_2"], ["민소003", "법관의 제척·기피·회피", "<div class=\"cs-h\">Ⅰ. 법관의 제척</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-def\"><strong>제척</strong></span><strong>의 의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">법관이 구체적 사건과 특수관계 있을 때 법률상 당연히 재판에서 배제 — 재판의 공정성·심급제도 실효성 확보 목적</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>제척이유 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§41</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\">(1) <span class=\"cs-u\"><strong>법관</strong></span><span class=\"cs-u\"> 또는 </span><span class=\"cs-u\"><strong>그 배우자나 배우자였던 사람</strong></span><span class=\"cs-u\">이 </span><span class=\"cs-u\"><strong>사건의 당사자</strong></span>가 되거나, 사건의 당사자와</span> <span class=\"cs-blue\"><span class=\"cs-u\"><strong>공동권리자·공동의무자</strong></span><span class=\"cs-u\"> 또는 </span><span class=\"cs-u\"><strong>상환의무자</strong></span><span class=\"cs-u\">의 관계</span>에 있는 때<strong>(1호)</strong></span>(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-blue\"><strong>‘공동권리자·의무자’</strong> 관계</span> = 소송목적 권리관계에 관해 공통되는 법률상 이해관계 O → 공정성 의심 사정 존재 지위</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><strong>[종중 상대 종중총회결의 무효확인의 소의 배석판사 중 1인이 종중원]</strong> 제척<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\">(2) 법관이 사건에 관하여<strong> 불복신청이 된 </strong><span class=\"cs-u\"><strong>전심재판</strong></span>에 <span class=\"cs-u\"><strong>관여</strong></span>한 때<strong>(5호)</strong></span>(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>1) 요건 &amp; 2) [인정범위]</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-blue\"><strong>'전심'</strong></span> = 상소 전 직접·간접 하급심재판</div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">①<strong> [재심대상 확정판결]</strong> : <span class=\"cs-red\">전심</span><span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">② ★ <strong>[</strong><span class=\"cs-neg-tag\"><strong>소송상화해 관여</strong></span><strong> → 그 </strong><span class=\"cs-neg-tag\"><strong>화해내용에 따른 본안소송</strong></span><strong> 관여]</strong><span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">③ ★ <strong>[본안소송에서 </strong><span class=\"cs-neg-tag\"><strong>재판장에 대한 기피신청사건 재판에 관여</strong></span><strong>]</strong><span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-blue\"><strong>'재판'</strong></span> = 본안 종국판결+중간적 재판</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-blue\"><strong>'관여'</strong></span> = <span class=\"cs-red\">최종변론·판결합의·판결서작성</span>에 실질관여, <span class=\"cs-red\">동일사건</span>일 것</div><div class=\"cs-li\" style=\"margin-left:64px\">↔<span class=\"cs-green\"> 최종변론 전 변론·증거조사·소송지휘·선고관여</span>는 제외</div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">↔ ④ ★ <span class=\"cs-gbg\"><strong>[환송·이송 전 원심판결 관여판사]</strong></span>: 본안관여<span class=\"cs-o\"><strong>(O)</strong></span> — 환송심 관여 불가 (<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§436③</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>제척의 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">법률상 당연히 재판에서 배제, 일체 소송행위 관여 불가</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">예외 : 단, <span class=\"cs-green\">긴급행위·종국판결선고·간이각하후 직무행위</span>는 가능 (<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§48단서)</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><strong>[관여한 소송행위]</strong>: 무효</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><strong>[간과판결]</strong>: 무효X, 위법한 판결<span class=\"cs-o\"><strong>(O)</strong></span> → 확정<strong>전</strong><span class=\"cs-red\"><strong>상소</strong></span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§424①2호</strong></span></span>)·확정<strong>후</strong><span class=\"cs-red\"><strong>재심</strong></span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①2호</strong></span></span>) 사유</div><div class=\"cs-h\">Ⅱ. 법관의 기피</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>통상인의 판단</strong>으로 불공평한 재판 우려의 <span class=\"cs-red\"><strong>객관적 사정</strong></span> ↔ <span class=\"cs-green\"><strong>주관적 의혹</strong>만<strong><span class=\"cs-x\"><strong>(X)</strong></span> :</strong></span> <strong>[소송지휘 불만]</strong><span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: <strong>평균인</strong>이 의심가질 객관적 사정 있으면 <span class=\"cs-red\"><strong>실제 편파성 없어도</strong> 기피 인정<span class=\"cs-o\"><strong>(O)</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>기피신청에 대한 재판</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① <span class=\"cs-red\"><strong>간이각하</strong></span> : <span class=\"cs-u\"><strong>[신청방식미준수·소송지연목적 명백시]</strong></span> <span class=\"cs-red\">기피당한 법원·법관 스스로 간이각하 가능</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-green\">간이각하<strong> X</strong> → ② <span class=\"cs-u\"><strong>소속법원 다른 합의부</strong></span>가 결정으로 재판</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>기피신청의 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-red\">원칙 :</span> 기피신청에 관한 재판확정까지 <span class=\"cs-red\">본안소송절차 정지</span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§48본문</strong></span></span>)</div><div class=\"cs-li\" style=\"margin-left:32px\"><span class=\"cs-green\">예외 : 긴급행위·종국판결선고·간이각하</span>는 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>[예외사유 없는 절차정지 X 소송행위]</strong>: 위법</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>[간과판결]</strong>: 무효<span class=\"cs-o\"><strong>(O)</strong></span> → 확정<strong>전</strong><span class=\"cs-red\"><strong>상소</strong></span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§424①2호</strong></span></span>)·확정<strong>후</strong><span class=\"cs-red\"><strong>재심</strong></span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①2호</strong></span></span>) 사유</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[기피신청 기각·각하결정 확정시 절차속행 하자의 치유 여부]</strong></span>(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-stat\">(<strong>학설</strong>: <strong>하자치유 </strong><span class=\"cs-u\"><strong>부정설/ 긍정설/ 절충설</strong></span>: 신청권자 소송행위 가능햇을 경우만 치유) </span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: <span class=\"cs-u\"><strong>기피신청자의 소송상이익 보장 여부</strong></span>에 따라 달리 판단 <span class=\"cs-stat\"><strong>→ 절충설</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-red\">① <strong>적극설</strong></span>(<strong>치유</strong><span class=\"cs-o\"><strong>(O)</strong></span>): <span class=\"cs-red\">[기피신청 후 변론관여→ 소송상이익 보장 O] 종국판결을 한 경우</span>, 기피신청 이유없음 확정시 유효<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-green\">② <strong>소극설</strong></span>(<strong>치유</strong><span class=\"cs-x\"><strong>(X)</strong></span>) : <span class=\"cs-green\">[기피신청 후 불출석→소송상이익 보장 X] 변론기일 진행해 쌍방불출석효과 발생</span>시, 절차위반 하자 치유 X</div>", ["★"], 1, "mp_2"], ["민소004", "관할", "<div class=\"cs-li\" style=\"margin-left:16px\"><span class=\"cs-u\">[사례풀이 구조]</span></div><div class=\"cs-theory\"><div class=\"cs-h\">Ⅰ. 관할위반의 소제기인지 판단 <span class=\"cs-stat\">: 토지관할 → 합의관할 단계적 검토</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법정관할 - 법률에 의해 직접 정해진 관할</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">가. 직분관할</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">나. 사물관할</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">다. <strong>토지관할</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 보통재판적</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 특별재판적</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 관련재판적</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 관할의 경합</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>지정관할 - 상급법원의 결정에 의해 정해지는 관할(§28)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>거동관할 - 당사자의 거동(합의나 변론)에 의한 관할</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">가. <strong>합의관할</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 유효성(약관에 의한 합의, 유효요건)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 모습(부가적합의·전속적합의·불분명한 경우)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 관할의 변동</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 주관적 범위</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">나. 변론관할</div><div class=\"cs-h\">Ⅱ. 관할위반의 소제기에 대한 법원의 조치</div></div><div class=\"cs-h\">Ⅰ. 법정관할</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>직분관할 : </strong>담당직분 차이 기준 관할</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-red\"><strong>전속관할·직권조사사항 </strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\"><strong>[청구이의의 소]</strong></span> <span class=\"cs-u\"><strong>'제1심판결법원'</strong></span><span class=\"cs-blue\">(민사집행법§44①)</span><span class=\"cs-u\"><strong>=</strong></span><span class=\"cs-u\">직분관할 → 전속관할</span></div><div class=\"cs-li\" style=\"margin-left:64px\">—  <span class=\"cs-fact-tag\">지방법원 합의부의  항소심(고등법원)판결을 대상으로 한 청구이의의 소 &amp; 부수한 강제집행정지 신청</span> = 수소법원 전속관할</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>사물관할 : </strong>제1심 사건에 대해 <span class=\"cs-u\"><strong>소송목적값 기</strong></span>준으로 정한 <span class=\"cs-u\"><strong>지방법원 단독판사·합의부 간 재판권 분담</strong></span>관계</div><div class=\"cs-tbl\" style=\"overflow-x:auto\"><table class=\"sub\">\n<tr><th>단독 사건</th><th>합의 사건</th></tr>\n<tr><td>① 재정사건 (재정단독)\n② 소가 5억 이하\n③ 5억 초과라도 간단한 사건 (어음↔수표 청구, 대여금·구상금·보증금 청구, 손배 및 채무부존재확인)\n④ 본소가 단독판사 관할인 관련청구 </td><td>① 재정사건 (재정합의)\n② 소가 5억 초과\n③ 비재산상 소 (해고무효확인) / 소가산정불가 재산상 소 (주주대표소송)\n④ 본소가 합의부관할인 관련청구 (소변경/중간확인의 소/반소/독립당사자 참가)</td></tr>\n</table></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[병합심리시  합산액이 소액사건 소가 초과시, 소액사건 해당여부</strong></span><span class=\"cs-blue\">(소액사건심판법 적용)</span><strong>] </strong><span class=\"cs-o\"><strong>(O)</strong></span> — <span class=\"cs-u\">제소당시 기준</span>으로 판단</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[청구병합의 경우의 소가 산정 방식]</strong></span> (★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-red\"><strong>원칙: 합산</strong></span> —  경제적 이익 <strong>독립한 별개</strong>인 단순병합 → 여러 청구값 모두 합산 (<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§27①</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-green\"><strong>예외: 흡수</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">① <span class=\"cs-fact-tag\"><strong>[경제적이익 동일]</strong></span>, ② <span class=\"cs-fact-tag\"><strong>[목적</strong></span><span class=\"cs-red\">(토지인도)</span><span class=\"cs-fact-tag\"><strong>-수단</strong></span><span class=\"cs-red\">(건물철거)</span><span class=\"cs-fact-tag\"><strong>관계]</strong></span> : <span class=\"cs-glabel\">중복범위 내 다액 청구가액에 </span><span class=\"cs-red\"><strong>흡수(선택적·예비적병합)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">③ <span class=\"cs-fact-tag\"><strong>[주된 청구</strong>(원금)<strong>-부대청구</strong>(이자·지연이자) <strong>병합청구]</strong></span>시: <span class=\"cs-red\"><strong>흡수<span class=\"cs-o\"><strong>(O)</strong></span></strong></span> <span class=\"cs-red\">↔ 본래는 별개소송물 </span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-neg-tag\"><strong>[변론병합]</strong></span>: <span class=\"cs-red\"><strong>합산<span class=\"cs-x\"><strong>(X)</strong></span></strong></span> — <span class=\"cs-u\">제소당시 기준</span>으로 판단, 소가합산액이 소액사건 소가 초과해도 소액사건 변함X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-hl\"><strong>토지관할</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(1) 보통재판적 : </strong>모든 사건에 공통 적용</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">사람=<span class=\"cs-glabel\">피고 주소지</span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§2·§3</strong></span></span>), 법인=<span class=\"cs-glabel\">본점소재지</span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§5</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(2) 특별재판적</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">1) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§8</strong></span></span> - <span class=\"cs-def\"><span class=\"cs-u\"><strong>의무이행지</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\"><span class=\"cs-red\"><strong>원칙 : 지참채무</strong></span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§467②</strong></span></span>) → <span class=\"cs-u\"><strong>채권자(원고) 주소지</strong></span>가 의무이행지 — 재산권 소는 의무이행지 법원에도 제기 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">判例 : <span class=\"cs-fact-tag\"><strong>['영업에 관한 채무'의 '현영업소']</strong></span> 채권추심업무 실제담당 영업소도 <span class=\"cs-red\"><strong>포함<span class=\"cs-o\"><strong>(O)</strong></span></strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">2) <span class=\"cs-green\"><strong>예외</strong></span> - <strong>원고 주소지에 의하지 않는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\"><span class=\"cs-green\"><strong>[특정물인도채무]</strong></span> 채권성립 당시 <span class=\"cs-u\"><strong>물건소재지</strong></span> — 원고주소지 <span class=\"cs-green\"><strong>X</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\"><span class=\"cs-green\"><strong>[어음·수표]</strong></span> <span class=\"cs-u\"><strong>지급지 법원</strong></span> — 원고주소지 <span class=\"cs-green\"><strong>X</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\"><span class=\"cs-green\"><strong>[등기신청협조의무]</strong></span> <span class=\"cs-u\"><strong>등기할 공무소소재지</strong></span> — 원고주소지 <span class=\"cs-green\"><strong>X</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\"><span class=\"cs-green\"><strong>[불법행위 손해배상]</strong></span> 피고 예측불가 방지 위해 <span class=\"cs-green\"><strong>의무이행지 개념 자체를 제외</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">3) ★ <strong>사해행위취소의 소의 의무이행지</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">의무이행지 = <span class=\"cs-red\"><strong>'취소로 형성되는 법률관계(말소등기 등)의 의무이행지'</strong></span> <span class=\"cs-red\">↔</span> <span class=\"cs-green\"><strong>'취소대상 법률행위의 의무이행지'</strong></span> <span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">등기신청협조의무는 <span class=\"cs-u\"><strong>등기할 공무소소재지</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">4) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§24①</strong></span></span> - <strong>특허권 등을 제외한 지식재산권·국제거래에 관한 소</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">고등법원 소재지 지방법원도 관할 <span class=\"cs-o\"><strong>(O)</strong></span> — <span class=\"cs-u\"><strong>경합적 특별재판적</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">5) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§24②</strong></span></span> - 고등법원 소재지 지방법원의 <span class=\"cs-red\"><strong>전속관할</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">특허권 등 지식재산권에 관한 소는 고등법원소재지 지방법원의 <span class=\"cs-red\"><strong>전속관할</strong></span> — <span class=\"cs-u\"><strong>경합 불가</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">6) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§24③</strong></span></span> - <strong>서울중앙지방법원에의 중복관할</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\"><span class=\"cs-red\"><strong>원고의 선택</strong></span>으로 서울중앙지방법원에도 제기 <span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">7) §24②·③의 항소사건의 관할 - 특허법원</div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">전문재판부 집중을 위해 특허법원의 전속관할(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>법원조직법§28의4</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(3) 관련재판적</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">1) <strong>의의 및 취지</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\"><span class=\"cs-def\"><span class=\"cs-u\"><strong>관련재판적</strong></span></span> = 1소로 여러 청구 시, <span class=\"cs-u\"><strong>하나의 청구에 관해 관할권 O</strong></span> → 나머지 청구에 대하여도 관할권 인정 <span class=\"cs-o\"><strong>(O)</strong></span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§25</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">취지 : 원고의 <span class=\"cs-red\"><strong>소제기 편의</strong></span>, 피고의 <span class=\"cs-red\"><strong>응소편의</strong></span>, 법원의 <span class=\"cs-red\"><strong>소송경제</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">2) ★ <strong>객관적 병합과 관련재판적(청구의 병합)</strong> - <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§25①</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">3) ★ <strong>주관적 병합과 관련재판적(공동소송)</strong> - <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§25②</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">5) 중요 判例 - 주관적 병합과 관련재판적 및 관할선택권 남용</div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\"><span class=\"cs-fact-tag\"><strong>[관할선택권 남용]</strong></span> 신의칙 위반으로 허용 <span class=\"cs-red\"><strong>X</strong></span> → <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§25</strong></span></span> 적용 배제, 관련재판적 인정 <span class=\"cs-red\"><strong>X</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">4) 효과 - 관할권의 창설</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(4) 관할의 경합</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">토지관할법원이 <span class=\"cs-u\"><strong>여러 개</strong></span>인 경우 → <span class=\"cs-red\"><strong>모두 관할권 인정</strong></span></div><div class=\"cs-h\">Ⅱ. 합의관할</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>유효성</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">★ <strong>(1) 약관에 의한 합의</strong> - 판례 3개</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-u\"><strong>무효판단기준</strong></span> : 약관규제법상 약관 + 대기업유리·원거리고객불편 + 부당불리조항 = <span class=\"cs-red\"><strong>무효</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-neg-tag\"><strong>[전속적 관할합의 약관]</strong></span> ⅰ) 고객에게 다소 불이익하다는 점만으로는 부족 — 그 자체로 무효 <span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">ⅱ) <span class=\"cs-red\"><strong>일방지정법원과 다를 바 없거나</strong></span> ⅲ) <span class=\"cs-red\"><strong>거래상지위 남용</strong></span>해야 비로소 무효 <span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">합의관할 변경시 <span class=\"cs-statute\"><span class=\"cs-u\"><strong>'회사 관할영업점'</strong></span></span>은 <span class=\"cs-u\"><strong>계약체결 당시 영업점</strong></span> 기준</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(2) 관할합의의 요건</strong></div><div class=\"cs-li\" style=\"margin-left:48px\">① <span class=\"cs-red\"><strong>제1심법원 임의관할</strong></span> 합의(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§29①</strong></span></span>) ② <span class=\"cs-red\"><strong>일정한 법률관계</strong></span>로 특정(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§29②</strong></span></span>) ③ <span class=\"cs-red\"><strong>관할법원 특정</strong></span> ④ <span class=\"cs-red\"><strong>서면 방식</strong></span>(동항)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>모습</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-red\"><strong>부가적합의</strong></span>(법정관할+추가) <span class=\"cs-red\">↔</span> <span class=\"cs-green\"><strong>전속적합의</strong></span>(그 법원만)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">당사자 의사 <span class=\"cs-u\"><strong>불분명</strong></span>시 : 법정관할 중 하나 합의 = <span class=\"cs-green\"><strong>전속적 합의</strong></span> / 법정관할 외 합의 = <span class=\"cs-red\"><strong>부가적 합의</strong></span>로 추정</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">전속합의 후 외국적요소 발생시 다른국가 재판권 완전배제 <span class=\"cs-x\"><strong>(X)</strong></span>, 채권양수인에게 효력 <span class=\"cs-red\"><strong>불미침</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(1) 관할의 변동</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-red\"><strong>부가적합의</strong></span> = 관할권 없던 법원에 관할 발생 <span class=\"cs-red\">↔</span> <span class=\"cs-green\"><strong>전속적합의</strong></span> = 합의법원에만 제소, 다른 법정관할 <span class=\"cs-green\"><strong>소멸</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(2) 주관적 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">1) <strong>당사자와 포괄승계인</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">당사자와 포괄승계인(상속인)에만 미침</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">2) ★ <strong>채권의 특정승계인</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">지명채권처럼 <span class=\"cs-u\"><strong>권리관계 내용 자유변경 가능 + 동일성 유지 양수</strong></span> → 관할합의 효력 특정승계인에게도 <span class=\"cs-red\"><strong>미침<span class=\"cs-o\"><strong>(O)</strong></span></strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">3) ★ <strong>물권의 특정승계인</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\"><span class=\"cs-u\">물권법정주의</span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§185</strong></span></span>)로 <span class=\"cs-u\"><strong>내용변경 불가 + 합의 등기불가</strong></span> → 관할합의 효력 물권 특정승계인에게는 <span class=\"cs-green\"><strong>불미침<span class=\"cs-x\"><strong>(X)</strong></span></strong></span></div><div class=\"cs-h\">Ⅲ. 변론관할</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(1) 요건</div><div class=\"cs-li\" style=\"margin-left:48px\">① <span class=\"cs-red\"><strong>임의관할 없는 제1심법원에 소제기</strong></span> ② 피고의 <span class=\"cs-red\"><strong>관할위반 항변 없음</strong></span> ③ 피고가 <span class=\"cs-red\"><strong>이의없이 본안변론을 구술로</strong></span> 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(2) </strong><span class=\"cs-hl\"><strong>청구기각의 답변만을 구한 경우 변론관할 발생 여부</strong></span><strong>(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-u\">부정설</span> : 청구기각 답변만 하고 청구원인 답변을 다음기일로 미루면 <span class=\"cs-u\"><strong>'이의없이 본안변론'</strong></span>에 해당 <span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(3) </strong><span class=\"cs-hl\"><strong>진술간주로 변론관할 발생 여부</strong></span><strong>(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">서면제출+불출석 <span class=\"cs-u\"><strong>진술간주</strong></span>는 출석하여 구술진술한 것이 아니므로 변론관할 <span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">관할위반 항변 없이 본안 진술시 <span class=\"cs-red\"><strong>변론관할 발생</strong></span> → 이후 피고는 관할위반 항변 <span class=\"cs-green\"><strong>불가</strong></span></div><div class=\"cs-h\">Ⅳ. 관할위반의 소제기에 대한 법원의 조치(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-u\"><strong>관할흠결</strong></span>은 원칙 각하이나, <span class=\"cs-red\"><strong>관할위반은 소송경제 위해 이송</strong></span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§34①</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">법원이 변론기일 지정 → 피고가 <span class=\"cs-red\"><strong>관할위반 항변</strong></span>시 이송 <span class=\"cs-red\">↔</span> <span class=\"cs-green\"><strong>항변없이 본안변론</strong></span>시 변론관할 발생(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§30</strong></span></span>)으로 <span class=\"cs-green\"><strong>하자치유·절차속행</strong></span></div><div class=\"cs-h\">Ⅴ. 소송의 이송</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>관할위반에 의한 이송 - §34</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(1) 제1심법원 사이</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">원칙적으로 <span class=\"cs-u\"><strong>제1심법원 상호간</strong></span> 적용 — 이송시 <span class=\"cs-red\"><strong>최초 소제기시 기간준수효과 유지</strong></span> <span class=\"cs-red\">↔</span> <span class=\"cs-green\">소각하·기록송부는 불유지</span>(논의실익)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(2) 상급법원과 하급법원 사이</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">1) ★ <strong>심급관할위반의 소제기</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">심급관할은 <span class=\"cs-u\"><strong>공익적 문제</strong></span> → <span class=\"cs-red\"><strong>당사자 의사와 무관하게 이송</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">2) ★ <strong>심급관할 위반의 상소제기</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:64px\">상소장 원심 미제출 · 원심의 상소법원 기록송부 누락시 → 원칙적으로 <span class=\"cs-red\"><strong>소송기록 송부로 해결</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(3) 다른 종류의 법원 사이</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\"><strong>[가사·행정사건을 민사법원에 제소]</strong></span> <span class=\"cs-red\"><strong>이송해야 함</strong></span> — 행정사건 항소사건은 고등법원 <span class=\"cs-red\"><strong>전속관할</strong></span>(원심 지방법원합의부가 심판했다면 이송)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\"><strong>[비송사건을 소송사건으로 제소]</strong></span> 구제절차 있으면 <span class=\"cs-u\"><strong>권리보호이익(제소장애사유)</strong></span> 없어 <span class=\"cs-red\"><strong>각하</strong></span> — 단 석명상 비송처리 의사 확인되면 비송으로 심리·이송</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(4) ★ <strong>재심의 소제기</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">항소심에 제기할 재심의 소를 제1심에 제기해도 이송은 <span class=\"cs-red\"><strong>적법<span class=\"cs-o\"><strong>(O)</strong></span></strong></span> — 재심제기기간 준수여부는 <span class=\"cs-u\"><strong>제1심 제기시 기준</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(5) </strong><span class=\"cs-hl\"><strong>지방법원 항소부에서 고등법원으로 이송 가부</strong></span><strong>(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">심급관할은 <span class=\"cs-u\"><strong>제1심법원의 존재로 결정되는 전속관할</strong></span>로 항소심 관할에 영향 <span class=\"cs-red\"><strong>X</strong></span> → 항소부에서 고등법원으로 이송 <span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-hl\"><strong>관할위반에 의한 이송의 경우 이송신청권 인정여부</strong></span><strong> - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§39</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(1) 문제점</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§34①</strong></span></span>은 <span class=\"cs-u\"><strong>직권이송만 규정</strong></span>, 당사자의 이송신청권 인정여부가 문제</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>(2) 判例</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">이송신청권 <span class=\"cs-green\"><strong>부정<span class=\"cs-x\"><strong>(X)</strong></span></strong></span> → 신청은 <span class=\"cs-u\"><strong>직권발동촉구</strong></span>에 불과</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">거부재판에 항고 <span class=\"cs-green\"><strong>불허</strong></span> · 특별항고도 <span class=\"cs-green\"><strong>불허</strong></span> · 이송결정이 취소되어도 신청인의 재항고 <span class=\"cs-green\"><strong>불허</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-hl\"><strong>전속적 관할합의가 있는 경우 재량이송 가부</strong></span><strong>(★) - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§35</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">전속적합의는 <span class=\"cs-u\"><strong>임의관할의 성격</strong></span> → <span class=\"cs-red\"><strong>공익상 필요</strong></span>(현저한 지연 회피)가 있는 경우에 한해 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§35</strong></span></span> 재량이송 <span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>지식재산권과 국제거래에 관한 소송의 이송 - §36</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(1) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§36①</strong></span></span>(특허권 등을 제외한 지식재산권과 국제거래에 관한 소송의 이송)(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">직권 또는 당사자 신청으로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§24</strong></span></span> 관할법원 상호간 이송 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(2) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§36③</strong></span></span>(특허권 등의 지식재산권에 관한 소송의 이송)(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-statute\"><span class=\"cs-u\"><strong>'현저한 손해 또는 지연을 피하기 위하여'</strong></span></span> 필요시 순회재판부(지원)로 이송 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-hl\"><strong>전속관할을 위반한 이송결정의 기속력 인정 여부</strong></span><strong>(★) - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§38</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">전속관할 위반 이송결정도 기속력 <span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">단 심급관할 위배 이송은 <span class=\"cs-green\"><strong>상급심법원에는 기속력 불미침</strong></span>(심급이익·입증기회 보호) <span class=\"cs-red\">↔</span> <span class=\"cs-red\"><strong>하급심법원에는 기속력 미침</strong></span>(전전이송 방지)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>반소제기에 의한 이송 - §269②</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">본소가 단독사건 + 피고가 합의부 반소제기시 → 직권·신청으로 <span class=\"cs-red\"><strong>본소·반소 모두 합의부 이송</strong></span>(<span class=\"cs-u\"><strong>원고의 합의부심리이익 보호</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">단 원고가 관할위반항변 없이 변론(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§30</strong></span></span> 변론관할 발생)시 <span class=\"cs-green\"><strong>이송 불요</strong></span></div><div class=\"cs-h\">Ⅵ. 소송계속의 이전</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">이송결정 확정시 소송은 <span class=\"cs-u\"><strong>처음부터 이송받은 법원에 계속</strong></span>된 것으로 간주 → <span class=\"cs-red\"><strong>시효중단·기간준수 효력 유지</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[행정소송을 민사소송으로 오인제기 후 이송+소변경]</strong></span> 제소기간 준수여부는 <span class=\"cs-u\"><strong>최초 소제기시 기준</strong></span>으로 판단</div>", ["★★★"], 1, "mp_2"], ["민소005", "당사자의 확정", "<div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-u\"><strong>[사례풀이 구조]</strong></span> 1. 당사자를 확정 → 2. 당사자자격 판단과 흠결발견시 보정방법 → 3. 간과판결의 효력</div><div class=\"cs-h\">Ⅰ. 당사자 확정기준(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例 : <span class=\"cs-u\"><strong>소장 기재 표시 + 청구의 내용·원인사실</strong></span>을 종합하여 확정(<span class=\"cs-u\">실질적 표시설</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[피고가 제소 전 사망한 것을 모르고 제소]</strong></span> 사실상 피고는 <span class=\"cs-red\"><strong>사망자의 상속인</strong></span></div><div class=\"cs-h\">Ⅱ. 당사자자격 판단과 흠결발견 시 보정방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>당사자자격 판단 및 보정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">확정된 당사자 기준 자격구비여부 판단, 흠결시 부적법 각하 → 법원은 <span class=\"cs-red\"><strong>보정기회 부여의무 <span class=\"cs-o\"><strong>(O)</strong></span></strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[자격 없는 자를 당사자로 잘못 표시했는데 표시정정 조치 없이 각하]</strong></span> <span class=\"cs-red\"><strong>위법</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>보정 방법(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① <span class=\"cs-u\"><strong>양자 동일성 인정</strong></span> → <span class=\"cs-red\"><strong>당사자표시정정신청</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">② <span class=\"cs-u\"><strong>동일성 불인정 + 소송계속 중 권리의무 승계 인정</strong></span> → <span class=\"cs-red\"><strong>소송승계</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">③ <span class=\"cs-u\"><strong>동일성·승계 모두 불인정</strong></span> → <span class=\"cs-green\"><strong>임의적 당사자변경</strong></span> — 원칙 <span class=\"cs-green\"><strong>불허<span class=\"cs-x\"><strong>(X)</strong></span></strong></span>, 예외적으로 법규정 있는 경우만 허용(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§260</strong></span></span> 피고경정)</div><div class=\"cs-h\">Ⅲ. 당사자 표시정정</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">★ <strong>공부상 오기가 명백한 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(1) 당사자확정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例(<span class=\"cs-u\">실질적 표시설</span>) : <span class=\"cs-u\"><strong>공부상 기재에 비추어 이름 오기가 명백</strong></span>하면 <span class=\"cs-red\"><strong>동일성 인정되는 자</strong></span>를 당사자로 확정</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(2) 당사자표시의 잘못을 발견시 보정방법</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">동일성 인정되는 자로의 <span class=\"cs-red\"><strong>표시정정 허용<span class=\"cs-o\"><strong>(O)</strong></span></strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(3) 간과판결의 효력 및 구제책</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">당사자를 잘못 표시한 확정판결도 <span class=\"cs-green\"><strong>당연무효<span class=\"cs-x\"><strong>(X)</strong></span></strong></span> <span class=\"cs-red\">↔</span> <span class=\"cs-red\"><strong>유효<span class=\"cs-o\"><strong>(O)</strong></span></strong></span> → 동일성 인정되는 범위 내에서 적법하게 확정된 당사자에게 효력 미침</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">★ <strong>당사자능력 없는 사람을 당사자로 잘못 표시한 것이 명백한 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(1) 당사자확정과 당사자자격 판단</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例(<span class=\"cs-u\">실질적 표시설</span>) : <span class=\"cs-fact-tag\"><strong>[당사자능력 없는 자(행정관청·지점·학교)를 당사자로 잘못 표시]</strong></span>한 것이 명백하면 <span class=\"cs-u\"><strong>소장 전취지 합리적 해석</strong></span>으로 <span class=\"cs-red\"><strong>올바른 당사자능력자(국가·본점·설립자)</strong></span>가 당사자로 확정</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(2) 당사자표시의 잘못을 발견 시 보정방법</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-u\">표시정정설</span> : 올바른 당사자능력자와 동일성 인정되는 당사자로 <span class=\"cs-red\"><strong>표시정정 <span class=\"cs-o\"><strong>(O)</strong></span></strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(3) 간과판결의 효력 및 구제책</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[당사자능력 없는 사망한 사람]</strong></span> 상대 판결은 <span class=\"cs-red\"><strong>당연무효 判例<span class=\"cs-o\"><strong>(O)</strong></span></strong></span> <span class=\"cs-red\">↔</span> <span class=\"cs-green\"><strong>그 외(행정관청·지점·학교)</strong></span> 유형은 판시 없음 → 사회적 조직체로 활동하므로 당연무효 <span class=\"cs-x\"><strong>(X)</strong></span>, <span class=\"cs-green\"><strong>유효<span class=\"cs-o\"><strong>(O)</strong></span></strong></span>로 봄이 타당(사견)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>표시정정의 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">표시정정은 <span class=\"cs-u\"><strong>당사자 동일성 유지</strong></span>로 소제기의 효과 그대로 유지(시효중단·기간준수)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">★ <span class=\"cs-fact-tag\"><strong>[제소전 사망 이외의 경우]</strong></span> 제1심·항소심·상고심 모두 상대방 동의 없이 표시정정 <span class=\"cs-red\"><strong>허용<span class=\"cs-o\"><strong>(O)</strong></span></strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-red\">↔</span> ★ <span class=\"cs-gbg\"><strong>[제소전 사망의 경우]</strong></span> <span class=\"cs-green\"><strong>제1심에서만 허용<span class=\"cs-o\"><strong>(O)</strong></span></strong></span>, 항소심·상고심(법률심)에서는 <span class=\"cs-green\"><strong>불허<span class=\"cs-x\"><strong>(X)</strong></span></strong></span></div><div class=\"cs-h\">Ⅳ. 성명모용소송(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>당사자의 확정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例 : 소장 기재 표시 + 청구내용 + 원인사실 종합 확정 원칙 → <span class=\"cs-u\">실질적 표시설</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>발견 시 법원의 조치</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(1) 위장출석의 경우 - </strong><span class=\"cs-def\"><span class=\"cs-u\"><strong>가장성명모용</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">표시설상 <span class=\"cs-red\"><strong>피모용자가 당사자</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[원고측 모용]</strong></span> 피모용자가 추인하지 않는 한 판결로 <span class=\"cs-red\"><strong>소각하</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[피고측 모용]</strong></span> 모용자의 소송관여를 배척하고 <span class=\"cs-red\"><strong>진정한 피고를 소환</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><strong>(2) 성명모용의 경우 - </strong><span class=\"cs-def\"><span class=\"cs-u\"><strong>진정성명모용</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">실제 피고는 <span class=\"cs-u\"><strong>모용자</strong></span>이며 당사자는 <span class=\"cs-u\"><strong>피모용자 명의</strong></span>로 확정</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">모용자 명의로의 변경은 동일성 불인정으로 <span class=\"cs-green\"><strong>표시정정 불가<span class=\"cs-x\"><strong>(X)</strong></span></strong></span> → <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§260</strong></span></span> 피고경정에 의해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例 : <span class=\"cs-neg-tag\"><strong>[피고를 잘못 지정한 것이 명백한 경우가 아님]</strong></span> 피고경정 <span class=\"cs-red\"><strong>불허<span class=\"cs-x\"><strong>(X)</strong></span></strong></span> → 원고는 <span class=\"cs-red\"><strong>소취하 후 신소 제기</strong></span>할 수밖에 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>간과한 판결의 효력 및 피모용자의 구제책</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">유효하나 위법한 판결이며 표시설상 효력은 피모용자에게 미치므로, 불리하면 무권대리를 이유로 확정전 상소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§424①4호</strong></span></span>)·확정후 재심(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①3호</strong></span></span>)로 취소 가능, 유리하면 이익으로 원용 가능</div><div class=\"cs-h\">Ⅴ. 사망자당사자소송(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>제소전사망</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) 당사자의 확정(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例 : 이미 사망한 자를 모르고 피고로 제소한 경우 사실상 피고는 <span class=\"cs-red\"><strong>'사망자의 상속인'</strong></span>(<span class=\"cs-u\">실질적 표시설</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">상속인 = <span class=\"cs-u\"><strong>'실제로 상속하는 사람'</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">★ <span class=\"cs-fact-tag\"><strong>[1순위 상속인이 상속포기]</strong></span> 그는 제외, <span class=\"cs-red\"><strong>후순위 상속인</strong></span>이 실제 상속인이 되면 그가 당사자로 확정</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) 발견 시 법원의 조치(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">상속인으로 당사자 확정, 표시된 피고(사망자)는 당사자능력 없어 부적법 → 실질적 표시설에 따라 당사자표시정정 허용(사망사실 모르고 표시한 경우) → ★ [1순위 상속인이 상속포기, 2순위 상속인이 실제 상속인이 된 경우] 표시정정의 대상이며, 이를 '피고경정'의 방법으로 취했더라도 표시정정으로서의 법적성질·효과는 유지된다고 본</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) ★ <strong>간과한 판결의 효력 및 구제책</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) <strong>판결의 효력이 미치는 자</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">소제기 이전 사망을 간과한 본안판결은 <span class=\"cs-red\"><strong>사망한 자에게 미침</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\"><strong>[사망자에 대한 송달]</strong></span> 원칙 <span class=\"cs-red\"><strong>무효</strong></span> — 단 상속인이 <span class=\"cs-u\"><strong>현실적으로 수령</strong></span>하면 하자치유되어 그때부터 상속인에 대한 송달로 효력 발생</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) <strong>제소 전 사망자임을 간과한 판결의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-u\"><strong>대립당사자 구조 무시</strong></span>로 실질적 소송관계 불성립 → 제1심판결 있었어도 <span class=\"cs-red\"><strong>'당연무효'<span class=\"cs-o\"><strong>(O)</strong></span></strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) <strong>제소 전 사망자임을 간과한 판결에 대한 구제책</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">당연무효이므로 — ① 상대방 상소는 대상적격 없어 <span class=\"cs-green\"><strong>부적법 상소각하</strong></span> ② 재심의 소도 대상적격 없어 <span class=\"cs-green\"><strong>재심의소각하판결</strong></span> ③ 상속인들의 소송수계신청도 <span class=\"cs-green\"><strong>허용 불가<span class=\"cs-x\"><strong>(X)</strong></span></strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) <strong>제소 전 실종선고를 간과한 판결의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-u\"><strong>실종선고 효력 발생 전</strong></span>에는 실종기간 만료되어도 당사자능력 유지 → 그를 상대로 한 소·판결 <span class=\"cs-red\"><strong>유효<span class=\"cs-o\"><strong>(O)</strong></span></strong></span>, 확정시 기판력도 발생</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\"><strong>[사후 실종선고 확정으로 사망간주시점이 소제기 전으로 소급]</strong></span> 기존 판결이 소급하여 무효가 되지 <span class=\"cs-red\"><strong>않음(유효)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) ★ <strong>소멸시효와 시효중단</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[표시정정]</strong></span> 동일성 유지로 소제기 효과 그대로 <span class=\"cs-red\"><strong>유지<span class=\"cs-o\"><strong>(O)</strong></span></strong></span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§265</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-gbg\"><strong>[사망자에 대한 소제기]</strong></span> 부적법·당연무효로 상속인에 <span class=\"cs-green\"><strong>시효중단효 없음<span class=\"cs-x\"><strong>(X)</strong></span></strong></span>(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§170②</strong></span></span> 부적용)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">단 상속인으로 표시정정된 경우는 <span class=\"cs-red\"><strong>당초 소제기시로 시효중단 인정</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">★ <strong>소제기 후 소장부본 송달 전에 피고가 사망한 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-u\"><strong>대립당사자 구조 무시</strong></span>로 실질적 소송관계 불성립 → 소장부본 송달 전 사망에도 동일 법리 → <span class=\"cs-red\"><strong>'당연무효'<span class=\"cs-o\"><strong>(O)</strong></span></strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">★ <strong>소송대리인에게 소송위임 후 제소 전 사망한 경우 법률관계</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">당사자가 사망해도 <span class=\"cs-red\"><strong>소송대리권은 불소멸</strong></span> → 소의 제기는 <span class=\"cs-red\"><strong>적법<span class=\"cs-o\"><strong>(O)</strong></span></strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">시효중단 등 소제기 효과는 <span class=\"cs-u\"><strong>상속인들에게 귀속</strong></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§233①</strong></span></span> 유추적용되어 상속인들은 <span class=\"cs-red\"><strong>소송절차를 수계</strong></span>해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송계속 후 변론종결 전 사망 - 중단에서 후술</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">상속인 있으면 당사자의 지위는 상속인에게 당연승계 → 수계절차 밟을 때까지 절차 중단 / 이를 간과한 판결은 당연무효는 아니고 대리권 흠을 이유로 확정전 상소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§424①4호</strong></span></span>)·확정후 재심(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①3호</strong></span></span>) 취소사유</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>변론종결 후 사망 - 변론종결 뒤의 승계인에서 후술</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">상속인은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span>의 <span class=\"cs-u\"><strong>변론종결한 뒤의 승계인</strong></span>에 해당 → 사자명의 판결도 상속인에게 <span class=\"cs-red\"><strong>기판력 미침<span class=\"cs-o\"><strong>(O)</strong></span></strong></span>, <span class=\"cs-red\"><strong>승계집행문</strong></span> 부여받아 강제집행 가능</div><div class=\"cs-h\">Ⅵ. 법인격부인론(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-def\"><span class=\"cs-u\"><strong>법인격부인론</strong></span></span> = 회사의 법인격이 <span class=\"cs-u\"><strong>형해화·남용</strong></span>된 경우 특정 사안에 한해 법인격을 부인하고 <span class=\"cs-red\"><strong>배후자에게 법인의 채무 책임</strong></span>을 지우는 이론</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>근거</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">배후자가 별개 인격 주장하는 것은 신의성실의 원칙에 반한다는 <span class=\"cs-u\">신의칙설</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">★ <strong>적용요건 및 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-u\"><strong>요건</strong></span> : ① 법인격 형해화·남용 ② 배후자의 부정행위로 인한 자본불충분 야기 ③ 자본불충분과 원고의 손해 사이 인과관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-u\"><strong>판단시기</strong></span> : <span class=\"cs-red\"><strong>형해화</strong></span>는 문제된 법률행위·사실행위 시점 <span class=\"cs-red\">↔</span> <span class=\"cs-green\"><strong>남용</strong></span>은 채무면탈 등 남용행위 시점 기준</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-u\"><strong>효과</strong></span> : 특정사안에 한해 법인격 부인, 배후자가 <span class=\"cs-red\"><strong>채무자인 법인과 함께 책임</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-hl\"><strong>법인격이 부인되는 법인에 대한 소제기가 적법한지 여부</strong></span><strong> - 당사자 확정과 자격</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-u\">실질적 표시설</span>에 의하면 피고는 <span class=\"cs-green\"><strong>배후자가 아니라</strong></span> <span class=\"cs-red\"><strong>그 법인으로 확정</strong></span> → 이러한 법인도 당사자능력·적격 유지하므로 소제기 <span class=\"cs-red\"><strong>적법<span class=\"cs-o\"><strong>(O)</strong></span></strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-hl\"><strong>배후자에 대한 별소제기 가부와 배후자의 소멸시효 주장 가부</strong></span><strong>(★) - 발견시 조치</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) 법인격 부인의 정적용</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[회사가 배후자의 개인기업에 불과]</strong></span> 별개 인격체임을 내세워 배후자의 책임을 부정하는 것은 <span class=\"cs-red\"><strong>신의칙 위반</strong></span> → 채권자는 회사·배후자 모두에게 별소제기 <span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) 법인격부인의 역적용</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">회사설립 전 개인의 채무부담행위에 대해 회사 책임을 부인하는 것이 정의·형평에 반하는 때에는 회사에도 회사설립 전 개인이 부담한 채무의 이행청구 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) 배후 법인에 대한 별소제기</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">★ <span class=\"cs-fact-tag\"><strong>[기존회사 채무 면탈 목적으로 실질적 동일한 신설회사 설립]</strong></span> <span class=\"cs-u\"><strong>회사제도 남용</strong></span>으로 별개 법인격 주장은 신의칙상 허용 <span class=\"cs-red\"><strong>X</strong></span> → 채권자는 두 회사 어느 쪽에도 채무이행 청구 <span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) 다른 법인에 대한 별소제기</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">기존회사 자산이 제3자를 거쳐 다른 회사로 이전되었더라도 정당한 대가 없이 이전된 것이라면 채무면탈 의도의 법인격 남용으로 보아 다른 회사에도 채무이행청구 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(5) 소멸시효 주장 가부</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">신설회사가 별개로 <span class=\"cs-u\"><strong>소멸시효 완성</strong></span>을 주장하는 것도 별개 법인격 전제로 하므로 신의칙상 <span class=\"cs-red\"><strong>불허<span class=\"cs-x\"><strong>(X)</strong></span></strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-hl\"><strong>판결의 효력이 배후자에게 미치는지 여부</strong></span><strong>(★) - 간과 판결</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-u\"><strong>절차의 명확·안정을 중시하는 소송·집행절차 성격</strong></span>상 법인격 부인되는 회사에 대한 판결의 <span class=\"cs-green\"><strong>기판력·집행력을 배후자에게 확장하는 것은 불허<span class=\"cs-x\"><strong>(X)</strong></span></strong></span></div>", ["★★★"], 1, "mp_2"], ["민소006", "당사자능력", "<div class=\"cs-h\">Ⅰ. 비법인사단의 당사자능력과 소송수행방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>비법인사단의 당사자능력 - 비법인사단의 명의로 소송수행(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">비법인사단은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§52</strong></span></span>가 당사자능력 인정<span class=\"cs-o\"><strong>(O)</strong></span> → 그 명의로 원·피고 가능. 요건: ⅰ) 사단으로서의 실질 구비 ⅱ) 대표자 존재</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例상 '사단의 실질' = ⅰ) 의사결정·집행기관인 대표자 등 조직 구비 ⅱ) 다수결 의결·업무집행 ⅲ) 단체성 유지</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">판단시점은 사실심 변론종결일 기준, 직권조사사항<span class=\"cs-o\"><strong>(O)</strong></span> → 비법인사단이 원고여도 직권으로 단체 실체를 파악·판단</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[사단법인의 하부조직이라도 독자적 활동]</strong></span> 별개의 독립된 비법인사단<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>구성원 전원의 명의로 소송을 수행하는 방법</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">총유재산 소송은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§276①</strong></span></span>상 관리처분권이 구성원 전원에 귀속 → 고유필수적 공동소송<span class=\"cs-o\"><strong>(O)</strong></span> → 구성원 전원이 당사자 안 되면 당사자적격 흠결로 부적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>구성원 일부의 명의로 소송을 수행할 수 있는지 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">총유재산 소송은 고유필수적 공동소송 → <span class=\"cs-gbg\"><strong>[구성원 중 일부만 소제기]</strong></span> 당사자적격 없어 부적법(X, 소각하) → 구성원 일부 명의 소송수행<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>중요 판례</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) 종중대표자 명의의 보존행위로서 소제기의 적부(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">종전판례: 총유물 보존행위 소송은 구성원이 소제기 가능<span class=\"cs-o\"><strong>(O)</strong></span> ↔ 변경판례: 총유는 공유·합유와 달리 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§265</strong></span></span>단서·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§272</strong></span></span>단서 같은 규정 없음 → ① 법인 아닌 사단 명의 ② 구성원 전원 고유필수적 공동소송 형태로만 가능<span class=\"cs-o\"><strong>(O)</strong></span>, ③ 구성원 일부는 당사자 X(소각하)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) 종중의 당사자능력</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">종중은 자연발생적 종족단체로 특별한 조직행위 없이 성립<span class=\"cs-o\"><strong>(O)</strong></span> → 단, 고유한 의미의 종중이라도 비법인사단 요건(사단 실질)을 갖춰야 당사자능력 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) 사원총회의 결의</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">비법인사단 대표자가 총유물 처분 소송행위를 하려면 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§276①</strong></span></span>상 사원총회 결의 필요 → 결의 없이 한 소송행위는 특별수권 없는 경우로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>3호 재심사유<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 조합의 당사자능력과 소송수행방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>조합의 당사자능력(★) - 조합 명의로 소송수행 가부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 조합은 계약관계로 단체 실질이 없고 민법·민소법에 당사자능력 인정 규정도 없음 → 조합의 당사자능력<span class=\"cs-x\"><strong>(X)</strong></span> → 조합 명의 소송수행<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>조합원 전원과 일부명의로 소송수행 가부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">조합은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§704</strong></span></span>본문상 합유물 관리처분권이 구성원 전원에 귀속 → 고유필수적 공동소송<span class=\"cs-o\"><strong>(O)</strong></span> → 조합원 전원이 당사자여야 하고 일부만 소제기시 당사자적격 없어 부적법<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">예외 : ① 보존행위(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§272</strong></span></span>단서) ② 조합채무 이행 수동소송(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§712</strong></span></span>)은 조합원 각자가 소송수행 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>업무집행조합원을 활용하여 소송수행하는 방법에 대한 판례의 입장(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) 명문규정이 있는 임의적 소송담당으로 선정당사자로 선정 가부</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">조합은 ① 공동소송할 다수자 ② <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§65</strong></span></span> 전문의 '소송목적 권리·의무가 여러 사람에게 공통' 해당 ③ 그 중 업무집행조합원 선정이므로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§53</strong></span></span> 요건 구비<span class=\"cs-o\"><strong>(O)</strong></span> → 업무집행조합원을 선정당사자로 소송수행 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) 명문규정이 없는 경우 임의적 소송담당 인정 여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">원칙 : ⅰ) 소송신탁금지 ⅱ) 변호사대리원칙 잠탈 염려로 불허<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">예외 : ⅰ) 위 염려 없고 ⅱ) 허용할 합리적 이유(권리주체의 포괄적 관리처분권 수여 + 소송담당자 고유이익) 있으면 허용<span class=\"cs-o\"><strong>(O)</strong></span> → 判例: <span class=\"cs-gbg\"><strong>[업무집행조합원에 대한 조합원의 임의적 소송신탁]</strong></span> 변호사대리원칙 회피나 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§7</strong></span></span> 잠탈 아니라고 보아 인정<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["★★"], 1, "mp_2"], ["민소007", "당사자적격", "<div class=\"cs-h\">Ⅰ. 이행의 소</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판단기준(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 이행의 소의 당사자적격은 '원고의 주장 자체'로 구비 → 이행청구권자로 주장하는 자가 원고적격, 이행의무자로 주장된 자가 피고적격 → 실제 권리자·의무자 아님이 밝혀져도 청구기각일 뿐 당사자적격 흠결로 각하할 것은 아님</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[간접점유자를 상대로 한 이행청구]</strong></span> <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§213</strong></span></span> 불법점유자에 대한 인도청구는 직접점유자만 상대 가능하나(간접점유자 상대 불가), 인도약정에 따른 이행청구는 직접·간접점유자 모두 가능 → 간접점유자 상대 인도청구 소는 이행의 소이므로 피고적격 인정<span class=\"cs-o\"><strong>(O)</strong></span>, 본안에서 원고청구기각</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>예외</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>말소등기청구에서 피고적격(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 피고적격은 등기의무자인 등기명의인에게만 있음 → 등기명의 없는 자에 대한 청구는 원고 주장 자체로 피고적격 없어 부적법 각하(본안심리 불요)<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>저당권이전의 부기등기의 말소등기청구의 피고적격(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 부기등기는 주등기(근저당권설정등기)에 종속·일체 → 주등기 말소만 구하면 되고 부기등기는 직권말소(별도 청구는 소의 이익 없어 각하) ② 부기등기로 새 권리 발생 아님 → 말소청구는 양수인만 상대, 양도인은 피고적격 없음(X, 각하)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>가등기의 이전에 의한 부기등기의 말소등기청구의 피고적격·당사자적격(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 피담보채무 소멸시 주등기(가등기) 말소만 구하면 됨(부기등기 별도청구는 소이익 없어 각하) ② 가등기 말소청구는 양수인만 상대, 양도인은 피고적격 없음(X, 각하)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>말소등기의 회복등기청구의 소에서 피고적격(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: <span class=\"cs-gbg\"><strong>[불법말소]</strong></span> 회복등기의무자에게만 피고적격 → 가등기 말소 당시의 소유자(제3취득자)가 회복등기의무자, 가등기 당시 원소유자는 피고적격 없어 부적법<span class=\"cs-x\"><strong>(X)</strong></span> / <span class=\"cs-gbg\"><strong>[직권말소]</strong></span> 등기공무원 직권·법원 촉탁으로 말소된 등기는 등기명의인 상대 회복등기청구 자체가 소의 이익 없어 부적법(피고적격 문제 아닌 권리보호자격 중 제소장애사유)<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(5) <strong>말소등기청구의 소에서 등기명의인이 허무인인 경우 피고적격(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 등기명의인이 허무인·실체없는 단체인 때에는 '실제 등기행위를 한 사람'을 피고로 말소를 구할 수 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(6) <strong>진정명의회복을 원인으로 한 소유권이전등기의 피고적격(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 현재의 등기명의인을 상대로만 절차이행을 구해야 함 → 등기의무자 아닌 자(중간 등기명의인 등) 상대 소는 피고적격 없어 부적법 각하<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 확인의 소</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판단기준</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">'확인의 이익이 있는 자'가 원고적격, '원고의 이익과 대립·저촉되는 이익을 가지는 자'가 피고적격</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>단체내부 분쟁의 원고적격과 피고적격(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>원고적격</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">확인의 이익 있는 자는 누구든지 원고적격<span class=\"cs-o\"><strong>(O)</strong></span> → 이사회결의 무효확인의 소도 마찬가지 / 비법인사단인 교회도 스스로 원고가 되어 교인총회 결의부존재확인의 소 제기 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>피고적격</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><strong>[법인인 회사]</strong> 주주총회결의 무효·부존재확인의 소는 단체(회사) 자체를 피고로 해야 하며 대표자 개인은 확인의 이익 없음(X, 각하) - <span class=\"cs-u\"><strong>회사피고설</strong></span> / <strong>[비법인사단]</strong> 관리단 대표자 지위 확인소송도 대표자 개인 아닌 단체를 상대해야 근본적 해결(대표자 개인 상대는 확인의 이익 없어 부적법)<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 형성의 소</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">명문규정 있으면 그에 따르고 없으면 당해 권리관계에 가장 강한 이해관계 있는 자가 당사자적격 → 判例: 사해행위취소의 소에서 채무자는 피고적격 없고 수익자·전득자만 피고적격<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅳ. 고유필수적 공동소송(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">여러 사람 전원이 공동으로 원·피고가 되어야 하는 소송 → 전원이 함께 하지 않으면 당사자적격 흠결로 부적법<span class=\"cs-x\"><strong>(X)</strong></span>(단 제1심 변론종결시까지 추가되면 하자치유, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span>)</div><div class=\"cs-h\">Ⅴ. 제3자의 소송담당</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법정소송담당</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>병행형 - 제3자가 권리관계 주체와 함께 소송수행권을 갖는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">채권자대위소송의 채권자(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§404</strong></span></span>), 회사대표소송의 주주(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>상법§403</strong></span></span>), 채권질의 질권자(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§353</strong></span></span>), 공유자 전원을 위해 보존행위하는 공유자(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§265</strong></span></span>) 등</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>채권자대위소송(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 법적성질과 요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 채권자가 스스로 원고가 되어 채무자의 권리를 행사 → 병행형 법정소송담당 / 당사자적격 요건: ① 피보전채권 ② 보전필요성 ③ 채무자권리불행사(흠결시 소각하) / 소송물은 ④ 피대위권리(흠결시 청구기각)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 피보전채권의 흠결</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">피보전채권 부존재시 당사자적격 없어 부적법<span class=\"cs-x\"><strong>(X)</strong></span> / <span class=\"cs-gbg\"><strong>[피보전채권 소멸시효 완성]</strong></span> 채무자가 시효항변하여 적법하게 완성되면 채권자는 더이상 대위할 권한 없음(X, 부적법) / <span class=\"cs-gbg\"><strong>[채무자 사망·실존인물 아님]</strong></span> 피대위자의 권리 자체가 인정 불가하므로 당사자적격 없음(X, 부적법)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 보전의 필요성의 흠결</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\"><strong>[피보전채권 패소확정]</strong></span> 동일청구 재차 불가로 보전필요성 없어 부적법 / <span class=\"cs-fact-tag\"><strong>[공동상속]</strong></span> 자기 지분 범위만 대위행사 가능, 초과부분은 보전필요성 없음 / <span class=\"cs-fact-tag\"><strong>[공유물분할청구권 대위]</strong></span> 책임재산 보전과 직접관련 없고 채무자의 자유로운 재산관리행위 부당간섭이 되어 보전필요성 부정</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 채무자의 권리행사</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\"><strong>[청구기각 확정후 대위]</strong></span> 이미 재판상 권리행사했다면 당사자적격 없어 부적법(청구기각판결이어도) / <span class=\"cs-fact-tag\"><strong>[비법인사단 소각하확정]</strong></span> 사원총회결의 없어 소각하된 경우는 채무자 권리행사로 볼 수 없음 / <span class=\"cs-fact-tag\"><strong>[소취하 vs 화해]</strong></span> 단순소취하는 권리행사 없는 것으로 보나, 소취하 전 상호양보로 화해한 경우는 권리행사로 볼 수 있어 이후 소취하해도 대위소송 당사자적격 흠결로 부적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>갈음형 - 제3자가 권리관계 주체에 갈음하여 소송수행권을 갖는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의 및 유형</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">파산재단에 관한 소송의 파산관재인, 유언에 관한 소송의 유언집행자(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§1101</strong></span></span>) 등</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>추심채권자의 당사자적격 유무와 법률관계(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 당사자적격 유무에 대한 판례의 입장</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">종래판례: 추심명령이 있으면 제3채무자에 대한 이행의 소는 추심채권자만 제기 가능, 채무자는 당사자적격 상실<span class=\"cs-x\"><strong>(X)</strong></span>(갈음형) ↔ 변경판례: 채무자는 추심명령이 있더라도 당사자적격 상실하지 않음<span class=\"cs-o\"><strong>(O)</strong></span>(갈음형 아님)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 근거</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 채무자가 이행의 소를 제기할 법적 근거 없음 ② 채무자 당사자적격 유지해도 추심채권자에게 부당한 결과 없음 ③ 제3채무자에게도 불리하지 않음(응소부담 최소화) ④ 당사자적격 상실을 인정하면 분쟁의 일회적 해결·소송경제에 반함 / 채무자는 시효중단·집행권원 확보 이익이 있어 이행의 소를 제기할 이익 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 추심채권자의 참가 가부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 채무자 이행소송에 대한 추심채권자 소송참가 방식: 종래판례는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§81</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§79</strong></span></span> 승계참가 가능했으나, 변경판례는 승계참가 요건 미충족 → <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§83</strong></span></span> 공동소송참가 또는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§78</strong></span></span> 공동소송적 보조참가 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 추심소송에 대한 채무자·다른 채권자의 참가 방식: 종래판례는 채무자 공동소송참가 불가하였으나, 변경판례에 의하면 당사자적격 유지되므로 공동소송참가도 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">다) 참가의 중복소제기 해당여부: 공동소송참가는 소제기 실질이므로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§259</strong></span></span> 중복소제기 문제될 수 있으나, 判例는 소송경제 도모+판결 모순저촉 유발가능성 없어 중복소제기에 해당하지 않는다고 봄</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 채무자가 받은 기판력이 추심채권자에게 미치는지 여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">변경판례: 채무자가 받은 확정판결의 효력은 추심채권자에게 미치고(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218③</strong></span></span>), 역으로 추심채권자가 받은 판결의 기판력도 채무자를 통해 다른 추심채권자에게 미침(변론종결 전후 불문)<span class=\"cs-o\"><strong>(O)</strong></span> → 근거: ⅰ) 추심채권자는 별도 소제기 필요 없이 채무자의 승소확정판결에 관한 승계집행문을 부여받아 곧바로 강제집행 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민사집행법§25</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§31</strong></span></span>) ⅱ) 채무자의 패소확정판결 효력까지 추심채권자에게 미쳐도 부당하다 볼 수 없음 ⅲ) 당사자적격이 상실된다면 추심채권자는 별도 소제기·승계참가해야 하므로 추심명령을 받은 채권자의 의사에도 배치될 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">5) 추심채권자의 별소제기가 중복소제기에 해당하는지 여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 채무자 이행소송 계속 중 추심채권자 별소제기: 변경판례는 실질적 동일사건이므로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§259</strong></span></span> 중복소제기에 해당하여 부적법, 추심채권자는 참가만 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 어느 추심채권자 소송계속 중 다른 추심채권자 별소제기: 마찬가지로 중복소제기에 해당하여 부적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">6) 상고심 조치</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">당사자적격 상실을 인정하면 상고심에서도 직권조사하여 소각하해야 하여 그동안의 소송이 무위로 돌아갈 수 있음 → 분쟁의 일회적 해결·소송경제에 현저히 반함(변경판례의 주요 근거)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">7) 보상금 증액 청구의 소에서 추심채권자의 당사자적격 상실 여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 손실보상금채권에 압류·추심명령이 있어도 토지소유자의 보상금증액청구 소송수행 당사자적격은 상실되지 않음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>전부명령과 당사자적격</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">전부채권자는 제3자 소송담당이 아니라 '자기 권리'를 행사하는 자 → 이행청구권자라고 주장하는 이상 원고적격 있어 소제기 자체는 적법하나, 실체법상 이행청구권 없으면 본안에서 청구기각</div><div class=\"cs-h\">Ⅵ. 임의적 소송담당(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의와 허용 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">권리관계의 주체가 자신의 의사로 제3자에게 소송수행권을 수여하는 경우 / 명문 인정례: 선정당사자(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§53</strong></span></span>), 추심위임배서의 피배서인(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>어음법§18</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>명문의 규정이 없는 경우 임의적 소송담당 허용 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>허용 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">원칙: ⅰ) 소송신탁금지 ⅱ) 변호사대리원칙 잠탈 염려로 법규정 없는 임의적 소송담당은 불허<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">예외: 그 염려 없고 허용할 합리적 이유(권리주체의 포괄적 관리처분권 수여 + 소송담당자의 고유이익) 있으면 허용<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>조합의 업무집행조합원</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 업무집행조합원에 대한 조합원의 임의적 소송신탁은 변호사대리원칙 회피·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>신탁법§7</strong></span></span> 잠탈이 아니라고 보아 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>관리단의 입주자대표회의에게의 임의적 소송담당</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 관리단이 입주자대표회의에 공용부분 변경업무를 포괄 위임한 경우 그 비용에 관한 재판상청구 권한도 수여한 것으로 볼 수 있고 합리적 필요성 인정 → 예외적 허용<span class=\"cs-o\"><strong>(O)</strong></span> ② 관리단이 위탁관리업자에게 관리비 부과·징수 재판상청구도 수여한 경우도 마찬가지로 허용되고 위탁관리업자에게 당사자적격 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅶ. 제3자의 소송담당과 기판력(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218③</strong></span></span>: 갈음형 소송담당자·직무상 당사자·임의적 소송담당은 소송담당자가 받은 판결의 기판력이 권리주체에게 미치나, 병행형인 채권자대위소송은 判例상 '채권자대위소송 제기 사실을 채무자가 알았을 경우'에만 기판력이 채무자에게 미침</div>", ["★★★★★"], 1, "mp_2"], ["민소008", "소송능력", "<div class=\"cs-h\">Ⅰ. 소송행위의 유효요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(1) <strong>소송무능력자의 소송행위·소송무능력자에 대한 소송행위의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">무효 → 법원은 이러한 소송행위를 배척해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(2) <strong>소송무능력자의 소송행위가 유효로 되는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">1) 추인</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소송무능력자의 소송행위·그에 대한 소송행위는 확정적 무효 아닌 '유동적 무효' → 법정대리인 추인시 그 행위시로 소급하여 확정적 유효</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">2) 일괄추인과 일부추인(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">원칙: 소송행위 전체 일괄추인, 선별적 일부추인 불허</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">예외: 判例 '소송의 혼란을 야기할 염려 없으면' 일부추인도 유효</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">3) 예외적 유효</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">민법상 원칙과 같이 ① 미성년자 혼인시 소송능력(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§826의2</strong></span></span>) ② 미성년자가 독립적으로 법률행위 가능한 범위(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§8</strong></span></span>) ③ 근로계약체결·임금청구(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>근로기준법§67</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span>) 범위에서는 소송능력 인정</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">4) 예외의 예외</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">민법상 미성년자·피한정후견인이 법정대리인 동의로 법률행위 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§5</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§10</strong></span></span>)하거나 처분허락 재산 임의처분 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§6</strong></span></span>)해도, 소송법상 소송능력은 인정 안 됨 → 이러한 소송행위는 무효, 법정대리에 의해야 함</div><div class=\"cs-h\">Ⅱ. 소송요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(1) <strong>흠결시 법원의 조치</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소송능력은 소송요건·직권조사사항 → 무능력자의 소제기는 소각하판결 / 단 추인의 여지 있어 보정 가능하면 보정명령을 해야 하며, 지연으로 손해의 염려 있는 때에는 보정을 조건으로 일시적인 소송행위를 할 수 있다(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§59</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(2) <strong>소송능력에 대하여 당사자 간에 다툼이 있는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">조사결과 능력이 없을 때에는 소각하할 것이지만, 그 능력이 긍정되는 경우에는 중간판결이나 종국판결의 이유에서 판단하면 된다 / 소송무능력자라 하더라도 그 능력의 존부가 기판력 있는 판결로 확정되기까지는 소송능력을 다투는 한도 내에서는 소송능력이 있는 것으로 취급되어, 유효하게 소송행위를 할 수 있다</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(3) <strong>소송무능력을 간과한 판결과 구제방법(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">1) 소송무능력자가 패소한 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소송무능력을 간과하고 소송무능력자에게 청구기각의 본안판결을 한 경우라도 그 판결은 당연무효<span class=\"cs-x\"><strong>(X)</strong></span>, 유효<span class=\"cs-o\"><strong>(O)</strong></span> → 패소한 소송무능력자는 확정 전에는 상소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§424①</strong></span></span>4호), 확정 후에는 재심의 소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>3호)로 위 판결을 취소할 수 있다</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">2) 소송무능력자가 승소한 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소송무능력자가 청구인용판결을 선고받은 경우, 패소한 상대방은 항소이유로 신의칙상 소송능력 흠결을 주장할 수 없고, 승소한 소송무능력자 역시 상소·재심으로 이를 취소할 이익이 없다</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(4) <strong>소송계속 중 소송능력의 상실의 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소 자체가 부적법해지는 것은 아니고 그 뒤의 소송행위만 개별적으로 무효가 된다 → 법정대리인이 수계할 때까지 소송절차가 중단되나(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§235</strong></span></span>), 소송대리인이 있는 경우에는 중단되지 않는다(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§238</strong></span></span>)</div>", ["★"], 1, "mp_2"], ["민소009", "소송상의 대리인", "<div class=\"cs-h\">Ⅰ. 법정대리인</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송무능력자를 위한 특별대리인</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의 및 선임신청 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">법정대리인 없거나 대리권 행사 불가시 법원이 선임하는 소송상 대리인, 무능력자 보호 및 소송지연방지 목적 / <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§62①</strong></span></span> 각호 사유로 절차지연 손해 우려 소명하여 신청 / 判例: 신청 수소법원은 본안사건이 장래 계속될 또는 이미 계속된 법원을 의미</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>선임효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">특별대리인은 대리권 있는 후견인과 같은 권한, 그 범위에서 법정대리인 권한은 정지(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§62③</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법정대리권의 소멸</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>법정대리권의 소멸통지(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 원칙</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">소송진행 중 법정대리권 소멸시 본인·대리인이 상대방에게 그 소멸사실을 통지해야 대리권소멸 효과 주장 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§63①</strong></span></span>본문) → 통지 없으면 악의·과실 불문하고 구 대리인의 소송행위를 유효로 본다</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 예외</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">배신적 소취하 등으로 인한 본인의 손해 방지 위해 법원에 소멸사실이 알려진 뒤에는 통지되기 전이라도 구 대리인의 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§56②</strong></span></span> 행위(소·상소취하, 화해, 청구의 포기·인낙, 소송탈퇴 등)는 할 수 없도록 규정(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§63①</strong></span></span>단서)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 적용범위</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§63</strong></span></span>는 법인 또는 비법인사단의 대표자(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§64</strong></span></span>), 임의대리인(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§97</strong></span></span>), 선정당사자를 바꾸는 경우(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§63②</strong></span></span>)에 준용된다(준용규정을 반드시 적시할 것)</div><div class=\"cs-h\">Ⅱ. 임의대리인</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송위임에 의한 소송대리인의 대리권 범위(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>소송대리권의 법정범위 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§90①</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">'일체의 소송행위'를 할 수 있으며, '일체의 사법행위'를 할 수 있다 / 단 '재판 외 행위'는 대리할 수 없으므로 재판 외에서 화해계약은 대리권 범위에 포함되지 않는다</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>소송대리권의 제한 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§91</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소송대리인이 변호사인 경우 권한을 제한할 수 없다 / 본인과 대리인 사이에 대리권의 제한이 있거나 대리인의 행위가 본인의 의사에 반하는 경우라도, 이는 기초적 내부관계에서 손해배상책임이 성립함은 별론, 소송법상의 효력에는 영향이 없다</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>특별수권 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§90②</strong></span></span><strong>3호 (상소의 제기 또는 취하)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 심급대리의 원칙(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ① 소송대리권의 범위는 당해 심급에 한정되며 당해 심급의 판결을 송달받을 때까지 ② '상소제기의 특별수권이 있는 경우'에는 판결정본이 송달되어도 소송대리권 존속, 상소제기시 소멸</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 대리권 부활(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ① 상고심 파기환송판결 선고시 환송 전 항소심 소송대리인의 대리권 부활 긍정 → 환송 후 항소심 사무까지 처리해야 위임사무 종료에 따른 보수 청구 가능 ② 재상고한 경우에는 환송 전 상고심 대리인의 대리권 부활 부정 ③ 재심 전 소송대리인이 당연히 재심소송의 대리인이 되는 것은 아님</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 소송대리인의 상소장 보정권한과 보정명령 송달의 효력(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ① 특별수권 있으면 상소장 제출 권한·의무 있으므로 인지 흠결은 소송대리인이 보정 가능하고 재판장도 보정명령 가능 ② 소송대리인에게 보정명령이 송달되면 피고에게 송달효력 발생, 실제 전달여부는 영향 없음 → 보정기간 내 미보정을 이유로 한 제1심 항소장각하명령은 적법 ③ <span class=\"cs-fact-tag\"><strong>[당사자 본인이 직접 상고장 제출]</strong></span> 소송대리인은 보정명령 수령권능 없으므로 원심재판장의 소송대리인에 대한 송달은 부적법하여 효력 없음 → 보정기간이 진행되지 않았음에도 이를 이유로 한 상고장 각하명령은 위법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>당사자의 경정권 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§94</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">경정 대상은 '사실상의 진술'에 한함(신청, 소취하, 화해, 청구의 포기·인낙 등 소송물 처분행위, 법률상의 진술은 제외) / 본인이 소송대리인과 함께 출석하여 지체없이 취소·경정해야 함 → 경정권 행사시 대리인의 사실상 진술은 효력상실되고 본인 진술만 판결기초가 됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>수인의 소송대리인 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§93</strong></span></span><strong>(각자대리)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 여러 소송대리인은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§93</strong></span></span>에 의해 각자가 당사자를 대리 → 1인 송달원칙을 규정한 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§180</strong></span></span>가 적용될 여지가 없어 법원은 각각 송달해야 하지만, 판결정본송달의 효력은 여러 소송대리인 중 1인에게 최초로 송달되었을 때 발생 ② 당사자와 그 소송대리인 모두에게 송달된 경우 먼저 도달한 것 기준으로 송달효력을 따져야 함(당사자 본인이 먼저 받았다면 본인 기준)</div><div class=\"cs-h\">Ⅲ. 무권대리인</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>대리권의 소송상 취급 - 소송행위의 유효요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">대리권 존재는 유효요건, 무권대리인에 의한(대한) 소송행위는 유동적 무효 → 추인시 행위시에 소급하여 확정적 유효, 추인거절시 확정적 무효(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§97</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§60</strong></span></span>) / 추인은 명시·묵시적으로 가능, 시기 제한 없어 상급심에서도 하급심 무권대리행위 추인 가능, 원칙 일괄추인해야 하나 判例상 소송혼란 염려 없고 소송경제상 적절하다고 인정될 때에는 예외적 일부추인 허용 / 判例: 대표자격 없는 비법인사단 대표자의 소송행위는 후에 적법 자격 취득한 대표자가 추인하면 행위시 소급하여 효력, 상고심에서도 추인 가능 / 判例: <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§59</strong></span></span> 전단·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§60</strong></span></span>에 의해 법정대리권 흠결시 법원은 보정을 명해야 할 의무 있고, 항소심에서도 보정 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§64</strong></span></span>에 의해 법인 대표자에도 준용)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>쌍방대리의 금지(★) - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>변호사법§31</strong></span></span><strong>에 위반된 소송행위의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">쌍방대리란 당사자 한쪽이 상대방을 대리하거나 같은 사람이 당사자 양쪽의 대리인을 겸하는 것 → <span class=\"cs-blue\"><span class=\"cs-u\"><strong>변호사법§31</strong></span></span>에서 금지 / 判例(이의설): 상대방 당사자가 법원에 이의를 제기하면 그 소송행위는 무효이지만, 알았거나 알 수 있었음에도 사실심 변론종결시까지 이의를 제기하지 아니하였다면 그 소송행위는 소송법상 완전한 효력이 생긴다(이의는 사실심 변론종결시까지 가능, '상고심'에서는 불가) / 判例: <span class=\"cs-blue\"><span class=\"cs-u\"><strong>변호사법§31</strong></span></span>은 법무법인에도 준용되며, 같은 쟁점 민형사건에서 형사사건의 피해자 측에 해당하는 상대방 당사자를 위한 소송대리인 직무 수행도 금지, 위 법무법인이 해산된 이후라도 변호사 개인 지위에서 민사사건 수임 역시 금지 → <span class=\"cs-fact-tag\"><strong>[민사사건 담당 변호사가 앞선 형사사건에서 피고인을 위한 직접 변론에 관여한 바 없어도]</strong></span> <span class=\"cs-blue\"><span class=\"cs-u\"><strong>변호사법§31①</strong></span></span>1호 수임제한규정 위반<span class=\"cs-o\"><strong>(O)</strong></span> / 判例: 법률사무소는 하나의 변호사로 취급되므로, 그 소속 변호사들이 상대방 관계의 당사자 쌍방으로부터 각자 수임한 경우도 쌍방대리로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>변호사법§31①</strong></span></span>1호에 따라 원칙적 수임제한, 위반시 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§124</strong></span></span>가 적용되어 원칙적으로 허용되지 않는 무권대리행위에 해당하고 예외적으로 본인의 허락이 있는 경우에 한하여 효력이 인정될 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>표현대리의 법리 유추적용 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">민사소송법에 표현대리 규정이 없어 소송행위에 민법상 표현대리를 유추적용할 수 있는지 문제 / 判例: ⅰ) 소송법상 근거규정이 없고 ⅱ) 거래안전을 위한 민법상 표현대리 법리는 절차의 안정을 중요시하는 소송행위에 적용될 수 없다는 점을 들어 부정<span class=\"cs-x\"><strong>(X)</strong></span> / 단, 법인의 고의·태만으로 부실등기가 된 경우라면 적어도 묵시적 추인이 되므로 무권대리의 하자가 치유될 수 있음 / <span class=\"cs-gbg\"><strong>[상대방의 대표권 흠을 재심사유로 할 수 있는지]</strong></span> 判例: <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>3호는 대리권 흠 있는 쪽 당사자 보호를 위한 제도이므로, 그 상대방이 재심사유로 삼으려면 '그러한 사유를 주장함으로써 이익을 받을 수 있는 경우'로 제한됨</div>", ["★★"], 1, "mp_2"], ["민소010", "소의 의의와 종류", "<div class=\"cs-h\">Ⅰ. 공유물분할청구의 소</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공유물의 분할방법에 관하여 공유자 간에 협의가 성립되지 아니한 때 판결에 의한 분할을 청구하는 소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§269①</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법적성질</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">성질은 비송사건이나 형식상 민사소송의 형태로 처리하는 형식적 형성의 소</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>처분권주의 적용 여부와 법원의 심판방법(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 형식적 형성의 소이므로 법원은 당사자 주장내용에 구속받지 않고 재량대로 판단 → ① 처분권주의 배제 ② 불이익변경금지원칙도 적용 안 됨 ③ 어떤 형식으로라도 법률관계를 형성해야 하므로 원고 청구를 기각할 수 없음 → 분할방법에 대한 당사자 신청은 법원을 구속하지 못하고, 원고가 현물분할을 청구해도 법원은 청구취지 변경 없이 경매분할을 명하는 판결 가능</div><div class=\"cs-h\">Ⅱ. 경계확정의 소</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의 및 필요성</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">서로 인접한 토지들 간에 경계가 불분명한 경우 법원의 판결에 의하여 그 경계선을 확정해 줄 것을 청구하는 소송</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법적성질</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 경계확정의 소의 본질은 비송사건에 속하나 형식상 민사소송의 형태로 처리되는 형식적 형성의 소</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>처분권주의 적용 여부와 법원의 심판방법(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 경계확정소송은 본질이 비송사건이므로 ① 처분권주의 적용 안 되어 법원은 당사자가 주장하는 경계선에 구속되지 않고 ② 불이익변경금지원칙 적용 안 되어 항소심법원이 제1심판결이 정한 경계선보다 항소인에게 불리하게 경계를 설정해도 되며 ③ 원고가 주장하는 경계선보다 유리한 판단을 해야 할 경우에도 청구기각판결을 해서는 안 되고 경계설정의 필요가 인정되는 한 청구변경 없이도 본안판결로서 경계를 설정해야 함 → 결국 법원은 당사자 쌍방이 주장하는 경계선에 구속되지 않고 스스로 진실하다고 인정되는 바에 따라 경계를 확정해야 하며, 특별한 사정이 없는 한 원고 주장 경계가 인정되지 않더라도 청구의 전부·일부를 기각할 수 없음</div>", ["★"], 1, "mp_3"], ["민소011", "소송요건", "<div class=\"cs-h\">Ⅰ. 소송요건의 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">소송요건이란 '소가 적법한 취급을 받기 위해 구비해야 할 사항'으로서 '본안심리와 본안판결의 전제요건'(소송성립요건·소송행위의 유효요건과는 구별) → 흠결시 소가 부적법<span class=\"cs-x\"><strong>(X)</strong></span> → 법원은 판결로 소를 각하</div><div class=\"cs-h\">Ⅱ. 직권조사사항의 심판대상 결정(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법원의 심판대상 결정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소송요건 중 항변사항을 제외한 나머지는 법원의 직권조사사항<span class=\"cs-o\"><strong>(O)</strong></span> → 피고의 항변 유무와 무관하게 의문 있으면 직권조사의무, 소송절차에 관한 이의권 포기<span class=\"cs-x\"><strong>(X)</strong></span>, 피고의 항변은 직권발동촉구에 불과</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>判例의 입장</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[종중 대표자의 적법한 대표권 유무]</strong></span>는 소송요건·직권조사사항<span class=\"cs-o\"><strong>(O)</strong></span> → 법원이 사실·증거를 스스로 탐지할 의무까지는 없으나<span class=\"cs-x\"><strong>(X)</strong></span>, 제출된 자료상 의심 갈만한 사정이 보이면 상대방이 구체적으로 다투지 않아도 심리·조사할 의무<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[채권자대위소송의 피보전채권 존부]</strong></span>도 소송요건<span class=\"cs-o\"><strong>(O)</strong></span> → 법원에 현출된 모든 소송자료를 통해 의심할 사정이 발견되면 직권으로 추가 심리·조사할 의무<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[손해배상액 산정시 피해자 과실]</strong></span>은 당사자가 주장하지 않아도 소송자료로 인정되면 직권조사사항으로 심리·판단<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅲ. 직권조사사항의 사실·증거자료 수집방식(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例: 직권조사(Prüfung) 방식</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 법원은 당사자가 제출한 사실만 고려 가능, 스스로 탐지<span class=\"cs-x\"><strong>(X)</strong></span>(사실의 주장책임 인정)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">② 당사자 간 다툼 없는 사실도 법원을 구속하지 못함 → 의심 있으면 자백된 사실도 증거조사 가능(자백의 구속력 부정)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">③ 다툼 있는 사실 인정은 원칙적으로 당사자가 제출한 증거에 의함, 법률상 허용범위 내에서만 직권증거조사<span class=\"cs-o\"><strong>(O)</strong></span>(증거제출책임 인정)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">④ 직권조사사항의 존재를 지적하는 진술은 법원의 직권조사를 촉구하는 의미에 불과 → 다른 공격방어방법과 달리 제출시기 제한<span class=\"cs-x\"><strong>(X)</strong></span>(적시제출주의 적용 부정)</div><div class=\"cs-h\">Ⅳ. 소송요건 존재의 판단시기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① 소송요건의 존부는 '사실심 변론종결시' 기준 → 제소당시 부존재해도 변론종결시까지 구비하면 됨<span class=\"cs-o\"><strong>(O)</strong></span>, 반대로 제소당시 구비되어도 그 뒤 소멸하면 소각하</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">② 단, ⅰ) 관할권의 존부는 '소제기시'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§33</strong></span></span>) 기준 ↔ ⅱ) 소송계속 중 당사자능력·소송능력 상실, 법정대리권 소멸은 소각하사유<span class=\"cs-x\"><strong>(X)</strong></span> → 소송중단사유<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">③ 소송요건은 직권조사사항 → 당사자 주장 여부와 무관하게 법원이 직권판단, 사실심 변론종결 후 흠결·치유가 있어도 상고심에서 참작</div><div class=\"cs-h\">Ⅴ. 소송요건조사와 본안판결의 순서(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例: 소송요건은 본안판결의 요건이므로 본안판결에 앞서 미리 조사해야 함 → 소송요건 존부를 남겨둔 채 먼저 청구기각판결<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">소송요건 존부 불명한 경우 청구가 이유 없음이 명백해도 청구기각의 본안판결<span class=\"cs-x\"><strong>(X)</strong></span>, 소각하판결과 청구기각판결 모두 해야 할 것으로 판단되면 '소송요건의 선순위성'에 의해 소각하판결(본안판결요건설, 소송요건심리의 선순위성 긍정설)</div>", ["★"], 1, "mp_3"], ["민소012", "모든 소에 공통적인 권리보호이익", "<div class=\"cs-h\">Ⅰ. 청구가 소구할 수 있는 구체적인 권리·법률관계일 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">소로써 구할 수 없는 청구는 권리보호자격<span class=\"cs-x\"><strong>(X)</strong></span>, 단순한 사실관계의 존부 다툼도 권리보호자격<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-neg-tag\"><strong>[토지대장에 진실한 소유권자 아닌 자 명의가 등재된 경우]</strong></span> 대장상 명의말소청구는 소의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span> → 토지대장은 사실관계를 공시하는 장부에 불과, 부동산등기부와 달리 권리관계를 공시하지 않으므로 사실 존부의 다툼에 불과</div><div class=\"cs-h\">Ⅱ. 법률상·계약상 소제기 금지사유가 없을 것(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(법률상 금지사유) 중복소제기금지(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§259</strong></span></span>), 재소금지(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§267②</strong></span></span>) 등</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(계약상 금지사유) 부제소특약 위반 제소, 소취하합의 위반 제소, 부제소합의 있는 채권을 피보전권리로 한 사해행위취소청구 등</div><div class=\"cs-h\">Ⅲ. 제소장애사유가 없을 것(★) - 특별구제절차가 없을 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">법률이 소가 아닌 간이·경제적인 특별구제절차를 마련해 둔 경우에 소를 제기하면 권리보호자격<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">예: <span class=\"cs-fact-tag\"><strong>[비송사건절차법에 의할 것을 통상의 소로 제기한 임시이사선임취소의 소]</strong></span>, <span class=\"cs-fact-tag\"><strong>[등기관 직권말소사항인 부기등기의 말소등기의 소]</strong></span>, <span class=\"cs-fact-tag\"><strong>[상소로 다투지 않고 확정시켜 놓고 별도 소제기하는 것]</strong></span> 등</div><div class=\"cs-h\">Ⅳ. 원고가 동일청구에 대해 승소확정의 판결을 받은 경우가 아닐 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">모순금지설 입장: ① 승소확정판결을 받은 자가 동일한 소를 제기하면 권리보호이익 없어 소송요건으로 소각하<span class=\"cs-o\"><strong>(O)</strong></span> ↔ ② 패소확정판결을 받은 자가 동일한 소를 제기하면 전소와 모순된 판단을 할 수 없다고 보아 소송요건이 아니라 청구기각판결<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅴ. 신의칙 위반의 제소가 아닐 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">신의성실의 원칙에 위반한 소제기는 권리보호자격<span class=\"cs-x\"><strong>(X)</strong></span></div>", ["★"], 1, "mp_3"], ["민소013", "개별적인 소의 권리보호의 이익", "<div class=\"cs-h\">Ⅰ. 이행의 소</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>현재이행의 소</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>강제집행이 불가능하거나 현저히 곤란한 경우 (소의 이익 긍정)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 이행판결을 받더라도 집행불능인 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">채무자 무자력이어도 소의 이익 인정<span class=\"cs-o\"><strong>(O)</strong></span> — 判例: ⅰ) 판결절차는 '관념적 분쟁해결절차' ⅱ) 집행권원 보유는 '피고에게 심리적 압박' → 이행판결을 받아도 집행이 사실상 불가능·현저히 곤란하다는 사정만으로는 이익 부정<span class=\"cs-x\"><strong>(X)</strong></span> / <span class=\"cs-fact-tag\"><strong>[제3자를 위한 계약에서 낙약자가 요약자의 이행청구에 불응하는 경우]</strong></span> 요약자는 낙약자에게 제3자에게 급부할 것을 소구할 이익 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 최종등기명의인에 대한 패소확정 후 중간명의자에 대한 등기말소청구(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\"><strong>[순차 등기된 부동산에서 최후 등기명의자 상대 말소등기청구가 패소확정된 후, 중간명의자 상대로 다시 말소등기청구]</strong></span> 전순위등기 말소가 사실상 불가능해졌더라도 그 말소를 구할 소의 이익 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 가압류된 금전채권(★) - 소의 이익 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">(적법) 가압류는 채무자의 추심만 금지할 뿐 → 채무자는 제3채무자 상대 이행청구소송 제기 가능<span class=\"cs-o\"><strong>(O)</strong></span>, 법원도 가압류를 이유로 배척<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">(본안) 청구 이유 있으면 전부청구인용판결<span class=\"cs-o\"><strong>(O)</strong></span> — 집행단계에서 이를 저지하면 되기 때문</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 가압류·가처분된 소유권이전등기청구권(★) - 가압류 해제조건부 이행청구 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">(적법) 금전채권과 달리 이행을 구하는 소제기 가능<span class=\"cs-o\"><strong>(O)</strong></span> / (본안) 이전등기판결 확정시 채무자가 일방적으로 이전등기 신청 가능하고 제3채무자는 이를 저지할 방법 없음 → 법원은 전부청구인용판결<span class=\"cs-x\"><strong>(X)</strong></span>, 가압류 해제를 조건으로 한 인용판결<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">5) 소유권이전등기청구권이 가압류된 경우 채무자의 이행의 소에 대한 제3채무자의 응소의무(★) - 긍정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">이전등기판결 확정시 채무자가 일방적으로 이전할 수 있으므로, 응소하여 가압류된 사실을 주장·입증해야 할 의무<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">6) 소유권이전등기청구권 가압류 사실이 직권조사사항인지 여부(★) - 부정<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">피고의 항변사유에 해당 → 소장에 가압류사실이 기재되어도 이는 선행자백에 불과하여 피고가 응소해 원용해야 비로소 고려<span class=\"cs-o\"><strong>(O)</strong></span> → 피고 불응소시 전부승소판결<span class=\"cs-o\"><strong>(O)</strong></span>, 가압류 해제조건부 판결<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>목적이 실현된 청구 - 권리보호이익이 없다</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-gbg\"><strong>[소유권이전등기청구소송 중 다른 원인으로 원고 앞으로 이전된 경우]</strong></span>, <span class=\"cs-gbg\"><strong>[근저당권설정등기 말소청구소송 중 경락으로 그 등기가 말소된 경우]</strong></span> 권리보호이익 부정<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">단, <span class=\"cs-fact-tag\"><strong>[사해행위인 근저당설정계약에 기해 설정된 등기가 경락으로 말소된 경우]</strong></span>는 수익자가 배당받는 것이 부당하므로 채권자는 근저당권설정계약의 취소를 구할 이익 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>실익이 없는 청구 - 부기등기말소의 소</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(원칙) 근저당권 이전의 부기등기는 주등기(근저당권설정등기) 말소만 구하면 되고 부기등기는 주등기 말소에 따라 직권말소<span class=\"cs-o\"><strong>(O)</strong></span> → 분리 청구는 실익 없어 각하<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(예외) 근저당권 이전원인만 무효·취소·해제된 경우(주등기 자체는 유효 전제) → 부기등기만의 말소를 소구할 필요 있어 예외적으로 소의 이익<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>장래이행의 소(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>적법요건 - 청구적격 + 미리 청구할 필요</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(청구적격) ⅰ) 청구기초가 되는 사실상·법률상 관계가 변론종결시에 존재 ⅱ) 의무불이행사유가 장래 이행기까지 존속함을 변론종결 당시 확정적으로 예정할 수 있을 것 → 흠결시 부적법 소각하<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(미리 청구할 필요) 채무자의 임의이행을 기대할 수 없는 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-gbg\"><strong>[쌍무계약에서 이행기 미도래 상태에 선제적 집행권원 확보는 계약상 권리 침해 우려]</strong></span> → 화해권고 요청 불응 사정만으로는 미리 청구할 필요 인정<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>조건부·기한부 청구권</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">청구기초관계 성립 + 변론종결 후 청구권 발생이 확정적으로 예정되면 청구적격 인정<span class=\"cs-o\"><strong>(O)</strong></span> / 이행기 도래·조건성취 전 의무자가 미리 다투면 즉시 이행 기대 불가로 미리 청구할 필요 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(긍정예) <span class=\"cs-fact-tag\"><strong>[학교법인이 감독청 허가 없이 기본재산인 부동산 매매계약을 체결한 후 매수인이 허가를 조건으로 한 소유권이전등기청구]</strong></span> 청구적격<span class=\"cs-o\"><strong>(O)</strong></span> ↔ (부정예) <span class=\"cs-neg-tag\"><strong>[토지거래허가구역 내 매매계약에서 허가를 조건으로 한 소유권이전등기청구]</strong></span> 허가 전에는 아무런 효력이 없어 이행청구 자체 불가, 청구적격<span class=\"cs-x\"><strong>(X)</strong></span> → 소각하</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>선이행청구(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(청구적격) 조건성취의 개연성이 커서 조건부 청구로서 인정<span class=\"cs-o\"><strong>(O)</strong></span> / (미리청필) 원칙 부정<span class=\"cs-x\"><strong>(X)</strong></span>, 단 저당권·양도담보에서 채권자가 피담보채무액을 다투거나 담보목적 아님을 다투어 채무자가 변제해도 즉시 등기말소 협력을 기대할 수 없으면 미리청필 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>장래의 부당이득반환청구(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 판례의 태도 - 장래의 계속적 불법행위·부당이득도 청구적격<span class=\"cs-o\"><strong>(O)</strong></span> 인정, 이미 이행기 도래분을 불이행한 이상 장래분도 자진이행 기대 불가로 미리청필<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 사인 간의 무단점유로 인한 장래부당이득반환청구(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\"><strong>[무단점유 토지의 점유시부터 인도시까지 차임 상당액 부당이득반환청구]</strong></span> (변론종결 후 장래분) 청구적격·미리청필 모두 인정<span class=\"cs-o\"><strong>(O)</strong></span> → 적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 임대차 종료 후의 점유로 인한 장래부당이득반환청구(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">(적법점유) <span class=\"cs-neg-tag\"><strong>[동시이행항변하며 적법하게 점유중인 경우]</strong></span> 인도하는 날까지 의무불이행 사유 존속을 확정적으로 예정할 수 없음 → 청구적격<span class=\"cs-x\"><strong>(X)</strong></span> 부적법('사용·수익 중지시까지'로 청구해야 적법) ↔ (불법점유) <span class=\"cs-fact-tag\"><strong>[조정성립 후 임차인이 제3자에게 열쇠를 건네 불법점유케 한 경우]</strong></span> 점유 자체가 위법점유가 되어 인도시까지 확정적 예정 → 청구적격<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 국가 또는 시의 무단점유로 인한 장래부당이득반환청구(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">(적법) <span class=\"cs-fact-tag\"><strong>[도로폐쇄에 의한 점유종료일 또는 소유권상실일까지 둘 모두를 종기로]</strong></span> 청구하면 의무불이행 사유 존속을 확정적으로 예정 가능<span class=\"cs-o\"><strong>(O)</strong></span> ↔ (부적법) <span class=\"cs-neg-tag\"><strong>[점유종료일 또는 소유권상실일 둘 중 하나만을 종기로]</strong></span> 청구하면 그 전에 점유종료·소유권상실이 가능하므로 확정적 예정 불가<span class=\"cs-x\"><strong>(X)</strong></span> 부적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">5) 국가·시의 도로 무단사용시 '원고의 소유권 상실일까지' 기재의 필요 여부 - 불요<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">이러한 기재는 이행판결 주문표시로 바람직하지 않음(소유권 변동여부를 수소법원이 아닌 다른 기관의 판단에 맡기는 형태이고, 확정된 이행판결의 집행력에 영향 없는 무의미한 기재) → 점유시부터 점유종료일까지만 기재해도 적법<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 확인의 소</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>대상적격(권리보호자격) - 자기·현재의 권리법률관계일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>원피고 당사자 간의 권리법률관계일 것 - 자기의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">원칙 자기의 권리관계만 대상적격<span class=\"cs-o\"><strong>(O)</strong></span> → 예외적으로 타인 간 권리관계 확인이 자기 권리관계 불안·위험 제거의 유효·적절한 수단이 되는 경우 확인의 이익<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[매도인 명의이나 미등기 상태에서 제3자가 매도인의 소유권을 다투는 경우]</strong></span> 매수인은 매도인을 대위하여 제3자 상대 소유권확인의 소 제기 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[물상보증인이 근저당권자의 채권을 다투는 경우]</strong></span> 근저당권자가 물상보증인 상대 피담보채권 존부확인의 소 제기 가능, 확인의 이익 있어 적법<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>현재의 권리법률관계일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 판례의 입장</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">원칙 과거의 권리관계 존부확인은 대상적격<span class=\"cs-x\"><strong>(X)</strong></span> ↔ 예외적으로 과거 권리관계라도 ⅰ) 현재의 권리관계에 영향을 미치고 ⅱ) 현재의 권리관계에 대한 위험을 제거하기 위해 ⅲ) 확인판결이 유효·적절한 수단이라고 인정될 때에는 확인의 이익<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 매매계약무효확인(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">과거의 법률행위인 매매계약무효 확인을 구하는 것으로 볼 것이 아니라, 현재 매매계약에 기한 채권·채무가 존재하지 않는다는 확인을 구하는 취지로 선해하여 확인의 이익 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 과거 포괄적 법률관계 확인(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">신분·단체·행정소송관계처럼 포괄적 법률관계인 경우 과거의 권리관계라도 분쟁의 일거해결에 유효·적절하면 확인의 이익<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">(신분관계) <span class=\"cs-neg-tag\"><strong>[이혼으로 해소된 혼인관계의 과거 무효확인]</strong></span> 종래 확인의 이익 부정<span class=\"cs-x\"><strong>(X)</strong></span> ↔ 변경판례: 신분관계는 그것을 전제로 수많은 법률관계가 형성되므로 과거의 법률관계 자체의 무효확인이 분쟁을 한꺼번에 해결하는 수단이 될 수 있어 확인의 이익 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">(회사관계) 법원은 확인의 대상이 과거의 법률관계라는 이유만으로 곧바로 각하<span class=\"cs-x\"><strong>(X)</strong></span>할 것이 아니라 청구취지 변경 기회를 주어야 함 / <span class=\"cs-fact-tag\"><strong>[감사 임용계약 체결거부에 대해 감사 지위확인을 구한 경우]</strong></span> 파생되는 법률관계가 여러개면 확인의 이익 인정<span class=\"cs-o\"><strong>(O)</strong></span> ↔ <span class=\"cs-neg-tag\"><strong>[임기만료 이사의 과거 재직기간 확인]</strong></span> 파생법률관계가 임금청구권 1개뿐이면 확인의 이익 부정<span class=\"cs-x\"><strong>(X)</strong></span> — 과거 법률관계 확인이익은 파생되는 법률관계가 '2개 이상'이어야 인정</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">(행정관계) <span class=\"cs-fact-tag\"><strong>[정학 징계 후 졸업한 학생의 징계 무효확인]</strong></span> 학교생활기록부 기재와 밀접 관련된 현재의 위험 제거를 위해 확인의 이익 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>권리법률관계의 확인을 구할 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">원칙 권리·법률관계의 확인을 구해야 함 / 예외적으로 증서진부확인은 사실관계이지만 법이 인정(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§250</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-gbg\"><strong>[담보지상권의 피담보채무 범위 확인을 구하는 청구]</strong></span> 담보지상권은 피담보채무가 존재하는 것이 아니므로, 이는 권리·법률상 지위에 관한 청구로 보기 어려워 확인의 이익 부정<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>확인의 이익 - 권리보호이익</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>'법률상 이익'일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 원칙: 반사적으로 받게 될 사실상·경제상 이익은 확인의 이익 부정<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 유치권부존재확인의 소의 확인의 이익(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">(법률상 이익 O) <span class=\"cs-fact-tag\"><strong>[근저당권자가 유치권자 상대 유치권부존재확인]</strong></span> 경매절차에서 저가낙찰로 인한 배당액 감소 위험은 사실상·경제상 이익이 아닌 법률상 이익<span class=\"cs-o\"><strong>(O)</strong></span> → 확인의 이익 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">(일부 부존재확인과 일부패소판결 가부) 유치권 전부뿐 아니라 일부 부존재확인도 구할 법률상 이익 있음<span class=\"cs-o\"><strong>(O)</strong></span>, 피담보채권 일부만 유치권으로 대항되면 처분권주의에 의해 근저당권자의 일부패소판결을 해야 함<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">(저당권 소멸시 확인의 소 적부) 경매절차에서 유치권이 주장되었으나 매각·근저당권이 소멸하면 소유자·근저당권자 모두 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span> ↔ 유치권 미주장 상태에서 경매로 근저당권이 소멸하면 근저당권자는 매수인의 담보책임 추급 우려로 확인의 이익<span class=\"cs-o\"><strong>(O)</strong></span>, 채무자 아닌 소유자는 담보책임 부담<span class=\"cs-x\"><strong>(X)</strong></span>하므로 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>현존하는 불안·위험이 있을 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 원칙: (적극적 확인의 소) 자기 지위가 타인으로부터 부인되거나 양립되지 않는 주장을 당하는 경우, (소극적 확인의 소) 타인에게 지위가 없는데도 있다고 주장하는 경우 → 현존하는 불안 인정<span class=\"cs-o\"><strong>(O)</strong></span> / 당사자 간 다툼 없으면 원칙적 확인의 이익<span class=\"cs-x\"><strong>(X)</strong></span>, 단 주장하는 법률요건이 다르면 다툼이 있다고 볼 수 있어 확인의 이익 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 국가 상대 소유권확인의 소의 확인의 이익(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 미등기 토지: (국가와 다툼 있는 경우) 확인의 이익 당연히 인정<span class=\"cs-o\"><strong>(O)</strong></span> / (다툼 없는 경우) 등록명의자 없는 미등기 토지는 보존등기를 위한 소유권 증명 목적상 다툼 없어도 확인의 이익<span class=\"cs-o\"><strong>(O)</strong></span> / (점유취득시효가 완성된 경우) 국가가 미등기 토지를 점유시효취득한 경우 소유자는 국가에게 이전등기의무를 부담하는 지위이므로 소유권확인판결을 받아도 지위 변동 없어 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 제3자 명의로 등기등록된 경우: 제3자에 대한 승소판결만으로 자기 명의 보존등기 신청 가능 → 이와 병합한 국가상대 소유권확인청구는 유효적절한 수단 아님 → 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 보험관련 분쟁을 대상으로 한 확인의 소</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) <span class=\"cs-fact-tag\"><strong>[보험회사가 보험수익자 상대 소극적 확인의 소]</strong></span> 확인의 이익 인정<span class=\"cs-o\"><strong>(O)</strong></span>: 보험계약자는 제한 없이 이행의 소를 제기할 수 있는데 보험회사만 제한되면 형평에 반함</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) <span class=\"cs-fact-tag\"><strong>[보증보험 보험계약자가 피보험자 상대 소극적 확인의 소]</strong></span> 확인의 이익 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 주식회사가 체결한 계약의 무효 확인을 구할 이익이 있는지 여부 - 원칙 소극<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) <span class=\"cs-gbg\"><strong>[주주가 회사·제3자 간 거래의 계약무효확인]</strong></span> 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span>(영업양도계약도 동일)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) <span class=\"cs-fact-tag\"><strong>[주식회사 채권자가 회사의 계약으로 변제자력 감소된 경우]</strong></span> 계약이 채권자의 권리·법적 지위를 구체적·직접적으로 침해하면 확인의 이익 있음<span class=\"cs-o\"><strong>(O)</strong></span> ↔ 변제자력 감소로 채권 만족 불가능해지는 데 그칠 뿐이면 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">5) 주식회사의 주주권 확인의 소의 확인의 이익 유무</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) <span class=\"cs-neg-tag\"><strong>[주주명부상 주주라는 이유만으로 확인의 이익 부정 가부]</strong></span> 부정<span class=\"cs-x\"><strong>(X)</strong></span>: 회사가 주주권 귀속을 부인할 가능성이 없다고 단정할 수 없음 → 명의개서 거부 태세 등을 종합해 확인의 이익 판단<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) <span class=\"cs-fact-tag\"><strong>[주식공유자 중 일부가 명의개서를 원하지 않아 공유자전원 명의개서 청구 불가능]</strong></span> 공유자 일부의 주주권 확인의 이익<span class=\"cs-o\"><strong>(O)</strong></span>(단독 취득자는 직접 명의개서 청구 가능하므로 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>불안제거에 가장 유효적절한 수단일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 적극적 확인의 소(★) - 자기 소유권존재확인의 소를 제기할 수 있는데 상대방 소유권부존재확인을 구하는 것은 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span>. 독립당사자참가인도 원고 상대 권리부존재확인은 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 당해 소송에서 구제수단(★) - 대리권 같은 소송요건의 존부, 소취하의 무효 등 소송상 다툼은 당해 소송에서 구제받으면 되므로 별소로 구하면 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 확인의 소의 보충성(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 원칙: 이행의 소를 바로 제기할 수 있음에도 이행청구권 자체의 존재확인을 구하는 것은 분쟁의 근본적 해결방법이 아니므로 원칙적으로 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span>(확인판결은 집행력 없음) / <span class=\"cs-gbg\"><strong>[후순위 진정채권자가 가장임차인 상대 배당금지급청구권부존재확인을 구하는 소]</strong></span>, <span class=\"cs-gbg\"><strong>[주주가 회사 상대 직접 명의개서 구할 수 있음에도 주주권확인을 구하는 소]</strong></span> 모두 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 예외: '선결적 법률관계'의 확인청구는 예외적으로 확인의 이익 있음<span class=\"cs-o\"><strong>(O)</strong></span> / <span class=\"cs-fact-tag\"><strong>[소유권에 기한 인도이행의 소에서 선결적 법률관계인 소유권 자체에 다툼이 있는 경우]</strong></span>, <span class=\"cs-fact-tag\"><strong>[매매계약무효확인의 경우 부당이득반환청구의 선결적 법률관계 확인]</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">다) 예외의 예외(★): <span class=\"cs-gbg\"><strong>[근저당권설정자가 피담보채무부존재확인(선결적 법률관계)과 함께 근저당권설정등기의 말소(이행의 소)를 구하는 경우]</strong></span> 등기말소청구가 직접적 해결수단 → 별도 채무부존재확인은 확인의 이익 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>증서의 진정 여부를 확인하는 소(★) - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§250</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>대상적격 - 권리보호자격</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">'법률관계를 증명하는 서면'이 '진정한지 아닌지'를 확정하는 경우만 대상적격<span class=\"cs-o\"><strong>(O)</strong></span> / (법률관계를 증명하는 서면)이란 ⅰ) 서면내용에 의해 직접적으로 ⅱ) '현재'의 ⅲ) '법률관계'의 존재가 증명될 수 있는 경우 → 처분문서(매매계약서 등)는 대상적격<span class=\"cs-o\"><strong>(O)</strong></span>, 보고문서는 대상적격<span class=\"cs-x\"><strong>(X)</strong></span> / '진정 여부'란 서면이 그 작성명의자에 의해 작성된 것인지 여부이지, 내용의 진정을 뜻하는 것은 아님</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>확인의 이익 - 권리보호이익</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">확인의 소와 마찬가지로 확인의 이익 요함 → <span class=\"cs-neg-tag\"><strong>[서면으로 증명될 법률관계에 관해 이미 별소가 제기되어 있는 경우]</strong></span>는 확인의 이익 없어 부적법<span class=\"cs-x\"><strong>(X)</strong></span> ↔ <span class=\"cs-fact-tag\"><strong>[증서진부확인의 소 제기 후 그 법률관계에 관련된 소가 나중에 제기된 경우]</strong></span>는 진부확인의 소의 확인의 이익 소멸되지 않음<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["★"], 1, "mp_3"], ["민소014", "소송물 - 청구의 특정", "<div class=\"cs-h\">Ⅰ. 소송물 - 구소송물이론</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例: 원칙적으로 구소송물이론에 입각 → 청구원인에 의해 특정되는 실체법상 권리가 소송물, 청구원인에 의해 동일성 식별<span class=\"cs-o\"><strong>(O)</strong></span> / 단, 확인의 소에서는 '일정한 권리 또는 법률관계'의 존부 주장이 소송물이고 청구취지만으로 동일성 특정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 이행의 소의 소송물</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>부당이득반환청구의 소송물(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소송물은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§741</strong></span></span>의 부당이득반환청구권 자체, 발생원인은 '법률상 원인 없음' → 계약의 불성립·취소·무효·해제 주장은 공격방법에 불과<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>부당이득반환청구권과 불법행위로 인한 손해배상청구권</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">실체법상 별개의 청구권으로 소송물을 달리함<span class=\"cs-o\"><strong>(O)</strong></span> → 하나의 청구권으로 승소확정판결을 받아도 만족을 얻지 못했으면 다른 청구권에 관한 이행의 소 제기 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>부당이득반환청구권과 계약해제로 인한 원상회복청구권(★) - 소송물 동일</strong><span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">해제의 효과인 원상회복은 부당이득의 특별규정 성격(법조경합) → 전소의 매매대금반환청구와 후소의 계약해제 원상회복청구는 성질이 같아 소송물 동일, 전소 확정판결의 기판력에 저촉(후소 불허, X)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소유권이전등기청구의 소송물</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">ⅰ) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§568</strong></span></span> 매매에 기한 청구, ⅱ) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§245</strong></span></span> 점유시효취득에 의한 청구는 근거조문이 다르므로 소송물 다름<span class=\"cs-o\"><strong>(O)</strong></span> → 서로 기판력 불상충<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>말소등기청구의 소송물(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>원칙 - 소송물이 동일한 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소송물은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§214</strong></span></span>의 말소등기청구권 자체, 발생원인은 '등기원인무효' → 수반하는 개별 사유들은 공격방법에 불과 → 전후소 소송물 동일시 후소 주장사유는 전소 기판력에 저촉<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>예외 - 소송물이 다른 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-gbg\">[소유권에 기한 방해배제청구(<span class=\"cs-u\">민법§214</span></span>)의 전소 기판력]<strong>은 </strong>[계약해제에 따른 원상회복(<span class=\"cs-blue\"><span class=\"cs-u\">민법§548</span></span>) 말소청구 후소]<strong>에 미치지 않음</strong><span class=\"cs-x\"><strong>(X)</strong></span> — 소송물 다름(부당이득반환청구권과 계약해제 원상회복청구권을 소송물 동일로 본 점과 구별)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-gbg\"><strong>[상속회복청구의 소에 해당한다는 이유로 패소확정된 전소 기판력]</strong></span>은 <span class=\"cs-gbg\">[중복등기를 이유로 한 무효 말소청구(<span class=\"cs-u\">§214</span></span>) 후소]<strong>에 미치지 않음</strong><span class=\"cs-x\"><strong>(X)</strong></span> - 소송물 다름</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-gbg\"><strong>[피담보채무 변제를 이유로 한 말소본소(부종성)]</strong></span>와 <span class=\"cs-gbg\"><strong>[이전등기 원인무효를 이유로 한 전소청구(유인성)]</strong></span>는 소송물 동일이라 볼 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[사기를 이유로 한 근저당권설정계약 의사표시취소를 원인으로 한 말소청구(유인성)]</strong></span>와 <span class=\"cs-fact-tag\"><strong>[피담보채무 부존재를 원인으로 한 말소청구(부종성)]</strong></span>는 각 청구원인을 달리하는 별개의 독립된 소송물로 선택적 병합관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>진정명의회복을 위한 소유권이전등기청구의 소송물 - 말소등기청구와 같음</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">실체법적 근거에 의해 소송물이 특정되므로 소송물은 '<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§214</strong></span></span>'로 1개(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§108</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§109</strong></span></span> 등은 공격방어방법에 불과) → 말소등기청구와 진정명의회복청구는 목적·근거·성질이 동일하여 소송물 실질상 동일<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>손해배상의 소송물(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">생명·신체침해 손해배상청구는 적극적 손해, 소극적 손해, 정신적 손해(위자료) 3개 항목마다 소송물이 별개(<span class=\"cs-u\"><strong>손해3개설</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>일부청구의 소송물(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例(<span class=\"cs-u\"><strong>명시설</strong></span>): 일부청구임을 명시한 경우에는 일부만이 독립의 소송물<span class=\"cs-o\"><strong>(O)</strong></span>, 명시하지 않은 경우에는 전부가 소송물<span class=\"cs-o\"><strong>(O)</strong></span> → 명시 여부는 잔부청구와 구별해 심리범위를 특정할 수 있는 정도의 표시로 족함</div><div class=\"cs-h\">Ⅲ. 확인의 소의 소송물(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">확인소송의 소송물은 '일정한 권리 또는 법률관계'의 존부 주장이며, 소장의 '청구취지'만으로 동일성 특정(청구원인에 의한 보충 불요)<span class=\"cs-o\"><strong>(O)</strong></span> / <span class=\"cs-fact-tag\"><strong>[증여를 원인으로 한 소유권확인 본안판결 확정 후 변론종결 전 다른 취득원인(상속·매매 등)이 있었더라도 이미 확정판결의 기판력이 거기까지 미침]</strong></span></div><div class=\"cs-h\">Ⅳ. 형성의 소의 소송물</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(1) <strong>구소송물이론에 의하면 실체법적 근거에 의해 소송물이 특정 → 이혼소송의 소송물은 '</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§840</strong></span></span><strong> 각 호'의 각 이혼사유마다 별개의 소송물</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(2) <strong>채권자취소송의 소송물은 '채권자 자신의 채권자취소권(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§406</strong></span></span><strong>)'이며 ① 피보전채권 존재 ② 사해행위 존재 ③ 사해의사 존재를 요건으로 하고 원상회복은 원물반환·가액배상(공격방법 5개) → 피보전채권 추가·교환은 공격방법 변경에 불과하여 소의 변경 아님</strong><span class=\"cs-x\"><strong>(X)</strong></span></div>", ["★★★"], 1, "mp_3"], ["민소015", "소제기와 재판장의 소장심사와 소제기 후의 조치", "<div class=\"cs-h\">Ⅰ. 소제기 방식</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">원칙적으로 소장과 첨부서류(규칙<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§63②</strong></span></span>)를 제1심법원에 제출(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§248①</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개정 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§248③</strong></span></span> 신설 → 법원에 제출한 소장이 접수되면 소장이 제출된 때에 소가 제기된 것으로 간주<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 재판장의 소장심사와 소장각하명령의 행사시기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>재판장의 소장심사의 대상</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소장심사 대상은 ① 필요적 기재사항 기재 여부 ② 소장에 인지를 붙였는지 여부(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§254①</strong></span></span>) → 흠결시 소장각하명령<span class=\"cs-o\"><strong>(O)</strong></span> / 소송요건 구비 여부와 청구의 당부는 소장심사의 대상<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: (소송요건 심사) <span class=\"cs-gbg\"><strong>[대표자 표시에 잘못이 있는 경우]</strong></span> 보정명령 불응을 이유로 한 소장각하<span class=\"cs-x\"><strong>(X)</strong></span> → 오직 판결로만 소각하 가능 / (본안 심사) 청구의 특정이 가능한 정도로 청구취지·원인이 기재되어 있으면 불명확해도 소장심사의 대상<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소장각하명령의 행사시기(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-gbg\"><strong>[항소장부본이 적법히 송달된 이상, 항소인에게 주소보정을 명하고 불응해도]</strong></span> 명령으로 항소장 각하<span class=\"cs-x\"><strong>(X)</strong></span> - 소송계속시설</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-gbg\"><strong>[독립당사자참가소송에서 항소장이 송달되어 항소심 소송관계가 일부라도 성립한 경우]</strong></span> 항소장각하명령<span class=\"cs-x\"><strong>(X)</strong></span> → 소장부본이 피고에게 송달되면 소송법률관계 발생 → 소장각하명령은 소장부본송달시까지만 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-gbg\"><strong>[주소보정명령 보정기간 경과 후 각하명령 하지 않고 재차 보정기간을 정해 주소보정명령을 한 경우]</strong></span> 재차 보정기간이 경과하기 전에는 종전 보정기간 내 불이행을 이유로 각하명령<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>항소인이 인지보정명령에 응하지 않았다는 이유로 항소장각하명령이 성립한 시점 이후 인지를 보정한 경우 항소장각하명령의 위법 여부(원칙적 소극)(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">종래판례: 재항고장각하명령 송달 전 인지 등이 보정되면 즉시항고에 정당한 이유 있음으로 각하명령 취소<span class=\"cs-o\"><strong>(O)</strong></span> ↔ 변경판례: ⅰ) 재판장이 항소장을 각하하는 명령은 적법<span class=\"cs-o\"><strong>(O)</strong></span> ⅱ) 결정·명령은 일단 성립하면 별도 규정 없는 한 법원 스스로 취소변경 불가한 구속력<span class=\"cs-o\"><strong>(O)</strong></span> ⅲ) 각하명령 성립 후에는 인지를 보정하더라도 특별한 사정 없는 한 각하명령이 위법하게 되지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 무변론판결(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>피고가 소장부본송달을 받은 날로부터 30일 이내에 답변서 미제출 또는 자백취지 답변서 제출 &amp; 항변 미제출</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>무변론판결의 예외에 해당하지 않을 것 - ① 공시송달사건(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§256①</strong></span></span><strong>단서) ② 직권조사사항 있는 사건(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§257①</strong></span></span><strong>단서) ③ 판결선고기일까지 피고가 청구를 다투는 답변서 제출시(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§257①</strong></span></span><strong>본문) ④ 당사자 주장에 구속받지 않는 형식적 형성소송 ⑤ 자백간주 법리 부적용 사건은 무변론판결</strong><span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>원고승소판결의 요건을 갖추어야 할 것 - ① 적식의 소장 제출 ② 소가 적법할 것 ③ 주장 자체로 법률상 이유가 있을 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">요건 구비시 청구원인 사실을 자백한 것으로 보아 변론기일 지정 없이 선고기일만 지정해 무변론 원고승소판결 선고 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>원고의 주장 자체로 이유가 없는 경우 무변론 원고청구기각판결 가부(★) - 부정</strong><span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 무변론판결은 원고의 청구를 인용할 경우에만 가능, 청구가 이유 없음이 명백해도 변론 없이 하는 청구기각판결은 인정<span class=\"cs-x\"><strong>(X)</strong></span> → 변론준비절차 회부 또는 변론기일 지정해 심리 후 판결</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>답변서 제출을 간과한 무변론 원고청구인용판결의 적부와 항소심 조치(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 제1심법원이 피고의 답변서 제출을 간과한 채 무변론판결을 선고했다면 이는 절차가 법률에 어긋난 경우(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§417</strong></span></span>) → 항소법원은 제1심판결 취소의무<span class=\"cs-o\"><strong>(O)</strong></span> ② 단, 항소법원이 제1심법원으로 반드시 환송해야 하는 것은 아니므로<span class=\"cs-x\"><strong>(X)</strong></span> 사건을 환송하지 않고 직접 다시 판결 가능<span class=\"cs-o\"><strong>(O)</strong></span></div>", [], 1, "mp_3"], ["민소016", "중복된 소제기의 금지", "<div class=\"cs-h\">Ⅰ. 의의 및 요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">이미 법원에 사건이 계속되어 있을 때에는 그와 동일한 사건에 대하여 당사자는 다시 소를 제기하지 못한다는 원칙(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§259</strong></span></span>) — 판결의 모순저촉 방지가 취지 / 요건: ① 전·후 양소의 당사자가 동일할 것 ② 전·후 양소의 청구가 동일할 것 ③ 전소 법원에 소송계속 중 후소를 제기할 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>당사자의 동일</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>원칙</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">당사자가 다르더라도 '전소 당사자가 받은 판결효력(기판력)이 후소 당사자에게 미치면' 예외적으로 당사자 동일 인정<span class=\"cs-o\"><strong>(O)</strong></span> → 判例: <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span> 변론종결 뒤의 승계인, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218③</strong></span></span> 소송담당자는 판결의 효력이 미쳐 중복소제기<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>채권자대위소송과 중복소제기(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 채권자대위소송 계속 중 채무자가 소를 제기한 경우 - 중복소제기<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: '판결의 모순·저촉 방지' 취지상 양 소송은 당사자가 다를지라도 실질적 동일소송 → 채무자가 대위소송 계속을 알든 모르든 후소는 중복소제기<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 채무자의 제3채무자에 대한 소송 중 채권자대위소송이 제기된 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: (중복소제기 긍정) 법정소송담당을 통해 채무자가 받은 판결 효력이 채권자에게 미치므로 실질적 동일소송으로 보아 대위소송은 중복소제기<span class=\"cs-o\"><strong>(O)</strong></span> ↔ (당사자적격 흠결) 대위권 행사 당시 이미 채무자가 권리를 행사했으면 대위요건 흠결로 당사자적격 없어 부적법<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 채권자의 대위소송 계속 중 다른 채권자가 다시 대위소송을 제기한 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 어느 채권자가 대위소송을 제기해 계속 중인데 다른 채권자가 동일한 피대위채권에 대해 다시 대위소송을 제기하면, 양 소송은 실질적으로 동일소송이므로 후소는 중복소제기<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>채무자가 제3채무자를 상대로 한 이행의 소 계속 중 추심채권자의 추심의 소가 중복소제기에 해당하는지 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">종래판례: 제3채무자에게 이중응소 부담을 지우지 않고 판결 모순·저촉 위험도 크지 않다고 보아 중복소제기<span class=\"cs-x\"><strong>(X)</strong></span> ↔ 변경판례: 채무자의 제3채무자에 대한 채권에 관하여 추심명령이 있더라도 채무자는 피압류채권에 관한 이행의 소를 제기할 당사자적격을 상실하지 않음<span class=\"cs-o\"><strong>(O)</strong></span> → 채무자가 먼저 제기한 이행의 소와 추심채권자가 나중에 제기한 추심의 소는 실질적 동일사건이므로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§259</strong></span></span> 중복소제기에 해당하여 부적법<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>채권자취소소송과 중복소제기(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 수인의 채권자가 수익자를 상대로 각각 채권자취소소송을 제기한 경우 - 중복소제기<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 소송물은 '각 채권자 자신의' 채권자취소권 → 채권자마다 별개의 권리로 보아 중복소제기<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 채권자가 피보전채권을 변경(대여금채권→손해배상채권)하여 동일 수익자 상대로 재차 제기하는 경우 - 중복소제기<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 소송물은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§406</strong></span></span>의 채권자취소권이고 피보전채권은 공격방법에 불과 → 피보전채권을 바꿔도 전·후 소송물 동일 → 후소는 중복소제기<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>청구의 동일</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>청구취지가 같은 경우 - 구소송물이론상 청구취지가 같아도 청구원인을 이루는 실체법상 권리가 다르면 청구 비동일 → 중복소제기</strong><span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>청구취지가 다른 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 선결적 법률관계로 주장한 권리에 대한 별소제기 - 중복소제기<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">(전소의 선결적 법률관계가 후소의 소송물인 경우) 청구취지가 다르므로 중복소제기<span class=\"cs-x\"><strong>(X)</strong></span> ↔ (전소의 소송물이 후소의 선결적 법률관계인 경우)도 청구취지 다르면 중복소제기<span class=\"cs-x\"><strong>(X)</strong></span> / <span class=\"cs-gbg\"><strong>[채무인수자 상대 이행청구 계속 중 채무인수자가 원고 상대 채무부존재확인청구]</strong></span> 청구취지·원인이 서로 다르므로 중복소제기<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 상계의 항변</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 상계항변 선행형(★) - 중복소제기<span class=\"cs-x\"><strong>(X)</strong></span>: 判例 먼저 제기된 소송에서 상계항변을 제출한 다음(상계항변 선행형) 소송계속 중 자동채권과 동일한 채권에 기한 소를 별소나 반소로 제기하는 것도 가능(<span class=\"cs-u\"><strong>중복소제기부정설</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 별소 선행형(★) - 중복소제기<span class=\"cs-x\"><strong>(X)</strong></span>: 判例 상계항변 제출 당시 이미 자동채권에 기한 소송이 별도로 제기되어 계속중인 경우(별소선행형) 이부·변론병합 등이 바람직하더라도 별소로 계속 중인 채권을 자동채권으로 하는 소송상 상계의 주장 허용<span class=\"cs-o\"><strong>(O)</strong></span>(<span class=\"cs-u\"><strong>중복소제기부정설</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 일부청구와 잔부청구(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例(<span class=\"cs-u\"><strong>명시설</strong></span>): ① 명시적 일부청구는 잔부청구가 중복소제기<span class=\"cs-x\"><strong>(X)</strong></span> ② 묵시적 일부청구는 소송계속의 효과가 잔부청구에도 미쳐 소송물 동일하므로 중복소제기<span class=\"cs-o\"><strong>(O)</strong></span> / 단, 원고가 전소에서 청구취지 확장으로 용이하게 후소를 할 수 있음에도 별소로 잔부를 청구하는 것은 소권남용으로 부적법<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>전소의 계속 중 후소 제기</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>전소의 소송계속 중 - 전후소 구별기준은 소송계속(소장부본송달시) 발생시기의 선후 → 전소가 소송요건 흠결의 부적법한 소라도 소송계속은 발생</strong><span class=\"cs-o\"><strong>(O)</strong></span><strong> → 후소 제소 당시 전소가 각하되어 그 계속이 소멸되지 않는 한 후소는 중복소제기</strong><span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>후소 제기 - 전소 소송계속 중 후소를 제기해야 함 / 같은 법원인지 다른 법원인지 불문하고 후소가 독립의 소에 한하지 않으며, 소의 변경·반소·중간확인의 소 또는 당사자참가의 방법으로 제기되어도 무관 / 단, 동일한 소송절차에 소송참가하는 경우는 판결의 모순·저촉 우려 없어 중복소제기에 해당</strong><span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 소송법상의 효과</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>직권조사사항</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">중복소제기금지는 소극적 소송요건이자 직권조사사항<span class=\"cs-o\"><strong>(O)</strong></span> → 후소가 중복소송에 해당되면 판결로 후소를 부적법 각하해야 함(의무)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>중복소제기임을 간과한 판결</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>판결의 효력 및 구제책(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">후소가 중복소송임을 간과하여 본안판결을 하는 것은 중복소제기금지 위반으로 위법(유효취소)<span class=\"cs-o\"><strong>(O)</strong></span> → 확정전 상소사유(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§423</strong></span></span> 일반적 상소이유)<span class=\"cs-o\"><strong>(O)</strong></span> ↔ 확정 후 재심사유<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>후소의 판결이 먼저 확정된 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">후소의 간과판결이 먼저 확정되면 후소 판결의 기판력이 전소를 구속<span class=\"cs-o\"><strong>(O)</strong></span> → 전후 양소의 판결이 모두 확정되어 서로 모순·저촉될 경우, 먼저 확정된 판결이 효력이 있고 뒤에 확정된 판결은 재심의 소에 의해 취소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>10호)</div>", ["★★★"], 1, "mp_3"], ["민소017", "실체법상의 효과", "<div class=\"cs-h\">Ⅰ. 응소와 시효중단(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>응소의 시효중단 사유 해당여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 시효중단의 근거는 '권리행사'에 있고, 피고의 응소행위도 권리행사이므로 응소행위는 시효중단의 사유<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>시효중단요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 채무자가 제기한 소에서 채권자가 응소행위를 하였을 것 ② 응소행위로서 시효가 중단되었다고 주장하였을 것 ③ 이것이 받아들여질 것</div><div class=\"cs-h\">Ⅱ. 일부청구와 시효중단의 범위(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>명시설</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 명시적 일부청구의 경우에는 그 일부만이 소송물이므로 일부만 시효중단<span class=\"cs-o\"><strong>(O)</strong></span> ② 묵시적 일부청구의 경우에는 전부가 소송물이므로 전부에 대하여 시효중단<span class=\"cs-o\"><strong>(O)</strong></span> → 단, 명시적 일부청구라도 전부청구한 것으로 해석되면 전부중단<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>명시적 일부청구하면서 청구취지 확장의 뜻을 표시한 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>실제로 청구금액 확장한 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소송이 종료될 때까지 실제로 확장한 경우에는 채권 전부에 관하여 판결을 구한 것으로 해석 → 채권 전부에 관하여 재판상 청구로 인한 시효중단의 효력 발생<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>실제로 청구금액 확장하지 않은 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">원칙 나머지 부분에는 시효중단의 효력 불발생<span class=\"cs-x\"><strong>(X)</strong></span> → 단, 확장할 뜻을 표시하여 최고에 의해 권리를 행사하고 있는 상태가 지속되고 있다고 보아, 소송이 종료된 때(판결확정시)부터 6월 내에 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§174</strong></span></span>에서 정한 조치를 취함으로써 나머지 부분의 시효를 중단시킬 수 있음(최초 소제기시 시효중단됨)<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>특정 부분을 청구범위에서 명시적으로 제외한 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">확장할 뜻을 표시하였다가 후에 채권의 특정부분을 청구범위에서 명시적으로 제외한 경우 그 부분은 애초부터 소제기가 없었던 것과 마찬가지로 시효중단효력 불발생<span class=\"cs-x\"><strong>(X)</strong></span> → 단, 그 채권자는 당해 소송이 계속 중인 동안에는 나머지 부분을 최고에 의해 권리를 행사하고 있는 상태가 지속되는 것으로 보아, 소송이 종료된 때부터 6월 내에 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§174</strong></span></span> 조치로 나머지 부분의 소멸시효를 중단시킬 수 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅲ. 법률상의 기간준수 - 제척기간 준수</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>직권조사사항과 제척기간 도과의 효과(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 제척기간 중 제소기간(채권자취소소송, 상속회복청구소송, 점유회복청구소송 등)의 도과 여부는 소송요건이자 그 준수 여부는 직권조사사항<span class=\"cs-o\"><strong>(O)</strong></span> → 기간을 도과하여 제기된 소는 부적법하여 소각하<span class=\"cs-x\"><strong>(X)</strong></span> ② 제척기간 가운데 '제소기간이 아닌 경우' 그 기간 도과로 권리가 당연히 소멸하므로 청구기각<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>효력발생시기(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">피고가 소장부본의 송달을 지연시켜 시효완성이나 출소기간이 도과해버리는 원고의 불이익을 막기 위해 소송계속의 효과(소장부본송달시)와 달리, 시효중단·법률상 기간준수의 효력은 소장을 법원에 제출한 때에 발생(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§265</strong></span></span>전단) / 소송 중의 소는 소장에 해당하는 서면을 법원에 제출한 때 그 효력 발생(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§265</strong></span></span>후단)</div>", ["★★★"], 1, "mp_3"], ["민소018", "처분권주의", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">처분권주의란 원고가 심판대상을 특정한 만큼 법원은 그에 대해서만 판결해야 한다는 원칙(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§203</strong></span></span>) → 법원은 신청사항에 대하여(질적동일) 신청의 범위 내에서만(양적동일) 판단해야 함 / 상소심에서의 발현이 불이익변경금지의 원칙</div><div class=\"cs-h\">Ⅱ. 질적 동일 - 당사자가 신청한 사항</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송물(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§203</strong></span></span>의 '신청사항'이란 소송물을 의미 → 법원은 원고가 특정한 소송물에 대해서만 판단해야 하며 다른 소송물 판단 불가(구소송물이론은 실체법상 권리마다 소송물이 다름)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">[소유권 상실로 인한 불법행위 손해배상청구에 대해 당사자가 주장하지 않은 소유권보존등기말소등기절차 이행의무의 채무불이행으로 인한 손해배상책임을 인정한 판결] 처분권주의 위반<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-gbg\"><strong>[부진정연대채무 관계를 전제로 연대하여 지급할 것을 구하였는데 피고들에게 개별적 지급책임을 인정한 판결]</strong></span> 처분권주의 위반<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-gbg\"><strong>[제1심에서 피고가 상계항변을 하였다가 이를 철회하였는데 법원이 이에 관하여 판단한 경우]</strong></span> 당사자가 주장하지 않은 사항을 심판한 것으로 처분권주의 위반<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-gbg\"><strong>[채권자가 건물에서 퇴거할 것을 구하는데 법원이 건물 인도를 명한 경우]</strong></span> 처분권주의 위반<span class=\"cs-x\"><strong>(X)</strong></span> — '인도'는 현실적·사실적 지배를 완전히 이전하는 것, '퇴거'는 점유를 해제하는 것일 뿐 점유 이전까지는 의미하지 않아 구별</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">최근판례는 손해배상청구소송에서 법원이 인정한 손해액이 청구금액보다 많더라도 청구금액을 초과하여 지급을 명하지 않는 이상 처분권주의 위반<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소의 종류·순서(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§203</strong></span></span>의 '신청사항'에는 원고가 정한 소의 종류·순서도 포함 → 법원은 원고가 정한 소의 종류·심판순서에 구속<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅲ. 양적 동일 - 신청의 범위 내</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>인명사고에 의한 손해배상청구(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例(<span class=\"cs-u\"><strong>손해3개설</strong></span>): 적극적·소극적·정신적 손해는 서로 소송물을 달리함 → 각 손해항목에서 원고가 청구한 금액을 초과하여 인정하면 처분권주의 위반<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>일부청구와 과실상계(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 일부청구는 <span class=\"cs-u\"><strong>명시설</strong></span> 입장이나, 일부청구와 과실상계의 경우만은 <span class=\"cs-u\"><strong>외측설</strong></span> 입장 → 손해전액에서 과실상계액을 공제한 잔액이 일부청구액을 초과하면 청구액 한도내 인용(양적상한 초과), 잔액이 청구액에 미달하면 잔액대로 인용(일부인용)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>채무부존재확인의 소와 일부인용 판결</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>채무의 존부만 다투는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(의의) 가해자의 손해배상채무 부존재확인과 같이 채무의 존부만 다투는 경우 / (소송물) 이 경우 소송물은 '채무의 존부' 그 자체 / (일부인용판결 부정) 법원은 과실 유무만 심리해 없으면 전부채권인용, 있으면 전부청구기각판결을 해야 하며 일부인용판결은 불가<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>채무의 존부 및 액수를 다투는 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(의의) '원고의 피고에 대한 2010. 10. 1.자 대여금 채무 1,000만 원 중 400만 원을 초과해서는 존재하지 아니함을 확인한다'라고 청구하여 1,000만 원 중 400만 원을 초과하는 채무의 존부·액수를 다투는 경우 / (소송물) 그 소송물은 1,000만 원 중 400만 원을 초과하는 채무 600만 원 / (일부인용판결 가부) 법원이 400만 원을 초과하는 채무가 인정된다고 판단한 경우 전부청구기각 불가<span class=\"cs-x\"><strong>(X)</strong></span>, 일부인용·일부기각판결을 해야 함<span class=\"cs-o\"><strong>(O)</strong></span>(예: 600만 원 채무 인정시 '1,000만 원 중 600만 원을 초과해서는 존재하지 않음을 확인, 나머지 청구는 기각'하는 일부인용판결) — 양적상한초과: 잔존채무가 200만 원이라는 심증을 얻은 때 '400만 원'을 초과해서는 존재하지 않는다고 판결해야 하고, 이를 넘어 200만 원을 초과해서는 존재하지 않는다고 판결하면 800만 원 부존재를 인정한 것이 되어 양적 상한 초과로 처분권주의 위반<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>동시이행항변이나 유치권 항변을 하는 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">원고의 단순이행청구에 대해 피고가 동시이행·유치권 항변을 하고 그 항변권 행사가 이유 있을 때는 청구기각이 원칙이나, 원고가 반대 의사표시를 하지 않는 한 법원은 상환이행판결 가능<span class=\"cs-o\"><strong>(O)</strong></span> — '질적 일부인용판결'로서 처분권주의에 반하지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>건물매수청구권을 행사하는 경우 상환이행판결 가부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: (상환이행판결 불허) 건물철거·토지인도청구 속에 건물매수대금과 상환한 건물인도청구가 포함되어 있다고 볼 수 없으므로 상환이행판결 허용<span class=\"cs-x\"><strong>(X)</strong></span> → (적극적 석명의무 인정) 단, 법원은 청구기각판결을 하기 전에 임대인이 종전의 청구를 유지할 것인지, 대금지급과 상환으로 건물인도를 청구할 의사가 있는지 석명해야 함(의무)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[사례풀이구조]</strong></span> ① 건물철거·토지인도청구와 매수대금지급과 상환하여 건물인도를 명하는 상환이행판결은 처분권주의 반하므로 바로 할 수 없고 ② 청구기각판결을 해야 하나 ③ 적극적으로 소변경을 시사하는 석명을 해야 하며 ④ 원고가 소변경을 하면 상환이행판결, 소변경을 하지 않으면 청구기각판결을 해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>채권자취소소송에서 원물반환청구의 경우에 가액배상판결</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 사해행위를 전부 취소하고 원상회복을 구하는 채권자의 주장 속에는 일부취소와 가액배상을 구하는 취지도 포함 → 채권자가 원상회복만 구하는 경우에도 법원은 청구변경 없이 가액배상을 명할 수 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>현재이행의 소의 경우에 장래이행판결(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[채무자가 피담보채무 전액변제를 이유로 저당권설정등기 말소청구를 하였는데 채무가 잔존하는 것으로 밝혀진 경우]</strong></span> 청구기각이 원칙이나, 判例: ① 원고가 단순이행청구(현재이행의 소)를 하였고 ② 피고가 선이행항변을 하였고 심리결과 잔액이 있는 때 ③ 법원은 바로 청구기각할 것이 아니라 ⅰ) 원고의 의사에 반하지 않고 ⅱ) 장래이행의 소로서 미리청구할 필요가 있으면 장래이행판결 가능<span class=\"cs-o\"><strong>(O)</strong></span>('피고는 원고로부터 피담보채무를 변제받은 다음에 등기를 말소하라'는 장래이행판결)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">단, <span class=\"cs-gbg\"><strong>[피담보채무의 변제를 전제한 것이 아니라 피담보채무가 발생하지 않은 것을 전제로 말소를 구하는 경우]</strong></span>에는 변제를 조건으로 한 장래이행 취지가 포함된 것으로 볼 수 없어 장래이행판결 불가<span class=\"cs-x\"><strong>(X)</strong></span>(이때 장래이행을 명하면 처분권주의 위반)</div><div class=\"cs-h\">Ⅳ. 위반의 효과</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">처분권주의를 위반한 판결은 무효인 판결이 아니며<span class=\"cs-x\"><strong>(X)</strong></span>, 유효하지만 위법한 판결<span class=\"cs-o\"><strong>(O)</strong></span> → 확정 전에는 상소로 취소 가능, 재심사유로 규정되어 있지 않으므로 확정 후에는 재심으로 취소 불가<span class=\"cs-x\"><strong>(X)</strong></span></div>", ["★★★"], 1, "mp_3"], ["민소019", "변론주의", "<div class=\"cs-h\">Ⅰ. 변론주의의 내용</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>사실의 주장책임</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">주장책임이란 당사자가 주요사실을 주장하지 아니하면 그 사실은 판결의 기초로 삼을 수 없는 불이익 — ⅰ) 당사자는 변론에서 주요사실을 주장해야 하며 ⅱ) 법원은 당사자가 주장하지 않은 사실은 판결의 기초로 삼을 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> / '주장공통의 원칙'에 의해 주요사실은 반드시 주장책임을 지는 당사자가 진술해야 하는 것은 아니며<span class=\"cs-x\"><strong>(X)</strong></span>, 어느 당사자든 변론에서 주장하기만 하면 주장한 것으로 됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>간접적 주장의 인정 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 주요사실에 대한 주장은 직접·명시적으로 한 경우뿐 아니라, 당사자가 법원에 ⅰ) 서증을 제출하여 '증명취지를 진술'함으로써 서증에 기재된 사실을 주장하거나 ⅱ) 서증을 '이익으로 원용'한 때 ⅲ) 변론을 전체적으로 관찰하여 간접적으로 주장한 것으로 볼 수 있으면 주요사실의 주장이 있는 것으로 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>묵시적 주장(★) - 주장의 포함</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">묵시적 주장이란 당사자의 주장에 다른 주장도 포함되어 있는 것 — 判例: ① <span class=\"cs-gbg\"><strong>[채무불이행으로 인한 손해배상청구권의 소멸시효 항변]</strong></span>에 <span class=\"cs-gbg\"><strong>[불법행위로 인한 손해배상청구권의 소멸시효 항변]</strong></span>은 포함되어 있지 않음<span class=\"cs-x\"><strong>(X)</strong></span> ② <span class=\"cs-gbg\"><strong>[증여를 원인으로 한 부동산소유권이전등기청구에서 피고가 시효취득을 주장]</strong></span>해도 그 주장 속에 원고의 이전등기청구권이 시효소멸했다는 주장까지 포함되어 있다고 볼 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> ③ <span class=\"cs-gbg\"><strong>[유권대리 주장 속에 표현대리 주장]</strong></span>이 포함되어 있다고 볼 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> - 유권대리와 표현대리는 구성요건해당사실(주요사실)을 달리함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>법원에 현저한 사실에 주장책임 적용 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 변론주의 하에서는 법원에 현저한 사실이라 해도 당사자가 그 사실에 대해 주장해야 법원이 이를 사실인정의 자료로 할 수 있다고 하여 주장책임 적용<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>자백의 구속력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">자백한 사실에 대해 법원은 다른 사실인정권이 배제되어 증거조사 없이 그대로 판결의 기초로 해야 하고<span class=\"cs-o\"><strong>(O)</strong></span> 이는 구속력이 있음 — 단, 현저한 사실에 반하는 자백은 구속력 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>증거제출책임(직권증거조사의 금지) - 주관적 증명책임</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">다툼 있는 사실에 대한 증거는 당사자가 제출해야 하며, 법원도 당사자가 신청한 증거에 대해서만 증거조사하며, 원칙적으로 직권증거조사<span class=\"cs-x\"><strong>(X)</strong></span> — 단, 당사자가 신청한 증거에 의하여 '심증을 얻을 수 없을 때에만' 보충적으로 직권증거조사 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 변론주의의 적용범위</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>변론주의가 적용되는 사실과 구별기준(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">변론주의는 '주요사실'에만 적용<span class=\"cs-o\"><strong>(O)</strong></span> → '간접사실이나 보조사실'에는 적용<span class=\"cs-x\"><strong>(X)</strong></span> — 判例(<span class=\"cs-u\"><strong>법규기준설</strong></span>): 당사자가 변론에서 주장한 주요사실만이 심판의 대상이 되며, '주요사실'이란 법률효과를 발생시키는 실체법상의 구성요건 해당사실, 주요사실을 추인케 하는 사실을 간접사실으로 분류</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>구별의 효과 - 실익</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>변론주의의 적용</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">주요사실에만 변론주의 적용 → 당사자의 주장이 있어야 판결의 기초로 삼을 수 있고, 자백의 구속력이 인정되며, 증거에 의해 인정해야 함 — 간접사실은 당사자가 변론에서 주장하지 않았더라도 판결의 기초로 삼을 수 있고<span class=\"cs-o\"><strong>(O)</strong></span>, 자백의 구속력이 부정되며<span class=\"cs-x\"><strong>(X)</strong></span>, 주요사실과 무관하면 증거조사 불필요</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>유일한 증거의 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">유일한 증거가 주요사실에 관한 것일 때 법원은 그 조사를 거부할 수 없음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§290</strong></span></span>단서) — 간접사실에 관한 것일 때에는 그 조사를 거부할 수 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>판단누락</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">주요사실의 경우 판단누락이 있으면 상소이유·재심사유(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>9호)가 됨 — 간접사실은 판단하지 않아도 상소이유·재심사유로서의 판단누락이 되지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소멸시효의 기산일이 주요사실인지 여부(★) - 주요사실설</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例(<span class=\"cs-u\"><strong>법규기준설</strong></span>, <span class=\"cs-u\"><strong>주요사실설</strong></span>): 소멸시효의 기산일은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§166①</strong></span></span>의 '권리를 행사할 수 있을 때부터'라는 법규의 요건사실이므로 주요사실<span class=\"cs-o\"><strong>(O)</strong></span> → 본래의 기산일과 당사자가 주장하는 기산일이 다르면 법원은 당사자가 주장하는 기산일을 기준으로 소멸시효를 계산해야 함(어느 방향이든 마찬가지)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소멸시효 기간이 주요사실인지 여부(★) - 직권조사사항</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 소멸시효기간이 얼마나 되는지에 관한 주장은 단순한 법률상 주장에 불과하여 변론주의 적용대상<span class=\"cs-x\"><strong>(X)</strong></span>, 법원이 직권으로 판단 가능<span class=\"cs-o\"><strong>(O)</strong></span> ② 당사자가 민법상 소멸시효기간을 주장해도 법원은 직권으로 상법상 기간을 적용 가능<span class=\"cs-o\"><strong>(O)</strong></span> ③ 10년 소멸시효를 주장해도 지방자치단체에 대한 금전지급목적 채권의 소멸시효기간이 5년이면 이에 따라 심리<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>취득시효의 기산일이 주요사실인지 여부(★) - 간접사실설</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例(<span class=\"cs-u\"><strong>법규기준설</strong></span>, <span class=\"cs-u\"><strong>간접사실설</strong></span>): <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§245①</strong></span></span>은 '20년간 부동산을 점유한 사실'만 규정할 뿐 그 기산점은 규정하지 않으므로 간접사실에 해당<span class=\"cs-o\"><strong>(O)</strong></span> → 법원은 당사자의 주장에 구애되지 않고 소송자료에 의해 진정한 점유의 시기를 인정하여 판단 가능<span class=\"cs-o\"><strong>(O)</strong></span> / 점유취득의 점유권원도 간접사실에 해당 → 법원은 당사자 주장에 구애되지 않고 진정한 점유의 권원을 심리해 취득시효 완성 여부를 판단 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>유권대리와 표현대리사실이 주요사실인지 여부(★) - 주요사실</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(처분권주의 위반 여부) 判例: 주요사실이란 법률효과를 발생시키는 실체법상의 구성요건해당사실인바, 대리권에 기한 대리나 표현대리나 모두 제3자가 한 대리행위의 효과가 본인에게 귀속된다는 점에서 차이가 없으므로 법원이 표현대리 성립을 인정해도 처분권주의 위반<span class=\"cs-x\"><strong>(X)</strong></span> ↔ (변론주의 위반 여부) 표현대리가 성립한다고 해서 무권대리의 성질이 유권대리로 전환되는 것이 아니므로 양자의 구성요건해당사실(주요사실)은 서로 다름 → 유권대리 주장 속에 표현대리 주장이 당연히 포함되어 있다고 볼 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> → 원고가 유권대리만 주장하는데 법원이 표현대리를 심리해 원고승소판결을 하면 변론주의 위반<span class=\"cs-o\"><strong>(O)</strong></span> / (지적의무 위반 여부) 유권대리 주장을 하는 당사자에게 표현대리의 주장·입증을 촉구할 의무는 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>일실이익의 산정기초 사실이 주요사실인지 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 일실이익 산정의 기초가 되는 월수입·가동연한·생계비 등은 주요사실<span class=\"cs-o\"><strong>(O)</strong></span>, 중간이자공제방식에 관한 주장(Hoffmann식/Leibnitz식)은 간접사실<span class=\"cs-o\"><strong>(O)</strong></span>로 보아 당사자 주장에 불구하고 법원이 자유로운 판단 가능<span class=\"cs-o\"><strong>(O)</strong></span> / 인신사고 손해배상의 기대여명은 주요사실<span class=\"cs-o\"><strong>(O)</strong></span>로 재판상 자백의 대상이 되며 적법하게 취소되지 않는 한 법원도 구속<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅲ. 석명권</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">석명권이란 소송관계를 분명히 하기 위하여 당사자에게 사실상 또는 법률상 사항에 대하여 질문하고 증명촉구를 할 뿐 아니라 당사자가 간과한 법률상 사항을 지적하여 의견진술의 기회를 주는 법원의 권능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§136</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>석명의 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>소극적 석명</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">당사자의 신청·주장이 불분명·불완전·모순될 때 이를 분명히 하기 위해 행사하는 소극적 석명은 제한 없이 행사 가능<span class=\"cs-o\"><strong>(O)</strong></span> — 判例: 제출된 증거가 당사자의 부주의나 오해로 불완전·불명료한 경우에는 이를 명확히 할 것을 촉구하거나 보충할 기회를 주어야 하고, 이를 게을리한 채 배척하면 위법<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>적극적 석명(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 의의와 인정여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">적극적 석명이란 당사자의 신청·주장이 없음에도 새로운 신청·주장의 제출을 권유하는 석명 — 判例: (원칙 부정) 당사자가 주장하지 않은 법률효과의 요건사실이나 공격방어방법을 시사하여 제출을 권유함은 변론주의 원칙 위반으로 석명권 행사의 한계 일탈이라 보아 원칙적으로 적극적 석명 부정<span class=\"cs-x\"><strong>(X)</strong></span>, (예외 인정) ⅰ) (전매적 석명) 임차인이 건물매수청구권을 행사한 사안에서 임대인이 종전의 청구를 유지할 것인지, 대금지급과 상환으로 건물인도청구로의 소변경 의사가 있는지 석명하고 이에 응해 소변경하면 상환이행판결을 해야 함 ⅱ) (배상액의 석명) 손해배상의무는 인정되는데 배상액 증명이 없는 경우 배상액은 적극적 석명사항 ⅲ) (지적의무) 지적의무를 통한 적극적 석명도 인정</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 인정요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 적극적 석명을 전면적으로 인정하면 석명권 범위가 불분명해지고 처분권주의·변론주의에 반하므로 원칙적으로 부정<span class=\"cs-x\"><strong>(X)</strong></span> ② 변론주의의 결함을 시정하기 위해 종전 소송자료에 비추어 새로운 주장이 법률상·논리상 예기되는 것일 것, 상대방 방어권 행사에 불이익이 없을 것을 요건으로 함 → 이 요건 충족시 석명의무 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>손해액의 증명이 없는 경우 적극적 석명(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 불법행위에 기한 손해배상책임은 인정되나 손해액 증명이 없는 경우, 배상액 증명이 없다 하여 청구기각할 것이 아니라 ⅰ) 적극적으로 석명권을 발동하여 증명을 촉구할 의무가 있고 ⅱ) 경우에 따라 직권으로 손해액을 심리·판단해야 함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§202의2</strong></span></span>: 손해발생은 인정되나 구체적 액수 증명이 사안의 성질상 매우 어려운 경우 변론 전체의 취지와 증거조사 결과에 의해 상당한 액수를 인정할 수 있음)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>지적의무의 의의 및 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의와 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">당사자가 간과하였음이 분명한 법률상 사항에 관하여 의견진술 기회를 주어야 하는 법적 의무(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§136④</strong></span></span>) — 요건: ① 당사자가 간과했음이 분명할 것 ② 법률상 사항일 것 ③ 재판의 결과에 영향이 있을 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>지적의무의 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 당사자가 부주의나 오해로 증명하지 않은 것이 분명하거나 쟁점이 될 사항에 관하여 명시적 다툼이 없는 경우에는 석명·증명촉구(소극적 석명)를 해야 하고, 당사자가 전혀 의식하지 못하거나 예상하지 못한 법률적 관점을 이유로 법원이 판단하려는 경우에는 이에 대해 의견진술 기회를 주어야 함(적극적 석명) — <span class=\"cs-fact-tag\"><strong>[사해행위취소소송에서 제척기간 도과가 쟁점된 바 없는데도 이를 이유로 각하한 판결]</strong></span>, <span class=\"cs-fact-tag\"><strong>[대표자 지위 쟁점없이 대표권 부족을 이유로 각하한 항소심 판결]</strong></span>, <span class=\"cs-fact-tag\"><strong>[소멸시효 중단 주장의 취지를 지적하지 않고 예상외 재판을 한 경우]</strong></span>, <span class=\"cs-fact-tag\"><strong>[청구취지 불특정을 간과한 채 본안 공방 후 예상외 재판으로 각하]</strong></span>, <span class=\"cs-fact-tag\"><strong>[대위청구 전제 없이 신의칙 위반을 인정]</strong></span>, <span class=\"cs-fact-tag\"><strong>[종중규약 무효 여부를 쟁점화된 바 없이 직권으로 판단]</strong></span>, <span class=\"cs-fact-tag\"><strong>[보험자대위권과 구상권 혼용]</strong></span>, <span class=\"cs-fact-tag\"><strong>[주위토지통행권 확인 의사 석명 미이행]</strong></span> 모두 지적의무(석명의무) 위반<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>적용 위반의 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">지적의무를 어기고 판결한 경우 절차위배로 확정 전에는 일반적 상고이유(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§423</strong></span></span>)가 되고(지적의무 위반이 판결에 영향을 미칠 것을 요함), 확정 후에는 재심사유 없음<span class=\"cs-x\"><strong>(X)</strong></span>, 당연무효도 아니므로<span class=\"cs-x\"><strong>(X)</strong></span> 유효<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["★★★★"], 1, "mp_3"], ["민소020", "실기한 공격방어방법", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">실기한 공격방어방법을 각하함으로써 당사자에게 적시에 사실자료와 증거자료를 제출하게 하여 소송촉진과 집중심리 적시제출주의의 실효성을 확보하는 법원의 권한</div><div class=\"cs-h\">Ⅱ. 각하요건과 효과</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">요건: ① '적시제출주의를 어기어' 늦게 제출할 것 ② 당사자에게 '고의 또는 중과실'이 있을 것 ③ '공격방어방법'을 늦게 제출할 것 ④ '소송의 완결이 지연'될 것 → 요건을 갖추면 법원은 결정으로 각하 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§149①</strong></span></span>)<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例: 항소심에서 새로운 공격방어방법이 제출된 경우 시기에 늦었는지 여부는 항소심이 속심구조이고 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§149</strong></span></span>가 총칙규정인 점을 고려하여 제1심·제2심을 통관하여 판단해야 함<span class=\"cs-o\"><strong>(O)</strong></span> — 최근판례도 항소심에서 새로운 공격방어방법이 제출된 경우에는 특별한 사정이 없는 한 항소심뿐만 아니라 제1심까지 통틀어 시기에 늦었는지를 판단해야 한다고 보았다<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["★"], 1, "mp_3"], ["민소021", "부인과 항변", "<div class=\"cs-h\">Ⅰ. 부인과 항변의 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">'원고의 청구를 배척하기 위한 피고의 사실상의 진술'인 점에서 항변과 부인은 차이가 없으나, 항변은 원고 주장사실이 '진실함(자백)을 전제'로 이와 '양립가능한 별개사실'을 주장하는 것, 부인은 원고 주장사실이 '진실이 아니라는' '양립불가능한' 사실의 주장이라는 점에서 구별</div><div class=\"cs-h\">Ⅱ. 간접부인과 항변의 구별</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>구별</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">간접부인은 원고의 주장사실과 양립불가능한 별개사실을 진술하는 것<span class=\"cs-o\"><strong>(O)</strong></span> ↔ 항변은 원고의 주장사실이 진실(자백)임을 전제로 이와 양립가능한 사실을 진술하는 것<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>부인과 항변의 구별의 실익 Ⅰ</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[대여금청구소송에서 원고 X가 대여사실을 주장함에 대해 피고 Y가 '甲으로부터 무상증여 받았다'고 주장한 경우]</strong></span>(간접부인) ↔ <span class=\"cs-fact-tag\"><strong>['甲으로부터 면제받았다'고 주장한 경우]</strong></span>(항변)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(증명책임) 무상증여 주장(부인)은 원고가 대여사실의 존재에 대해 증명책임을 지나<span class=\"cs-o\"><strong>(O)</strong></span>, 면제 주장(항변)은 이에 대해 원고가 부인하면 피고가 채무면제사실에 대해 증명책임을 짐<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(판결이유) 무상증여 주장(부인)은 이를 배척해도 판결이유에 설시불필요<span class=\"cs-o\"><strong>(O)</strong></span> ↔ 면제 주장(항변)은 배척시 반드시 판결이유에 설시해야 함<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>부인과 항변의 구별의 실익 Ⅱ - 말소등기청구(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>말소등기청구의 요건사실</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소유권이전등기말소청구는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§214</strong></span></span>의 소유권에 기한 방해제거청구권 → 요건: ① 원고 소유일 것 ② 피고명의의 등기가 있을 것 ③ 위 등기가 원인무효일 것(<span class=\"cs-u\"><strong>법규기준설</strong></span>상 이 요건사실이 주요사실)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>등기명의인의 등기가 원인무효인 사실이 주요사실인 근거 - 등기의 추정력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">현재의 등기명의인은 등기의 추정력으로 인해 적법한 소유권자 및 유효한 대리행위로 법률상 추정 → 증명책임이 전환되어 상대방(원고)이 무권대리라는 사실을 증명해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>피고(등기명의인)의 유권대리 주장의 법적 성격과 근거</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">유권대리 주장은 말소등기청구의 요건사실인 무권대리행위로 인한 원인무효 사실과 '양립불가능'한 사실의 주장으로 부인에 해당<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>피고(등기명의인)의 표현대리 주장의 법적 성격과 근거</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">표현대리 주장은 원고가 요건사실로 주장하는 무권대리 주장을 인정(자백)하면서 무권대리사실과 '양립가능'한 표현대리사실의 주장으로 항변에 해당<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(5) <strong>사례의 결론</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">현재 등기명의인이므로 대리권 존재 및 적법한 소유권자로 법률상 추정 → 증명책임이 전환되어 원고가 등기의 원인무효를 주장·증명해야 함</div>", ["★★"], 1, "mp_3"], ["민소022", "소송상 상계의 항변", "<div class=\"cs-h\">Ⅰ. 상계항변의 특수성(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>문제점</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">[피고가 변제항변·소멸시효항변을 하고, 그것이 받아들여지지 않을 경우에 대비해 예비적으로 상계항변을 하였는데, 법원이 상계항변부터 먼저 심리해 이유 있다고 청구기각판결을 한 경우] 이 판결이 적법한가?</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>순서불구속의 원칙</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">원칙적으로 법원은 당사자의 사실상 주장을 심판함에 있어 당사자가 정한 순서에 구속되지 않음<span class=\"cs-o\"><strong>(O)</strong></span> → 예비적 주장·항변의 경우 법원은 그 어느 것을 선택하여 당사자를 승소시켜도 무방<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>상계항변 최후판단</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 소송상 방어방법으로서의 상계항변은 통상 수동채권의 존재가 확정되는 것을 전제로 하여 행하는 예비적 항변<span class=\"cs-o\"><strong>(O)</strong></span> → 근거: ⅰ) 판결이유 중에서 판단되지만 기판력이 생김(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§216②</strong></span></span>) ⅱ) 피고의 반대채권이 함께 소멸되는 출혈적 항변 ⅲ) 상계항변은 최후에 판단해야 함<span class=\"cs-o\"><strong>(O)</strong></span> → <span class=\"cs-fact-tag\"><strong>[변제·소멸시효항변을 판단하지 않고 상계항변부터 판단해 청구기각한 위 판결]</strong></span>은 상계항변의 특수성을 무시한 판단누락의 위법한 판결<span class=\"cs-o\"><strong>(O)</strong></span> → 확정전 상소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§424①</strong></span></span>6호), 확정후 재심(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>9호 판단누락)으로 취소 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 소송상 형성권의 행사(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>문제점</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">사법상의 형성권 행사를 소송상 항변으로 동시에 행사하는 경우, 형성권의 사법상 효과가 발생하여 존속하는지 문제 — 특히 소송상 상계항변이 소취하·소각하, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§149</strong></span></span>의 실기한 항변으로 각하된 경우에 상계의 사법상 효과가 발생하여 존속하는지 문제</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례의 입장(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: (해제의 항변은 병존설) 소송상 해제의 항변을 한 경우, 소를 취하하여도 해제권은 형성권이므로 사법상 행사의 효력에 영향 없음<span class=\"cs-o\"><strong>(O)</strong></span> ↔ (상계의 항변은 신병존설) 소송상 상계의 의사표시에 의해 확정적으로 효과가 발생하는 것이 아니라 당해 소송에서 수동채권의 존재 등 상계에 관한 법원의 실질적 판단이 이루어지는 경우에 실체법상 상계의 효과 발생<span class=\"cs-o\"><strong>(O)</strong></span> → <span class=\"cs-neg-tag\"><strong>[소송절차 진행 중 조정이 성립되어 수동채권 존부에 관한 법원의 실질적 판단이 이루어지지 않은 경우]</strong></span>에는 그 소송절차에서 행해진 소송상 상계항변의 사법상 효과도 발생<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 소송상 상계의 항변에 대한 소송상 상계의 재항변(★) - 소극</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">소송상 상계항변에 대해 원고가 다시 피고의 자동채권을 소멸시키기 위해 소송상 상계의 재항변을 하는 경우, (상계항변 배척시) 법원이 재항변과 무관한 사유로 상계항변을 배척하면 재항변 판단 불필요, (상계항변 인용시) 상계적상 당시 대등액에서 이미 소멸되어 재항변 대상채권이 그 범위에서 존재하지 않게 되어 마찬가지로 재항변 판단 불필요 → 피고의 소송상 상계항변에 대해 원고가 소송상 상계의 재항변을 하는 것은 허용<span class=\"cs-x\"><strong>(X)</strong></span></div>", ["★★★"], 1, "mp_3"], ["민소023", "소송행위", "<div class=\"cs-h\">Ⅰ. 소송상의 합의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>명문의 규정이 있는 경우 소송상 합의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">관할의 합의(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§29</strong></span></span>), 불항소합의(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§390①</strong></span></span>단서) 등은 명문의 규정이 있으므로 당연히 허용<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>명문의 규정이 없는 경우 소송상 합의(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>허용여부 및 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(허용여부) 判例: 강행규정을 배제하는 합의는 무효<span class=\"cs-x\"><strong>(X)</strong></span>이지만, 의사결정의 자유가 확보된 소송행위에 관한 계약은 허용<span class=\"cs-o\"><strong>(O)</strong></span>한다는 제한적 허용설의 입장 — (요건) 부제소특약이 효력이 있으려면 ⅰ) 합의 당사자가 처분할 수 있는 권리범위 내일 것 ⅱ) 특정한 법률관계에 한정된 합의일 것 ⅲ) 그 합의 시 예상할 수 있는 상황에 관한 것일 것 ⅳ) 불공정하지 아니할 것을 요함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>법적성질</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 소송상 합의를 소송상의 사항에 관하여 약정대로 작위·부작위의무를 발생케 하는 사법상의 계약으로 보는 사법계약설의 입장<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>소송상 합의 위반 시 구제방법</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 부제소특약과 소취하계약을 어긴 경우 '권리보호의 이익이 없다'고 보아 소각하해야 한다는 항변권발생설(본안전 항변)에 의함<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>부제소특약이 직권조사사항인지 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: '부제소 합의'의 경우 이에 위배되어 제기된 소는 권리보호의 이익이 없고, 부제소합의에 위배되어 제기된 경우 법원은 직권으로 소의 적법 여부를 판단할 수 있다고 하여 직권조사사항<span class=\"cs-o\"><strong>(O)</strong></span>으로 본다</div><div class=\"cs-h\">Ⅱ. 소송행위의 의사표시 하자 및 철회</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>민법의 의사표시 하자에 관한 규정을 유추적용하여 취소할 수 있는지 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 민사소송법상 소송행위에는 민법상 법률행위에 관한 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§109</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§110</strong></span></span>의 규정이 적용될 여지가 없으므로 사기·강박 또는 착오 등 의사표시의 하자를 이유로 그 무효나 취소를 주장할 수 없다<span class=\"cs-x\"><strong>(X)</strong></span>고 하여 원칙적으로 소송행위에는 의사표시 하자에 관한 민법규정이 적용되지 않는다는 의사표시하자불고려설의 입장<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송행위의 철회(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>소송행위 철회의 자유 및 제한</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(철회의 자유) 소송행위는 처분권주의·변론주의가 적용되므로 변론종결시까지 원칙적으로 신청·주장·증거신청 등을 자유롭게 철회 가능<span class=\"cs-o\"><strong>(O)</strong></span> — (철회의 제한) 단, 상대방에게 '유리한 법률상 지위'가 형성된 소송행위, 즉 '구속적 소송행위'는 절차의 안정을 위해 철회 불가<span class=\"cs-x\"><strong>(X)</strong></span> — ⅰ) 피고가 응소한 뒤의 소의 취하 ⅱ) 재판상 자백의 철회 ⅲ) 증거조사개시 후의 증거신청의 철회 등은 제한<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>소송행위의 철회 제한의 예외</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>5호의 형사처벌행위의 유추적용 여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 소취하 등 소송행위가 사기·강박 등 '형사상 처벌받을 행위'로 이뤄진 경우에는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>5호를 유추적용하여 소송행위의 효력을 부인할 수 있다<span class=\"cs-o\"><strong>(O)</strong></span>고 본다</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 형사상 처벌받을 행위에 유죄판결의 확정이 필요한지 여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: (사기) 소송행위가 타인의 사기·강박 등 형사상 처벌 행위로 인한 경우 ⅰ) 그 타인의 행위에 대해 유죄판결이 확정되고 ⅱ) 또 소송행위에 부합되는 의사 없이 외형적으로만 존재할 때에 한하여 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>5호, 동조 ②을 유추적용하여 효력을 부인할 수 있다는 유죄확정판결필요설의 입장<span class=\"cs-o\"><strong>(O)</strong></span> ↔ (강박) 예외적으로 강요와 폭행에 의한 소 취하는 무효이므로 '유죄의 확정판결 없이' 소 취하의 효력을 부인할 수 있음<span class=\"cs-o\"><strong>(O)</strong></span> / (착오) ⅰ) 소의 취하는 소송행위로 사법상 행위와 달리 내심의 의사보다 그 표시를 기준으로 효력 유무를 판정할 수밖에 없는바 ⅱ) 소송대리인 사무원의 착오는 소송대리인의 착오로 보아야 하므로 사무원의 착오로 원고들 전원의 소를 취하하였다 하더라도 이를 무효로 볼 수 없고 ⅲ) 적법한 소 취하 서면이 제출된 이상 그 서면이 상대방에게 송달되기 전·후를 묻지 않고 원고는 이를 임의로 철회할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 배임에 의한 항소취하의 철회 가부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ⅰ) (상소취하) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>5호를 유추적용하여 형사상 처벌받을 다른 사람의 행위로 항소 취하를 한 경우에도 재심사유가 됨 ⅱ) (대리인의 배임죄) 형사상 처벌받을 다른 사람의 행위에는 당사자의 대리인이 한 배임도 포함되나, 대리인의 배임행위가 '소송행위 효과를 당사자 본인에게 귀속시키는 것이 절차적 정의에 반하여 도저히 수긍할 수 없다'고 볼 정도로 대리권에 실질적인 흠이 발생한 경우라야 함 ⅲ) (재심사유 인정사례) 대표이사가 자기 이익을 위해 임무를 위반하여 회사에 불이익한 것을 알면서도 전부패소한 제1심판결에 항소하였다가 업무상배임죄로 유죄확정된 경우 → <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>5호에 준하는 재심사유 인정<span class=\"cs-o\"><strong>(O)</strong></span> ⅳ) (항소취하의 효력) 항소취하가 재심사유가 있다고 인정되는 경우 항소취하는 효력 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 상대방의 동의</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">피고가 본안에 응소한 후의 소의 취하는 제한되지만 피고가 동의한 때에는 소 취하 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§266②</strong></span></span>) / 증거조사개시 후의 증거신청 철회, 재판상의 자백의 취소도 상대방이 동의하면 허용<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송행위의 효력을 다투는 방법(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소송행위의 효력을 다투는 방법은 별소제기와 당해절차에서의 기일지정신청이 있음 — (당해절차) '당해절차'에서 소 취하의 효력을 다투는 방법으로 민사소송규칙<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67</strong></span></span>의 변론기일지정을 신청하는 방법이 있음 → 당사자 신청시 법원은 필요적으로 변론기일을 정하여 심사 → <span class=\"cs-fact-tag\"><strong>[소 취하의 효력을 부인하게 되면]</strong></span> 구소가 부활하여 심리가 속행되고, 이 판단은 중간판결이나 종국판결의 이유에서 내려지며, <span class=\"cs-fact-tag\"><strong>[소의 취하의 하자가 인정되지 않으면]</strong></span> 법원은 '소송종료선언'을 내림<span class=\"cs-o\"><strong>(O)</strong></span> — (별소제기) 별소제기하는 방법으로 '무효확인의 소'를 제기하는 방법과 같은 청구를 소송물로 하는 별개의 소를 제기하는 방법이 있음</div>", ["★★"], 1, "mp_3"], ["민소024", "결석", "<div class=\"cs-h\">Ⅰ. 출석강제의 3간주</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">민소법은 ① 양쪽 당사자 모두 결석할 경우에는 이른바 소의 취하간주(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§268</strong></span></span>) ② 당사자 일방의 결석의 경우에는 가) 진술간주(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§148</strong></span></span>)와 나) 자백간주(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§150</strong></span></span>) 규정을 두어 당사자가 결석한 경우 일정한 불이익(또는 제재)을 주어 대처함</div><div class=\"cs-h\">Ⅱ. 당사자의 결석 요건(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">요건: ① 필요적 변론기일에 ② 당사자가 적법한 기일통지를 받고도 ③ 불출석하거나 출석하여도 변론을 하지 않는 경우일 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例: 공시송달에 적법요건의 흠이 있어 부적법하더라도 공시송달의 효력은 유효<span class=\"cs-o\"><strong>(O)</strong></span> ↔ 공시송달이 부적법한 경우에는 불출석이 인정될 수 없어<span class=\"cs-x\"><strong>(X)</strong></span> 기일불출석에 따른 쌍불취하의 효과까지 인정할 수는 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 소의 취하간주(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소의 취하간주의 의의 및 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 양쪽 당사자가 변론기일에 1회 불출석하거나 출석·무변론이었을 것 ② 양쪽 당사자가 1회 불출석 후의 신기일 또는 그 뒤의 기일에 불출석하거나 출석·무변론이었을 것(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§268②</strong></span></span>) ③ 양쪽 당사자의 2회 결석 이후 1개월 내에 당사자가 기일지정신청을 하지 않으면 소의 취하가 있는 것으로 본다(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§268②</strong></span></span>) ④ 기일지정신청에 의해 정한 기일 또는 그 후의 기일에 양쪽 당사자가 3회 결석한 경우에도 소의 취하가 있는 것으로 본다(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§268③</strong></span></span>) ⑤ 동일 심급의 동종 기일에 2회 또는 3회 결석일 것을 요함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">⑥ 判例: 변론준비기일에서 쌍방불출석의 효과가 변론기일에 승계되는지 여부에 관하여 ⅰ) 법에는 별도 규정이 없고 ⅱ) 변론준비기일이 비공개로 진행될 수 있어 직접주의·공개주의가 후퇴되는 점에서, 변론준비기일에서의 쌍방불출석 효과는 변론기일에 승계되지 않는다<span class=\"cs-x\"><strong>(X)</strong></span>고 본다</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소의 취하간주의 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">제1심에서 양쪽 당사자의 기일해태가 있으면 소취하간주로 본다 → 법률상 당연히 발생하는 것이므로 당사자나 법원의 의사로 그 효과를 좌우할 수 없음<span class=\"cs-o\"><strong>(O)</strong></span> / 항소심에서 양쪽 당사자의 기일해태가 있는 경우 '항소 취하'로 간주되어 항소심 절차는 종결되고, 제1심판결은 확정된다(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§268④</strong></span></span>)</div><div class=\"cs-h\">Ⅳ. 진술간주(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의 및 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 변론기일 또는 변론준비기일에 당사자 일방이 결석할 것 ② 결석한 당사자가 소장·답변서·준비서면 등의 서면을 제출할 것을 요건으로 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>상대방 주장사실에 대하여 서면에서 ① (자백) 자백한 경우에는 재판상의 자백이 성립 ② (자백간주) 명백히 다투지 않은 경우에는 자백간주가 되어 증거조사 없이 변론을 종결할 수 있고 ③ (부인) 주장사실을 다투는 경우에는 증거조사를 해야 하므로 속행기일의 지정이 필요 ④ (법원의 재량) 이때 진술간주의 규정을 적용하여 변론을 진행하느냐 다음 기일로 연기하느냐는 법원의 재량</strong><span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>判例: 상대방 주장사실을 인정하는 서면을 제출하고 결석한 경우 진술간주로 재판상 자백이 되는지 여부에 관하여, 변론에서 진술된 경우뿐 아니라 자백하는 취지의 서면이 진술간주되어도 재판상 자백이 성립</strong><span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>한계</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(변론관할 진술간주 부정) 관할권 없는 법원에 제소한 때 피고가 본안에 관한 사실을 기재한 답변서만을 제출한 채 불출석한 경우 그것이 진술간주되어도 변론관할(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§30</strong></span></span>)이 생기는 것은 아님<span class=\"cs-x\"><strong>(X)</strong></span> — (증거신청 진술간주 부정) 준비서면에 증거를 첨부하여 제출하였을 때 그 서면이 진술간주되어도 증거신청의 효과는 생기지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>청구인낙의 진술간주(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">종래판례: 피고가 변론기일에 출석하여 구술로써 인낙하지 아니한 이상 인낙의 효력 불발생<span class=\"cs-x\"><strong>(X)</strong></span> ↔ <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§148②</strong></span></span> 신설: 일방 당사자가 불출석하여 '진술간주되는 답변서 그 밖의 준비서면'에 청구의 인낙의 의사표시가 적혀 있고 '공증사무소의 인증'을 받은 때에는 그 취지에 따라 청구의 인낙이 성립된 것으로 본다<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅴ. 자백간주(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의 및 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 통상의 송달(공시송달 제외)에 의해 기일통지를 받았을 것 ② 준비서면 등을 제출하지 아니하였을 것 ③ 기일에 불출석하였을 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 상대방의 주장사실을 자백한 것으로 간주되며 원·피고 쌍방에게 동일하게 적용 ② 자백간주되면 재판상 자백과 같이 법원에 대한 구속력이 생기지만 ③ 재판상 자백과 달리 당사자에 대한 구속력은 생기지 않음(철회 가능)</div><div class=\"cs-h\">Ⅵ. 변론재개(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① 변론이 종결된 후라도 심리미진이 있거나 필요하다고 인정할 때에는 법원은 자유재량으로 변론을 재개할 수 있다(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§142</strong></span></span>) ② 判例: ⅰ) 변론재개신청을 한 당사자에게 책임을 지우기 어려운 사정으로 주장·증명을 제출할 기회를 제대로 갖지 못하였고 ⅱ) 그 주장·증명의 대상이 판결의 결과를 좌우할 수 있는 관건적 요증사실에 해당하는 경우 ⅲ) 석명·지적의무를 위반한 경우 ⅳ) 재심사유 등과 같이 ⅴ) 그 주장·증명을 제출할 기회를 주지 않은 채 패소의 판결을 하는 것이 절차적 정의에 반하는 경우에는 예외적으로 법원은 변론재개의무가 있다<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["★"], 1, "mp_3"], ["민소025", "송달", "<div class=\"cs-h\">Ⅰ. 추후보완(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의 및 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">요건: ① 당사자가 책임을 질 수 없는 사유로 불변기간을 지키지 못했을 것 ② 그 사유가 없어진 날부터 '2주 이내'에 게을리한 소송행위를 보완할 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>추후보완사유 - 당사자가 책임을 질 수 없는 사유로 불변기간을 지킬 수 없었을 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>당사자가 책임질 수 없는 사유</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">천재지변·불가항력 외에도 일반인의 주의와 능력을 다해도 피할 수 없었던 사유를 말함 — 判例: <span class=\"cs-neg-tag\"><strong>[소송대리인이 판결정본 송달을 받고도 당사자에게 알리지 않아 당사자가 상고기간 경과 후 그 사실을 알게 된 경우]</strong></span> 책임질 수 없는 사유에 해당하지 않음<span class=\"cs-x\"><strong>(X)</strong></span> ↔ <span class=\"cs-fact-tag\"><strong>[조정불성립 후 피신청인이 주소변경신고를 하지 않은 상태에서 소송으로 이행되어 발송송달·공시송달된 경우]</strong></span>(처음부터 적법히 송달된 경우와 달라 조사의무 없음) 책임질 수 없는 사유<span class=\"cs-o\"><strong>(O)</strong></span> / <span class=\"cs-fact-tag\">[당사자가 소송계속 중 수감되었는데 법원이 판결정본을 <span class=\"cs-u\">§182</span></span>에 의해 교도소장에게 송달하지 않고 공시송달한 경우]<strong> 공시송달 요건을 갖추지 못해도 송달 자체는 유효</strong><span class=\"cs-o\"><strong>(O)</strong></span><strong>하나, 수감자는 과실 없이 판결을 알지 못한 것이므로 추완상소 가능</strong><span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>공시송달의 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 공시송달사실에 대해 ① 수송달자의 부지와 ② 부지에 대한 무과실(소송계속사실을 알았으면 과실 O, 모르면 과실 X)이 있으면 추후보완 허용<span class=\"cs-o\"><strong>(O)</strong></span> — 피고가 소송을 회피할 목적으로 의도적으로 송달을 받지 아니하거나 주소신고까지 해두고도 장기간 방치한 사정 등은 과실 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例(<span class=\"cs-u\"><strong>원칙 추후보완 허용</strong></span>): 처음부터 공시송달된 경우 신청인은 과실 없이 판결의 송달을 알지 못한 것으로 추후보완 허용<span class=\"cs-o\"><strong>(O)</strong></span> ↔ <span class=\"cs-u\"><strong>예외 추후보완 불허</strong></span>: <span class=\"cs-fact-tag\"><strong>[원고가 스스로 신고한 주소로 송달되지 않아 공시송달된 경우]</strong></span>, <span class=\"cs-fact-tag\"><strong>[피고가 회피목적으로 허위주소를 기재하여 공시송달에 이른 경우]</strong></span>, <span class=\"cs-neg-tag\"><strong>[소송 진행 도중 송달불능으로 공시송달에 이른 경우]</strong></span>(소송진행상황을 조사할 의무 있음) → 모두 과실 인정, 추후보완 불허<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>추후보완기간 - 그 사유가 없어진 날부터 2주 이내</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>사유가 없어진 날의 의미 - 장애사유 종료</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">천재지변 등 사유의 경우에는 재난이 없어진 때, 판결의 송달을 과실 없이 알지 못한 경우에는 당사자나 소송대리인이 판결이 있었던 것을 안 때를 말함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>공시송달의 경우 종료의 의미(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 공시송달된 사실을 안 때 - 원칙</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">공시송달에 의한 판결의 송달사실을 과실 없이 알지 못한 경우에는 당사자 등이 '판결이 있었던 사실'을 안 때가 아니라<span class=\"cs-x\"><strong>(X)</strong></span>, '판결이 공시송달의 방법으로 송달된 사실을 안 때'(당해사건기록 열람 또는 새로이 판결정본을 영수한 때)를 기준<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 판결이 있었던 사실을 안 때(★) - 예외</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 피고가 ⅰ) 당해판결이 있었던 사실을 알았고 ⅱ) 사회통념상 경위에 대하여 당연히 알아볼 만한 특별한 사정이 있었다고 인정되는 경우에는 그 경위에 대해 알아보는 데 ⅲ) 통상 소요되는 시간이 경과한 때(2주)에 ⅳ) 판결이 공시송달의 방법으로 송달된 사실을 알게 된 것으로 추인하여 책임질 수 없는 사유가 소멸(2주+2주=4주 내 추완항소 가능)</div><div class=\"cs-h\">Ⅱ. 송달실시 방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>교부송달의 원칙</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">교부송달이란 송달받을 사람에게 직접 서류의 등본·부본을 교부하는 방법 → 원칙(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§178</strong></span></span>) — '송달장소'는 ⅰ) 사람의 주소 등에서의 교부송달과 ⅱ) 근무장소에서의 교부송달이 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>보충송달에서 근무장소의 의미(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 주소를 알지 못하거나 그곳에서 송달할 수 없을 때에는 '근무장소'에서 송달 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§183②</strong></span></span>), 이때 근무장소란 고용계약 등 법률상 행위로 취업하고 있는 지속적 근무장소를 말함<span class=\"cs-o\"><strong>(O)</strong></span> → <span class=\"cs-neg-tag\"><strong>[다른 주업을 가진 비상근이사·사외이사에게 회사본점소재지]</strong></span>는 지속적 근무장소<span class=\"cs-x\"><strong>(X)</strong></span> → 그곳에서 수령해도 보충송달로서 효력<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법인의 주소지로 소장 부본의 보충송달과 공시송달의 적법 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 법인은 먼저 그 사무소에 송달하고 송달불능이 되면 대표자 주소에 송달하고 그곳도 송달불능이 될 때 주소보정을 명해야 하므로, 법인 주소지로 소장부본을 송달하였다가 송달불능되었다는 이유만으로 주소보정을 명한 것은 잘못<span class=\"cs-x\"><strong>(X)</strong></span>이며, 대표자 주소로 교부송달이 가능함에도 송달불능을 이유로 한 공시송달명령은 공시송달의 보충성에 반하여 위법<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>주소 등에서의 보충송달의 의의 및 송달의 효력발생시기</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">주소 등에서 송달받을 사람을 만나지 못한 때에는 사무원·피용자·동거인으로 사리분별지능 있는 자에게 교부 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§186①</strong></span></span>) → 교부시 송달효력 발생, 실제 전달여부는 영향<span class=\"cs-x\"><strong>(X)</strong></span> — 判例: '사무원'은 고용관계 불필요하고 평소 본인을 위해 사무를 보조하는 자면 족<span class=\"cs-o\"><strong>(O)</strong></span> / '법률상 배우자'는 동거인으로 인정<span class=\"cs-o\"><strong>(O)</strong></span> ↔ 별거·혼인공동체 실체 소멸 등 특별한 경우에는 동거인 지위 부정 가능(이 경우 심리 필요, 송달무효)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>보충송달 장소(★) - 우체국 창구에서 동거자에게 교부한 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 보충송달은 법이 정하는 송달장소에서만 허용되고 송달장소 아닌 곳에서 교부하는 것은 부적법<span class=\"cs-x\"><strong>(X)</strong></span> → 우체국 창구에서 동거자에게 서류를 교부한 것은 부적법한 보충송달<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>상반된 이해관계가 있는 수령대행인에 대한 보충송달의 효력(★) - 무효</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 본인과 수령대행인 사이에 당해 소송에 관해 이해대립 관계가 있을 때에는 전달 기대 불가, 쌍방대리금지원칙에도 반하므로 보충송달 불가<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>동일한 수령대행인이 쌍방을 대신하여 동시에 받은 보충송달의 효력(★) - 원칙적 무효</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 동일한 수령대행인이 이해대립되는 쌍방을 대신하여 소송서류를 동시에 수령하면 상대방에게 제대로 전달될 것이라고 기대하기 어렵고 쌍방대리금지 원칙에도 반하므로 무효<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>유치송달</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">유치송달이란 수령자가 정당한 사유 없이 수령을 거부할 때 송달장소에 서류를 놓아두는 것(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§186③</strong></span></span>) — ⅰ) 본인·대리인의 거부뿐 아니라 ⅱ) 사무원·피용자·동거인의 거부에도 가능<span class=\"cs-o\"><strong>(O)</strong></span> — 근무장소에서 보충송달받을 수 있는 사람에게는 유치송달 불가<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>발송송달(우편송달)의 의의와 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">보충송달·유치송달로 송달할 수 없는 경우(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§187</strong></span></span>) 법원사무관이 서류를 등기우편으로 발송하면 되는 송달 — 判例: 우편송달은 당해 서류에 교부·보충·유치송달이 불가능할 것을 요건으로 하므로 그 서류에 한하여 할 수 있을 뿐 별개의 서류 송달에 이 요건이 따로 구비되지 않는 한 당연히 우편송달을 할 수 있는 것은 아님<span class=\"cs-x\"><strong>(X)</strong></span> / (발송송달 무효) 수감된 당사자에 대한 송달을 교도소장 등에게 하지 않고 당사자의 종전 주소나 거소로 한 것은 부적법한 송달로서 무효<span class=\"cs-x\"><strong>(X)</strong></span>(법원이 수감사실을 몰랐거나 서류 내용을 알았더라도 마찬가지), 소송대리인이 있어 실제 송달받은 적이 없는 당사자에게 소장기재 주소가 송달불능이라는 이유로 한 발송송달도 요건미구비로 무효<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>전자소송에서의 송달</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(확인시) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민소전자문서법§11④</strong></span></span>에 따라 수령자가 등재 전자문서를 확인한 때 송달<span class=\"cs-o\"><strong>(O)</strong></span>, (불확인시 1주뒤) 등재사실 통지받은 날부터 1주 이내 미확인시 통지일부터 1주 경과한 날에 송달<span class=\"cs-o\"><strong>(O)</strong></span> — 상소기간은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§157</strong></span></span>단서에 따라 송달효력 발생 당일부터 초일산입해 기산(2주) / (전자소송 동의시 소송대리인만 수령권, 비동의시 당사자와 소송대리인 둘 다 수령권) 당사자가 전자소송 진행에 동의해도 소송대리인이 있으면 전자적 송달은 소송대리인에게 하여야 함 — 동의하지 않은 당사자는 소송대리인이 있어도 본인 고유의 소송수행권을 잃지 않으므로 본인에게 우편을 보내도 적법<span class=\"cs-o\"><strong>(O)</strong></span>, 당사자와 소송대리인 모두 송달된 경우 먼저 도달한 것 기준으로 효력 판단</div><div class=\"cs-h\">Ⅲ. 공시송달(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의와 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공시송달이란 당사자의 주소 등을 알 수 없어 통상의 송달방법으로 송달을 실시할 수 없게 된 때 하는 송달 — 개정 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§194④</strong></span></span>: 원고가 소권(항소권 포함)을 남용하여 청구가 이유 없음이 명백한 소를 반복적으로 제기하여 법원이 변론 없이 판결로 소를 각하하는 경우에는 재판장이 직권으로 피고에 대해 공시송달을 명할 수 있음 — 요건: ① 당사자의 주소 등 또는 근무장소를 알 수 없는 경우와 외국에서 해야 할 송달에 관해 촉탁송달이 어려울 것(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§194①</strong></span></span>) ② 다른 송달방법이 불가능할 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 공시송달은 주소 등 송달장소를 알 수 없는 경우에만 가능, 법원이 송달장소는 알지만 폐문부재로 송달되지 않은 경우에는 공시송달불가<span class=\"cs-x\"><strong>(X)</strong></span>(발송송달 가능하기 때문) ↔ 송달받을 사람이 주소나 거소를 떠나 더이상 송달장소로 인정하기 어려워진 경우는 '송달할 장소를 알 수 없는 경우'에 해당<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>공시송달의 경우 소송절차의 진행(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공시송달에 의해 소송절차가 진행되는 경우, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§150③</strong></span></span>의 자백간주 법리와 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§257</strong></span></span>의 무변론판결 규정이 적용<span class=\"cs-x\"><strong>(X)</strong></span> → 법원은 변론기일을 열어야 하며, 공시송달받은 피고가 변론기일에 불출석하더라도 원고에게 변론을 명해야 하고, 이에 따라 원고는 일체의 주요사실에 관하여 주장·증명해야 하며, 법원은 그 결과에 따라 판결을 하여야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>공시송달의 효력과 구제수단(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(공시송달 자체의 하자) 공시송달요건에 흠이 있다 하더라도 재판장이 공시송달을 명하여 절차를 취한 경우에는 유효한 송달<span class=\"cs-o\"><strong>(O)</strong></span> → (구제수단) 판결정본이 공시송달된 경우 요건에 흠이 있더라도 그 공시송달은 유효하므로 항소기간이 진행하며, 그 기간의 도과로 판결은 형식적으로 확정 → 패소당사자는 추후보완항소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§173</strong></span></span>)나 재심(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>11호)으로 구제 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(송달 일반의 하자) <span class=\"cs-gbg\"><strong>[당사자가 변론종결 후에 사망한 상태에서 판결이 선고된 경우]</strong></span> 망인에 대한 판결정본의 공시송달은 무효<span class=\"cs-x\"><strong>(X)</strong></span> → 송달 일반의 무효사유가 있는 경우 공시송달로 이루어졌다 해도 '무효' → (구제수단) 상소기간이 진행하지 않아 판결이 확정되지 않고 기판력도 미발생 → 항소제기나 별소제기로 구제 가능</div><div class=\"cs-h\">Ⅳ. 송달의 하자와 치유</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>송달의 하자</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">법이 정한 방식에 위배된 경우 예: ⅰ) 송달받을 사람 아닌 자에게 송달 ⅱ) 수령권자 아닌 자에게 송달 ⅲ) 송달장소 아닌 곳에서 송달 ⅳ) 보충송달·유치송달을 해보지도 않고 하는 우편송달 등은 무효<span class=\"cs-o\"><strong>(O)</strong></span> — 단, ⅰ) 공시송달 요건에 흠이 생긴 경우 ⅱ) 수령권자 아닌 자가 교부받아 동거자에게 전달한 경우에는 송달이 유효<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>하자의 치유</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 송달규정이 임의규정인 경우(소장이나 소송서류 등의 송달) 그 송달에 하자가 있으면 원칙적으로 무효라도 이의 없이 변론하거나 수령하면 이의권의 포기·상실로 하자가 치유<span class=\"cs-o\"><strong>(O)</strong></span> ② 송달규정이 강행규정인 경우(상소기간의 기산점이 되는 판결정본의 송달) 송달에 하자가 있으면 무효<span class=\"cs-o\"><strong>(O)</strong></span> — 단, 이 경우에도 송달받을 자가 추인하면 유효하게 됨<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>허위주소송달(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>법원의 소송절차 진행</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[피고의 주소를 허위로 기재하여 제3자가 수령하여 통상의 송달이 된 경우]</strong></span> ⅰ) 소장송달 받은 후 30일 내 답변서 미제출을 이유로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§257①</strong></span></span>에 의해 무변론원고승소판결 선고 가능<span class=\"cs-o\"><strong>(O)</strong></span> ⅱ) 원고승소판결하기에 부족한 경우는 법원이 변론기일을 지정하게 되고, 원고는 출석하나 피고는 불출석하여 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§150③</strong></span></span> 자백간주로 취급하여 변론 진행</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>허위주소송달의 효력 및 구제책</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 허위주소송달은 피고가 송달받지 않았으므로 그 송달은 무효<span class=\"cs-o\"><strong>(O)</strong></span> → 판결정본 송달도 무효로 보므로 (상소제기) 항소기간이 진행하지 않아 판결이 확정되지 않으므로 피고는 언제든지 항소를 제기하여 구제받을 수 있고(기간의 정함이 없는 항소, 단 실효의 원칙 적용 가능), (별소제기) 기판력도 발생하지 않으므로 별소를 제기하여 구제받을 수도 있음</div>", ["★★★"], 1, "mp_3"], ["민소026", "소송절차의 중단 - 소송계속 중 사망", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">소송절차의 중단이란 당사자에게 소송수행을 할 수 없는 사유가 발생한 경우에 새로운 소송수행자가 소송에 관여할 수 있을 때까지 법률상 당연히 절차의 진행이 정지되는 것</div><div class=\"cs-h\">Ⅱ. 당사자 지위의 당연승계 인정 여부(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(당연승계인정설): 소송 도중 당사자 일방이 사망한 경우 그때부터 소송은 사망자의 상속인들과의 관계에서 대립당사자구조를 형성하여 존재하게 되는 것이므로 소송계속 중 사망 등 포괄승계가 있으면 소송상 당사자 지위도 당연히 승계<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅲ. 소송절차의 중단(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>중단의 의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">당사자에게 소송수행을 할 수 없는 사유가 발생한 경우 새로운 소송수행자가 소송에 관여할 수 있을 때까지 법률상 당연히 절차 진행이 정지되는 것(당사자의 절차관여권 보장이 취지)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>중단의 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">요건: ① 소송계속 중 당사자가 사망(실종선고에 의한 사망간주 포함)할 것 ② 소송대리인이 없을 것(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§238</strong></span></span>) ③ 상속인이 있을 것 ④ 소송물이 상속의 대상이 될 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>중단의 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">법원이나 당사자가 이를 알았는지 여부와 관계없이 당연히 중단<span class=\"cs-o\"><strong>(O)</strong></span> — 통상공동소송(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§66</strong></span></span>, 공동소송인독립의 원칙)은 사망한 당사자와 상대방 간에서만 중단<span class=\"cs-o\"><strong>(O)</strong></span> ↔ 필수적 공동소송(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67③</strong></span></span> 합일확정의 원칙)은 당사자 전원에 대해 중단<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>중단의 효과 - 중단 중 소송행위 가부와 효력과 하자치유</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§247①</strong></span></span>은 판결의 선고는 소송절차가 중단된 중에도 할 수 있다고 규정 → 중단 중에는 판결의 선고를 제외한 일체의 소송행위 불가<span class=\"cs-x\"><strong>(X)</strong></span> — 중단 중 소송행위는 ⅰ) 소송절차 중단을 간과한 절차상 위법(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§233</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§247</strong></span></span> 위반 간과)과 ⅱ) 대리권 흠결을 간과한 위법이 있음 → 소송절차의 중단에 관한 규정은 임의규정이므로 중단을 간과한 절차상 위법을 명백히 다투지 않는 한 이의권의 포기·상실로 하자가 치유 가능<span class=\"cs-o\"><strong>(O)</strong></span>, 대리권 흠결은 직권조사사항(강행규정)이므로 이의권상실의 대상이 아니지만<span class=\"cs-x\"><strong>(X)</strong></span>, 상속인의 추인에 의해 하자가 치유될 수 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>중단의 예외 - 소송대리인이 있는 경우(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§238</strong></span></span><strong>)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">중단사유가 발생하여도 소송대리인이 있으면 소송절차는 중단되지 않음<span class=\"cs-x\"><strong>(X)</strong></span> — 중단사유가 발생해도 대리권은 소멸되지 않으므로(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§95</strong></span></span>) 소송대리인에 의해 절차관여권이 보호될 수 있기 때문 → 소송대리인은 새로이 수권받을 필요 없이 법률상 당연히 상속인의 소송대리인이 되므로 상속인이 수계신청을 하든 안 하든 '판결의 효력'은 상속인에게 미침<span class=\"cs-o\"><strong>(O)</strong></span> — 소송절차가 중단되지 않으므로 중단을 해소하는 의미의 수계신청은 불필요하지만, 상속인 등의 수계신청은 '표시정정신청'의 의미를 가짐</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>중단사유</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>당사자의 사망</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>당사자의 소송능력상실, 법정대리인의 사망, 대리권의 소멸</strong></div><div class=\"cs-h\">Ⅳ. 수계신청(★) - 중단의 해소</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">수계신청이란 중단사유가 있는 당사자 측에서 중단된 절차가 계속 진행되도록 속행을 구하는 신청 — 判例: 공동상속재산에 관한 소송은 공유자들의 통상공동소송관계이므로 상속인들이 개별적으로 수계신청해도 되고, 상속인 중 한 사람만이 수계신청한 경우 수계신청하지 않은 다른 상속인의 소송관계는 중단된 채 제1심에 그대로 계속된다<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>수계신청법원</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>원칙 - 중단 당시 소송이 계속된 법원(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§243</strong></span></span><strong>)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소송계속 중 사망으로 중단되고 이를 알고 상속인이 수계신청하는 경우, 원칙적으로 중단 당시 소송이 계속된 법원에 해야 함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§243②</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>예외 - 상소심법원에도 수계신청을 할 수 있는지 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 문제점: ① 종국판결이 송달된 뒤에 중단된 경우와 ② 소송계속 중 사망하여 중단되었음에도 이를 간과하고 판결이 선고되어 송달된 경우에 수계신청을 원심법원에만 해야 하는지 상소심법원에 해도 되는지 견해 대립</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 判例의 입장(선택설): 소송계속 중 사망을 간과하고 판결이 선고된 경우 ⅰ) 원심법원에 수계신청하여 판결을 송달받아 상고하거나 ⅱ) 판결을 송달받아 상고장을 제출하고 상고심에서 수계신청을 한 경우에도 수계와 상고는 적법<span class=\"cs-o\"><strong>(O)</strong></span> → 상소심 법원에 수계신청을 하여 그 하자를 치유시키는 것도 가능(<span class=\"cs-u\"><strong>선택설</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>부적법한 수계신청 간과판결의 적부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 법원이 부적법한 소송수계신청을 받아들여 소송을 진행한 후 소송수계인을 당사자로 하여 판결을 선고하였다면, 소송에 관여할 수 있는 적법한 당사자가 법률상 소송행위를 할 수 없는 상태에서 심리되어 선고된 것이어서 마치 대리인에 의해 적법하게 대리되지 아니한 경우와 마찬가지로 위법<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅴ. 간과판결의 효력(<span class=\"cs-blue\"><span class=\"cs-u\">§247</span></span>)(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>중단을 간과한 판결의 효력(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>판례의 입장</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 소송계속 중 사망에 의한 중단을 간과한 판결은 ⅰ) 소송에 관여할 수 있는 적법한 수계인의 권한을 배제한 결과가 되는 절차상 위법은 있지만 판결이 당연무효라고 할 수는 없고<span class=\"cs-x\"><strong>(X)</strong></span>, ⅱ) 대리권 흠결을 이유로 상소 또는 재심에 의해 취소를 구할 수 있다는 위법설의 입장<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>구제방법</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">중단을 간과한 판결은 대리권 흠결을 간과한 위법한 판결로 상속인은 대리권 흠결의 경우에 준해 확정 전이면 상소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§424①</strong></span></span>4호), 확정 후이면 재심(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>3호)에 의한 취소를 구할 수 있고, 판결의 하자는 추인(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§60</strong></span></span>)에 의해 치유될 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>사망자 명의 판결문에 기해 승계인에게 강제집행하는 방법(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>문제점</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">중단을 간과한 판결도 형식적으로 확정된 경우 위 확정판결은 유효하므로 강제집행을 할 수 있다 — 단, 승계인에게 강제집행을 하기 위해서는 승계인 명의로 집행문을 부여받아야 하는데 방법이 문제된다</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>판례의 입장</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: (소송대리인이 없어 절차가 중단되었음을 간과)하고 사망한 자가 당사자로 표시된 판결에 기해 사망자의 승계인을 위한 또는 사망자의 승계인에 대한 강제집행을 실시하기 위하여는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민사집행법§31</strong></span></span>을 준용하여 승계집행문을 부여함이 상당하다는 승계집행문설의 입장<span class=\"cs-o\"><strong>(O)</strong></span> ↔ (소송대리인이 선임되어 있는 경우에는 소송절차가 중단되지 않으므로) 수계신청을 했음에도 이를 간과하여 구 당사자를 표시하여 판결을 선고한 때에는 수계인으로 판결을 경정하면 된다고 본다(<span class=\"cs-u\"><strong>판결경정설</strong></span>)</div><div class=\"cs-h\">Ⅵ. 판결정본의 송달과 판결의 확정 및 수계신청 가부(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송대리인에게 상소의 특별수권이 없는 경우(★) - 송달/확정/수계</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">심급대리의 원칙상 판결정본이 소송대리인에게 송달되면 소송대리인의 대리권은 소멸되므로 소송절차는 중단된다 → 상소기간이 진행하지 않으며, 판결은 확정되지 않는다 — 이때 상속인은 수계신청을 하여 중단을 해소시킬 수 있고, 이때부터 상소기간이 진행한다</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송대리인에게 상소의 특별수권이 있는 경우(★) - 송달/확정/수계</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 소송대리인에게 상소에 관한 특별한 수권이 있다면 판결정본이 송달되어도 대리권이 소멸되지 않기 때문에 중단되지 않는다 ② 따라서 상소기간이 진행하게 되며, 상소기간의 도과로 판결은 확정된다 → 그러므로 상속인은 수계신청을 할 수 없다 ③ 그러나 소송대리인이 상소제기(상소장 제출)하면 소송절차는 중단되며, 상속인들은 상소심에서 수계신청을 할 수 있다</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>공동상속인들 중 일부 상속인들 '스스로' 항소를 제기한 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>사실관계: [소송계속 중 피고 사망, 상속인 A·B·C·D 있고 소송대리인 병 선임된 상태에서 제1심 청구인용판결이 소송대리인 병에게 송달되었는데, A·B가 스스로 항소를 제기하자 C·D가 항소심에 수계신청을 한 경우(C·D에 대한 항소기간은 도과)]</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>判例: 공동상속인의 재산관계는 공유관계로 공동소송의 형태는 통상공동소송이므로 상소불가분의 원칙 적용이 없으며</strong><span class=\"cs-x\"><strong>(X)</strong></span><strong>, A·B가 스스로 항소한 경우라면 A·B만 항소심으로 이심되며, C·D에 대한 제1심판결은 상소기간의 도과로 분리확정된다고 보고, 누락한 C·D의 소송계속이 소멸되었으므로 항소심에서 C·D의 수계신청은 허용되지 않는다(</strong>확정설<strong>)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>공동상속인들 중 일부에 대해서만 '망인의 소송대리인'이 항소를 제기한 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>사실관계: [제1심 소송계속 중 피고 사망으로 공동상속인 중 A·B만이 수계신청하여 패소판결이 선고되었고, 상소의 특별수권을 부여받은 '망인의 소송대리인 병'이 항소인을 '망인의 소송수계인 A, B'로 기재하여 항소를 제기한 경우(항소심 계속 중 C·D가 수계신청을 한 경우)]</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>判例: 소송대리인 병이 A·B만을 항소인으로 표시하여 항소를 제기하였지만, 항소제기에 의해 A·B·C·D 전부에 대해 이심되고 확정이 차단되어 항소심절차가 개시되며, 단 상속인 C·D의 청구는 항소제기로 소송대리권이 소멸함에 따라 소송절차가 중단되었으므로 항소심은 C·D의 수계신청을 받아들여야 한다(</strong>효력확장설<strong>)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>상소의 특별수권이 있는 소송대리인에게 소송위임 후 제소 전 사망한 경우 법률관계(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[원고가 소송대리인을 선임한 다음 제소 전에 사망하였고, 소송대리인이 이를 모르고 원고를 원고로 표시해 제소한 경우]</strong></span> 判例: 당사자가 사망해도 소송대리권은 소멸하지 않으므로(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§95</strong></span></span>) 소의 제기는 적법하고, 시효중단 등 소제기의 효과는 상속인들에게 귀속되며(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§233①</strong></span></span> 유추적용되어 상속인들은 소송절차를 수계해야 함)<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["★★★★★"], 1, "mp_3"], ["민소027", "자백과 현저한 사실", "<div class=\"cs-h\">Ⅰ. 재판상 자백(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의 및 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">재판상 자백이 성립하기 위해서는 당사자가 ① 변론 또는 준비절차에서 ② 상대방 주장과 일치하고 ③ 자기에게 불리한 ④ 구체적 사실로서 주요사실에 대한 진술일 것을 요함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>변론에서 진술</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>일치진술 - 선행자백(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 일치진술의 시기: 자백은 상대방의 주장사실과 일치되는 사실의 진술일 것을 요함 — 상대방 진술이 먼저 이루어진 뒤 인정하는 후행자백 ↔ 상대방 진술 전에 먼저 인정하는 선행자백</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 상대방의 원용 전의 선행자백: 判例: 선행자백은 일방 당사자가 자진하여 자기에게 불리한 사실상 진술을 한 후 상대방이 이를 원용함으로써 당사자 쌍방의 주장이 일치함을 요하므로, 일치가 있기 전에는 전자의 진술을 선행자백이라 할 수 없고<span class=\"cs-x\"><strong>(X)</strong></span> → 자기에게 불리한 사실을 진술한 당사자도 그 후 상대방의 원용이 있기 전에는 자인한 진술을 철회하고 이와 모순된 진술을 자유롭게 할 수 있으며<span class=\"cs-o\"><strong>(O)</strong></span>, 이 경우 자인사실은 소송자료에서 제거됨(당사자에 대한 구속력 X)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 상대방의 원용 후의 선행자백: 判例: 선행자백은 상대방이 원용하면 재판상 자백이 됨<span class=\"cs-o\"><strong>(O)</strong></span> → 당사자에 대한 구속력으로 철회 불가<span class=\"cs-x\"><strong>(X)</strong></span>, 법원에 대한 구속력으로 법원도 자백에 구속되어 반대심증에도 불구하고 이를 기초로 판단해야 함<span class=\"cs-o\"><strong>(O)</strong></span> — 단, 진술에 잘못된 계산이나 표현상의 잘못이 있고 그 잘못이 분명한 경우에는 상대방이 원용하였더라도 쌍방 주장이 일치한다고 할 수 없어 선행자백 성립 불가<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>불리한 사실(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例(<span class=\"cs-u\"><strong>패소가능성설</strong></span>): <span class=\"cs-fact-tag\"><strong>[원고의 소유권확인사건에서 원고측이 소유권이전등기를 마친다는 사실을 원고들이 증명책임을 부담할 사항인데 스스로 마치지 않았음을 자인한 경우]</strong></span> 자백 성립<span class=\"cs-o\"><strong>(O)</strong></span> → 상대방이 증명책임을 지는 사실뿐 아니라 자기가 증명책임을 지는 사실도 패소될 가능성이 있으면 자기에게 불리한 사실로 보는 패소가능성설의 입장<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>구체적 사실로서 주요사실의 진술 - 권리자백</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 구체적 사실의 진술: 재판상 자백은 상대방의 '사실상의 진술'에 대하여 성립함이 원칙, 단순히 침묵하거나 불분명한 진술만으로는 자백 부정<span class=\"cs-x\"><strong>(X)</strong></span> — 재판상 자백은 사실상 주장에만 적용되고 법률상 주장에는 적용<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 주요사실의 진술: 재판상 자백은 변론주의의 제2원칙이므로 주요사실에만 적용<span class=\"cs-o\"><strong>(O)</strong></span>, 간접사실·보조사실에는 자백 성립<span class=\"cs-x\"><strong>(X)</strong></span> — 判例: 소극적 손해인 일실수입은 주요사실이며 피해자의 사고 당시 수입을 기초로 산정하므로 그 수입은 자백의 대상<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>(상대방 당사자) 재판상 자백한 사실에 대해서는 증명책임이 면제(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§288</strong></span></span><strong>본문)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>(법원에 대한 구속력) 재판상 자백이 성립되면 법원의 사실인정권 배제 → 법원은 자백사실이 진실인가의 여부에 관하여 판단할 필요 없으며, 증거조사 결과 반대의 심증을 얻었더라도 자백에 반하는 사실을 인정</strong><span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>(당사자에 대한 구속력) ⅰ) (원칙 철회불허) 자백이 성립되면 자백한 당사자는 원칙적으로 임의철회 불가능</strong><span class=\"cs-x\"><strong>(X)</strong></span><strong> ⅱ) (예외 철회허용) 그러나 ① 상대방의 동의가 있을 때 ② 자백이 제3자의 형사상 처벌할 행위로 인한 때(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span><strong>5호) ③ 자백이 진실에 반하고 착오로 인한 것임을 증명한 때(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§288</strong></span></span><strong>단서) ④ 소송대리인의 자백을 당사자가 경정할 때(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§94</strong></span></span><strong>)는 예외적으로 철회 허용</strong><span class=\"cs-o\"><strong>(O)</strong></span><strong> ⅲ) 또한 자백의 성립 후 청구를 교환적으로 변경하여 원래의 주장사실을 철회한 경우 이미 성립되었던 상대방의 자백도 그 대상이 없어짐으로써 소멸</strong><span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例(자백이 진실에 반하고 착오로 인한 것에 대한 판례): ⅰ) 자백의 취소는 자백이 진실에 반한다는 것 외에 착오로 인한 것임을 아울러 증명해야 하고, 진실에 반하는 것임이 증명되었다고 하여 착오로 인한 자백으로 추정되지는 아니함<span class=\"cs-x\"><strong>(X)</strong></span> ⅱ) 자백의 취소는 명시적으로 하여야만 하는 것은 아니고<span class=\"cs-x\"><strong>(X)</strong></span> 종전의 자백과 배치되는 사실을 주장함으로써 묵시적으로도 가능<span class=\"cs-o\"><strong>(O)</strong></span> ⅲ) 취소하고 상대방이 동의하면 반진실·착오의 요건을 고려할 필요 없이 취소를 인정해야 하나<span class=\"cs-o\"><strong>(O)</strong></span>, 이의를 제기하지 않았다는 점만으로는 동의로 볼 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> ⅳ) 진실에 부합하지 않는다는 사실은 반대사실을 직접증거로 증명할 수도 있고 이를 추인할 수 있는 간접사실의 증명에 의해도 가능<span class=\"cs-o\"><strong>(O)</strong></span> ⅴ) 진실과 부합하지 않는 사실이 증명된 이상 변론 전체의 취지에 의해서도 착오로 인한 것이라는 점을 인정할 수 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 권리자백</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>권리자백의 의의 및 구별개념</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">권리자백이란 '상대방 주장의 법률상의 진술 또는 의견에 대한 자기에게 불리한 진술'을 말함 — 자기에게 불리한 사실의 진술인 재판상 자백과 구별됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법규의 존부·해석에 관한 진술</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">법규의 존부·해석은 법원이 직책상 스스로 판단해야 할 전권사항이므로 자백의 대상<span class=\"cs-x\"><strong>(X)</strong></span> — 判例: 자백은 법률 적용의 전제가 되는 주요사실에 한정되고, 적용할 법률이나 법적 효과는 자백의 대상<span class=\"cs-x\"><strong>(X)</strong></span>, '월급금액으로 정한 통상임금을 시간급 금액으로 산정하는 방법'은 자백의 대상이 아니라고 보며, 법정변제충당의 순서 자체는 법률규정의 적용에 의해 정해지는 법률상의 효과라 자백이라 볼 수 없다<span class=\"cs-x\"><strong>(X)</strong></span> — 이행불능에 관한 주장은 법률적 효과에 관한 진술에 불과하여 자유롭게 철회할 수 있고 법원도 구속<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>사실의 평가적 판단에 대한 진술(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 사실에 대한 법적 판단이나 평가는 자백의 대상<span class=\"cs-x\"><strong>(X)</strong></span> → 법률상 혼인외의 자가 아닌 것을 혼인외의 자라고 시인하여도 혼인외의 자로 될 수 없고<span class=\"cs-x\"><strong>(X)</strong></span>, 법률상 유언 아닌 것을 유언이라 시인하여도 유언이 될 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법률적 사실의 진술</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">법률상 개념을 사용하여 사실을 진술한 경우라면 그 내용을 이루는 사실에 대한 압축진술으로 보아야 함(예: 매매·소비대차처럼 상식적으로 널리 알려진 것) → 진술자가 이해했으면 재판상 자백으로서의 구속력 인정<span class=\"cs-o\"><strong>(O)</strong></span> — 判例: 당사자가 법률적 용어로 진술한 경우에도 그것이 구체적인 사실관계의 표현으로서 사실상의 진술을 포함하고 있을 때에는 그 범위에서 자백 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>선결적 법률관계에 대한 진술(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소송물의 존부 판단의 전제가 되는 선결적 법률관계를 인정하는 진술도 재판상 자백이 성립하는지 문제 → 判例: <span class=\"cs-fact-tag\"><strong>[소유권에 기한 등기말소청구소송에서 피고가 원고 주장의 소유권을 인정하는 진술]</strong></span>은 소유권의 내용을 이루는 사실에 대한 진술로 볼 수 있으므로 재판상 자백 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅲ. 자백간주(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>자백간주의 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>상대방의 주장사실을 명백히 다투지 아니한 경우 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§150①</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">당사자가 변론기일에 출석하였으나 상대방이 주장사실을 명백히 다투지 아니하였을 경우에는 그 사실에 대해 자백간주가 성립된다 — 단, 변론 전체의 취지로 보아 다툴 것으로 인정되는 경우에는 자백간주가 성립되지 않음<span class=\"cs-x\"><strong>(X)</strong></span> — 判例: 제1심에서 원고의 주장사실을 명백히 다투지 아니하여 자백간주로 패소한 피고가 항소심에서도 원고 청구기각의 판결을 구했을 뿐 청구원인으로 주장한 사실에 대하여는 아무런 답변도 진술하지 않았다면 항소심에서도 자백간주가 성립한다는 입장<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>한 쪽 당사자가 기일에 불출석한 경우 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§150③</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§150③</strong></span></span>이 적용되기 위해서는 ① 공시송달이 아닌 통상의 송달을 받았을 것 ② 상대방의 주장사실을 다투는 서면을 제출하지 않았을 것 ③ 기일에 불출석하였을 것을 요함 — 判例: <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§150③</strong></span></span>의 요건이 구비되어 일단 자백간주의 효과가 발생한 때에는 그 이후의 기일에 공시송달하게 되었다 하더라도 이미 발생한 자백간주의 효과가 상실되는 것은 아니다<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>답변서의 부제출 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§257①</strong></span></span><strong>·②</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">피고가 소장 부본을 송달받고 30일 이내에 답변서를 제출하지 아니한 경우에는 원고의 청구원인 사실에 대해 자백한 것으로 보고 무변론원고승소판결을 할 수 있다(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§257①</strong></span></span>) / 피고가 청구원인사실을 모두 자백하는 취지의 답변서를 제출하고 따로 항변을 하지 아니한 때도 마찬가지(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§257②</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">자백간주가 성립되면 재판상 자백과 마찬가지로 ① 법원에 대한 구속력이 생기며, 법원은 증거에 기하여 자백간주에 배치되는 사실을 인정할 수 없다 ② 그러나 자백간주는 재판상 자백과 달리 당사자에 대한 구속력이 없어<span class=\"cs-x\"><strong>(X)</strong></span>, 당사자는 자백간주가 있었다 하여도 사실심 변론종결시까지 그 사실을 다툼으로써 그 효과를 철회할 수 있다<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅳ. 현저한 사실</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의와 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">현저한 사실이란 법관이 명확하게 인식하고 있고 증거에 의해 그 존부를 인정할 필요가 없을 정도로 객관성이 담보된 사실 — ① 공지의 사실(일반인에게 알려진 사실)과 ② 법원에 현저한 사실(법원에 알려진 사실)이 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 직종별임금실태조사보고서와 한국직업사전의 존재 및 기재내용을 법원에 현저한 사실로 보아, 이를 기초로 피해자의 일실수입을 산정한 조치는 객관적이고 합리적인 방법<span class=\"cs-o\"><strong>(O)</strong></span> ② <span class=\"cs-neg-tag\"><strong>[피고와 제3자 사이의 민사소송 확정판결 자체를 넘어 판결의 이유를 구성하는 사실관계까지]</strong></span> 법원에 현저한 사실로 볼 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> — 이미 확정된 관련 민사사건의 판결에서 인정된 사실은 유력한 증거가 되나, 다른 증거 내용에 비추어 그대로 채용하기 어려우면 합리적 이유를 설시하여 배척할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>변론주의와 관계(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">현저한 사실에 대해 判例: ① 주장책임 적용설(소극설)이 적용된다고 보아 당사자가 주장하지 않은 사실은 법원이 판결의 기초로 삼을 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> ② 현저한 사실에 반하는 자백의 효력은 부정<span class=\"cs-x\"><strong>(X)</strong></span> ③ 현저한 사실은 증거에 의한 증명이 필요없음</div>", ["★★★"], 1, "mp_3"], ["민소028", "증거조사의 개시", "<div class=\"cs-h\">Ⅰ. 증거의 채부결정</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>증거신청의 채부결정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">당사자가 증거신청을 하면 법원이 그 증거방법을 조사할 것인지 여부를 결정함 → 증거신청의 채택여부는 원칙적으로 법원의 직권에 속하는 재량사항<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>위법수집증거의 증거능력과 증거조사방법(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">증거능력이란 '증거방법으로서 증거조사의 대상이 될 수 있는 자격'을 말함 — 判例: 자유심증주의를 채택하고 있는 민사소송법 하에서 상대방 부지 중 비밀리에 상대방과의 대화를 녹음하였다는 이유만으로 그 녹음테이프가 증거능력이 없다고 단정할 수 없다<span class=\"cs-x\"><strong>(X)</strong></span>고 보아 증거능력 긍정 — 최근판례도 대화 상대방의 동의 없이 대화를 녹음하였더라도 그 녹음파일이나 녹취록을 증거로 사용할 수 있다고 보았다<span class=\"cs-o\"><strong>(O)</strong></span> — (증거조사방법) 判例: \"녹음테이프에 대한 증거조사는 검증의 방법에 의해야 한다\"고 보아 검증설의 입장<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 유일한 증거(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판단기준</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① (쟁점단위로 판단) 사건 전체가 기준이 아니라 쟁점단위로 보아야 함 ② (전심급을 통관하여 판단) 유일한가 여부는 전 심급을 통관하여 판단해야 함 ③ (여러 개의 증거) 유일한가 여부는 이미 조사한 증거가 있느냐에 따라 결정되는 것이지, 신청한 증거의 개수를 기준으로 하지 않음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>적용범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 주요사실에 대해서만 유일한 증거가 문제됨 → 간접사실·보조사실에 대한 증거(간접증거)는 포함<span class=\"cs-x\"><strong>(X)</strong></span>, 단 문서의 진정성립에 대해서는 유일한 증거의 법리 적용<span class=\"cs-o\"><strong>(O)</strong></span> ② 유일한 증거란 본증에 한하고 반증은 해당<span class=\"cs-x\"><strong>(X)</strong></span> ③ 종래판례는 당사자신문의 보충성을 근거로 유일한 증거가 아니라고 보았으나, 개정 민사소송법에서 보충성을 삭제하였으므로 유일한 증거로 본다<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>유일한 증거의 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>유일한 증거이면 반드시 증거조사를 해야 함 → 이를 조사하지 않으면 채증법칙 위반으로 상고이유</strong><span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>예외적으로 ① 증거신청이 부적법한 경우 ② 증거신청서 부제출·비용 미예납 등 거증자의 고의나 태만의 경우 ③ 증인의 병환·송달불능 등 언제 조사할 수 있을지의 장애가 있는 경우 ④ 쟁점판단에 부적절하거나 불필요한 증거신청 ⑤ 직권탐지주의에 의하는 소송의 경우에는 유일한 증거라도 배척이 가능</strong><span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅲ. 증인신문(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">감정증인은 특별한 학식·경험으로 얻은 과거의 구체적 사실을 보고하는 사람 → 경험을 보고하는 이상 증인이므로 법원은 증인과 마찬가지의 절차로 조사(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§340</strong></span></span>) — 주신문에서는 특별한 경우가 아닌 한 유도신문 금지, 반대신문에서는 필요한 경우 유도신문 허용(규칙<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§91</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§92</strong></span></span>) — 증인진술서가 제출되었으나 작성자가 출석하지 않고 당사자가 반대신문권을 포기하여 진정성립을 다투지 않는 경우, 법원은 이를 서증으로 채택할 수 있으나, 그 내용이 허위라 하더라도 작성자에게 위증죄를 물을 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> — 법원이 증언거부권이나 선서거부권을 고지하지 않았다고 하여도 위법<span class=\"cs-x\"><strong>(X)</strong></span>이지 않으며, 적법한 선서절차를 마쳤는데도 허위진술한 증인은 위증죄 성립<span class=\"cs-o\"><strong>(O)</strong></span> — 만 14세 미만인 사람을 증인으로 신문할 때에는 선서를 시키지 못함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§322</strong></span></span>) — 증인이 직업의 비밀에 속하는 사항에 대해 신문받을 때 비밀을 지킬 의무가 면제된 경우에는 증언거부권을 가지지 못함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§315②</strong></span></span>) — 당사자나 법정대리인을 증인으로 신문하였더라도 지체 없이 이의권을 행사하지 않으면 이의권 포기·상실로 하자 치유<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅳ. 당사자신문(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(구법 보충성 요구) 구법은 다른 증거방법에 의해 법원이 심증을 얻지 못한 경우에만 당사자본인신문이 허용된다고 하여 보충성의 원리를 채택<span class=\"cs-o\"><strong>(O)</strong></span> → (개정법 보충성 폐지) 그러나 개정법에서 보충성을 폐지<span class=\"cs-o\"><strong>(O)</strong></span> → 다른 증거방법이 있는 경우에도 당사자신문이 허용되며, 당사자신문 결과만 가지고도 주요사실을 인정할 수 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(당사자 본인신문에서 증명방해) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§369</strong></span></span>에서 당사자 본인이 정당한 사유 없이 출석의무 등을 이행하지 아니하면 법원은 신문사항에 관한 상대방의 주장을 진실한 것으로 인정할 수 있는데, 判例는 상대방의 요증사실을 진실로 인정할 수 있는 것이 아니라 신문사항에 관한 상대방의 주장을 진실한 것으로 인정할 수 있다고 하여 자유심증설 입장<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["★★★"], 1, "mp_3"], ["민소029", "서증", "<div class=\"cs-h\">Ⅰ. 서증과 문서의 종류</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>서증의 의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">서증이란 '문서를 열람하여 그에 기재된 내용을 증거자료로 하기 위한 증거조사'를 말함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>처분문서와 보고문서(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">처분문서란 '증명하고자 하는 법률적 행위가 문서 자체에 의해 이루어진 경우'의 문서(계약서, 채무증서, 법원의 재판서 등) ↔ 보고문서란 작성자가 보고·듣고·느끼고 판단한 바를 기재한 문서(상업장부, 등기부, 일기, 진단서 등) — (논의의 실익) ⅰ) 처분문서는 형식적 증거력이 인정되면 실질적 증거력이 추정<span class=\"cs-o\"><strong>(O)</strong></span> ↔ ⅱ) 보고문서는 형식적 증거력이 인정되어도 실질적 증거력이 추정<span class=\"cs-x\"><strong>(X)</strong></span>되지 않고 법관이 자유심증으로 판단한다는 점에서 구별의 실익</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>원본, 정본, 등본과 초본</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">법원에 문서를 제출하거나 보낼 때에는 원본, 정본 또는 인증이 있는 등본으로 해야 함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§355</strong></span></span>)</div><div class=\"cs-h\">Ⅱ. 문서의 증거능력</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">증거능력이란 '증거조사의 대상이 될 수 있는 자격'을 말함 — 민사소송은 원칙적으로 증거능력에 제한이 없음<span class=\"cs-o\"><strong>(O)</strong></span> → ① 소제기 후 계쟁사실에 관하여 작성된 문서도 증거능력<span class=\"cs-o\"><strong>(O)</strong></span> ② 서증의 사본도 증거능력 부정<span class=\"cs-x\"><strong>(X)</strong></span> ③ 형사사건의 각종 조서도 증거능력 부정<span class=\"cs-x\"><strong>(X)</strong></span> ④ 위법수집증거도 증거능력 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅲ. 문서의 증거력(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>문서의 증거력의 의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">문서의 증거력이란 '그 문서가 요증사실의 증명에 기여하는 힘'을 말함 — 문서의 증거력에는 문서의 진정성립을 의미하는 '형식적 증거력'과 문서의 증거가치를 의미하는 '실질적 증거력'이 있음 → 판단순서는 형식적 증거력을 먼저 조사하고 다음 실질적 증거력을 조사</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>문서의 형식적 증거력(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">문서가 거증자가 주장하는 작성자의 의사에 기해 '진정하게 작성된 것'을 '문서의 진정성립'이라고 하고, 진정성립된 문서는 '형식적 증거력'이 있다고 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>성립의 인부(★) - 형식적 증거력 판단절차(3단계)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 진정성립의 요부: 문서가 증거로 제출되면 법원은 작성자에게 문서의 진정성립 여부를 인정할 것인지 답변하게 하는데 이를 '성립의 인부'라 함 → 작성자는 ⅰ) 성립의 인정 ⅱ) 침묵 ⅲ) 부인 ⅳ) 부지 4가지로 답변</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 서명날인의 인부: 성립의 인부절차에서 작성자가 성립을 인정하면 형식적 증거력이 인정되나, 부인하는 경우 법원은 서명날인의 인정여부를 답변하게 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 인영의 인부: 서명날인의 인부절차에서 작성자가 서명날인을 인정하면 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§358</strong></span></span>에 의해 형식적 증거력이 추정되나, 부인하면 법원은 인영의 인정여부를 답변하게 함 → 작성자가 ⅰ) 인영을 인정하면 형식적 증거력은 2단계의 추정이 되며, ⅱ) 부인하면 거증자는 작성자의 진정성립, 서명날인, 인영 중 하나에 대해 증명책임을 짐</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>성립의 인정(침묵)(★) - 3단계</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 재판상 자백 성립: 判例: 처분문서의 성립에 관한 자백은 보조사실에 관한 자백이지만 주요사실에 대한 경우처럼 재판상 자백의 법리가 적용되며, 당사자 사이에 성립에 다툼이 없으면 법원은 자백에 구속되어 그 형식적 증거력을 인정해야 함<span class=\"cs-o\"><strong>(O)</strong></span> → 성립의 인정진술은 원칙적으로 철회 불가, 예외적으로 철회 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 적용범위: ⅰ) '문서의 진정성립'에 대한 인정 진술뿐만 아니라 ⅱ) '날인의 진정'에 대한 인정 진술 ⅲ) '인영의 진정'에 대한 인정 진술에 대해서도 判例는 이러한 인정 진술은 보조사실에 관한 자백으로 보면서도 주요사실에 대한 자백과 같은 기능을 한다는 이유로 재판상 자백의 성립을 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 재판상 자백의 구속력: 재판상 자백이 성립하면 ① 당사자에 대한 구속력을 인정하여 원칙적으로 철회 불가, 예외적으로 철회 가능 ② 법원에 대한 구속력도 인정되어 법원은 자백에 구속되어 형식적 증거력을 인정해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>부인</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">작성자가 부인·부지로 답변하는 경우 문서의 진정성립을 증명해야 하는데, 이에 관한 증명책임은 문서제출자에게 있음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§357</strong></span></span>) — 判例: 변론의 전체적 취지만으로도 그 진정성립을 인정할 수 있다<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(5) <strong>부지</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 타인 명의의 문서에 대해서는 부지할 수 있음<span class=\"cs-o\"><strong>(O)</strong></span> ② 그러나 자기 명의의 문서에 대해서는 부지라고 할 수 없고<span class=\"cs-x\"><strong>(X)</strong></span>, 부인 또는 인정을 해야 함 — 判例: 부지라고 답변하면 석명을 해야 하며, ⅰ) 부인하는 취지라면 상대방에게 입증을 촉구하고, ⅱ) 서명이나 인영의 진정을 인정하는 것이라면 문서의 기재내용과 같은 의사표시의 존재를 인정해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>성립의 진정의 추정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>공문서의 진정성립의 추정과 복멸</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">문서의 방식과 취지에 의해 공무원이 직무상 작성한 것으로 인정한 때에는 진정한 공문서로 추정(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§356</strong></span></span>) → 공문서가 인정되면 진정성립에 '전면적 추정력'이 미침</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>사문서의 진정성립의 추정과 복멸 - 형식적 증거력 판단</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 진정성립의 증명과 서명날인의 추정: 성립의 인부절차에서 상대방이 부인하는 경우 사문서의 진정성립에 대해서 거증자가 진정성립을 증명해야 함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§357</strong></span></span>) — 判例: '변론의 전체적 취지만'으로 그 진정성립을 인정할 수 있음<span class=\"cs-o\"><strong>(O)</strong></span> — 단, 본인 또는 대리인의 서명·날인·무인이 진정한 것임을 증명하면 진정한 문서로 추정을 받음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§358</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 형식적 증거력에 대한 2단계 추정(★) - 5단계 추정</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ① 인영의 진정이 인정되면 날인의 진정이 사실상 추정(1단의 추정)되고 ② 날인의 진정이 인정되면 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§358</strong></span></span>에 의해 문서전체의 진정성립의 증거법칙적 추정(2단의 추정)이 이루어진다고 하여 이단의 추정으로 형식적 증거력을 추정<span class=\"cs-o\"><strong>(O)</strong></span> — 또한 형식적 증거력이 추정되면 실질적 증거력도 사실상 추정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 형식적 증거력에 대한 2단계의 추정의 복멸 Ⅰ(★) - 도용의 항변</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 도용의 항변: 判例: ① 날인행위가 작성명의인의 의사에 기한 것이라는 추정(1단의 추정)은 사실상의 추정이므로, 날인사실을 다투는 자(을)가 반증을 들어 날인행위가 작성명의인의 의사에 기한 것임에 관하여 법원으로 하여금 의심을 품게 할 수 있는 사정을 증명하면 날인사실의 추정은 깨어진다<span class=\"cs-o\"><strong>(O)</strong></span> ② 이때 날인사실의 추정은 날인행위가 작성명의인 이외의 자(갑)에 의해 이루어졌다는 도용사실이 증명된 경우에는 깨지고, 도용사실의 증명은 주장자(을)가 '본증'으로 법관에게 확신을 줘야 한다(도용사실을 본증으로 증명하면 형식적 증거력이 부정된다)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 정당한 권원에 의한 날인: 다만, 判例: ① 2단의 추정은 날인행위가 작성명의인 이외의 자(갑)에 의하여 이루어진 것임이 증명된 경우에는 깨지므로 ② 문서제출자(갑)는 날인행위가 작성명의인(을)으로부터 위임받은 정당한 권원에 의한 것이라는 사실을 증명할 책임이 있다(증명하면 다시 형식적 증거력이 인정된다)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 형식적 증거력에 대한 2단계의 추정의 복멸 Ⅱ(★) - 백지문서의 항변</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 백지문서의 항변: 判例: 작성명의인의 날인만 되어 있고 내용이 백지로 된 문서를 교부받아 백지 부분을 작성명의자 아닌 자가 보충한 경우, 문서의 진정성립의 추정은 배제(백지문서를 본증으로 증명하면 형식적 증거력이 부정된다)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 정당한 권원에 의한 날인: 判例: 백지문서에 날인한 사실이 인정되어 2단계 추정이 복멸된 경우, 서증제출자가 작성명의인으로부터 위임받은 정당한 권원에 의한 기재내용임을 증명할 책임이 있다(증명하면 다시 형식적 증거력이 인정된다)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>문서의 실질적 증거력(★) - 증거가치</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의와 판단</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">문서의 형식적 증거력이 있다고 판단되면 '문서가 요증사실을 증명할 수 있는 능력'인 '문서의 실질적 증거력'을 판단 → 실질적 증거력의 판단은 법관의 자유심증에 의하므로<span class=\"cs-o\"><strong>(O)</strong></span> 자백의 법리 적용<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>처분문서의 실질적 증거력(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 처분문서는 형식적 증거력이 인정되면 실질적 증거력이 사실상 추정<span class=\"cs-o\"><strong>(O)</strong></span> → 진정성립이 인정되는 이상 기재 내용을 부정할 만한 분명하고도 수긍할 수 있는 반증이 없으면 기재된 문언대로 법률행위의 존재와 내용을 인정해야 함 ② 진정성립이 인정된 처분문서의 증거력을 배척함에는 합리적인 이유설시를 요함 ③ 단, 이러한 추정은 사실상의 추정이므로 다투는 자가 반증을 들어 의심을 품게 하는 사정을 증명하면 추정은 깨어짐<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>보고문서의 실질적 증거력(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 보고문서의 경우에는 형식적 증거력이 인정되어도 실질적 증거력이 추정<span class=\"cs-x\"><strong>(X)</strong></span>되지 않으므로 이는 법관의 자유심증으로 결정 ② 단, 일정한 공문서인 경우(확정된 민사 및 형사판결 등)에는 기재사항이 진실한 것이라는 추정을 받으며, 배척함에 있어서는 합리적인 이유설시를 요함</div><div class=\"cs-h\">Ⅳ. 서증신청의 절차</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>서증신청 방법</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">당사자가 서증을 신청하고자 하는 때에는 문서를 제출하는 방식 또는 문서제출명령을 신청하는 방식으로 함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§343</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>문서의 직접 제출</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>원칙</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">서증 신청자가 소지하고 있는 문서에 대하여 증거신청하는 것은 법원에 직접 제출하는 방식으로 함 — 문서는 원본·정본·인증등본으로 제출(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§355</strong></span></span> 원본제출원칙) — 사본에 의한 증거의 제출은 정확성의 보증이 없어 부적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>예외(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 사본을 원본에 갈음하여 제출하는 경우: 判例: ① 원본의 존재 및 진정성립에 다툼이 없고 ② 사본을 원본으로 대용하는 데 이의 없는 경우는 사본에 의한 증거신청을 허용<span class=\"cs-o\"><strong>(O)</strong></span> → 이때는 원본이 제출된 경우와 동일한 효과 발생</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 사본 자체를 원본으로 제출하는 경우: 判例: 사본이 독립한 서증이 되나<span class=\"cs-o\"><strong>(O)</strong></span>, 이에 의해 원본이 제출된 것으로 되지는 않으며<span class=\"cs-x\"><strong>(X)</strong></span>, ① 증거에 의해 사본과 같은 원본이 존재하고 ② 원본이 진정하게 성립하였음이 인정되어야 하고, 그렇지 않으면 그와 같은 내용의 사본이 존재한다는 것 이상의 증거가치는 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>문서제출명령(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의 및 취지</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">문서제출명령이란 상대방이나 제3자가 소지한 문서를 법원이 제출하도록 명하는 제도</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>요건(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 문서제출의무 있는 문서일 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§344①</strong></span></span>의 문서: ① 인용문서(제1호) ② 인도 및 열람문서(제2호) ③ 이익문서 및 법률관계문서(제3호) — 단, 제3호의 경우 ⅰ) 공무원의 직무상 비밀에 동의를 받지 아니한 문서(가목, 나목), ⅱ) 증인의 증언거부사유(다목)가 있는 문서의 제출은 거부 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§344②</strong></span></span>의 문서: 제1항 외의 모든 문서도 문서제출의무가 있다고 규정하여 증거개시제도와 거의 같은 효과를 거둘 수 있도록 문서제출명령제도를 확장·강화 — 거부사유로 ⅰ) 공무원의 직무상 보관문서(본문) ⅱ) 증언거부사유 있는 때(제1호) ⅲ) 오로지 소지인이 이용하기 위한 문서(제2호)를 규정</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">다) 인용문서에 대한 판례: 判例: ① <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§344①</strong></span></span>1호의 인용문서는 당사자가 소송에서 문서를 증거로서 인용한 경우뿐 아니라 자기주장을 명백히 하기 위하여 적극적으로 문서의 존재와 내용을 언급하여 자기주장의 근거나 보조 자료로 삼은 문서도 포함<span class=\"cs-o\"><strong>(O)</strong></span> ② 인용문서에 해당하면 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§344②</strong></span></span>에서 정하고 있는 '공무원이 그 직무와 관련하여 보관하거나 가지고 있는 문서'라도 문서제출의무를 면할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">라) 직업비밀에 대한 판례: 判例: '직업의 비밀'은 공개되면 직업에 심각한 영향을 미치고 이후 직업의 수행이 어려운 경우를 가리키는데, '보호가치 있는 비밀일 경우에만' 문서의 제출을 거부할 수 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">마) 자기이용문서에 대한 판례: 判例: '자기이용문서'는 오로지 문서를 가진 사람이 이용할 목적으로 작성되고 외부자에게 개시하는 것이 예정되어 있지 않으며 개시할 경우 문서를 가진 사람에게 간과하기 어려운 불이익이 생길 염려가 있는 문서</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">바) 회사내부문서의 자기이용문서 해당여부: 判例: ① 문서 자체를 외부에 개시하는 것은 예정되어 있지 않더라도 ② 문서에 기재된 '정보'의 외부 개시가 예정되어 있거나 ③ 정보가 공익성을 가지는 경우 등에는 내부문서라는 이유만으로 자기이용문서로 쉽게 단정할 것이 아니다(제출의무 있음)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">사) 통신사실확인자료가 문서제출명령의 대상이 되는지 여부(★): 判例: ① 법원은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§344</strong></span></span>의 규정을 근거로 통신사실확인자료에 대한 문서제출명령을 할 수 있고 통신사업자는 이에 응할 의무가 있으며 ② 통신사업자가 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>통신비밀보호법§3</strong></span></span>을 들어 제출을 거부하는 것은 정당한 사유가 없음 ③ 통신비밀보호법은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민사소송법§294</strong></span></span>에서 정한 조사의 촉탁의 방법에 따른 통신사실확인자료제공을 허용하고 있고 ④ 통신비밀보호법과 민사소송법은 입법취지를 달리하므로 각각 적용될 수 있다는 점 ⑤ 통신비밀보호법의 사생활 및 대화의 비밀의 자유를 보호하는 입법 취지는 법원이 신중하고 엄격한 심리를 거쳐 문서제출명령 제도를 운용함으로써 충분히 구현될 수 있다는 점을 근거로 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">아) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§344②</strong></span></span>의 공무원의 직무상 보관문서: 判例: 금융감독원 직원이 직무상 작성하여 관리하고 있는 문서는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§344②</strong></span></span>이 적용되는 문서 중 예외적으로 제출을 거부할 수 있는 '공무원 또는 공무원이었던 사람이 그 직무와 관련하여 보관하거나 가지고 있는 문서'에 준하여 정보공개법에서 정한 절차와 방법에 의하여 공개 여부가 결정될 필요가 있고, 문서의 소지자는 그 제출을 거부할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 문서의 존재와 소지 및 제출의무에 대한 증명책임(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§345</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">문서제출명령을 하려면 문서의 존재와 소지가 증명되어야 하며, 이에 대한 증명책임은 원칙적으로 신청인에게 있음 — 단, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§344①</strong></span></span>3호 단서나 제2항의 거부사유는 문서소지인이 증명할 책임이 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>절차</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 문서제출명령 신청: 증거를 신청할 때에는 증명할 사실(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§289</strong></span></span>)과 증명취지를 밝혀야 함(규칙<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§74</strong></span></span>) — 이는 모색적 증명을 방지하여 소송절차의 신속을 기하기 위한 취지(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§345</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 문서정보공개제도(★): 문서제출신청자가 신청대상인 문서의 취지나 증명할 사실을 개괄적으로 표시하여 신청하면 법원이 상대방 당사자에게 신청내용과 관련하여 가지고 있는 문서의 표시와 취지 등을 명확히 적어내도록 명령할 수 있음 — 현대형 소송에서 증명책임을 부담하는 사람이 사실경과를 잘 모르는 경우에 일반·추상적 증거신청을 허용하여 구체적이고도 확실한 증거자료를 취득하는 방도를 열어주는 '모색적 증명제도'를 도입한 것(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§346</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 심판 방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 문서제출명령: 법원은 문서제출신청에 정당한 이유가 있다고 인정한 때에는 결정으로 문서를 가진 사람에게 제출을 명할 수 있음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§347</strong></span></span>) — 문서의 일부에 대하여만 이유 있다고 인정한 때에는 일부제출명령을 해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 비밀심리절차(★): 법원이 문서제출거부사유를 알아보기 위하여 문서제출을 명하게 되면 문서소지인의 비밀사항이 공개되는 위험이 발생할 수 있으므로, 법원이 문서제출의무 있는지 판단하기 위해 필요한 때에는 문서소지자에게 문서를 제시하도록 명하여 제시받은 다음, 다른 당사자의 참여를 배제한 채 비공개로 심리하는 절차를 둠(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§347④</strong></span></span>) — 비밀심리절차는 제출거부사유가 있는 ⅰ) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§344①</strong></span></span>3호의 이익문서·법률관계문서와 ⅱ) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§344②</strong></span></span> 문서에만 적용되고, 거부사유 없는 제1호·제2호 인용문서·인도·열람문서의 경우에는 적용되지 아니함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>부제출의 효과 및 제재(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§349</strong></span></span><strong>·</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§350</strong></span></span><strong>)(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 상대방 주장의 진실인정: 당사자가 문서제출명령·일부제출명령·비밀심리를 위한 문서제시명령을 받고도 거부하거나, 사용방해의 목적으로 제출의무 있는 문서에 대해 훼손을 한 때에는 법원은 문서의 기재에 대한 상대방의 주장을 진실한 것으로 인정할 수 있는바, '진실로 인정할 수 있는 것이 문서의 존재인지 아니면 요증사실인지' 문제됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 判例의 입장: 문서제출명령에 거부한 경우에는 법원은 문서에 관한 주장을 진실한 것으로 인정한다는 것이지, 문서에 의하여 증명하고자 하는 주장사실까지 증명되었다고 인정해야 하는 것은 아니며, 이러한 요증사실의 인정은 법관의 자유심증에 의한다고 하여 자유심증설의 입장<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>문서의 송부촉탁(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§352</strong></span></span><strong>)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">문서의 소지자에게 제출을 의무지울 수 없는 경우에 법원이 그 문서를 가진 자에게 송부를 촉탁하는 방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>문서 있는 장소에서의 서증조사(규칙</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§112</strong></span></span><strong>, </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§354</strong></span></span><strong>)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">문서를 소지한 자가 이를 법원에 제출하기 곤란한 사정이 있는 때에 문서가 있는 장소에서 직접 서증을 실시하는 방법</div>", ["★★★★★"], 1, "mp_3"], ["민소030", "자유심증주의", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">자유심증주의란 'ⅰ) 주요사실 주장이 진실인지 아닌지의 판단을 ⅱ) 법관이 증거법칙의 제약을 받지 않고 ⅲ) 변론 전체의 취지와 증거자료를 참작하여 형성된 ⅳ) 자유로운 심증으로 행할 수 있는 원칙'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§202</strong></span></span>) — 判例: 도시일용근로자의 월 가동일수를 22일로 인정한 원심의 조치는 가동일수에 관한 법리를 오해하여 필요한 심리를 다하지 아니하거나 논리와 경험의 법칙을 위반하여 자유심증주의의 한계를 벗어난 잘못이 있다(20일 초과 인정은 어려움)<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 증거원인</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>변론 전체의 취지(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">변론 전체의 취지란 '증거조사의 결과를 제외한 일체의 소송자료'를 의미 — 判例(<span class=\"cs-u\"><strong>보충적 증거원인설</strong></span>): 주요사실인 임대차계약체결사실의 존부가 문제된 사안에서 변론 전체의 취지만으로는 주요사실을 인정할 수 없다<span class=\"cs-x\"><strong>(X)</strong></span>고 보아 독립된 증거방법이 될 수 없다는 입장<span class=\"cs-o\"><strong>(O)</strong></span> — 단, 문서의 진정성립과 자백의 철회요건인 착오는 보조사실이지만 변론 전체의 취지만으로도 이를 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>증거조사의 결과 - 증거자료</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>증거력의 자유평가(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: (처분문서) 처분문서는 진정성립이 인정되면 그 기재내용에 따른 의사표시의 존재와 내용을 인정해야 하나, 그 기재 내용과 다른 특별한 명시적·묵시적 약정이 있는 사실이 인정될 경우에는 그 기재 내용의 일부를 달리 인정할 수 있고, 작성자의 법률행위 해석에 있어서도 경험칙과 논리법칙에 어긋나지 않는 범위 내에서 자유로운 심증으로 판단<span class=\"cs-o\"><strong>(O)</strong></span> — (확정판결) 민사재판에서 다른 증거가 있으면 형사판결의 내용과 달리 사실인정을 할 수 있지만<span class=\"cs-o\"><strong>(O)</strong></span>, 확정된 형사판결의 인정사실은 특별한 사정이 없는 한 유력한 증거자료가 됨<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>증거공통의 원칙(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">증거조사결과는 그 제출자에게 유리하게 판단될 수 있을 뿐만 아니라, 상대방의 원용과 관계없이 제출자에게 불리하게 오히려 상대방에게 유리한 판단에 사용될 수 있다는 원칙으로 판례는 자유심증주의의 내용으로 이를 인정<span class=\"cs-o\"><strong>(O)</strong></span> — 단, 통상공동소송의 경우에는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§66</strong></span></span>의 독립성의 원칙이 적용되어 증거공통의 원칙이 적용되지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 자유심증주의의 예외</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>명문의 규정이 있는 경우의 증명방해(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§349</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§350</strong></span></span> 규정에 따라 당사자 일방이 고의로 상대방에 대해 증명방해행위를 한 경우에 그에게 불리한 사실을 인정할 수 있게 함 — 判例(<span class=\"cs-u\"><strong>자유심증설</strong></span>): 법원이 상대방의 '문서의 존재 및 내용'에 관한 주장을 진실한 것으로 인정할 수 있다는 것이지, 요증사실을 인정할지 여부는 법관의 자유심증에 의함<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>명문의 규정이 없는 경우의 증명방해(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>증명방해의 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (객관적 요건) 증명책임을 지지 않는 당사자의 '적극적 방해행위'가 있어야 하며, 소극적 불이행은 증명방해가 아님<span class=\"cs-x\"><strong>(X)</strong></span> ② (주관적 요건) 증거방법을 고의·과실 있는 행위로 훼손하였을 것과 이로 인하여 증명방해의 결과가 초래된다는 것을 알았거나 부주의로 알지 못하였을 것을 요함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>증명방해의 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例(<span class=\"cs-u\"><strong>자유심증설</strong></span>): <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§349</strong></span></span> 등의 법규정에 의한 증명방해와 같이 법원이 증명방해행위에 의하여 증명하고자 하는 '요증사실 자체를 진실한 것'으로 인정할 수 있는 것은 아니며<span class=\"cs-x\"><strong>(X)</strong></span>, 이를 바탕으로 요증사실을 인정할 것인지 여부는 법관의 자유심증에 의함<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>자유심증과 증거계약(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>자백계약</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (허용성) 변론주의의 제2원칙이므로 허용<span class=\"cs-o\"><strong>(O)</strong></span> ② (법적성질) 사법계약 ③ (위반시 구제방법) 다투지 않기로 합의한 사실에 대해 상대방이 다투는 경우 거증자가 '증거항변'으로 자백계약사실을 주장·증명하면 법원은 상대방의 부인을 배척하고 자백계약사실을 그대로 인정해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>증거방법 제한계약</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (허용성) 변론주의의 제3원칙이므로 허용<span class=\"cs-o\"><strong>(O)</strong></span>(단, '보충적 직권증거조사'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§292</strong></span></span>) 한도에서 증거제한계약은 무효) ② (법적성질) 사법계약 ③ (위반시 구제방법) ⅰ) (증거조사 전) '증거항변'으로 증거계약의 존재를 법원에 주장하여 증거채택의 거부를 신청하면 법원은 상대방 당사자의 증거항변에 구속되어 증거채택을 해서는 안 됨 ⅱ) (증거조사가 마쳐진 경우) 불사용합의 증거가 제출되어 이에 대해 법원이 증거조사까지 마친 상태라면 법원은 상대방당사자의 항변에 구속되지 아니함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>증거력계약</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">증거력계약이란 '증거조사결과의 증거력을 당사자 합의로 정하는 약정' → 민사소송법은 자유심증주의를 취하여 당사자가 제출한 증거에 대한 증거조사결과에 대한 자유로운 심증으로 사실의 진위 여부를 판단할 수 있게 하므로, 증거력을 제한하는 당사자의 합의는 그 효과가 없음<span class=\"cs-x\"><strong>(X)</strong></span></div>", ["★★"], 1, "mp_3"], ["민소031", "증명책임", "<div class=\"cs-h\">Ⅰ. 증명책임의 분배(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">증명책임의 분배란 '요증사실의 존부가 진위불명인 경우에 당사자 중 누구에게 불이익(패소판결)을 돌릴 것인가'하는 문제 — 분배의 기준에 관하여 判例는 법률요건분류설 입장<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법률요건분류설에 기한 분배</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>소송요건의 존부에 대한 증명책임</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">'직권조사사항인 소송요건'은 '원고'에게 증명책임이 있음(본안판결을 받는 것이 원고에게 유리하기 때문) — '항변사항인 소송요건'은 '피고'가 증명책임을 짐</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>본안의 요증사실의 존부에 대한 증명책임</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">권리의 존재를 주장하는 자는 권리근거규정의 요건사실(권리발생사실, 청구원인사실)에 대해 증명책임을 지며, 권리의 존재를 다투는 상대방은 반대규정의 요건사실(권리장애·멸각·저지사실)에 대해 증명책임을 짐</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>소극적 확인의 소에 있어서 주장책임과 증명책임의 분배</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">채무부존재확인의 소에서 ① 채무자인 원고가 채권자인 피고로부터 금전을 대여받은 사실이 없다고 하는 경우에는 부인에 해당하여 피고가 대여사실을 증명해야 하며 ② 채무를 변제하였다고 주장하는 경우에는 항변이므로 원고가 변제사실을 증명해야 함 — 判例: 유치권부존재확인소송에서 유치권의 요건사실인 견련관계 있는 채권의 존재는 피고가 주장·증명해야 함 / 청구이의소송에서 원고가 피고의 채권이 성립하지 아니하였음을 주장하는 경우에는 피고에게 채권의 발생원인 사실을 증명할 책임이 있고, 원고가 채권이 통정허위표시로서 무효라는 등 권리발생의 장애 또는 소멸사유에 해당하는 사실을 주장하는 경우에는 원고에게 그 사실을 증명할 책임이 있음</div><div class=\"cs-h\">Ⅱ. 증명책임의 완화</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법률상 추정(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>법률상 추정의 의의와 종류</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">법률상의 사실추정은 '갑사실(전제사실)이 있을 때 을사실(추정사실)이 있는 것으로 추정한다'고 규정된 경우 — 법률상의 권리추정은 '갑사실(전제사실)이 있을 때 을권리(추정권리)가 있는 것으로 추정한다'고 규정된 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>법률상 추정의 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 추정규정이 있어도 증명책임이 있는 사람은 추정되는 사실을 증명할 수도 있으나, 보통은 그보다도 증명이 쉬운 전제사실을 증명함으로써 이에 갈음하게 된다(증명주제의 선택) ② 따라서 추정규정에 의해 증명책임을 지는 당사자는 전제사실에 대해서만 증명책임을 지게 된다는 점에서 증명책임이 완화(증명책임의 완화) ③ 이에 대해 상대방으로서는 추정사실이 부존재한다는 것을 증명함으로써 추정을 번복할 수 있음(증명책임의 전환)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>등기의 추정력(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 소유권이전등기는 권리의 추정력이 있으므로, 이를 다투는 측에서 그 무효사유를 주장·증명하지 아니하는 한 등기원인 사실에 관한 증명이 부족하다는 이유만으로 그 등기를 무효라고 단정할 수 없다는 입장(<span class=\"cs-u\"><strong>법률상추정설</strong></span>) — 등기가 있으면 등기된 '권리'의 존재 및 귀속, '등기원인'의 존재 및 유효성, '등기절차'의 적법성, '유효한 대리행위'를 하였다는 점이 추정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[사례풀이구조]</strong></span> 말소등기청구의 요건사실은 ① 원고 소유일 것 ② 원고 소유의 부동산에 피고의 등기가 경료되어 있을 것 ③ 그 등기가 원인무효일 것을 요함 → 피고 명의의 등기가 등기의 추정력으로 인해 적법한 소유자 및 유효한 대리행위로 법률상 추정<span class=\"cs-o\"><strong>(O)</strong></span> → 이를 다투는 원고가 피고의 대리인이 무권대리임을 주장·증명해야 함 → 이때 대리권 수여 여부가 분명하지 않으면 증명책임을 지는 원고의 패소기각판결</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>잠정적 진실의 추정(★) - 점유취득시효의 요건사실의 증명책임이 쟁점</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">잠정적 진실의 추정이란 '전제사실로부터 일정한 사실을 추정하는 진정한 법률상의 추정과 달리 그 전제사실이 없는 무전제의 추정'을 말함 — <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§197①</strong></span></span>은 '점유자는 소유의 의사로 선의평온공연하게 점유한 것으로 추정한다'고 규정 → <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§245①</strong></span></span>의 점유취득을 주장하는 자는 소유의사·평온·공연에 대하여 증명책임이 없게 되고<span class=\"cs-x\"><strong>(X)</strong></span>, 이를 다투는 상대방인 소유자가 그 반대사실에 대한 증명책임을 부담<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>일응의 추정과 간접반증(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">일응의 추정이란 '사실상의 추정으로서, 고도의 개연성이 있는 경험칙을 이용하여 간접사실(전제사실)로부터 주요사실(추정사실)을 추정하는 경우' — 간접반증이란 '주요사실에 대하여 일응의 추정이 생긴 경우에, 그 추정의 전제사실과 양립되는 별개의 간접사실을 증명하여 일응의 추정을 방해하기 위한 증명활동'을 말함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>공해소송에서 간접반증에 의한 증명책임의 분담(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: '공장의 폐수에 의해 피해를 입은 경우' 인과관계의 고리를 ① 유해한 원인물질의 배출 ② 원인물질의 유해성과 피해물건 도달 및 손해발생 ③ 기업에서 원인물질의 생성·유출 세 가지 간접사실로 대별할 수 있는바, ①②에 대하여는 원고로 하여금 증명을 하게 하여 증명이 성공하면 인과관계가 있는 것으로 일응의 추정을 하되, ③에 대하여는 피고측의 간접반증의 대상으로 하여 그것의 부존재 증명이 성공하면 인과관계에 관한 일응의 추정에서 벗어난다는 입장<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>의료과오소송에서 진료의무위반에 대한 과실과 인과관계의 증명책임(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 의사에게 증명책임을 전환하기보다 일응의 추정이론으로 증명책임을 완화하려는 바, ① 환자 측은 일반인의 상식에 바탕을 둔 의료상의 과실 있는 행위를 증명하고 결과 사이에 일련의 의료행위 외에 다른 원인이 개재될 수 없다는 점을 증명하면 의사의 시술상 과실 및 인과관계의 존재는 일응 추정<span class=\"cs-o\"><strong>(O)</strong></span>되고 ② 의사가 결과가 의료상의 과실로 말미암은 것이 아니라 전혀 다른 원인으로 말미암은 것이라는 점을 증명하지 않으면 법원은 의사의 과실과 인과관계를 인정하여 원고승소판결을 선고하여야 한다는 입장<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>의사의 설명의무의 증명책임</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 의사는 최소한 환자에게 설명한 내용을 문서화하여 이를 보존해야 할 직무상 필요가 있고, 의사가 그러한 문서에 의해 설명의무의 이행을 입증하기는 매우 용이한 반면 환자측에서는 설명의무가 이행되지 않았음을 입증하기는 성질상 극히 어려운 점 등에 비추어, 의사측에 설명의무를 이행한 것에 대한 증명책임이 있다고 보아 증명책임을 전환한 것으로 평가<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["★★★"], 1, "mp_3"], ["민소032", "소송종료선언", "<div class=\"cs-h\">Ⅰ. 의의 및 특수성</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">종국판결로써 계속중이던 소송이 유효하게 종료되었음을 확인·선언하는 것</div><div class=\"cs-h\">Ⅱ. 소송종료선언의 사유</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>기일지정신청이 이유 없는 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 소취하(상소의 취하)의 효력을 다투거나 ② 이당사자대립구조 소멸의 효력을 다투는 경우에 기일지정신청 인정(규칙<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67</strong></span></span>) → 청구포기·인낙, 화해의 효력을 다투는 것은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§461</strong></span></span> 준재심으로만 다툴 수 있어 기일지정신청 불인정(신청시 각하) — 判例: 청구포기·인낙·화해조서의 '당연무효 사유'를 주장하며 기일지정신청한 때에는 기일을 지정해 심리한 후, 무효사유 불인정시 소송종료선언, 무효사유 인정시 절차속행하여 소각하<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">요건: ① (필요적 변론) 기일지정신청이 있으면 법원은 소송의 유효한 종료 여부에 관하여 필요적 변론 실시 ② 기일지정신청 이유 있으면(소송종료 처리가 잘못됨) 절차속행 ③ 이유 없으면(소송종료 처리가 정당함) 종국판결로 소송종료선언</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법원이 소송종료(소송계속 없음)를 간과하여 소송절차를 진행한 후 이를 발견한 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 소취하·취하간주의 간과 ② 청구의 교환적 변경의 간과 ③ 청구인낙의 간과 ④ 확정판결의 간과가 있는 경우 소송종료선언</div>", ["★"], 1, "mp_4"], ["민소033", "소취하와 재소금지", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">원고가 제기한 소의 전부 또는 일부를 철회하는 법원에 대한 단독적 소송행위로서, 소송계속의 소급적 소멸을 가져오는 당사자의 행위에 의한 소송종료사유(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§266①</strong></span></span>)</div><div class=\"cs-h\">Ⅱ. 요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>당사자에 관한 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소취하는 원고와 그 소송대리인이 할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송물에 관한 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 원고는 모든 소송물을 자유롭게 취하할 수 있으므로 변론주의뿐만 아니라 직권탐지주의 하에서도 가능 ② 소송요건의 흠 등으로 부적법한 소도 취하 가능 ③ 소송행위로서 유효요건을 갖춰야 함 — 判例: 착오·사기·강박 등 하자있는 의사표시에 의한 소취하도 취소 불가(의사표시하자불고려설), 다만 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>5호 유추적용하여 무효 주장 가능 ④ 소송행위이므로 조건을 붙일 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>시기</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소제기 후 판결이 확정되기까지 어느 때라도 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§266①</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>방식</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 원칙적으로 소송계속법원에 '취하서'를 제출, 다만 변론·변론준비기일에서는 '말'로도 허용(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§266③</strong></span></span>) ② 피고의 동의도 서면·말로 가능 ③ 말로 하는 소취하는 상대방 출석한 변론기일에서만 할 수 있는 것은 아니고, 불출석해도 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>피고의 동의(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">피고가 본안에 관하여 ① 준비서면 제출 ② 변론준비기일 진술 ③ 변론(이 3가지를 '본안에 관한 응소'라 함)을 한 뒤에는 피고의 동의를 요함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§266②</strong></span></span>) — 피고에게도 '청구기각판결을 받을 이익'이 생기기 때문</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 피고가 주위적으로 소각하판결만을 구하고 예비적으로 청구기각판결을 구한 경우 동의 불요(예비적인 것에 그침) / 일단 동의를 거절한 후에는 다시 동의해도 소취하의 효력 불발생(동의대상인 소취하가 없어졌기 때문) / 침해가 중복제소이고 피고 스스로 부적법함을 인정해 각하를 구한 경우라면, 그 전에 본안응소를 했더라도 동의 없이 소취하 효력 인정(피고의 소극적 확정이익 보호가 목적이므로)</div><div class=\"cs-h\">Ⅲ. 효과</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송법상 효과(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 소가 취하되면 처음부터 소송이 계속되지 않았던 것과 같은 상태로 되어 소송이 종료(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§267①</strong></span></span>) → 증거조사·종국판결 등 모든 소송행위가 당연히 실효 ② 피고가 본안 응소하기 전에는 취하서 제출시 효력발생, 본안 응소 후에는 피고 동의시 효력발생 ③ 소송계속의 소급적 소멸 및 재소금지 — 후술</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>사법상의 효과(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">시효중단·제소기간준수의 실체법상 효과도 소취하로 소급적 소멸(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§170</strong></span></span>) — 다만 소송상 형성권의 사법상 효과와 관련하여 判例: 소송상 해제항변을 한 경우에는 소취하해도 해제권의 사법상 행사의 효력에 영향이 없다고 보아 병존설 입장이나, 상계항변은 상계에 관한 법원의 실질적 판단이 이루어지는 경우에 실체법상 상계의 효과가 발생한다고 보아 신병존설 입장</div><div class=\"cs-h\">Ⅳ. 재소금지(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">본안에 관한 종국판결이 선고된 후 소를 취하한 경우에는 동일한 소에 대해 다시 소 제기하는 것이 금지되는 것(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§267②</strong></span></span>) — 취지: 소취하로 인한 법원의 종국판결 농락 염려 방지와 판결의 모순·저촉 방지</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">요건: ① 본안의 종국판결 후의 소취하일 것 ② 당사자가 동일할 것 ③ 청구가 동일할 것 ④ 권리보호의 이익이 동일할 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>본안에 대한 종국판결선고 후 소취하</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 본안판결</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">재소금지는 '본안판결'이 있은 뒤 소 취하한 경우에만 적용 → 소각하판결·소송종료선언 등 소송판결 후의 소취하엔 적용 없음 — 본안판결이면 원고승소·패소 불문</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 종국판결 선고 후</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">종국판결 선고 전 소취하시 재소금지 부적용되어 뒤에 동일한 소 제기 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 소취하</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: '원고는 소를 취하하고, 피고는 이에 동의한다'는 화해권고결정 확정시 소취하 합의로 보아 재소금지 적용<span class=\"cs-o\"><strong>(O)</strong></span> — 다만 승계참가신청이 위 화해권고결정 확정으로 종결된 소송과 당사자·소송물이 동일해도 권리보호이익이 달라 재소금지 위반 아니고<span class=\"cs-x\"><strong>(X)</strong></span>, 제1심 상계항변 제출 후 항소심에서 철회한 것은 방어방법 철회에 불과하여 재소금지 부적용<span class=\"cs-x\"><strong>(X)</strong></span> → 자동채권과 동일한 채권에 기한 소제기 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 항소심에서의 소의 교환적 변경과 재소금지(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 교환적 변경의 법적성질을 구소취하·신소제기로 보는 결합설에 의해, 항소심에서의 교환적 변경은 본안 종국판결 후 소취하가 되어 다시 구청구를 되살리면 재소금지의 적용을 받아 부적법(재소금지적용긍정설)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">5) 후소인 중복소제기의 본안판결 후 소취하시 전소가 재소금지에 해당하는지 여부(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 후소의 본안판결 후 후소를 취하한 자는 전소를 유지할 수 없으므로 전소는 부적법 각하해야 함<span class=\"cs-o\"><strong>(O)</strong></span> — 전소가 재소금지에 해당</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>당사자의 동일</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 전소의 원고</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">재소의 제재를 받는 것은 전소의 원고뿐이고, 전소의 피고나 보조참가인 등은 재소금지의 제재를 받지 않음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 전소의 원고 변론종결 뒤의 승계인(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 재소금지의 '소를 취하한 자'에는 변론종결한 뒤의 특정승계인을 포함<span class=\"cs-o\"><strong>(O)</strong></span> — 다만 특정승계인은 새로운 권리보호의 이익이 있어 동일한 소라고 할 수 없음 → 당사자는 동일하나 권리보호이익이 달라 재소금지에 해당되지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 채권자대위소송의 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 대위소송이 제기된 사실을 채무자가 안 이상, 대위소송 종국판결 후 소가 취하된 때에는 채무자도 재소금지규정 적용받아 동일한 소 제기 불가<span class=\"cs-o\"><strong>(O)</strong></span> / 을이 갑의 청구를 인낙해 갑에게 대위적격을 부여한 이상, 갑이 당사자적격이 없었더라도 을은 재소금지 원칙상 병을 상대로 동일소송 제기 불가<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>소송물의 동일</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 전후소 소송물의 동일</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例(구소송물이론): 실체법상 권리마다 별개 소송물 → 소유권에 기한 가옥인도청구 종국판결 후 소취하 후 매매계약에 기한 가옥인도청구는 동일한 소 아님<span class=\"cs-x\"><strong>(X)</strong></span> / 청구원인을 달리하는 별개의 독립된 소송물로서 선택적 병합관계에 있으며 공격방법만 달리하는 것이 아니라면, 하나를 종국판결 후 취하했다가 다시 제기하는 것은 재소금지 위반<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 청구기간이 다른 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 항소심에서 추가한 청구가 제1심에서 청구하지 않았던 기간에 해당하는 손해배상청구라면 제1심 청구와 소송물 동일하지 않아 재소금지 저촉 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 선결문제의 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>권리보호이익의 동일(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 권리보호이익이 동일한 경우에는 소취하권 남용의 의사가 있다고 보아 금지해야 하지만, 전소와 권리보호의 이익을 달리하는 재소일 때에는 종국판결을 농락하는 것으로는 볼 수 없어 재소금지 취지에 반하지 않음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(사정변경으로 새로운 이익이 발생한 경우) <span class=\"cs-fact-tag\"><strong>[피고가 원고의 소취하 전제조건으로 한 약정사항을 이행하지 않아 약정이 해제·실효된 사정변경]</strong></span>, <span class=\"cs-fact-tag\"><strong>[토지거래허가 전 소유권이전등기청구에서 승소 후 취하했다가 그 뒤 허가받은 경우]</strong></span>, <span class=\"cs-fact-tag\"><strong>[고유필수적 공동소송인 추가가 불가능한 항소심에서 누락사실을 안 경우 보정해 재소]</strong></span> 모두 권리보호이익을 달리하여 재소 허용<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(확인의 소 특유의 문제) <span class=\"cs-gbg\"><strong>[증여받았음을 원인으로 한 소유권확인청구 후 소취하 뒤 지분상속을 원인으로 한 지분소유권확인청구]</strong></span>는 확인의 소는 청구취지만으로 소송물이 특정되므로 청구는 동일하나 권리보호이익이 달라 동일한 소 아님<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(특정승계인의 재소) <span class=\"cs-fact-tag\"><strong>[부동산 인도청구소송 중 지분 양도·양수에 따른 소취하 및 재소]</strong></span>는 변론종결 뒤 특정승계인으로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span>에 의해 기판력이 미쳤으므로 당사자동일은 인정되나 권리보호의 이익을 달리하여 재소금지 위반 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(제3자의 새로운 권리보호이익) <span class=\"cs-gbg\"><strong>[갑의 채권자 병이 을을 상대로 추심금청구를 제기했다가 항소심에서 소취하한 후 갑의 다른 채권자 정이 동일한 추심금청구를 제기한 경우]</strong></span>, <span class=\"cs-gbg\"><strong>[구분소유자가 부당이득반환을 구하는 소를 제기했다가 패소 후 소취하하였다가, 관리단이 대신 제기한 부당이득반환청구]</strong></span> 모두 목적·주체가 달라 새로운 권리보호이익이 발생해 재소금지 반하지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(소송법상 효과) 재소금지는 소송요건·직권조사사항이므로 피고의 동의가 있어도 재소임이 발견되면 판결로 소를 각하해야 함 / (실체법상 효과) 재소금지는 소송법상의 효과에 그치고 실체법상 권리관계에는 영향이 없으므로 재소금지 효과를 받는 권리관계라 하여도 실체법상으로 소멸되는 것은 아님 — 判例: 명의신탁으로 무효인 소유권이전등기말소청구 승소 후 소취하했다가 재차 말소청구로 바꿔 제기한 사안에서, 재소금지의 효과는 동일당사자간 같은 소송물에 대해 다시 소를 제기하지 못하게 할 뿐 실체상의 권리는 소멸하지 않으므로, 원고의 소유권은 계속 남아있고 피고가 말소를 거부한 것만으로는 원고의 소유권 침해로 볼 수 없어 불법행위에 의한 손해배상청구 부정<span class=\"cs-x\"><strong>(X)</strong></span></div>", ["★★"], 1, "mp_4"], ["민소034", "청구포기인낙 및 소송상 화해", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① 청구의 포기는 원고패소확정판결과 동일한 효력 ② 청구의 인낙은 피고패소확정판결과 동일한 효력 ③ 화해는 '소송계속 중 당사자 쌍방이 소송물인 권리관계에 관한 주장을 서로 양보하여 소송을 종료시키기로 하는 기일에 있어서의 합의'로 원고일부승소·일부패소확정판결과 동일한 효력</div><div class=\"cs-h\">Ⅱ. 성립요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>당사자</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>변론주의에 의하는 소송일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">청구포기·인낙 및 소송상 화해는 변론주의에 의하는 절차에서만 허용되며 직권탐지주의 절차에서는 불허 — 判例: '재심대상판결을 각 취소한다'는 조정(화해)은 법원의 형성재판 대상으로서 당사자가 자유롭게 처분할 수 있는 권리에 관한 것이 아니어서 당연무효<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>소송요건에 흠이 있는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소송요건 흠결시에도 원칙적으로 소송상 화해 허용(제소전 화해 제도가 있기 때문) — 다만 청구의 포기·인낙은 제소전 청구포기·인낙 제도가 없어 소송요건 흠결시 소각하해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>강행규정 내지 반사회질서에 위반되지 아니할 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 청구포기·인낙 및 소송상 화해는 소송행위이므로 강행법규 위반 등 실체법상 하자가 있어도 화해는 유효<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>조건부 소송상 화해의 인정 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 소송상 화해의 성질을 소송행위설에 의하면서도, 실효조건부 화해의 효력은 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>시기</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소송계속 중이면 어느 때나 가능, 항소심·상고심에서도 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>방식</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 원칙: 변론기일·변론준비기일에 양쪽 당사자가 출석해 말로 함 ② 불출석한 당사자가 진술간주되는 서면에 청구의 포기·인낙 의사표시를 기재하고 공증사무소의 인증까지 받은 경우 청구의 포기·인낙 성립(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§148②</strong></span></span>) ③ 화해의 의사표시를 기재하고 공증사무소 인증까지 받은 경우, 상대방 당사자가 출석해 화해의 의사를 받아들였을 때 화해 성립(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§148③</strong></span></span>) — 서면화해제도</div><div class=\"cs-h\">Ⅲ. 법적성질(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例: 청구의 포기·인낙을 법원에 대한 소송의 종료를 목적으로 하는 관념의 표시에 불과한 소송행위로 보는 소송행위설 입장 — 소송상 화해도 판결의 내용으로서 소송물인 법률관계를 확정하는 효력이 있으므로 순연한 소송행위로 보는 소송행위설 입장(소송행위로 보면 소송법 규율만 받고 민법 적용이 배제되어, 강행법규 위반 등 실체법상 무효·취소사유가 있어도 화해는 유효) — 청구의 인낙은 피고가 원고의 주장을 승인하는 관념의 표시에 불과한 소송상 행위로서 조서 기재시 확정판결과 동일한 효력이 발생해 소송을 종료시키는 효력이 있을 뿐, 실체법상 채권·채무의 발생·소멸의 원인이 되는 법률행위는 아님<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅳ. 효과 - 확정판결과 동일한 효력</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>기판력(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>확정판결과 동일한 효력 발생</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">화해조서 작성시 확정판결과 동일한 효력(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§220</strong></span></span>) — 判例: 청구의 포기·인낙과 소송상 화해는 확정판결과 동일한 효력이 있으므로 제한 없이 기판력이 발생한다고 보는 무제한기판력설 입장</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>기판력의 발생범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例(조정): ① 조정조서에 인정되는 확정판결과 동일한 효력은 소송물인 법률관계에만 미치고 그 전제가 되는 법률관계까지는 미치지 않음 → 부동산소유권이전등기에 관한 조정조서의 기판력은 소송물이었던 이전등기청구권의 존부에만 미치고 부동산 소유권 자체에까지는 미치지 않음<span class=\"cs-x\"><strong>(X)</strong></span> ② 따라서 부동산소유자가 조정의 당사자로서 조정조서의 기판력으로 말미암아 등기부상 소유명의를 회복할 방법이 없어졌더라도 소유권이 그에게 없음이 확정된 것은 아니고, 제3자에 대해 다툼의 대상이 된 부동산이 자기 소유라는 확인을 구할 법률상 이익 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>화해조서가 서로 모순·저촉되는 경우의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 제1화해 성립 후 이와 모순·저촉되는 제2화해가 성립해도, 제1화해가 조서에 기재되어 기판력 발생한 이상 제2화해에 의해 제1화해가 당연히 실효되거나 변경되는 것은 아님<span class=\"cs-x\"><strong>(X)</strong></span> → 제1화해조서 집행으로 마쳐진 등기 등도 무효로 볼 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> — 이 경우 제2화해가 준재심사유(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§461</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>10호)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송종료효</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">청구의 포기·인낙 및 화해조서 작성시 확정판결과 동일한 효력이 있기 때문에 그 범위에서 소송은 종료됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>집행력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">화해조서에 구체적인 이행의무를 내용으로 하는 기재가 있는 경우 집행력을 갖춤</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>실체법상 화해의 창설적 효력 인정 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 재판상 화해에 실체법상 창설적 효력 인정 — 화해권고결정과 제소전 화해도 재판상 화해와 같은 효력을 가지며 창설적 효력을 가져, 화해가 이루어지면 종전의 법률관계를 바탕으로 한 권리·의무관계는 소멸함과 동시에 새로운 법률관계가 유효하게 형성 → 다투어지는 법률관계의 존부에 관해 확정된 화해권고결정이 있으면 당사자는 이에 반하는 주장 불가, 법원도 저촉되는 판단 불가<span class=\"cs-o\"><strong>(O)</strong></span> ② 소유권등기말소청구소송 중 화해권고결정 확정되면 상대방은 여전히 물권적 방해배제의무를 지고, 창설적 효력이 있다고 하여 청구권의 법적성질이 채권적 청구권으로 바뀌지 않음<span class=\"cs-x\"><strong>(X)</strong></span> ③ 창설적 효력이 미치는 범위는 당사자 간에 다투어졌던 권리관계에만 미치는 것으로, 다투지 않은 사실이나 화해의 전제로 서로 양해하고 있는 사항에는 창설적 효력이 생기지 않음 → 화해의 대상이 아닌 종전의 다른 법률관계까지 소멸하는 것은 아님<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>형성력(★) - 공유물분할에 관한 조정조서의 형성력 유무</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">화해조서가 법률관계의 발생·변경·소멸을 내용으로 하면 형성력이 생김 — 判例: 공유물분할청구에서 현물분할의 협의가 성립하여 조정이 성립하여도, 재판에 의한 공유물분할과 달리 협의에 따른 새 법률관계가 창설되는 것은 아니고, 다른 공유자의 공유지분을 이전받아 등기를 마쳐야 비로소 소유권을 취득(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§186</strong></span></span> 물권변동) → 형성력 부정(부정설)</div><div class=\"cs-h\">Ⅴ. 소송상 화해의 효력을 다투는 방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>기속력을 다투는 방법 - 판결의 경정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">화해조서에 명백한 오류가 있을 때에는 판결에 준하여 경정(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§211</strong></span></span>)이 허용됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>기판력을 다투는 방법(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>당연무효사유로 다투는 경우 - 기일지정신청</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">화해조서에 확정판결의 당연무효사유가 있는 경우, 당사자가 당연무효를 주장하며 기일지정신청을 한 때에는 법원은 무효사유의 존부를 심리한 다음 불인정시 소송종료선언을 해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>당연무효 외의 사유로 다투는 경우 - 준재심</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">무제한기판력설(判例)에 의하면 청구의 포기·인낙과 화해에 실체법상의 하자가 재심사유(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>3호 무권대리, 5호 사기강박)에 해당하는 경우에 한하여 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§461</strong></span></span>의 준재심으로만 다툴 수 있을 뿐, 기일지정신청이나 무효확인의 소를 제기할 수는 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>화해조서상 의무 불이행을 이유로 한 화해의 해제 가부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: (화해의 해제) 소송상 화해는 확정판결과 동일한 효력과 무제한 기판력을 갖는다고 보기 때문에, 소송상 화해가 사법상 계약이 아님을 들어 실체법상 채무불이행을 이유로 소송상 화해를 해제할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> — (화해에 따른 매매계약의 해제) 다만 화해 자체의 해제가 아니라, 화해에 따른 매매계약의 채무불이행을 이유로 매매계약 자체를 해제하는 것은 화해의 변론종결 뒤 새로이 발생한 해제권 행사로 시적범위에서 차단되지 않아 허용<span class=\"cs-o\"><strong>(O)</strong></span> — 소송상 화해의 변론종결시점은 화해조서 작성시라는 점 주의</div>", ["★"], 1, "mp_4"], ["민소035", "제소전 화해와 화해권고결정", "<div class=\"cs-h\">Ⅰ. 의의와 법적성질(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">소송계속 전에 지방법원 단독판사 앞에서 화해신청을 하여 민사분쟁을 해결하는 절차 — 判例: 제소전 화해는 재판상 화해로서 확정판결과 동일한 효력이 있고 창설적 효력을 가지는 것이므로 화해 성립시 종전의 법률관계를 바탕으로 한 권리의무관계는 소멸한다고 보아 소송행위설 입장으로 창설적 효력 인정</div><div class=\"cs-h\">Ⅱ. 성립요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① 당사자가 임의로 처분할 수 있는 권리관계일 것 ② 민사상의 다툼이 있을 것 — 判例: 제소전 화해를 신청하기 위해서는 화해절차 이전에 현실의 다툼이 있어야 하고, 다툼 없이 이미 성립된 토지거래계약에 기하여 오로지 거래허가제 적용을 면탈하기 위한 화해신청은 부적법<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 화해조서의 효력</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>기판력 발생과 다투는 방법(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">제소전 화해조서도 확정판결과 같은 효력(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§220</strong></span></span>) — 判例: 제소전 화해의 기판력에 관하여는 소송상 화해의 법리와 다르지 않다고 보아 무제한기판력설 입장, 흠이 재심사유에 해당하는 경우에 한하여 준재심의 소를 제기할 수밖에 없음 — 제소전 화해가 준재심으로 취소되지 않은 이상, 그에 기해 마쳐진 소유권이전등기가 원인무효라고 주장하며 말소청구하는 것은 제소전 화해로 확정된 청구권을 부인하는 것이어서 기판력에 저촉<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>제소전 화해와 중간생략합의(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 소유권이전등기가 제소전 화해조서의 집행으로 이루어진 경우, 화해 성립 이전에 제출할 수 있었던 사유에 기한 주장·항변은 기판력에 의해 차단되어 화해내용에 반하는 주장 불가<span class=\"cs-x\"><strong>(X)</strong></span> — 다만 화해 성립 이후에 새로 발생한 사실을 주장하여 화해에 반하는 청구를 하는 것은 기판력 저촉 아님<span class=\"cs-o\"><strong>(O)</strong></span> ② [갑이 병으로부터 매수한 부동산을 을에게 전매하면서 등기명의를 병에서 을로 직접 이전하기로 하는 중간등기생략합의를 하고, 을이 병을 상대로 제소전 화해를 신청해 소유권이전등기를 마친 경우] 을 명의 등기가 병·을 간 제소전 화해에 의한 것이라 해도 실질은 갑·을 간 매매계약과 중간생략합의에 의한 것이므로, 을이 잔대금을 미지급한 경우 갑은 최고절차를 거쳐 매매계약을 해제하고 을에게 직접 해제를 원인으로 한 말소등기청구 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅳ. 화해권고결정</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">법원·수명법관 또는 수탁판사는 계속중인 사건에 대하여 직권으로 당사자의 이익 등 모든 사정을 참작하여 청구의 취지에 어긋나지 아니하는 범위에서 화해권고결정 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§225</strong></span></span>) — 당사자는 조서·결정서 정본을 송달받은 날부터 2주 이내 이의신청 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§226</strong></span></span>) → 이 기간 내 이의신청 없는 때 등 일정사유에 해당하면 재판상 화해와 같은 효력(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§231</strong></span></span>) — 화해권고결정 확정시 확정판결과 동일한 효력이 있고, 기판력은 그 확정시를 기준으로 발생</div>", ["★"], 1, "mp_4"], ["민소036", "판결 - 일부판결", "<div class=\"cs-h\">Ⅰ. 일부판결</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>일부판결의 의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">동일소송절차에 의해 심판되는 사건의 일부를 다른 부분에서 분리하여 먼저 완결하는 종국판결(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§200①</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>일부판결의 허용 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>일부판결이 허용되는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">판결의 모순·저촉 우려가 없으면 가능하고, 여부는 원칙적으로 법원의 재량(가분적 청구 중 수액이 확정된 경우, 단순병합, 통상공동소송, 변론병합된 청구 중 하나, 본소·반소 중 하나 등에 가능) — 判例(단순병합): 원금청구부분만 판단하고 지연손해금청구부분을 판단하지 않은 경우, 이는 재판누락으로 아직 원심에 계속 중이어 적법한 상고의 대상이 아니므로 상고는 부적법<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>일부판결이 허용되지 않는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">일부판결 후 잔부판결이 법률상 허용될 수 없거나, 일부판결·잔부판결 간 모순·저촉 우려가 있을 때는 불허(선택적·예비적 병합, 본소·반소가 동일목적 형성청구이거나 소송물이 동일한 법률관계일 때, 필수적 공동소송, 예비적·선택적 공동소송, 독립당사자참가 등) — 判例: 예비적 공동소송은 판결의 모순·저촉 방지를 위해 모든 공동소송인에게 전부판결을 해야 하고, 일부 공동소송인에만 판결하거나 남겨진 자를 위해 추가판결하는 것은 불허<span class=\"cs-x\"><strong>(X)</strong></span> → 일부 공동소송인에 관한 재판도 전부판결에 해당해 판단누락에 준하는 위법한 판결이므로, 누락된 공동소송인은 판결의 유·불리와 무관하게 상소로 제1심판결 취소를 구할 수 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>일부판결의 효력(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(일부판결이 허용되는 경우) ① 의도적으로 일부판결을 한 경우 나머지는 잔부판결으로 완결해야 함 ② 모르고 일부판결을 한 때는 나머지 미판결 부분은 재판누락(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§212</strong></span></span>)으로 제1심에 계속 중이며 추가판결으로 완결해야 함 → 상소대상이 될 수 없어 상소는 부적법 각하</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(일부판결이 불허되는 경우인데도 일부판결한 경우) 전부판결로 취급되어 미판결 부분은 판단누락에 준하는 위법한 판결으로 취급되어, 추가판결이 아니라 판단누락으로서 확정 전 상소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§424①</strong></span></span>6호), 확정 후 재심(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>9호 판단누락)으로만 구제받을 수 있음 — 判例: 당사자 주장사항에 대한 구체적·직접적 판단이 판결에 표시되지 않아도 판결이유의 전반적 취지상 그 주장을 인용하거나 배척했음을 알 수 있는 정도라면 판단누락이 아님<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>재판의 누락과 추가판결</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>재판누락의 의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">법원이 청구 전부에 대하여 재판할 의사였으나 실수로 청구의 일부만 판결을 한 경우(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§212</strong></span></span>) — 추가판결: 누락된 부분에 대해 하는 종국판결</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>재판누락의 판단기준</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">재판누락 여부는 '판결주문의 기재'로 판단 — 判例: 주문에 표시 없으면 이유 속에 판단이 되어있어도 재판누락<span class=\"cs-o\"><strong>(O)</strong></span>, 반대로 이유 속에 표시 없어도 주문에 기재가 있으면 재판누락으로 볼 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>재판누락과 그 구제수단</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">일부판결이 허용되는 경우 실수로 재판누락이 있는 부분은 이를 누락시킨 법원에 그대로 계속되어 있으므로 추가판결해야 함 → 그에 대한 상소는 대상적격 없어 부적법하므로 상소각하판결을 면할 수 없음</div><div class=\"cs-h\">Ⅱ. 판결의 경정과 특별항고(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의 및 취지</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">판결내용을 실질적으로 변경하지 않는 범위 내에서 판결서의 표현상 오류를 판결법원 스스로 고치는 것(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§211</strong></span></span>) — 취지: 광의의 강제집행에 지장이 없도록 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 판결의 표현상 잘못이 있을 것 ② 표현상 잘못이 분명할 것 ③ 판결의 내용을 실질적으로 변경하는 경우가 아닐 것 — 判例: 경정가능한 오류에는 법원의 과실로 생긴 경우와 당사자의 청구에 잘못이 있어 생긴 경우도 포함되며, 경정결정 시 소송 전 과정에 나타난 자료뿐 아니라 경정대상 판결 이후 제출된 자료도 다른 당사자에게 불이익 없거나 다투어질 기회가 있었던 경우에는 소송경제상 참작해 오류의 명백성을 판단할 수 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>관련판례 연구</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 피신청인의 주민등록번호 미기재는 관련법령에 따른 적법한 것이어서 잘못된 기재나 이와 비슷한 잘못에 해당하지 않아 판결경정 신청 기각<span class=\"cs-x\"><strong>(X)</strong></span> — 강제집행상 어려움은 민사소송규칙 등으로 별도 해결 가능 / <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§446</strong></span></span>에 따라 제1심법원이 항소장각하명령에 관한 항고에 정당한 이유가 있다고 인정해 재판을 경정한 경우, 불이익받는 상대방 당사자는 경정재판에 다시 즉시항고로 불복 가능<span class=\"cs-o\"><strong>(O)</strong></span> — (판결경정기각결정에 대한 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§449①</strong></span></span> 특별항고 가부) ① 판결의 경정은 판결내용을 실질적으로 변경하지 않는 범위에서 표현상 오류가 명백한 경우 법원 스스로 경정 가능 ② 경정대상 판결 주문의 오류가 당사자의 잘못된 청구로 유발되었더라도 명백히 인정될 수 있고 경정해도 내용을 실질적으로 변경하지 않는다면 경정을 인정해야 함 → 이를 간과한 기각결정은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§449①</strong></span></span>의 재판에 영향을 미친 헌법위반에 해당하여 특별항고 인용 가능<span class=\"cs-o\"><strong>(O)</strong></span> — 다만 아직 수계신청을 하지 않아 소송절차가 중단된 상태의 당사자에 대해서는 경정을 통해 당사자를 변경 반영할 수 없어(그 절차는 별도 수계신청으로 해결), 그 부분 경정신청기각은 정당<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["★★★"], 1, "mp_4"], ["민소037", "기판력 사례풀이 구조", "<div class=\"cs-h\">Ⅰ. 기판력의 발생요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">유효한 종국판결이 확정되어야 하므로 무효인 판결에는 기판력이 발생하지 않음(재판권 흠결을 간과한 판결, 제소전 이미 사망한 자를 당사자로 한 판결, 당사자적격 없는 자가 받은 판결, 소송계속이 소멸하였음에도 이를 간과한 판결 등은 무효인 판결으로 기판력 불발생)</div><div class=\"cs-h\">Ⅱ. 기판력의 작용 여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>기판력의 주관적 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">기판력은 당사자에게만 미치고 제3자에게는 미치지 않는 것이 원칙(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span>) — 다만 예외적으로 법률에 특별한 규정이 있는 경우에는 기판력이 당사자 이외의 제3자에게도 미치는 경우가 있음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span>·②·③ 등)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>기판력의 객관적 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>전소 판결의 기판력의 발생범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">확정판결은 주문에 포함된 것에 한하여 기판력이 생기고 판결이유 중의 판단에는 생기지 않음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§216①</strong></span></span>) — 다만 상계항변은 판결이유 중에서 판단되지만 상계로 대항한 액수의 한도 내에서는 기판력 발생(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§216②</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>후소에의 기판력의 작용범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">전소확정판결의 기판력은 후소의 소송물이 전소의 소송물과 동일하거나, 전소의 소송물을 선결문제로 하거나, 전소의 소송물과 모순관계에 있는 경우에 작용</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>기판력의 시적 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 사실심 변론종결 전에 당사자가 주장했거나 주장할 수 있었던 공격방어방법은 기판력의 실권효로 차단되어 후소에서 주장 불가 ② 전소 변론종결 후 새로이 발생한 사실의 주장은 차단효의 제재를 받지 않음 ③ 전소 변론종결 전의 사유라도 소송물이 다르면(동일·선결·모순이 아닌 경우) 후소에서 차단되지 않음</div><div class=\"cs-h\">Ⅲ. 법원의 조치 - 기판력의 본질</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例: 기판력을 후소법원에 대해 전소 확정판결과 모순된 판단을 금지하는 효력으로 보는 모순금지설 입장 — (동일·모순관계로 작용하는 경우) ① 전소 승소확정판결 받은 원고가 다시 동일소 제기시 권리보호이익 없어 소각하판결 ② 전소 패소확정판결 받은 원고가 다시 동일소 제기시 전소와 모순된 판단 금지의 구속력 때문에 청구기각판결 — (선결관계로 작용하는 경우) 후소법원은 소각하판결 불가, 선결문제 한도 내에서 전소의 기판력 있는 판단을 전제하여 본안판결해야 함</div><div class=\"cs-h\">Ⅳ. 전소 승소확정 판결 후 동일한 후소 제기가 권리보호이익이 있는 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例: ① 임차인이 임대인 상대 보증금반환의 승소확정판결 받은 후 변론종결 뒤 승계인을 상대로 승계집행문 부여의 소를 제기해 승계집행문을 부여받아 강제집행 가능<span class=\"cs-o\"><strong>(O)</strong></span> ② 그럼에도 임차인이 승계인을 상대로 보증금반환의 후소를 제기한 경우 전소기판력이 후소에 미쳐 모순금지설에 의하면 후소는 권리보호이익 없어 부적법 소각하해야 함<span class=\"cs-x\"><strong>(X)</strong></span> ③ 다만 후소에서 임대인 지위 승계여부에 대해 공격방어 및 법원의 심리가 진행되어 사실상 승계집행문 부여의 소가 제기되었을 때와 차이가 없음에도 후소법원이 소의 이익 없다는 이유로 각하하고 다시 승계집행문 부여의 소를 제기하도록 하는 것은 당사자의 노력·시간을 무위로 돌리고 동일한 소송행위를 반복시켜 가혹하며, 신속한 분쟁해결·소송경제 측면에서도 타당하지 않아 소의 이익 인정<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["★★★★★"], 1, "mp_4"], ["민소038", "기판력의 주관적 범위", "<div class=\"cs-h\">Ⅰ. 기판력의 상대성의 원칙</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">기판력은 당사자에게만 미치고 제3자에게는 미치지 않는 것이 원칙(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span>) — 제3자의 절차권 침해 방지 취지 — 判例(법인격부인): 갑회사와 을회사의 기업형태·내용이 실질적으로 동일하고 갑회사가 을회사의 채무를 면탈할 목적으로 설립되었더라도, 절차의 안정을 중시해 소송절차 및 강제집행절차에서는 을회사에 대한 판결의 기판력·집행력이 갑회사에게까지 미치는 것은 아님<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 변론종결한 뒤의 승계인 - <span class=\"cs-blue\"><span class=\"cs-u\">§218①</span></span>(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의 및 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">확정판결의 기판력은 변론종결한 뒤의 승계인에게도 효력이 미침 — 요건: ① 변론종결 뒤에 승계가 이루어졌을 것 ② 승계인에 해당할 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>변론종결 '뒤에' 승계가 있을 것(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 부동산물권변동의 효력이 생기는 때(소유권이전등기) 기준으로 변론종결 전후 판단 — 가등기는 변론종결 전, 이에 기한 본등기(물권변동)가 변론종결 뒤에 마쳐진 때도 변론종결 뒤의 승계인<span class=\"cs-o\"><strong>(O)</strong></span> ② 피고측 제1차 승계가 변론종결 이전이면, 제2차 승계가 변론종결 이후라도 제2차 승계인은 변론종결 후의 승계인이 아님<span class=\"cs-x\"><strong>(X)</strong></span> ③ 채권양수인이 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span>의 승계인에 해당하는지는 채권양도 합의시가 아니라 대항요건을 갖춘 때를 기준으로 판단</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>'승계인'에 해당할 것(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">1) 소송물인 권리의무 자체를 승계한 자(★) - 청구취지에 기재된 권리의무의 승계</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">변론종결 뒤 소송물인 실체법상 권리의무를 승계한 자 — 원고의 청구권이 물권적·채권적이든 제한 없이 해당(변론종결 뒤의 포괄승계인인 상속인, 흡수·신설합병의 존속·신설회사, 소유권확인판결의 소유권 양수인, 이행판결의 채권 양수인·채무 면책적 인수인 등)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 대항력 있는 임차주택 양수인은 임대인 지위를 승계하므로 임대차보증금반환채무도 부동산소유권과 결합하여 일체로 이전되고 양도인의 채무는 소멸하므로, 변론종결 후 임대부동산 양수인은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span>의 승계인에 해당(O, 채권적 청구권이라도 해당)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(부정판례) ① 병존적 채무인수인은 전 채무자의 채무가 그대로 존속하며 별개의 채무를 부담하는 것으로 승계인 아님<span class=\"cs-x\"><strong>(X)</strong></span> ② 확정판결 변론종결 후 채무자로부터의 영업양수인은 채무를 면책적으로 인수하는 특별사정이 없는 한 승계인 아님<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">2) 계쟁물에 관한 당사자적격을 승계한 자(★) - 청구원인에 기재된 권리의무의 승계</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">변론종결 뒤의 계쟁물에 관한 당사자적격을 승계받은 자도 포함 — 判例(구소송물이론): 원고의 청구권이 ① 물권적 청구권이면 대세적 효력이 있어 승계인에 포함<span class=\"cs-o\"><strong>(O)</strong></span> ② 채권적 청구권이면 대인적 효력뿐이라 승계인에 불포함<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(물권적 청구권 → 승계인 O) 소유권에 기한 이전등기 말소청구 확정판결 확정 후 패소피고로부터 이전등기를 경료한 자는 승계인<span class=\"cs-o\"><strong>(O)</strong></span> / 소유권등기말소·진정명의회복청구(물권적 청구권) 소송물에 대해 화해권고결정이 확정되면 상대방은 여전히 물권적 방해배제의무를 지고, 창설적 효력이 있다고 해도 청구권의 성질이 채권적 청구권으로 바뀌지 않으므로 승계인 해당<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(채권적 청구권 → 승계인 X) 매매에 기한 소유권이전등기소송(채권적 청구권) 승소판결 확정 후 제3자가 먼저 패소피고로부터 이전등기를 경료한 경우 그 제3자는 승계인 아님<span class=\"cs-x\"><strong>(X)</strong></span> / [한국전력공사의 송전선이 상공을 통과하는 토지의 소유자가 제기한 부당이득반환소송(채권적 청구권)에서 정기금지급 확정판결 후, 그 후 토지소유권을 취득한 제3자가 다시 부당이득반환을 구한 경우]도 장래의 부당이득반환채권은 양도할 수 없어 소송물을 양수한 변론종결 뒤의 승계인에 해당하지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(예외판례 Ⅰ) [갑의 을에 대한 소유권에 기한 건물·토지인도소송에서 갑 청구기각판결이 확정된 뒤, 갑으로부터 소유권을 취득한 병이 다시 을을 상대로 소유권에 기한 인도청구를 제기한 경우] 병이 가지는 물권적 인도청구권은 적법하게 승계한 소유권(계쟁물)의 일반적 효력으로 발생한 것이지, 위 소송의 소송물인 패소자(갑)의 인도청구권(소송물)을 승계함으로써 가지게 된 것이 아니므로 병은 변론종결 후의 승계인에 해당하지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(예외판례 Ⅱ) <span class=\"cs-gbg\"><strong>[가등기말소청구소송의 사실심변론종결 후 토지소유자로부터 근저당권을 취득한 제3자]</strong></span>는 적법하게 취득한 근저당권(계쟁물)의 일반적 효력으로 물권적 청구권을 갖게 된 것이지, 소송물인 패소자의 가등기말소청구권을 승계한 것이 아니므로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span>의 승계인 아님<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(기판력의 객관적 범위가 다른 경우와 승계인)(★) 判例: 소송물이 동일·선결·모순관계로 기판력이 미치는 객관적 범위에 해당하지 않는 경우에는, 전소 변론종결 후 계쟁물을 승계한 자가 후소를 제기해도 후소에 전소의 기판력이 미치지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">3) 승계인에게 고유한 방어방법이 있는 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例(구소송물이론, 실질설): 승계인이 고유의 방어방법을 갖고 있으면 실질적으로 당사자 지위를 승계했다고 말할 수 없어 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span>의 승계인 아님<span class=\"cs-x\"><strong>(X)</strong></span> — 승계인은 판결의 효력을 받지 않으므로 원고가 집행문부여의 소를 제기해야 하고, 이때 승계인은 고유의 방어방법을 항변으로 제출해 집행문 부여를 막을 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(변론종결 뒤 승계인의 소의 이익 유무)(★) 判例: 전소기판력이 후소에 미쳐(명의신탁자가 임대인 지위 승계로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span> 승계인 해당) 모순금지설에 의하면 후소는 원칙적으로 권리보호이익 없어 소각하해야 하나, 후소에서 임대인 지위 승계여부에 대해 상당한 공격방어·법원심리가 진행되어 사실상 승계집행문 부여의 소가 제기된 것과 차이가 없다면, 법원이 이를 각하하고 다시 승계집행문 부여의 소를 제기하도록 하는 것은 당사자의 노력·시간을 무위로 돌리고 가혹하며 신속한 분쟁해결·소송경제에 반하므로 소의 이익 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>추정승계인(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 당사자가 변론종결 전에 소송물을 승계해도 승계사실을 진술하지 않으면 변론종결 후 승계가 있는 것으로 추정되어 기판력이 미침(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218②</strong></span></span>) ② 이에 따라 원고는 승계사실만 증명하면 피승계인 상대 승소판결으로도 승계인에 대한 승계집행문을 구할 수 있고, 이때 승계인이 변론종결 전에 승계되었음을 주장·증명해야만 기판력에서 벗어날 수 있음 — 判例: 종전 확정판결의 기판력 배제를 원하는 당사자가 변론종결 전 당사자지위 승계사실을 입증하면, 종전소송에서 승계에 관한 진술 여부와 무관하게 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218②</strong></span></span>의 추정은 깨어짐<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>청구의 목적물의 소지인 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">확정판결의 기판력은 당사자를 위하여 청구의 목적물을 소지한 사람에게도 미침</div><div class=\"cs-h\">Ⅲ. 제3자 소송담당의 경우 - <span class=\"cs-blue\"><span class=\"cs-u\">§218③</span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">다른 사람을 위하여 원고나 피고가 된 사람(소송담당자)이 받은 확정판결의 기판력은 권리의무의 귀속주체인 다른 사람에게도 미침</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>채권자대위소송과 기판력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>채권자대위소송의 기판력과 집행력이 채무자에게 미치는지 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(기판력 긍정) 判例: 채권자가 대위소송을 제기해 판결이 확정된 후 채무자가 별소를 제기한 경우, 채무자가 대위소송 제기사실을 안 경우에만 기판력이 채무자에게 미침<span class=\"cs-o\"><strong>(O)</strong></span> — (집행력 부정) 그러나 채권자대위소송의 청구인용판결이 확정되어도, 기판력은 채무자에게도 미치는 경우가 있더라도 집행력은 채권자·제3채무자간에만 생기고 채무자·제3채무자 사이에는 생기지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>채무자의 제3채무자에 대한 소송의 판결의 효력이 채권자에게 미치는지 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[채무자가 제3채무자에게 소를 제기해 패소본안판결이 확정된 후 채권자가 제3채무자를 상대로 채권자대위소송을 제기한 경우]</strong></span> ① (기판력) 당사자가 다르지만 실질상 동일한 소송으로 기판력이 미침(O, 모순금지설에 의해 후소는 청구기각판결) ② (대위요건 흠결) 다만 채권자가 대위권 행사 당시 이미 채무자가 권리를 재판상 행사했다면, 패소본안판결을 받았더라도 채권자는 대위할 당사자적격 없어 부적법 각하 ③ (법원의 조치) 후소는 기각사유와 각하사유가 모두 존재하나, 소송요건의 선순위성 원칙에 따라 부적법 각하해야 함 — <span class=\"cs-fact-tag\"><strong>[제3채무자가 채무자에게 소를 제기해 판결이 확정된 후 채권자가 제3채무자를 상대로 다시 채권자대위소송을 제기한 경우]</strong></span>도 동일한 논리가 적용됨(기판력 미침, 대위요건 흠결시 각하, 선순위성 원칙에 따른 각하)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>채권자대위소송의 기판력이 다른 채권자의 대위소송에 미치는지 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 어느 채권자가 대위소송을 제기해 판결이 확정된 후 다른 채권자가 다시 대위소송을 제기한 경우, 채무자가 전소인 채권자대위소송을 안 경우에만 전소의 기판력이 다른 채권자의 후소인 채권자대위소송에 미침<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>채권자대위권에서 피보전채권이 없다는 이유로 한 소각하 판결의 기판력이 채권자의 피보전채권 이행소송에 미치는지 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 채권자대위권의 소송물은 피대위권리, 채권자의 피보전채권 이행소송의 소송물은 피보전채권으로 서로 다르므로, 소각하판결의 기판력은 채권자의 피보전채권 이행소송에 미치지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(5) <strong>채권자가 채무자를 상대로 소를 제기하였으나 패소의 확정판결을 받은 후 채권자대위소송을 제기한 경우 대위소송의 적법 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 채권자가 대위소송에서 승소해 제3자 명의 이전등기가 말소되더라도 채권자가 채무자에게 동일한 청구원인으로 다시 이전등기절차 이행을 구할 수 있는 것도 아니므로, 대위소송은 보전의 필요성이 없어 부적법하여 각하<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(6) <strong>채권자가 채무자를 상대로 소를 제기하였으나 승소의 확정판결을 받은 후 제3채무자를 상대로 채권자대위소송을 제기한 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 이 경우 제3채무자를 상대로 한 대위소송에 기판력은 미치지 않으나, 제3채무자는 피보전채권의 존부를 다툴 수 없음(증명효가 미침)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>채권자취소소송과 기판력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>채권자취소소송의 판결이 확정된 후 다른 채권자가 다시 취소소송을 제기한 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(기판력) 채권자취소소송의 소송물은 채권자 자신의 채권자취소권이므로 각 채권자의 채권자취소권은 서로 별개의 권리 → 사해행위취소소송의 기판력은 다른 채권자가 제기한 동일한 사해행위취소소송에 미치지 않음<span class=\"cs-x\"><strong>(X)</strong></span> — 이미 승소판결이 확정되었다는 사정만으로 그 후에 제기된 다른 채권자의 동일한 청구가 권리보호의 이익이 없어지는 것은 아님</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(권리보호이익 긍정) 아직 수익자의 말소등기집행이 되기 전에는 후소에 권리보호이익 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(권리보호이익 부정) 수익자의 말소등기집행까지 완료된 경우 후소인 사해행위취소소송은 권리보호의 이익 없어 부적법<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>채권자취소소송으로 원물반환을 청구하여 승소판결이 확정된 후 다시 취소소송을 제기하여 가액배상을 청구한 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 원물반환청구 승소판결 확정 후 그 목적을 달성할 수 없게 되었다고 하더라도, 다시 가액배상청구를 하는 것은 권리보호의 이익 없어 허용되지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>사해행위의 수단인 확정판결의 기판력이 사해행위취소소송에 미치는지 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(사해행위 인정) 무자력상태의 채무자가 소송절차를 통해 수익자에게 책임재산을 이전하기로 하여, 수익자가 제기한 소송에서 자백 등의 방법으로 패소판결을 받아 확정시키고 소유권이전등기 등이 마쳐졌다면, 이러한 이전합의는 사해행위가 될 수 있음<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(기판력 부정) 채권자가 사해행위의 취소와 함께 수익자로부터 책임재산 회복을 명하는 판결을 받은 경우 수익자가 채권자에게 원상회복의무를 부담할 뿐, 채권자·채무자 간에 취소로 인한 법률관계가 형성되는 것은 아니므로 채무자·수익자 간 소송절차의 확정판결으로 마쳐진 등기가 사해행위취소 원상회복으로 말소되더라도 확정판결 등의 효력에 반하는 것이 아니므로 기판력 저촉 아님<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>추심채권과 기판력(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(종래판례) 압류·추심명령으로 당사자적격을 상실한 채무자가 이행소송에서 받은 확정판결의 효력은 변론종결 전 압류·추심명령을 받은 채권자에게 미치지 않고<span class=\"cs-x\"><strong>(X)</strong></span>, 이는 어느 한 추심채권자가 제기한 추심소송의 확정판결 기판력이 다른 추심채권자에게 미치지 않는다는 논리로 이어짐 → 동일채권에 복수 채권자가 압류·추심명령을 받은 경우 어느 한 채권자의 추심금소송 확정판결의 기판력은 그 변론종결일 이전에 압류·추심명령을 받았던 다른 추심채권자에게 미치지 않음(추심금소송의 소송물인 피압류채권 존부가 같아도 소송당사자가 다르면 확정판결의 기판력이 서로에게 미친다고 할 수 없고, 제3채무자에게도 부당하지 않기 때문 — 화해권고결정이 확정된 경우도 마찬가지)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(변경판례) 압류·추심명령이 있어도 채무자는 당사자적격을 상실하지 않으므로 채무자가 제3채무자 상대 이행소송에서 받은 확정판결의 효력은 추심채권자에게 미침<span class=\"cs-o\"><strong>(O)</strong></span> — 추심채권자가 추심소송에서 받은 확정판결의 기판력은 채무자에게 미치고(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218③</strong></span></span>), 채무자가 이행소송에서 받은 확정판결의 기판력은 추심채권자에게 미치므로, 결과적으로 어느 한 추심채권자가 추심소송에서 받은 확정판결의 기판력은 채무자를 통해 다른 추심채권자에게도 미침(추심명령 시기가 변론종결 전후인지 불문)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(추심권의 포기) 判例: 추심금소송에서 추심채권자가 제3채무자와 '피압류채권 중 일부 지급, 나머지 청구 포기'의 재판상 화해를 한 경우, 이는 추심채권자가 적법하게 포기할 수 있는 자신의 추심권에 관한 것으로 소송종료의 의미일 뿐, 처분권한 없는 피압류채권 자체를 포기한 것으로 볼 수 없으므로<span class=\"cs-x\"><strong>(X)</strong></span>, 이 화해의 효력은 별도의 추심명령으로 추심권을 행사하는 다른 채권자에게 미치지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>집합건물의 관리단과 기판력(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: (기판력) ① 관리단은 관리인을 대표자로 관리단집회 결의로 정한 바에 따라 공용부분의 관리에 관련된 재판상·재판외 행위를 할 수 있어, 정당한 권원 없이 공용부분·대지를 점유하는 사람에 대한 부당이득반환청구소송을 할 수 있음 ② 이는 구분소유자 공동이익을 위해 행사하는 것으로 구분소유자가 각자 부당이득반환소송을 하는 것과 다른 내용의 소송이 아님 ③ 관리단의 부당이득반환소송 판결이 확정되면 그 효력(기판력)은 구분소유자에게도 미치고(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218③</strong></span></span>), 특별한 사정이 없는 한 구분소유자가 부당이득반환소송을 제기해 판결이 확정되어도 그 효력도 관리단에게 미침(관리단은 구분소유자에 대한 집합건물법상 법정소송담당) — (재소금지) 관리단의 이러한 소송은 구분소유자 공동이익을 위한 것으로 구분소유자가 자신의 공유지분권에 관한 사용수익을 실현하는 것을 목적으로 하는 소송과 목적이 다르므로, 구분소유자가 부당이득반환청구소송 제기 후 본안 종국판결이 있은 뒤 소취하해도, 관리단의 부당이득반환청구 소제기는 특별한 사정 없는 한 새로운 권리보호이익이 발생한 것으로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§267②</strong></span></span> 재소금지 규정에 반하지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div>", ["★★★★★"], 1, "mp_4"], ["민소039", "기판력의 객관적 범위", "<div class=\"cs-h\">Ⅰ. 판결주문에 관한 판단</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>전소 확정판결의 기판력의 발생 범위 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§216①</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§216①</strong></span></span>에 의하면 확정판결은 주문에 포함된 것에 한하여 기판력이 있음 — (소송판결) 판결이유를 참작해 정해지는 소송요건의 흠에 대한 판단에만 기판력이 생김 → 소송요건 흠으로 각하판결 받은 후 흠을 그대로 둔 채 재소하면 기판력으로 각하되나, 당사자가 흠을 보완하여(변론종결 뒤 새로운 사유) 다시 소를 제기한 경우에는 기판력의 제한을 받지 않음 — [국가배상청구의 선행소송이 민주화보상법상 재판상 화해 성립을 이유로 권리보호이익 없다는 소각하판결로 확정된 후, 민주화보상법에 대한 위헌결정이 선고되어 이 위헌결정이 선행소송 각하판결의 소송요건 흠을 보완한다고 보아, 후소 국가배상청구가 위 각하판결의 기판력에 저촉되지 않는다고 본 경우] — (본안판결) 청구취지와 판결이유를 참작해 정해지는 소송물의 존부판단에 기판력 발생 — 判例: 장래이행의 소에 대한 이행판결의 주문에서 변론종결 이후 기간까지의 급부의무 이행을 명한 이상 확정판결의 기판력은 그 기간까지의 청구권 존부에 미침</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>전소 확정판결의 기판력이 후소에 작용하는 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>소송물의 동일</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 청구취지가 동일한 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">전소에서 원고 승소·패소 불문하고 동일한 소송물 재소시 기판력 저촉 — 예외적으로 기판력 있는 판결이 있어도 시효중단을 위해 다른 방법이 없을 때는 예외적으로 재소 허용(다만 후소의 판결은 전소의 판결내용에 저촉되어서는 안 됨)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 청구취지가 다른 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">청구취지가 다르면 원칙적으로 소송물이 동일하다고 할 수 없음 — 判例: 전소의 토지 특정부분에 대한 이전등기청구와 후소의 토지 중 일정지분에 대한 이전등기청구는 청구취지를 달리해 소송물 동일 X / (말소등기청구와 진정명의회복청구) 判例: 말소등기청구와 진정명의회복을 원인으로 한 소유권이전등기청구는 모두 진정한 소유자의 등기명의를 회복하기 위한 것으로 목적이 동일하고 법적근거·성질이 동일한 소유권에 기한 방해배제청구권이므로 소송물은 실질상 동일<span class=\"cs-o\"><strong>(O)</strong></span> → 말소청구소송의 패소확정판결의 기판력은 진정명의회복청구소송에도 미침 / (임대차보증금 지급판결과 연체차임채무 부존재확인) 보증금지급판결 확정시 변론종결 전 사유로 보증금 수액 자체를 다투는 것은 불허되나, 연체차임 등 피담보채무 부존재에는 기판력 부작용<span class=\"cs-x\"><strong>(X)</strong></span> / 점유물 인도판결의 기판력은 인도청구권 존부에만 미치고, 불법점유를 원인으로 한 손해배상청구소송에는 미치지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 청구취지는 동일하나 청구원인을 이루는 실체법상 권리만 다른 경우(★) - 사실관계 1개</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 1개 사고로 불법행위에 기한 손해배상청구(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§750</strong></span></span>)를 했다가 패소확정된 뒤 채무불이행을 원인으로 한 손해배상청구(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§390</strong></span></span>)는, 실체법상 권리를 소송물로 보기에 서로 소송물이 다름 → 전소의 기판력이 후소에 미치지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 청구취지는 동일하나 청구원인을 이루는 사실관계가 다른 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 어음발행사실에 기한 어음금청구(어음법)를 했다가 패소확정 후 원인관계인 대여금으로 청구(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§598</strong></span></span>)하는 경우, 동일 대지에 대해 매매를 원인으로 한 소유권이전등기청구(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§568</strong></span></span>)를 했다가 패소확정 후 점유취득시효에 기한 소유권이전등기청구(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§245</strong></span></span>)를 하는 경우 등은 (구이론) 실체법상 권리가 다르므로 소송물이 달라 전소의 기판력이 후소에 미치지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">5) 공격방법만이 다른 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">소송물은 동일하나 요건사실만 달리 주장해 공격방법만이 다른 경우에는 기판력에 저촉(대리에 기한 청구, 사해행위취소소송, 부당이득반환청구, 말소등기청구, 소유권확인청구 등) — 判例: 말소등기청구사건의 소송물은 말소등기청구권, 전소의 사기에 의한 매매의 취소 주장과 후소의 매매의 부존재·불성립 주장은 다같이 등기원인의 무효를 뒷받침하는 공격방법에 불과하므로 전후소 소송물 동일(O, 기판력 저촉) / 소유권확인을 구하는 전소 패소확정판결을 받은 원고는 전소 사실심변론종결 전에 주장할 수 있었던 소유권 귀속의 다른 사유를 동일 당사자간 후소에서 주장할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">6) 일부청구(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例(<span class=\"cs-u\"><strong>명시설</strong></span>): 전소에서 일부청구임을 명시한 때에는 소송물이 일부에 한정되어 후소와 소송물이 달라 기판력에 저촉되지 않으나, 묵시적인 경우 소송물은 전부이므로 후소와 소송물 동일하여 기판력에 의해 차단<span class=\"cs-x\"><strong>(X)</strong></span> — 일부청구임을 명시하는 방법으로는 전체 채권액을 특정해 일부만 청구하고 나머지 청구를 유보하는 취지를 밝힌 경우와, 일부청구하는 채권의 범위를 잔부청구와 구별해 심리범위를 특정할 수 있는 정도로 표시하여 전체채권의 일부로 우선 청구함을 밝히는 것으로 족함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>후소의 선결관계</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 전소의 소송물이 후소의 선결적 법률관계인 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">원고가 소유권확인청구로 승소확정판결을 받은 뒤 같은 피고를 상대로 소유권에 기한 물권적청구권을 구하는 경우와 같이 전소의 소송물이 후소의 선결적 법률관계가 되는 때에는 전소 확정판결의 기판력이 후소에 미쳐 후소법원은 전소 판단과 모순되는 판단을 할 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 항변사유가 되는 때(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">전소의 기판력 있는 판단이 후소의 항변사유가 될 때에도 기판력이 작용 — [갑이 채권자대위소송에서 소각하판결을 받은 뒤 을이 갑을 상대로 제기한 건물철거·대지인도청구에서 갑이 채권자대위권이 있음을 전제로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§213</strong></span></span>단서의 항변을 하는 경우] 후소의 선결관계로 기판력이 작용</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>모순관계</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 모순관계 판단</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">전·후소의 소송물이 동일하지 않더라도 후소의 소송물이 전소의 기판력 있는 판단과 모순관계에 있는 사항을 소송물로 할 때에는 후소는 전소의 기판력에 저촉</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 금전청구의 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">소비대차를 이유로 대여금청구를 해 승소확정판결을 받아 강제집행한 다음, 소비대차가 무효라고 주장하며 동액 부당이득청구의 소를 제기하는 경우, 후소의 청구취지는 전소의 주문판단인 금전지급청구권 자체를 부인하는 것이고, 청구원인도 전소 이유에서 인정된 소비대차사실을 부인하는 것이므로 모순관계로 기판력이 미침 — 금전채무이행의 소에서 원고가 승소확정된 뒤 피고가 채무부존재확인의 소를 제기하는 경우도 모순관계로 전소 기판력에 저촉</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 등기청구의 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">갑이 을을 상대로 매매계약 무효를 주장하며 말소등기청구를 해 승소확정판결을 받아 등기를 말소한 뒤, 을이 매매계약이 유효하다고 주장하며 소유권이전등기청구의 소를 제기한 경우, 후소의 청구취지는 전소 주문판단인 말소등기청구권 자체를 부인하고, 청구원인도 전소 이유에서 인정된 매매사실을 부인하는 것이므로 모순관계로 기판력이 미침 — (제소전 화해 사안) 신탁해지를 원인으로 한 소유권이전등기절차를 이행하기로 한 제소전 화해가 있고, 그에 기해 마쳐진 이전등기가 원인무효라 주장하며 말소청구하는 것은 제소전 화해로 확정된 소유권이전등기청구권을 부인하는 것이어서 모순관계로 기판력 저촉<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 모순관계 부정 판례(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">전소의 소유권이전등기말소청구 승소확정판결 집행 후, 전소와는 별개의 청구원인(전소의 말소사유는 등기위조사실, 후소의 사유는 매매사실인 경우 등)으로 제기한 소유권이전등기청구는 전소 판결주문 판단과는 모순되나 판결이유 중 인정된 사실과는 모순되지 않으므로 전소의 기판력에 저촉되지 않음<span class=\"cs-x\"><strong>(X)</strong></span> — (양도담보 판례) 갑이 적법한 양도담보권자라는 전제로 농지인도청구를 인용한 판결이 확정된 후, 을이 갑을 상대로 적법한 양도담보권자가 아님을 들어 말소청구를 한 경우, 전소 주문판단(농지인도청구권)을 부인하는 것이 아니므로 모순관계 아님<span class=\"cs-x\"><strong>(X)</strong></span> / 소유권이전등기절차를 이행하기로 한 매매계약을 원인으로 한 대금반환청구의 소에서 을이 갑의 청구를 인낙하는 인낙조서가 작성된 경우, 이 인낙조서의 기판력은 이후 위 매매계약을 원인으로 한 소유권이전등기절차이행청구의 소에 미치지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 판결이유 중의 판단</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>기판력 불발생</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§216①</strong></span></span> 반대해석상 판결이유 중 판단에 대해서는 기판력이 발생하지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>선결적 법률관계(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>기판력 발생 및 작용 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\"><strong>[소유권에 기한 이전등기 말소청구에서 원고에게 소유권이 없다는 이유로 패소확정된 뒤 원고가 다시 소유권확인의 소를 제기한 경우]</strong></span> 전소의 선결적 법률관계(소유권 존부)가 후소의 소송물인 경우, 소유권에 기한 말소등기청구에서 소유권의 존부는 판결이유 중에서 판단되므로 기판력이 발생하지 않음 → 후소에 기판력이 미치지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>판결이유 중 판단에 대한 구속력 인정 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: i) 피고 명의 소유권이전등기가 원인무효라는 이유로 등기말소청구를 했다가 청구기각판결로 확정되었더라도 ii) 확정판결의 기판력은 판결주문 판단인 말소등기청구권의 존부에만 미치고, 판결이유 중 판단인 기본이 된 소유권 자체의 존부에는 미치지 아니함<span class=\"cs-x\"><strong>(X)</strong></span> → 판결이유 중 판단에 구속력 부인</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>신의칙설</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">판결의 모순·저촉 방지를 위해 신의칙의 파생원칙인 모순거동금지의 원칙에 의해 판결이유의 판단에 구속력이 인정된다는 견해</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>판결서의 증명효(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (쟁점효 부인) 判例는 이미 확정된 관련 민사사건에서 인정된 사실은 후소에서 유력한 증거가 되므로 합리적 이유설시 없이 배척할 수 없다고 하여 증명력설 → 그 범위에서 판결의 모순·저촉 방지 ② 형사판결도 민사재판에서 그 사실인정에 구속되는 것은 아니나, 동일한 사실관계에 관해 이미 확정된 형사판결이 유죄로 인정한 사실은 유력한 증거자료가 되어 이와 반대되는 사실을 인정할 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>항변</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>원칙</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 판결이유 중 판단되는 피고의 항변(유치권·동시이행항변, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§213</strong></span></span>단서 법정지상권 항변 등)에 대해서는 원칙적으로 기판력 불발생 ② 判例: i) 상환이행판결에서 동시이행항변으로 제출한 반대채권의 존부·수액에는 기판력이 생기지 않음 ii) 다만 동시이행항변의 조건이 붙어 있다는 데 기판력이 생기므로, 뒤에 무조건의 이행의무가 있다는 주장은 기판력에 저촉</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>예외 - 상계의 항변</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 의의 및 취지</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">상계항변은 판결 주문 아닌 이유 중에 판단되지만, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§216②</strong></span></span>는 예외적으로 상계항변에 대한 판단에 기판력을 인정 — 반대채권 존부에 대한 이중분쟁 방지가 취지</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 상계항변의 기판력 발생요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 수동채권의 발생요건: ① 수동채권이 i) 소송물로서 심판되는 소구채권이거나 그와 실질적으로 동일한 경우에 기판력 인정(수동채권이 소구채권이고 자동채권이 상계항변인 경우만 기판력 발생) ii) 判例: 수동채권이 동시이행항변, 자동채권이 상계의 재항변으로 주장된 경우까지 기판력을 인정하면 동시이행항변에 행사된 수동채권에까지 기판력을 인정하는 결과가 되어 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§216①</strong></span></span>에 반하므로 기판력 부정<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 자동채권의 발생요건: 상계항변은 자동채권의 존부를 실질적으로 본안판단한 경우에만 기판력 발생 → i) 시기에 늦게 제출되어 각하된 경우(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§149</strong></span></span>) ii) 성질상 상계가 허용되지 않거나(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§492①</strong></span></span>단서 동시이행항변권 부착 자동채권) iii) 상계부적상(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§492①</strong></span></span>본문 자동채권 이행기 미도래)으로 배척된 경우는 기판력 불발생<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 상계항변의 기판력 발생범위</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① (발생) 자동채권 존부에 대해 상계로 대항한 액수 한도에서 기판력 발생 ② (배척) 상계항변을 배척하는 경우 자동채권의 부존재에 기판력 ③ (채택) 상계항변을 채택해 원고청구 기각시 '수동채권과 자동채권이 다함께 존재하다가 상계로 소멸'된 점에 기판력 ④ (상계항변의 철회) 선행소송에서 상계항변 철회로 자동채권 존부를 실질적으로 본안판단하지 않은 경우, 자동채권 이중행사가 아니고 원고 청구권 존부 판결이 무의미해질 우려도 없으므로 기판력 발생하지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\"><strong>[상계항변 배척시 기판력 발생범위 - 최근판례]</strong></span> 判例: 법원이 수동채권 전부·일부의 존재를 인정한 다음 상계항변을 배척한 경우, 반대채권 부존재라는 판결이유 중 판단의 기판력은 '법원이 반대채권 존재를 인정했더라면 상계로 수동채권의 상계적상일까지 원리금과 대등액에서 소멸한다고 판단할 수 있었던 반대채권 원리금 액수' 범위에서 발생(반대채권 액수가 소구채권보다 커도 동일) — 2개 이상 반대채권 중 하나를 인정해 상계하고 나머지를 부존재로 배척한 경우, 부존재 판단의 기판력 전체 범위는 상계 후 수동채권 잔액을 초과할 수 없음</div><div class=\"cs-h\">Ⅲ. 시효중단을 위한 재소에 대한 중요 판례</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>시효중단을 위한 신소제기 가부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 시효중단을 위해 예외적으로 확정된 승소판결과 동일한 소송물에 기한 신소 허용 → 다만 신소 판결이 전소 승소확정판결 내용에 저촉되어서는 안 되므로 후소법원은 확정된 권리를 주장할 요건이 구비되었는지 다시 심리할 수 없음 ② 피고가 후소에서 전소의 확정된 권리관계를 다투려면 먼저 전소 승소확정판결에 대해 적법한 추완항소를 제기해 그 기판력을 소멸시켜야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>시효중단을 위한 후소로서 '새로운 방식의 확인소송'이 허용되는지 여부(적극)(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 시효중단을 위한 후소로 이행소송 외에 '재판상 청구가 있다는 점'에 대해서만 확인을 구하는 '새로운 방식의 확인소송'도 허용 ② 채권자는 두 형태 중 자신의 상황·필요에 적합한 것을 선택해 제기 가능 ③ 위 확인의 소는 판결확정 채권의 소멸시효기간 10년 경과가 임박할 것을 요하지 않아 임박하지 않은 상태에서도 제기 가능(이행의 소는 10년 임박 아니면 부적법) ④ 확인소송에서는 청구권 존부·범위 등 실체적 법률관계 심리 불요 → 채무자는 전소 표준시 후 청구이의 사유가 있어도 주장할 필요 없고 법원도 심리 불요(이행의 소는 전소 변론종결 뒤 사유 주장 가능)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>시효중단을 위한 후소 절차에서 피고가 전소 변론종결 후 발생한 채권소멸사유를 들어 항변할 수 있는지 여부(적극)(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 시효중단을 위한 후소 판결은 전소 승소확정판결 내용에 저촉되어서는 안 되어 확정된 권리의 모든 요건 구비 여부를 다시 심리할 수 없으나, 후소판결의 기판력은 후소 변론종결시 기준으로 발생하므로 전소 변론종결 후 발생한 변제·상계·면제·소멸시효 완성 등 채권소멸사유는 후소의 심리대상 → 채무자인 피고는 후소에서 이를 항변할 수 있고 인정되면 청구기각 ② 따라서 후소가 전소판결 확정 후 10년 지나 제기되었어도 곧바로 소각하할 것이 아니라 피고 항변에 따라 소멸시효 완성 여부 본안판단해야 함 ③ 다만 전소판결 확정 후 소멸시효가 중단된 적이 있어 중단사유 종료시부터 새로 진행된 소멸시효기간 경과가 임박하지 않아 재소이익을 인정할 수 없다면 소각하</div>", ["★★★★★"], 1, "mp_4"], ["민소040", "기판력의 시적 범위", "<div class=\"cs-h\">Ⅰ. 의의 - 표준시</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① 기판력의 표준시는 '사실심의 변론종결시'(무변론판결은 판결선고시)(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민사집행법§44②</strong></span></span>) — 표준시에서의 현재 권리관계 존부판단에 대해 생기며, 표준시 이전 또는 이후의 권리관계에는 미치지 않음 ② 判例: 확정판결의 기판력은 사실심 변론종결 당시의 권리관계를 확정하는 것이므로, 원고 청구 중 변론종결시 후의 지연손해배상청구부분은 선결문제로서 확정판결에 저촉되는 원금 지급의무의 존재를 주장하는 것이어서 확정판결의 기판력 효과를 받으나, 변론종결 당시까지의 과거의 청구는 기판력 효과를 받지 않음</div><div class=\"cs-h\">Ⅱ. 변론종결 전에 존재한 사유</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>차단효</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">기판력은 표준시의 권리관계 존부판단에 대해 생기므로, 전소 변론종결시(표준시) 이전에 제출(주장)할 수 있었으나 변론종결시까지 제출(주장)하지 않은 공격방어방법은 후소에서 제출(주장)하지 못함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>실권의 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 전소에서 당사자가 그 공격방어방법을 알지 못하여 주장하지 못하였는지, 나아가 알지 못한 데 과실이 있는지는 묻지 않고 차단됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>표준시(변론종결시) 뒤에 발생한 새로운 사유</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>전소 변론종결 뒤에 새로이 발생한 사유는 실권되지 않음</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">변론종결 뒤 발생한 새로운 사유에 의해 ① 당사자는 후소를 제기해 전소 확정판결의 기판력을 다툴 수 있고(원고는 동일한 소를, 피고는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민사집행법§44</strong></span></span>의 청구이의의 소를 제기) ② 후소법원도 전소 확정판결과 달리 판단할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>새로운 사유의 의미(★) - 법률관계 사실 자체</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">변론종결 뒤 발생한 새로운 사유란 '법률관계사실 자체'(요건사실의 변동)를 말하는 것이지 '기존 법률관계에 대한 새로운 증거자료'를 의미하지 않음 → 법률·판례의 변경, 법원의 법적견해 변경, 사실관계에 대한 법률평가의 변경은 포함되지 않음<span class=\"cs-x\"><strong>(X)</strong></span> — <span class=\"cs-gbg\"><strong>[법적 평가가 담긴 다른 판결이 존재하는지]</strong></span> 判例: ① 확정판결의 기판력은 전소 변론종결 전에 주장했거나 주장할 수 있었던 모든 공격방어방법에 미치고, 변론종결 후 새로 발생한 사유로 전소판결과 모순되는 사정변경이 있는 경우에만 기판력 차단 ② 변론종결 후 발생한 새로운 '사실관계'를 말할 뿐, 새로운 증거자료가 있다거나 새로운 법적 평가 또는 법적 평가가 담긴 다른 판결이 존재한다는 사정은 포함되지 않음 ③ 기판력 있는 전소판결 변론종결 후 이와 저촉되는 후소판결이 확정되었다는 사정은 변론종결 후 발생한 새로운 사유에 해당하지 않아, 그 사유로 전소확정판결의 기판력이 미치지 않게 되었다고 할 수 없음 — <span class=\"cs-gbg\"><strong>[건물인도 확정판결(점유권원 없음 인정) 후 매매계약 무효확인판결이 확정되자 다시 인도소송을 제기한 경우]</strong></span> 제1차·제2차 인도소송의 소송물은 모두 소유권에 기한 건물인도청구권으로 동일하고, 점유할 정당한 권원 유무는 제1차 인도소송 변론종결 전 사유이며 그에 대한 법적 평가가 담긴 무효확인판결이 제1차 인도소송 변론종결 후 있었더라도 변론종결 후 새로운 사유로 볼 수 없으므로, 제2차 인도소송은 제1차 인도소송 확정판결의 기판력에 저촉되어 허용 불가<span class=\"cs-x\"><strong>(X)</strong></span> → 청구기각</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>현저한 사정변경</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 기대여명보다 일찍 사망하여 손해가 줄어든 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ① (부당이득반환청구) 확정판결이 실체적 권리관계와 달라도 재심으로 취소되지 않는 한 기판력에 저촉되는 주장 불가, 판결 집행으로 교부받은 급부를 법률상 원인 없는 이득이라 할 수 없음 ② (기판력) 불법행위 손해배상청구 판결확정 후 피해자가 손해배상액 산정 기초로 인정된 기대여명보다 일찍 사망해도, 판결이 재심 등으로 취소되지 않는 한 지급받은 손해배상금을 법률상 원인 없는 이득이라 하여 반환을 구하는 것은 기판력에 저촉되어 허용 불가<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 임료의 현저한 상승의 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ① (별소제기) 전소 사실심 변론종결 후 전소판결 기초 사정이 현저히 변경되어 인용된 임료액이 현저히 상당하지 않게 된 경우, 일부청구임을 명시하지 않았어도 명시적 일부청구가 있었던 것으로 보아 전소 기판력이 후소 차액청구에 미치지 않아 차액청구 별소제기 허용(<span class=\"cs-u\"><strong>명시적 일부청구간주설</strong></span>) ② (변경의 소) 불법점유자에 대한 임료상당 부당이득반환 정기금판결 확정 후, 전소 변론종결 당시 예상할 수 없던 임료폭등이 발생해 정기금 액수산정 기초 사정이 현저히 바뀌어 형평을 침해할 특별한 사정이 생긴 경우 정기금 변경의 소 제기 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 후유증 등이 발생하여 손해가 늘어난 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 불법행위 적극적 손해배상을 명한 전소 변론종결 후 새로운 적극적 손해가 발생한 경우 i) 변론종결 당시 손해 발생을 예견할 수 없었고 ii) 그 부분 청구를 포기했다고 볼 수 없는 특별한 사정이 있다면 전소송의 소송물과 별개의 소송물이므로 전소송 기판력에 저촉되지 않음(<span class=\"cs-u\"><strong>별개소송설</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>정기금판결에 대한 변경의 소(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의 및 소송물</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 정기금 지급을 명한 판결 확정 뒤 그 액수산정 기초 사정이 현저히 바뀐 경우 장차 지급할 정기금 액수를 바꿔달라는 소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§252</strong></span></span>) ② (소송물) 형평의 관념에서 전소판결의 기판력을 배제하는 것이므로 전소 소송물과 동일(<span class=\"cs-u\"><strong>소송물동일설</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>적법요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① '정기금'의 '지급'을 명하는 판결이 있을 것 ② 정기금 지급 판결이 '확정'될 것 ③ 정기금 지급판결 효력이 미치는 당사자일 것 ④ 전소 제1심판결 법원 전속관할에 제소할 것 ⑤ 정기금판결 변론종결 이후 액수산정 기초 사정이 현저히 바뀌어 당사자 사이의 형평을 침해할 특별한 사정이 생겼을 것 ⑥ 기타 일반 소송요건을 갖출 것 — <span class=\"cs-fact-tag\"><strong>[정기금판결 변론종결 뒤 승계인]</strong></span> 判例: ① 토지소유자가 무단점유자 상대로 인도시까지 차임상당 부당이득반환을 명하는 판결이 확정된 경우 소송물은 채권적 청구권인 부당이득반환청구권이므로, 변론종결 후 토지소유권을 취득한 사람은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span> 변론종결 뒤의 승계인에 해당하지 않음 → 정기금판결의 기판력이 미치지 않아 그 승계인의 정기금 변경의 소는 부적법<span class=\"cs-x\"><strong>(X)</strong></span> ② 그 승계인이 부당이득반환 별소를 제기하는 경우, 변론종결 뒤 승계인에 해당하지 않아 주관적 범위에서 작용하지 않고, 별소제기는 명시적 일부청구로 간주되어 전소 청구와 소송물이 달라 객관적 범위에서도 작용하지 않으므로 전소 기판력이 후소에 미치지 않아 별소제기는 적법<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>변론종결한 뒤의 형성권 행사</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>취소권·해제권 등 형성권 일반의 경우 - 실권 긍정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">표준시 이전에 존재하였던 '무효사유'도 기판력에 의해 차단되는데, 이보다 약한 취소권·해제권 등이 차단되지 않으면 균형에 맞지 않고 '법적안정성'에도 반하므로 실권됨<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>상계권의 경우(★) - 실권 부정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 채무자가 확정판결 변론종결 전에 상계적상에 있는 채권을 가지고 있었더라도 변론종결 뒤 상계 의사표시를 한 때에는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민사집행법§44②</strong></span></span>의 '이의 원인이 변론종결한 뒤에 생긴 때'에 해당하여, 전소 변론종결 전 자동채권 존재를 알았는지 여부와 관계없이 적법한 청구이의 사유가 됨(<span class=\"cs-u\"><strong>상계권비실권설</strong></span>) ② 최근판례: i) 집행권원 확정판결의 사실심 변론종결 이전에 별소에서 그 채권에 관해 소송상 상계 의사표시가 이루어지고 ii) 해당 확정판결 사실심 변론종결 이후 별소에서 소송상 상계 주장을 받아들이는 법원의 실질적 판단이 이루어진 경우 iii) (집행권원 확정판결 기판력에 저촉된다는 등 특별한 사정 없는 한) 이러한 사유는 확정판결 사실심 변론종결 이후 생긴 것(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민사집행법§44②</strong></span></span>)으로서 그 집행력을 배제하는 적법한 청구이의 이유가 됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>건물매수청구권의 경우(★) - 실권 부정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 토지임대인이 임차인 상대 토지인도·건물철거 청구소송에서 임차인이 패소확정되어도, 임차인은 건물매수청구권을 행사하여 별소로 임대인에게 건물 매매대금 지급을 구할 수 있고, 전소(토지인도·건물철거)와 후소(매매대금청구)는 소송물을 달리하므로 종전 확정판결의 기판력에 의해 건물매수청구권 행사가 차단되지 않음(<span class=\"cs-u\"><strong>건물매수청구권비실권설</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>한정승인의 경우(★) - 실권 부정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 채무자가 한정승인 사실을 주장하지 않으면 책임의 범위는 현실적 심판대상으로 등장하지 않아 주문·이유에서 판단되지 않으므로 고유재산에 관하여는 기판력이 미치지 않음(<span class=\"cs-u\"><strong>기판력 부정설</strong></span>) ② 따라서 채무자가 한정승인을 하고도 사실심 변론종결시까지 주장하지 않아 책임범위 유보 없는 판결이 확정되어도, 채무자는 그 후 한정승인 사실을 내세워 청구이의의 소를 제기하는 것이 허용됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(5) <strong>상속포기 - 실권 긍정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 한정승인에 대한 기판력 실권효 제한 법리는, 상속에 의한 채무의 존재 자체가 문제되어 확정판결 주문에 당연히 기판력이 미치게 되는 상속포기의 경우에는 적용될 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(6) <strong>백지보충권 - 실권 긍정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 어음요건 흠결을 이유로 청구기각판결이 확정된 후 백지 부분을 보충해 완성한 어음에 기해 다시 전소 피고에게 어음금 청구소송을 제기한 경우, 전·후 양 청구가 어음금청구로 청구동일이라 기판력의 객관적 범위에서 작용하므로, 백지보충권 행사는 전소 변론종결 전 주장할 수 있었던 공격방법이므로 시적범위에서 차단됨<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(7) <strong>상속재산 협의분할(★) - 실권 부정(변론종결 후의 사유)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">상속재산분할협의가 전소 변론종결 후에 이루어졌다면 비록 상속재산분할의 효력이 상속개시시로 소급하더라도, 상속재산분할협의에 의한 소유권 취득은 '전소 변론종결 후에 발생한 사유'에 해당하므로 기판력이 미치지 않음<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["★★★★★"], 1, "mp_4"], ["민소041", "무효인 판결과 판결의 편취", "<div class=\"cs-h\">Ⅰ. 당연무효인 판결(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판결의 당연무효란 판결로서의 외관을 갖추었지만 내용상 중대한 하자가 있어 판결의 내용상 효력인 기판력·집행력·형성력 등이 생기지 않는 경우 → ① 재판권 흠결 ② 제소 전 사망자를 상대로 한 소송 ③ 당사자적격 없는 자가 제기한 소송 ④ 소 취하 후 소송계속이 종료하였음을 간과한 판결 등</div><div class=\"cs-h\">Ⅱ. 당연무효인 판결의 취급</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① (확정 전 상소) 判例: 제소 전 사망자를 상대로 한 무효인 판결에 대한 상소는 '상소의 대상적격'이 없어 부적법하여 '상소 각하' — 단, '소송계속 종료를 간과한 판결'에 상소를 제기한 경우에는 상소심이 원판결을 취소(파기)하고 '소송종료선언'을 해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">② (확정 후 재심) 무효인 판결은 확정되어도 재심의 대상이 되지 않아 재심의 소는 대상적격 없어 각하 → 이에 기한 강제집행도 무효</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">③ (별소제기) 무효인 판결은 기판력이 발생하지 않았으므로 형식적으로 확정된 뒤에도 동일소송물에 대하여 신소 제기 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅲ. 판결의 편취(★) - 사위판결</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>편취판결의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ⅰ) 법적 안정성과 ⅱ) 판결편취가 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>11호 재심사유로 규정되어 있음을 근거로 유효한 판결로 봄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송법상의 구제책 - 동일절차에서 구제방법</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>공시송달에 의한 편취판결(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (공시송달의 효력) 判例: 공시송달에 의한 판결편취의 경우 '판결정본의 공시송달'은 '유효한 송달' ② (구제수단) 공시송달로 판결을 편취당해 판결이 확정되고 강제집행까지 종료된 경우, 추후보완상소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§173</strong></span></span>) 또는 재심의 소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>11호)에 의함[선택 '15, '16, '17, '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>허위주소송달에 의한 판결의 편취(★) - 자백간주에 의한 판결의 편취</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① (항소제기) ⅰ) 판결의 효력은 피모용자에게 미치고 ⅱ) 판결은 유효하며 ⅲ) 판결정본이 허위주소로 송달된 것은 무효이므로 항소기간이 진행하지 않아 ⅳ) 피모용자는 언제든지 항소제기하여 위 판결의 취소를 구할 수 있음 ② (별소제기) 허위주소송달에 의한 편취판결은 형식적으로 확정된 확정판결이 아니어서 기판력이 없으므로 원고는 별소를 제기할 수 있음(전소 계속 중이라도 전후소 청구가 달라 중복 아님)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>참칭대표자에 의한 판결의 편취(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (참칭대표자에게의 송달의 효력) 判例: 참칭대표자에 대한 송달은 유효 ② (구제방법) ⅰ) 판결확정 전에는 상소 ⅱ) 확정 후에는 추후보완항소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§173</strong></span></span>, 참칭대표자 송달은 불귀책 사유에 해당)나 재심의 소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>3호)로 구제</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>실체법상의 구제책(★) - 별소제기 가부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 부당이득·말소등기의 경우 편취된 판결이 재심의 소 등으로 취소되지 않는 한 별소제기 불가(<span class=\"cs-u\"><strong>재심필요설</strong></span>) ② 다만 불법행위에 의한 손해배상청구의 경우 원칙적으로 재심으로 판결이 취소되어야 별소 제기 가능하나, 예외적으로 절차적 기본권이 침해된 경우 또는 내용이 현저히 부당하여 재심사유가 있는 경우에 한정하여 바로 불법행위 손해배상 청구 가능(<span class=\"cs-u\"><strong>제한적 불요설</strong></span>) ③ 자백간주에 의한 판결의 편취는 허위주소송달에 의한 것으로 송달이 무효이므로 재심으로 취소할 필요 없이 별소제기 가능<span class=\"cs-o\"><strong>(O)</strong></span> ④ 재심의 소와 통상의 민사소송은 동종절차가 아니어서 병합 불허(재심 병합제기 부정)[사례 '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>부당집행에 대한 구제책(★) - 청구이의의 소제기 가부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① (금전) 청구이의의 소는 부당한 강제집행을 배제하려는 데 목적이 있으므로, 편취판결에 의한 강제집행신청은 그 자체가 불법하다는 점에서 변론종결 뒤 새로이 발생한 권리남용의 경우로 보아 청구이의의 소 인정<span class=\"cs-o\"><strong>(O)</strong></span> ② (등기) 그러나 소유권이전등기소송과 같이 의사의 진술을 명하는 판결은 확정과 동시에 의사를 진술한 것과 동일한 효력이 발생하여 현실적 집행절차가 필요하지 않으므로, 확정판결 이후 집행절차가 계속됨을 전제로 집행력 배제를 구하는 청구이의의 소는 소의 이익이 없어 허용되지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div>", ["★★★"], 1, "mp_4"], ["민소042", "상소", "<div class=\"cs-h\">Ⅰ. 상소의 적법요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">상소요건: ① 상소의 대상적격(선고된 종국판결로 유효) ② 적식의 상소제기(상소장을 판결정본 송달일부터 2주 내 원심법원에 제출) ③ 상소의 이익(패소자)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>상소의 대상적격 - 선고된 종국판결로 유효할 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① (선고된 종국판결일 것) 선고 전의 판결은 상소 대상 불가, 종국판결만 상소 대상이므로 중간판결 기타 중간적 재판은 독립하여 상소 불가<span class=\"cs-x\"><strong>(X)</strong></span> ② (유효한 판결일 것) 무효인 판결에 대해 判例는 항소의 대상적격이 없다고 보아 항소를 부적법 각하</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>적식의 상소제기 - 상소제기 방식과 상소기간 준수</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① '상소장이란 서면'에 의할 것 ② 상소장을 '원심법원'에 제출 ③ 상소기간 내 제기 — 항소·상고는 판결정본 송달된 날부터 2주일 내(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§396</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§425</strong></span></span>), 경과시 상소 불가</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>상소의 이익이 있을 것(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의와 판단기준</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 상소의 이익이란 '하급심 종국판결에 대해 불복신청하여 그 취소·변경을 구할 수 있는 당사자의 법적 지위' ② (판단기준) 判例는 예외를 인정하는 형식적 불복설 → ⅰ) 원칙적으로 '당사자의 신청과 판결주문'을 비교하여 불이익 여부 판단, 전부승소자는 이익 없음 ⅱ) 예외적으로 기판력 등 때문에 별소 제기가 허용될 수 없는 경우와 부대항소의 경우 항소이익 인정</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>전부승소한 당사자의 상소이익</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">(원칙) 전부승소한 당사자는 원칙적으로 상소의 이익 없음 → ⅰ) 원고가 전부승소시 청구변경을 위해 상소 불가 ⅱ) 피고가 전부승소시 반소를 위해 상소 불가(→ 상소각하)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 묵시적 일부청구(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">'일부청구'에 대한 判例(<span class=\"cs-u\"><strong>명시설</strong></span>): ⅰ) 명시적 일부청구는 잔부청구 후소가 허용되므로 항소이익 없으나 ⅱ) 묵시적 일부청구는 잔부청구 후소가 전소판결 기판력에 차단되므로, 전부승소한 경우라도 추가청구(청구취지 확장)를 위한 상소 인정 ⅲ) 判例: 손해배상청구에서 재산상 손해는 전부승소, 위자료는 일부패소하여 원고가 위자료 패소부분에 항소한 경우, 전부승소한 재산상 손해에 대한 청구의 확장도 허용[선택 '17, '25 / 변리사 사례 '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 상계항변(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 피고가 제1심에서 전부승소하여 원칙적으로 항소이익 없으나, 예비적 상계항변이 이유 있어 승소한 피고는 자동채권 존부에 대해 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§216②</strong></span></span>로 기판력이 발생하여 반대채권 별소제기가 차단되므로, 원고 수동채권 부존재를 이유로 승소하는 것이 결과적으로 이익이 되어 상소이익 있음 → '원고의 소구채권 자체를 부정하여 청구를 기각한 판결'과 '소구채권 존재를 인정하면서 상계항변을 받아들여 청구를 기각한 판결'은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§216</strong></span></span>에 따라 기판력 범위를 서로 달리하고, 후자에 대해 피고는 상소이익 있음[선택 '20, '22, '25 / 변리사 사례]</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 부대항소의 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">부대항소의 성질에 대한 判例(<span class=\"cs-u\"><strong>비항소설</strong></span>): 부대항소는 항소가 아니어서 항소이익 불요 → 제1심에서 전부승소한 피항소인도 청구의 확장·변경 또는 반소제기를 위해 부대항소 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 판결이유 중 판단에 대한 불복(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① (원칙) 승소한 당사자는 판결이유 중 판단에 불만이 있어도 상소이익 없음(기판력은 주문 판단에만 생기므로 어떤 이유로 승소해도 승소의 법률효과에 차이 없음) — 判例: 甲이 丙을 피고로 乙을 대위하여 소유권이전등기 말소청구를 하며 피보전권리를 매매계약으로 주장했으나 법원이 양도담보약정으로 인정해 甲승소판결을 한 경우, 기판력이 미치는 것은 피대위권리의 존부이고 판결이유에서 피보전권리를 잘못 인정했더라도 그 사유만으로는 상소이익 없음 ② (예외) 매매를 원인으로 한 소유권이전등기청구에 대해 법원이 양도담보약정을 원인으로 한 청구를 인용한 경우, 구소송물이론상 실체법상 개개 청구권마다 별개 소송물이므로 위 판결은 처분권주의에 반하여 위법하여 상소이익 긍정</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>소각하 판결</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 소각하판결은 원고에게 불이익일 뿐더러 피고가 청구기각 신청을 구한 때에는 본안판결을 받지 못한 점에 피고에게도 불이익이 있어 원·피고 모두 상소 가능 ② 判例: 피고가 원고의 소가 각하되어야 한다고 주장하였고 법원이 소의 이익 없어 부적법하다며 소를 각하하였는데 피고가 소각하판결에 상소한 사안에서, 피고는 재판 주문 기준 전부승소하였으므로 판결이유에 불만이 있어도 상고이익 없어 상고각하</div><div class=\"cs-h\">Ⅱ. 상소의 효력</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>상소의 효력 - 이심의 범위와 심판의 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① (이심의 범위) 상소 제기시 원심판결 확정이 차단되고 사건이 상급심으로 이심되는 '이심의 효력' 발생, 이심 범위는 '상소불가분의 원칙'에 의해 재판 전부에 대해 생김 ② (심판의 범위) 상소심 심판범위는 '불이익변경금지의 원칙'이 작용하여 상소인이 상소심 심판대상으로 특정한 청구만 심판대상</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>상소불가분의 원칙(★) - 이심의 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>상소불가분원칙의 의의 및 취지</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">상소 제기에 의해 확정차단 및 이심의 효력은 원심판결 전부에 대하여 불가분으로 발생 → 재판의 일부에 상소가 된 경우라도 재판 전부에 확정차단·이심 효력 발생</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>항소취지의 확장과 부대항소</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">상소불가분으로 상소 효력이 원심판결 전부에 미치므로 ① 항소인은 항소심 변론종결시까지 어느 때나 심판범위 확장 가능 ② 피항소인도 부대항소 신청(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§403</strong></span></span>) 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\"><strong>[사례: 항소취지 확장과 청구취지 확장(★)]</strong></span> 甲이 乙에 2억 원 매매대금+공작물인도 병합청구, 1심에서 매매대금 패소·공작물인도 승소, 패소한 매매대금 중 2,000만 원만 항소 후 항소심에서 6,000만 원으로 항소취지 확장·3억 원으로 청구취지 확장 가부 및 피고 乙의 공작물인도 부대항소 가부<span class=\"cs-fact-tag\"><strong>[사례]</strong></span> → ① (이심범위) 상소불가분으로 항소한 2천만 원+미항소 1억8천만 원+공작물인도 전부 이심 ② (심판범위) 불이익변경금지로 항소한 2천만 원에 국한 ③ (6,000만 원 항소취지 확장) 패소 1억8천만 원도 이심되어 있고 항소이익도 구비하므로 2억 원 동일 소송물 범위 내에서 변론종결 전까지 확장 가능<span class=\"cs-o\"><strong>(O)</strong></span> ④ (3억 원 청구취지 확장) 2억 원 외 1억 원 추가는 청구취지 확장, 2억 원 전부 이심되어 확장 가능, 항소이익 필요하며 다른 청구 확장이면 청구변경 요건 구비 필요[선택 '12] ⑤ (乙의 부대항소) 상소불가분으로 공작물인도까지 이심되므로 피고는 패소한 공작물인도에 부대항소 가능<span class=\"cs-o\"><strong>(O)</strong></span>[선택 '13]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>불이익변경금지의 원칙(★) - 심판의 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">상소심 심판범위는 상소인의 불복신청 범위에 한하며, 그 한도를 넘어 원심판결을 불이익 또는 이익으로 변경할 수 없는 원칙 (예: 甲이 乙에 1,000만 원 대여금청구, 1심에서 600만 원 승소·400만 원 패소, 甲이 패소 400만 원만 항소한 경우 상소불가분으로 승소 600만 원까지 이심되나 심판대상은 불이익변경금지로 400만 원만이며 항소심은 미항소 600만 원을 심판할 수 없음)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>원칙</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 상계의 항변(★)[선택 '20, '21, '22]</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 문제점: 甲이 乙 상대 매매대금청구, 乙이 대여금채권으로 상계항변, 법원이 수동·자동채권 존재를 인정하며 상계항변 인용해 청구기각한 후 피고나 원고가 항소한 경우 이심·심판범위가 문제</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 피고의 항소(★): 피고가 '수동채권의 부존재'를 이유로 항소한 때 ① 상소불가분으로 수동·자동채권 전부 이심되나 불이익변경금지로 수동채권만 심판대상 ② (자동채권은 존재하나 수동채권 부존재로 판단시) 수동채권 존재로 본 제1심은 정당하지 않으므로 ⅰ) 항소심은 피고 항소를 인용해 제1심 취소하고 청구기각 자판 ⅱ) 그러나 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§414②</strong></span></span>에 의해 항소기각 불가(상계항변에 관한 기판력의 객관적 범위가 달라지기 때문) ③ (수동채권은 존재하나 자동채권 부존재로 판단시) 항소심은 수동채권 존부만 심판할 수 있고 자동채권은 심판 불가하므로, 수동채권 존재로 본 제1심이 정당하다는 이유로 항소기각(자동채권 부존재를 이유로 판결하면 불이익변경금지 위반)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">다) 원고의 항소(★): 원고가 '자동채권의 부존재'를 이유로 항소한 경우 ① 상소불가분으로 자동·수동채권 전부 이심되나 불이익변경금지로 자동채권만 심판대상 ② (자동채권 존재·수동채권 부존재로 판단시) 항소심은 자동채권 존부만 심판할 수 있고 수동채권은 심판 불가하므로, 자동채권 존재로 본 제1심이 정당하다는 이유로 항소기각 ③ (수동채권 존재·자동채권 부존재로 판단시) 자동채권이 인정되지 않아 제1심이 부당하므로 항소를 인용해 제1심 취소하고 자동채권 부존재를 이유로 청구인용 자판</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 소각하의 소송판결(★)[선택 '13, '20, '25]</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 항소심이 제1심 소각하판결을 취소해야 한다고 판단한 경우 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§418</strong></span></span> 본문에 해당하면 필수적 환송(심급의 이익 보호) ② 다만 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§418</strong></span></span> 단서(제1심에서 본안판결할 수 있을 정도로 심리된 경우 또는 당사자 동의)에는 항소법원이 스스로 본안판결 가능 ③ <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§418</strong></span></span> 단서로 항소심이 본안판단해야 하는데 청구가 이유 없어 기각해야 하는 경우 判例: ⅰ) (항소심) 소각하판결보다 청구기각판결이 원고에게 불리하므로 불이익변경금지상 청구기각 불허, 항소기각판결을 해야 함(<span class=\"cs-u\"><strong>항소기각설</strong></span>) ⅱ) (상고심) 소를 부적법 각하한 항소심판결을 파기해도 청구기각될 운명이면 불이익변경금지를 적용하여 상고기각(<span class=\"cs-u\"><strong>상고기각설</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 동시이행항변(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 判例: 동시이행판결에서 반대급부는 '강제집행의 개시요건'으로 반대급부를 지급하지 않고는 집행할 수 없어, 반대급부 내용이 원고에게 불리하게 변경된 경우 강제집행개시 요건이 불이익하게 변경된 것으로 불이익변경금지 위반 ② 判例: 금전채권에 기한 동시이행 주장을 받아들인 판결에서 동시이행 주장을 한 당사자만 항소했는데 항소심이 제1심의 금전채권에 기한 동시이행 주장을 공제 또는 상계 주장으로 바꾸어 인정하면서 금전채권 내용을 항소인에게 불리하게 변경하는 것은 불이익변경금지 위반</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>예외</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 처분권주의에 의하지 않는 절차</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 불이익변경금지는 처분권주의에 근거하므로 직권탐지주의 절차에는 적용되지 않음 ② 判例: 직권조사사항에는 불이익변경금지가 적용되지 않으므로 항소심에서 '제1심판결을 취소하고 소각하'라는 불이익변경 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 형식적 형성의 소</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">경계확정의 소·공유물분할청구의 소 등 형식적 형성의 소는 성질상 비송사건이라 처분권주의가 적용되지 않으므로 불이익변경금지도 적용 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 항소심에서 상계의 주장(★)[변리사 사례 '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 항소심에서 상계에 관한 주장이 이유 있다고 인정된 때에도 불이익변경금지가 적용되지 않음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§415</strong></span></span>단서) ② 甲이 乙 상대 1억 원 대여금청구, 1심이 4,000만 원만 인용, 원고만 항소하자 항소심에서 乙이 1억 원 물품대금채권으로 상계 주장하여 상계항변이 전부 이유 있는 경우 ⅰ) 상소불가분으로 1억 원 전부 이심 ⅱ) 불이익변경금지로 원고가 불복한 6,000만 원만 심판대상이나 ⅲ) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§415</strong></span></span>단서로 불이익변경금지 적용 배제 ⅳ) 전부 심판대상이 되어 항소심은 제1심 취소하고 원고 1억 청구 전부를 기각</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 필수적 공동소송·예비적 공동소송·독립당사자참가소송(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">필수적 공동소송은 전부판결에 일부 상소시 상소불가분으로 전부 이심되며 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67</strong></span></span> 합일확정의 원칙 때문에 불이익변경금지가 배제되어 전부 심판대상 / 예비적 공동소송은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70①</strong></span></span>, 독립당사자참가는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§79②</strong></span></span>에서 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67</strong></span></span>을 준용하므로 불이익변경금지 배제</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>불이익변경금지의 원칙 위반의 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">불이익변경금지 위반은 처분권주의(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§203</strong></span></span>) 위반으로 법령위반으로 인한 상고이유</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>항소심에 이심은 되어 있으나 심판대상이 되지 않는 부분의 확정시기(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 수개의 청구를 모두 기각한 제1심판결에 원고가 일부 청구에만 항소한 경우, 미항소 나머지 부분도 확정이 차단되고 항소심에 이심되나 항소심 심판대상이 되지 않아 항소심판결 선고로 그 부분은 확정(소송종료)(<span class=\"cs-u\"><strong>항소심판결선고시설</strong></span>) ② 원고청구 일부인용된 환송 전 원심판결에 피고만 상고하고 상고심이 원심판결 중 피고 패소부분을 파기환송하면, 상고심 심리대상은 그 부분에 국한되고 환송 후 원심 심판범위도 피고 패소부분에 한정되며 환송 전 원심판결 중 원고 패소부분은 확정되어 환송 후 원심은 이를 심리할 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>항소심에 이르러 새로운 청구가 추가된 경우 항소심의 판단</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 항소심은 추가된 청구에 대해 실질상 제1심으로 재판해야 함 → 제1심이 기존청구를 기각한 데 원고가 항소하고 항소심이 기존청구와 추가청구를 모두 배척할 경우, \"원고의 항소를 기각한다\"라는 주문만 표시해서는 안 되고 추가청구에 대해 \"원고의 청구를 기각한다\"라는 주문도 표시해야 함</div><div class=\"cs-h\">Ⅲ. 항소의 취하[사례 '24, '25]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>당사자에 관한 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>소송물에 관한 요건(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">항소 제기시 항소불가분으로 모든 청구가 이심되므로 소취하와 달리 항소취하는 항소 전부에 대하여 해야 하고 일부항소취하는 허용되지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>시기에 관한 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 소취하는 '판결확정시'까지 가능하나 항소취하는 항소제기 후 항소심 종국판결 선고 전까지 가능(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§393①</strong></span></span>) ② (환송심에서 항소취하 긍정) 判例: 항소심 종국판결이 상고심에서 파기환송된 경우 먼저 있던 종국판결이 없었던 것과 같은 상태로 돌아가므로 새로운 종국판결 선고 전까지 부대항소 여부와 관계없이 항소취하 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>방식에 관한 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">항소취하는 서면으로 하고, 변론·변론준비기일에서는 말로도 할 수 있으며 조서에 기재(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§393②</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§266③</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(5) <strong>상대방의 동의 불요</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소취하와 달리 항소취하는 상대방의 동의가 필요 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① (★) 항소취하시 ⅰ) 항소심만 소급적으로 소멸(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§393②</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§267①</strong></span></span>) ⅱ) 제1심판결은 확정 ⅲ) 항소기간 경과 후 취하하면 항소기간 만료시에 소급하여 제1심판결 확정, 항소기간 만료 전 취하하면 판결은 확정되지 않고 항소인은 항소기간 내 다시 항소 가능 ② (★) 원고가 항소심에서 교환적 변경을 한 경우 피고가 항소를 취하할 수 있는지 — 判例: 항소심에서 원고의 교환적 변경시 구청구는 취하되고 항소심 심판대상은 새로운 청구만이 되어, 피고가 항소를 취하해도 항소취하는 대상이 없어 아무런 효력이 없음<span class=\"cs-x\"><strong>(X)</strong></span> ③ (일부항소 취하 부정)(★) 判例: 항소취하는 항소 전부에 대하여 해야 하고 일부취하는 효력이 없으므로, 병합된 수개 청구 전부에 불복한 항소에서 일부 청구에 대한 항소를 철회해도 불복범위를 감축해 심판대상을 변경하는 효과에 지나지 않고, 항소인이 변론종결시까지 불복범위를 다시 확장할 수 있는 이상 항소 자체 효력에 영향 없음 ④ (★) 判例: <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§268④</strong></span></span>의 항소취하 간주는 법률상 당연히 발생하는 효과이고 법원의 재판이 아니므로 상고 대상인 종국판결에 해당하지 않음 → 항소취하 간주 효력을 다투려면 민소규칙<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span> 절차로 항소심 법원에 기일지정신청을 할 수는 있으나 상고는 제기 불가</div><div class=\"cs-h\">Ⅳ. 부대항소</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의 및 법적성질</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 부대항소란 '피항소인이 항소인의 항소로 개시된 항소심절차에 편승하여 항소심 심판범위를 자기에게 유리하게 확장하는 신청'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§403</strong></span></span>) — 항소인이 불복하지 않은 부분뿐 아니라 제1심 판결사항이 아니었던 것까지 심판범위에 포함시킬 수 있음 ② (★) 判例(<span class=\"cs-u\"><strong>비항소설</strong></span>): ⅰ) 항소기간 도과 뒤에도 부대항소 가능 ⅱ) 항소이익 불요이므로 전부승소하여 항소권이 없는 피항소인도 상대방 항소에 편승해 청구변경 또는 반소제기를 위한 부대항소 가능[선택 '25]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 주된 항소가 적법하게 계속될 것 ② 피항소인이 항소인을 상대로 제기할 것 ③ 항소심 변론종결 전일 것 ④ 부대항소장 제출 ⑤ 부대항소는 비항소이므로 항소이익 불요</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① (전부승소자의 청구변경) 判例: 원고가 전부승소하여 항소하지 않고 피고만 항소한 사건에서 청구취지를 확장·변경하여 피고에게 불리하게 된 경우 그 한도에서 부대항소를 한 취지로 보며, 부대항소는 비항소여서 항소이익 불요 — '부대항소장 제출 없이 청구취지확장서·반소장을 제출'해도 되고 상대방에게 불리하게 되는 한도에서 부대항소를 한 것으로 봄[선택 '14, '16]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">② (항소기간 경과 후 항소) 判例: 피항소인이 항소기간 지난 뒤 단순 항소기각을 구하는 방어적 신청에 그치지 않고 제1심판결보다 자신에게 유리한 판결을 구하는 적극적·공격적 신청의 의미가 객관적으로 명백히 기재된 서면을 제출하고 상대방에게 절차적 권리가 보장된 경우, '부대항소장'·'부대항소취지' 표현이 없어도 부대항소로 볼 수 있음(항소기간 지난 뒤 실질적으로 패소부분에 불복하는 취지가 담긴 항소장을 제출한 경우에도 부대항소로 볼 수 있음)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>항소심의 심판범위의 확장(★) - 불이익변경금지원칙의 배제</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">부대항소를 하면 항소심 심판범위가 항소인의 불복신청범위보다 확장되어 불이익변경금지가 배제되므로 항소인에게 원심판결 이상의 불이익한 판결이 날 수도 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>부대항소의 종속성(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 종속적 부대항소</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">항소기간 경과 후에 하는 부대항소를 종속적 부대항소라 하며, 주된 항소의 취하·각하에 의하여 효력을 잃음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§404</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 독립적 부대항소</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">부대항소인이 항소할 수 있는 기간 내에 제기한 부대항소는 '독립적 부대항소'라 하며 독립된 항소로 보므로(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§404</strong></span></span>단서) 주된 항소가 취하·각하되어도 소멸하지 않음 — 주된 항소가 취하·각하되면 부대항소는 항소가 되므로 별도의 항소이익 요구(제1심에서 전부승소한 자가 독립 부대항소를 한 뒤 주된 항소가 취하되면 위 부대항소는 항소이익 없어 부적법)</div><div class=\"cs-h\">Ⅴ. 항소심의 종국적 재판</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>항소장 각하명령(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§402</strong></span></span><strong>)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 항소장 방식위배(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§397</strong></span></span>), 항소기간 도과, 항소장 송달불능의 경우 재판장의 명령으로 항소장 각하 — 判例: ⅰ) 항소인에게 상당한 기간을 정해 피항소인 주소를 보정하도록 명하고 그 기간 내 미보정시 명령으로 항소장 각하 ⅱ) 주소보정명령 보정기간 경과로 항소장 각하명령을 할 수 있음에도 항소심재판장이 각하명령을 하지 않고 다시 보정기간을 정해 주소보정명령을 하였다면, 다시 한 보정기간 경과 전에는 종전 보정기간 내 미이행을 이유로 항소장 각하명령 불가 ② 항소장 각하명령은 항소장 송달 전까지만 가능 → 항소장이 피항소인에게 송달되어 소송관계가 성립하면 재판장은 더 이상 소장각하명령을 할 수 없고 판결로 항소를 각하해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>항소각하(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§413</strong></span></span><strong>)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">항소적법요건에 흠이 있어 부적법할 때 판결로 항소를 각하 — 부적법한 항소로서 흠을 보정할 수 없으면 변론 없이 판결로 항소를 각하할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>항소기각(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§414</strong></span></span><strong>)(★)</strong><strong>[변리사 '08]</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 항소법원은 제1심판결을 정당하다고 인정하는 때에는 항소를 기각(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§414①</strong></span></span>) ② 제1심판결 이유가 정당하지 않아도 다른 이유로 그 판결이 정당하다고 인정되는 때에는 역시 항소기각(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§414②</strong></span></span>) ③ 判例: 상계항변에 의해 승소한 피고가 항소했을 때 항소법원이 볼 때 상계에 의할 필요 없이 변제 등으로 수동채권 부존재로 청구기각할 수 있으면, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§414②</strong></span></span>로 항소기각을 할 수 없고 항소를 인용해 제1심 취소하고 청구기각판결을 선고해야 함(상계항변 판단에 기판력이 생겨 결론은 같은 청구기각이어도 기판력의 객관적 범위가 달라지기 때문)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>항소인용</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">1) 원심 판결의 취소·자판(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§416</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">항소법원은 제1심판결을 정당하지 않다고 인정한 때 항소를 인용해 제1심판결을 취소해야 함 — 항소심은 사실심이므로 스스로 재판함이 원칙이고 예외적으로 환송·이송</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">2) 예외 - 필수적 환송(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§418</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 항소법원이 취소할 원심판결이 소각하판결인 경우 본안심리가 이루어지지 않았으므로 심급의 이익 보장을 위해 원심법원으로 환송(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§418</strong></span></span> 본문, 필수적 환송) ② 예외적으로 제1심에서 본안판결할 수 있을 정도로 본안심리가 된 경우나 당사자 동의가 있는 경우 환송하지 않고 자판(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§418</strong></span></span> 단서)</div><div class=\"cs-h\">Ⅵ. 상고</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>상고인용판결</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>원판결의 파기 및 환송 또는 이송</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 상고법원은 항소심판결이 잘못되어 상고에 정당한 이유가 있다고 인정할 때 원심판결을 파기 ② 법률심인 상고심은 사실심리를 할 수 없으므로 사건을 원심법원에 환송하거나 동등한 다른 법원에 환송·이송(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§436①</strong></span></span>) ③ (환송 후 환송심의 심판범위) 判例: ⅰ) 환송 후 원심 소송절차는 환송 전 항소심의 속행이므로 당사자는 새로운 사실·증거 제출, 소의 변경, 부대항소, 청구의 확장 등 그 심급에서 허용되는 모든 소송행위를 할 수 있고 환송 전 판결보다 상고인에게 불리한 결과가 생기는 것은 불가피 ⅱ) 환송판결에서 환송 전 원심판결 중 피고 패소부분만 파기했다면 환송 후 원심 심판범위는 피고 패소부분과 환송 후 확장된 부분에 한정되므로, 인용할 수 있는 한도액은 피고 패소부분에 환송 후 확장된 부분을 더한 금액</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>자판</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">상고법원은 원판결을 파기하는 경우 예외적으로 ① 확정된 사실에 법령적용이 어긋난다 하여 파기하는 경우 그 사실을 바탕으로 재판하기 충분한 때 ② 사건이 법원 권한에 속하지 않는다 하여 파기하는 때 ③ 그 밖의 소송요건 흠을 이유로 파기할 때에는 스스로 본안판결(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§437</strong></span></span>) ④ 파기자판시 상고법원은 제2심(항소심) 입장에서 재판(항소에 대한 응답의 형태)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (★) 判例: 소송요건 흠을 이유로 소각하한 제1심·항소심판결을 상고법원이 파기하는 경우 항소심판결을 파기·자판해야 하고, 제2심 입장에서 항소를 인용해 제1심판결을 취소하고 자판해야 하나, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§418</strong></span></span> 본문('소가 부적법하다고 각하한 제1심판결을 취소하는 경우 항소법원은 사건을 제1심법원에 환송')에 따라 결국 사건을 제1심법원으로 환송해야 함 ② (★) 判例: 추심채권자가 제3채무자 상대 추심금청구를 하여 제1심 일부승소 후 피고만 항소, 원심 항소기각 후 피고만 상고한 사안에서 상고이유서 제출기간 경과 후 채권압류·추심명령이 취소된 사정이 드러나자 직권으로 원고가 추심권능을 상실해 당사자적격 없는 부적법한 소로 판단하고, 제1심판결 중 항소심 심판대상이 아닌 원고패소부분은 원심판결 선고와 동시에 확정되어 소송종료되었으므로, 상고심은 원심판결을 파기·자판하여 제1심판결 중 피고패소부분 취소, 그 부분 소각하판결을 해야 함(추심명령이 취소되어 추심채권자의 추심권능이 상실된 사안으로 변경판례 사안이 아님에 주의)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>파기환송판결의 기속력(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>기속력의 의의 및 성질</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">환송판결의 기속력이란 '환송받은 법원이 다시 심판할 때 상고법원이 파기이유로 한 법률상·사실상 판단에 기속되는 것'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§436②</strong></span></span>단서) — 성질에 관하여 判例는 '심급제도의 유지'를 위해 상급심 판결이 하급심을 구속하는 특수한 효력으로 보는 특수효력설</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>기속력의 발생범위(★) - 파기환송 판결의 기속력이 발생하는 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 환송받은 법원이 기속되는 것은 대법원이 한 '사실상 판단'과 '법률상 판단' ② 기속력은 원심판결 판단을 부당하다고 하여 파기이유로 한 판단 및 파기이유와 논리필연적 관계에 있는 판단에 한하여 발생하므로 부수적으로 지적한 사항은 기속력 없음 ③ (논리필연적 전제) 判例: 환송판결이 피대위권리가 없다는 판단만 하였더라도 그 판단은 피보전채권을 구비하였다는 판단을 당연한 논리적 전제로 하므로 기속력이 소송요건 구비로 적법하다는 판단에도 미침에도, 환송 후 원심이 소송요건을 구비하지 못한 부적법한 소라고 본 것은 기속력에 반하여 위법</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>기속력의 작용범위 - 후소에 기속력이 작용하는 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 주관적 범위(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 환송받는 법원 및 하급심에 미치고 ② 사건이 재상고된 때에는 기속력을 절차적으로 담보하기 위해 상고법원(4인의 부)도 기속함이 원칙 ③ 判例: 종래 재상고심의 전원합의체까지 기속된다고 보았으나, 입장을 변경하여 의견변경권을 가진 재상고심의 전원합의체는 기속되지 않음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 객관적 범위</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">기속력은 객관적으로 당해 사건에 한하여 작용하고 다른 사건에는 미치지 않으므로 다른 사건에서는 이와 달리 판단해도 무방</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>기속력의 효력 - 후소법원의 조치</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 환송법원은 기속력 때문에 상고법원이 파기이유로 한 법률상·사실상 판단에 따라야 하므로 파기사유와 다른 판단 불가 ② 새로운 변론·증거조사 결과 사실관계가 달라져 법률판단도 달리 해야 하는 경우에까지 기속력이 미치는 것은 아님 → 이 경우 항소법원은 대법원이 파기사유로 한 법률판단과 다른 판단 가능</div><div class=\"cs-h\">Ⅶ. 재심</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>적법요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">재심의 소가 적법하려면 재심 당사자적격을 구비한 자가 ① 재심의 대상적격 ② 재심기간 준수(적식) ③ 재심의 이익 ④ 당사자 자격 ⑤ 법정 재심사유를 주장(주장 자체의 정당성) ⑥ 재심의 보충성 요건을 구비해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>대법원의 파기환송판결이 재심의 대상적격이 있는지 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 대법원의 환송판결은 '형식적'으로 보면 확정된 '종국판결'에 해당하지만 직접적으로 기판력·실체법상 형성력·집행력이 생기지 않으므로 '실질적으로 확정된 종국판결'이라 할 수 없음 → 환송판결을 대상으로 한 재심의 소는 부적법 각하<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>확정된 재심판결에 대하여 재심의 소 제기 가부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>은 '확정된 종국판결'에 대해 재심의 소를 제기할 수 있다고 규정하는데, 재심의 소에서 확정된 종국판결도 이에 해당하므로 확정된 재심판결에 재심사유가 있을 때에는 재심의 소 제기 가능<span class=\"cs-o\"><strong>(O)</strong></span> ② (확정되지 아니한 판결에 대한 재심의 소 부적법) 재심은 확정된 종국판결에 대해 제기할 수 있으므로 확정되지 않은 판결에 대한 재심의 소는 부적법하고, 판결 확정 전에 제기한 재심의 소가 각하되지 않고 있는 동안 판결이 확정되었더라도 재심의 소가 적법해지는 것은 아님<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>대법원이 판례변경을 하면서 대법관 2/3 이상 전원합의체가 아닌 소부(4인)에서 재판한 경우 재심사유(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 재심대상 대법원판결이 그 전 대법원판결의 의견을 변경하는 것이라면 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>법원조직법§7①</strong></span></span>3호에 의해 대법관 전원의 3분의 2 이상 합의체에서 심판했어야 하는데, 그에 미달하는 4인의 대법관만으로 구성된 부에서 심판했다면 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>1호의 '법률에 의하여 판결법원을 구성하지 아니한 때'의 재심사유에 해당</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>대리권의 흠이 있는 때 재심사유</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 무권대리인이 대리인으로서 본인을 위해 실질적 소송행위를 한 경우뿐 아니라 ② 대리권 흠결로 본인이나 그의 소송대리인이 실질적 소송행위를 할 수 없었던 경우도 재심사유에 해당</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>재심의 소에서 피참가인의 소의 취하(★) - 무효</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 재심의 소를 취하하는 것은 통상의 소취하와 달리 확정된 종국판결에 대한 불복 기회를 상실하게 하여 더 이상 확정판결의 효력을 배제할 수 없게 하는 행위이므로, 재판의 효력과 직접 관련된 소송행위로서 확정판결의 효력이 미치는 공동소송적 보조참가인에게 불리한 행위 ② 따라서 재심의 소에 공동소송적 보조참가인이 참가한 후에는 피참가인이 재심의 소를 취하해도 공동소송적 보조참가인의 동의가 없는 한 효력 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>재심 본안심판(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 처음부터 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451</strong></span></span> 각 호에 없는 사유를 주장하면 재심의 소를 부적법 각하 ② <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451</strong></span></span> 각호 사유를 주장했으나 심사 결과 그 사유에 해당하지 않으면 재심청구기각 ③ 判例: 재심사유는 하나하나가 별개의 청구원인을 이루므로, 여러 개의 유죄판결이 재심대상판결의 기초가 되었는데 이후 각 유죄판결이 재심으로 효력을 잃고 무죄판결이 확정된 경우, 어느 한 유죄판결이 효력을 잃고 무죄판결이 확정되었다는 사정은 특별한 사정이 없는 한 별개의 독립된 재심사유(각 유죄판결의 형사재심사유가 공통되거나 무죄판결 이유가 동일해도 달리 볼 수 없음)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>재심소송의 당사자적격(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 재심의 소는 확정판결을 취소해 기판력을 배제하는 데 목적이 있으므로 확정판결 당사자와 기판력이 미치는 변론종결 후의 승계인도 재심의 소의 당사자적격 있음 ② 判例: 재심대상판결의 소송물이 취득시효 완성을 이유로 한 소유권이전등기청구권(채권적 청구권)인 경우, 그 변론종결 후 원고로부터 소유권이전등기를 경료받은 승계인은 기판력이 미치는 변론종결 후의 제3자에 해당하지 않고, 피고들은 기판력 배제를 위해 승계인에게 재심의 소를 제기할 필요가 없으므로 승계인에 대한 재심의 소는 부적법<span class=\"cs-x\"><strong>(X)</strong></span>[사례 '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span><strong>8호의 재심사유(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>8호 재심사유인 \"판결의 기초가 된 민사·형사 판결, 그 밖의 재판 또는 행정처분이 다른 재판이나 행정처분에 따라 바뀐 때\"란 확정판결에 법률적 구속력을 미치거나 확정판결에서 사실인정의 자료가 된 재판 등이 그 후 다른 재판 등에 의해 변경된 경우 — 사실인정의 자료가 되었다는 것은 변경 전 재판내용 등이 확정판결 주문에 영향을 미치는 사실인정 자료가 된 경우를 의미하므로, 변경 전 재판내용 등을 제외한 나머지 증거들에 의해도 판결 주문에 아무 영향이 없는 경우에는 재심사유에 해당하지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div>", ["★★★"], 1, "mp_5"], ["민소043", "단순병합", "<div class=\"cs-h\">Ⅰ. 의의 및 요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① 단순병합이란 '원고가 여러 개의 청구에 대하여 차례로 심판을 구하는 형태의 병합'으로, 법원은 병합된 모든 청구에 대하여 심판해야 함 ② 단순병합 중 ⅰ) 어느 하나의 청구가 다른 청구의 선결관계에 있거나 ⅱ) 기본적 법률관계를 공통으로 하는 경우를 '관련적 병합'이라 함 ③ 요건: ⅰ) 동종 절차에 의하여 심판될 수 있을 것 ⅱ) 공통의 관할권이 있을 것 ⅲ) 관련성은 불요 ⅳ) 양립할 수 없는 청구의 경우 단순병합 불허<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 절차와 심판</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소가의 산정과 병합요건의 조사</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① (소가 산정) 단순병합은 청구들 사이의 경제적 이익이 독립·별개이므로 병합된 청구 가액을 합산함이 원칙 ② (병합요건) 병합요건은 법원의 직권조사사항이며, 흠이 있을 때에는 소를 각하할 것이 아니라 분리심판해야 함 ③ (소송요건) 병합요건이 갖추어지면 소송요건을 조사하여 흠이 있으면 당해 청구에 관한 소각하판결</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>심리의 공통</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">여러 개의 청구가 같은 절차에서 심판되며 '변론의 분리'가 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>종국판결과 상소의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>단순병합의 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">'전부판결'을 함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§198</strong></span></span>) — 그러나 단순병합은 '변론의 분리'가 허용되므로 '일부판결'을 할 수도 있음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§200</strong></span></span>) — 법원이 '모르고' 일부판결을 하였을 때에는 판결 안 한 부분은 '재판누락'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§212</strong></span></span>)으로 '제1심에 계속 중'이며 '추가판결'로 완결해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>단순병합 중 관련적 병합의 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 원금청구부분만 판단하고 확장된 지연손해금청구부분을 판단하지 않은 경우 이는 재판의 누락으로 그 부분 소송은 아직 원심에 계속 중이어서 적법한 상고 대상이 되지 않으므로 그 부분 상고는 부적법 → 일부판결이 허용됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>상소의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 전부판결에 전부상소한 경우 전부 이심되며 전부 심판대상 ② (★) 전부판결에 일부상소한 경우 상소불가분으로 전부 이심되나 불이익변경금지로 상소한 청구만 일부 심판대상 ③ (★) 단순병합은 일부판결이 허용되므로 ⅰ) 일부판결에 상소한 때 나머지 부분과 별도로 이심의 효력 발생 ⅱ) 다만 일부판결한 경우 판결 안 한 부분은 재판의 누락으로 제1심에 계속 중이며 추가판결로 구제 → 판결 안 한 부분에 대해 항소하면 항소의 대상적격이 없어 부적법하여 항소각하판결[선택 '12, '14, '25]</div><div class=\"cs-h\">Ⅲ. 관련문제</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>불법행위로 인한 손해배상(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">손해배상청구에서 ① 적극적 손해 ② 소극적 손해 ③ 정신적 손해를 함께 청구하는 경우, 判例의 손해3분설에 따르면 3개 청구의 단순병합으로 관련적 병합</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>부진정 예비적 병합(★) - 부진정 예비적 병합에서 후술</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>대상청구(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>대상청구</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">대상청구란 '원고가 물건의 인도를 구하면서 물건의 이행불능 또는 집행불능에 대비하여 그 물건의 가액에 상당하는 금액을 청구하는 것'</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>종류물 인도청구에 대비한 대상청구(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 청구의 성질</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">종류물의 인도청구와 대상청구를 하는 경우, 대상청구는 변론종결 후 '집행불능' 사태를 대비한 것으로, 判例는 양 청구가 서로 양립가능하므로 단순병합으로 봄</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 청구의 적법 여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">현재이행의 소인 종류물 인도청구와 장래이행의 소인 대상청구의 병합 → ⅰ) 전자는 현재이행의 소로 소의 이익이 있어 적법 ⅱ) 후자는 장래이행의 소로 청구적격과 미리 청구할 필요가 있어 적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 심판 방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">양 청구는 단순병합이므로 법원은 순서에 구속되어 판단하되 모든 청구에 대해 심판해야 함 → ⅰ) 종류물 인도청구를 인용하는 경우 대상청구도 인용하는 별개의 주문을 내야 하고 ⅱ) 반대로 인도청구가 이유 없어 기각할 때에는 대상청구도 기각</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>특정물 인도청구에 대비한 대상청구(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 청구의 성질</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 특정물의 경우 이행불능 또는 집행불능에 대비하여 대상청구도 가능 ② 이행불능에 대비하여 대상청구를 병합한 경우 진정 예비적 병합으로 봄 ③ 집행불능에 대비하여 대상청구를 병합하였다면 단순병합에 해당[사례 '26]</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 심판방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 이행불능에 대비하여 대상청구한 경우 예비적 병합의 심판방법과 같이 ⅰ) 주위적 청구가 인용될 때에는 해제조건 성취로 예비적 청구에 대해 심판할 필요 없으나 ⅱ) 기각되는 때에는 예비적 청구에 대해 심판해야 함 ② 특정물에서 집행불능에 대비하여 대상청구한 경우 종류물의 대상청구와 같이 심판[사례 '26]</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 당사자의 의사가 불분명한 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 특정물의 인도청구와 대상청구를 병합하면서 '인도불능'인 때로 기재한 경우와 같이 의사가 불분명한 경우 '집행불능'에 대비한 것으로 봄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>등기청구와 대상청구</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 채권자가 본래적 급부청구인 부동산등기청구에 이에 대신할 전보배상을 병합하여 소구한 경우, 대상청구는 본래적 급부청구권이 현존함을 전제로 이것이 판결확정 전에 이행불능되거나 판결확정 후에 집행불능이 되는 경우에 대비하여 전보배상을 미리 청구하는 경우로서 양자의 병합은 현재의 급부청구와 장래의 급부청구의 단순병합에 속하여 허용됨[변리사 사례 '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(5) <strong>가집행선고부 판결</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">가집행선고부 판결의 집행력은 후일 본안판결 또는 가집행선고가 취소·변경될 것을 해제조건으로 그 선고 즉시 발생하므로, 본래적 급부의 이행과 함께 대상적 급부의 이행을 명한 판결이 확정되기 전에 그 가집행선고부 판결에 기하여 한 본래적 급부에 대한 강제집행이 집행불능에 이른 경우에도 이후 위 판결 또는 가집행선고가 취소·변경되지 않는 한 그 집행불능의 시점에 대상적 급부청구권이 발생</div>", ["★★"], 1, "mp_6"], ["민소044", "선택적 병합", "<div class=\"cs-h\">Ⅰ. 의의 및 요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">선택적 병합이란 '여러 개의 청구 중 어느 한 청구가 택일적으로 인용될 것을 해제조건으로 하여 청구하는 형태의 병합' → 요건: ① 청구들이 논리적으로 양립가능할 것 ② 하나의 목적을 위해 수개의 청구권·형성권이 경합하는 경우일 것 ③ 논리적으로 관련성이 있을 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>논리적으로 양립가능할 것(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 논리적으로 양립할 수 없는 여러 개의 청구를 선택적으로 병합청구할 수 없음(선택적 병합을 인정하면 처분권주의 위배)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>하나의 목적을 위해 수개의 청구권·형성권이 경합하는 경우일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">청구취지는 하나이고 청구원인만이 여러 개인 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>논리적으로 관련성이 있을 것(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>관련성이 없어 단순병합으로 할 청구를 선택적 병합청구할 수 있는지 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 논리적 관련성이 없어 단순병합으로 구해야 할 수개 청구를 선택적 병합으로 청구하는 것은 부적법하여 불허<span class=\"cs-x\"><strong>(X)</strong></span> ② 법원은 소송지휘권을 행사해 단순병합청구로 보정조치를 취해야 함 — 법원이 이런 조치 없이 하나의 청구만 심판해 인용하고 나머지 청구 심판을 생략하는 판결을 해도 병합 형태가 선택적 병합으로 바뀌지 않음 → 이런 판결에 피고만 항소한 경우 제1심이 심판·인용한 청구만 항소심으로 이심되고 나머지 심판하지 않은 청구는 여전히 제1심에 남아있음[선택 '14, '25]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>논리적으로 관련성이 있는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 제1심판결 선고 전 명예훼손행위에 관해 손해배상청구를 하였으나 기각당한 원고가 항소심에서 청구취지를 변경하지 않은 채 피고가 제1심판결 선고 후 행한 새로운 명예훼손행위를 청구원인으로 추가하였다면 선택적 병합으로 봄</div><div class=\"cs-h\">Ⅱ. 절차와 심판</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소가의 산정과 병합요건의 조사</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소가 산정은 중복청구의 흡수의 법리를 따름 — 병합요건은 법원의 직권조사사항으로 흠이 있을 때에는 분리·심판, 병합요건이 갖추어지면 소송요건을 조사하여 흠이 있으면 소각하판결</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>심리의 공통</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">병합요건과 소송요건이 구비되면 병합된 여러 청구는 같은 절차에서 심판 — 선택적 병합은 어느 하나의 청구에 대한 '변론의 분리'가 허용되지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>종국판결</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>종국판결과 일부판결 가부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 선택적 병합된 청구는 '전부판결'을 해야 함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§198</strong></span></span>) ② 判例: 선택적 병합은 수개 청구가 불가분적으로 결합되어 있어 일부판결 불가<span class=\"cs-x\"><strong>(X)</strong></span> ③ 선택적 병합은 일부판결이 허용되지 않으므로 일부판결한 경우 전부판결(판단누락에 준하는 위법)로 취급 ④ 判例: ⅰ) 선택적으로 병합된 수개 청구를 모두 기각한 항소심판결에 원고가 상고한 경우, 상고법원이 선택적 청구 중 어느 하나의 청구에 관한 상고가 이유 있다고 인정할 때 일부만 파기할 수 없고 항소심판결을 전부 파기해야 함 ⅱ) 원심이 수개 선택적 청구 중 하나의 청구만 일부 인용하고 나머지 청구는 기각하여 원·피고가 모두 상고·부대상고를 하였고 그중 피고의 상고가 이유 있어 원심판결을 파기할 경우, 상고심은 원심판결 중 피고 패소부분 외에 나머지 청구 중 피고 패소부분에 대응하는 부분까지 함께 파기해야 함(이 법리는 성질상 선택적 관계에 있는 청구를 심판순위를 붙여 예비적으로 병합한 경우에도 동일 적용)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>상소의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 전부판결에 전부상소한 경우 전부 이심되며 전부 심판대상 ② 전부판결에 일부상소한 경우 상소불가분으로 전부 이심되나 불이익변경금지로 상소한 청구 일부만 심판대상</div><div class=\"cs-h\">Ⅲ. 판단누락(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판단방법</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">원고승소판결시 이유 있는 청구 중 어느 하나를 선택하여 인용판결하면 되고 나머지 청구는 심판 불요 — 그러나 원고패소판결시 병합된 청구 전부에 대해 배척 판단을 요함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판단누락(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>청구기각판결에서 일부 배척판단 안 한 경우 - 1개</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 선택적 병합은 일부판결이 허용되지 않으므로, 청구기각판결을 하면서 일부 청구에 대해 배척판단을 하지 않은 부분은 판단누락에 준하는 위법한 판결로 봄[선택 '13, '14, '16]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>판단누락에서 관련문제(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 제1심에서 추가판결 가부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例(<span class=\"cs-u\"><strong>판단누락설</strong></span>)에 의하면 제1심법원이 추가판결을 할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 항소심 조치</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例(<span class=\"cs-u\"><strong>판단누락설</strong></span>)에 의하면 선택적 병합에서 청구기각판결을 하면서 일부 청구에 배척판단을 하지 않은 것은 판단누락에 준하는 위법한 전부판결로 보고 상소와 재심으로 구제됨 → 제1심이 원고의 선택적 청구 중 하나만 기각하고 나머지 청구에 아무 판단을 하지 않은 조치는 위법하고, 원고가 위법한 제1심판결에 항소한 이상 선택적 청구 전부가 항소심으로 이심되었으므로 판단되지 않은 청구 부분이 재판의 누락으로 제1심에 계속되어 있다고 볼 것은 아님</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 별소제기 가부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 선택적 병합은 아니지만 예비적 병합에서 판단누락된 부분에 대한 별소제기는 권리보호이익(제소장애사유)이 없어 부적법</div><div class=\"cs-h\">Ⅳ. 청구인용판결에 대한 항소의 효력(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>청구인용판결에 대한 항소의 효력(★) - 전부 이심, 전부 심판의 대상</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>이심의 범위와 심판의 범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 선택적 병합의 청구인용판결은 전부판결이므로 항소가 있으면 모든 청구가 항소심으로 이심되고 다른 청구도 항소심 심판대상이 됨(항소심에서 제1심 인용청구가 이유 없다고 인정될 때 선택적으로 병합된 청구가 항소심 심판대상이 될 수 있어야 하기 때문)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>항소심 심판 순서</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 항소심은 제1심에서 인용된 청구를 먼저 심리·판단할 필요는 없고, 선택적으로 병합된 수개 청구 중 제1심에서 심판되지 않은 청구를 임의로 선택하여 심판할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>청구인용판결에 대한 항소심판결(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 제1심에서 선택적 병합청구하고 청구인용판결이 선고되어 피고가 항소한 경우, 항소심은 다른 청구가 이유 있다고 인정되고 결론이 제1심판결 주문과 동일한 경우에 제1심판결을 취소하고 청구를 인용하는 주문을 선고해야 함(<span class=\"cs-u\"><strong>항소인용설</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>선택적 관계에 있는 청구를 심판의 순위를 붙여 청구한다는 취지의 예비적 병합에 적용 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例(최근): ① 여러 청구가 제1심에서 선택적으로 병합되고 그중 어느 하나의 청구에 대한 인용판결이 선고되어 피고가 항소한 때에는 제1심이 판단하지 않은 나머지 청구까지도 항소심으로 이심되어 항소심 심판범위가 되므로, 항소심이 원고 청구를 인용할 경우 선택적으로 병합된 여러 청구 중 어느 하나를 임의로 선택하여 심판할 수 있음 ② 따라서 항소심이 하나의 청구는 일부만 인용하고 나머지 청구는 기각하여 피고만 상고하였는데 피고의 상고가 이유 있어 원심판결을 파기할 경우, 상고심은 원심판결 중 피고 패소부분 외에 나머지 청구 중 피고 패소부분에 대응하는 부분까지 함께 파기해야 함 ③ 이 법리는 성질상 선택적 관계에 있는 청구를 심판순위를 붙여 예비적으로 병합한 경우에도 동일 적용</div>", ["★★"], 1, "mp_6"], ["민소045", "예비적 병합", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">예비적 병합이란 '양립할 수 없는 여러 개의 청구를 하면서 그 심판의 순위를 붙여 제1차적(주위적) 청구가 인용될 것을 해제조건으로 제2차적(예비적) 청구에 대하여 심판을 구하는 형태의 병합'</div><div class=\"cs-h\">Ⅱ. 요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 청구들 사이에 순서를 붙일 것 ② 주위적 청구와 예비적 청구가 양립될 수 없는 관계에 있을 것 ③ 논리적으로 관련성이 있을 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>양립될 수 없는 관계일 것(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">예비적 청구는 주위적 청구와 양립될 수 없는 관계여야 하므로, 전자가 후자를 흡수·포함하는 관계일 때에는 예비적 병합이라 할 수 없음 — 判例: 주위적 청구와 동일한 목적물에 관하여 동일한 청구원인을 내용으로 하면서 주위적 청구를 양적·질적으로 일부 감축하여 하는 청구는 주위적 청구에 흡수될 뿐 예비적 청구라 할 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>관련성이 있을 것(★)</strong>[변리사]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">예비적 병합은 수개 청구들이 논리적으로 관련성(법률적·경제적으로 동일목적의 추구)이 있어야 함 — 논리적 관련성이 없어 단순병합으로 구해야 할 수개 청구를 예비적 병합으로 청구하는 것은 부적법하여 불허, 제1심법원은 단순병합청구로 보정하게 하는 조치를 취해야 함 → 법원이 이런 조치 없이 하나의 청구만 심판해 인용하고 나머지 청구 심판을 생략하는 판결을 해도 병합 형태가 예비적 병합으로 바뀌지 않음</div><div class=\"cs-h\">Ⅲ. 부진정 예비적 병합(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>부진정 예비적 병합의 의의와 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">부진정 예비적 병합이란 'ⅰ) 논리적으로 양립할 수 있는 각 청구에 ⅱ) 순서를 붙여 주위적 청구가 인용되지 않을 경우 예비적 청구에 대해 심판을 구하는 것' → 요건: ① 순위를 붙일 것 ② 양립가능할 것 ③ 순서를 붙여 청구할 합리적 필요성이 있을 것 ④ 양 청구 간 관련성이 있을 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>부진정 예비적 병합의 허용 여부와 심판방법</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 논리적으로 양립할 수 있는 수개 청구라도 당사자가 '심판의 순위를 붙여 청구할 합리적 필요성이 있는 경우'에는 당사자가 붙인 순위에 따라 먼저 구하는 청구를 심리하여 이유가 없으면 다음 청구를 심리해야 하고, 선택적 관계에 있는 양 청구를 주위적·예비적 병합 형태로 제소하여 심판의 순위와 범위를 한정하여 청구하는 '부진정 예비적 병합'의 소도 허용 ② 이 경우 당사자가 붙인 순위에 따라 먼저 구하는 청구를 심리하여 이유가 없으면 다음 청구를 심리하는 '진정 예비적 병합'으로 심판</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>부진정 예비적 병합의 인정범위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>단순병합관계에 있는 각 청구를 예비적 병합으로 청구한 경우(★) - 단순병합</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (단순병합 판례) 소유권이전등기청구(제1차 청구)에 병합청구한 전보배상의 대상청구(제2차 청구)는 소유권이전등기청구가 판결확정 전 이행불능되거나 판결확정 후 집행불능이 되는 경우에 대비하여 전보배상을 미리 청구하는 경우로서 양자의 병합은 현재의 급부청구와 장래의 급부청구의 단순병합에 속하여 허용됨 → 단순병합으로 봄 ② (부진정 예비적 병합 긍정 판례) 그러나 논리적으로 양립할 수 있는 수개 청구라도, 주위적으로 재산상 손해배상을 청구하면서 손해가 인정되지 않을 경우 예비적으로 같은 액수의 정신적 손해배상을 청구하는 것과 같이 수개 청구 사이에 논리적 관계가 밀접하고 심판순위를 붙여 청구할 합리적 필요성이 인정되는 경우에는 부진정 예비적 병합의 소도 허용</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>선택적 병합관계에 있는 각 청구를 순서를 붙여 청구할 합리적 필요성이 있는 경우(★) - 부진정 예비적 병합 - 청구 크기에 차이가 있는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 제1차 청구는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§265</strong></span></span>단서 보존행위를 근거로 매매를 원인으로 한 소유권이전등기청구, 제2차 청구는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§263</strong></span></span> 지분권에 기하여 지분에 관한 매매를 원인으로 한 소유권이전등기청구를 한 경우, 양 청구는 청구의 크기에 차이가 있어 원고는 순서를 붙여 청구할 합리적 필요성이 있음 ② 선택적 관계로 동시에 양립할 수 있는 전부금청구와 채무인수금청구를 주위적으로 1,400만 원 전부금청구, 예비적으로 1,000만 원 채무인수금청구로 하는 것도 심판순위와 범위를 한정하여 청구하는 경우로 순서를 붙여 청구할 합리적 필요성이 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>선택적 병합관계에 있는 각 청구라도 순서를 붙여 청구할 합리적 필요성이 없는 경우(★) - 선택적 병합 - 청구 크기에 차이가 없는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 주위적으로 대여금 1억 원 지급청구, 예비적으로 사기에 의한 불법행위를 원인으로 한 1억 원 손해배상청구를 병합청구한 사안에서, 병합 형태가 선택적인지 예비적인지 여부는 당사자 의사가 아닌 병합청구의 성질을 기준으로 판단하고 항소심 심판범위도 병합청구의 성질을 기준으로 결정해야 하므로, 청구의 크기에 차이가 없어 순위를 붙여 청구할 합리적 필요성이 인정되지 않는 경우에는 실질적 선택적 병합으로 봄[사례 '23] ② 불법행위에 기한 손해배상청구와 채무불이행에 기한 손해배상청구는 모두 동일한 목적 달성을 위한 것으로 어느 하나의 채권이 변제로 소멸하면 나머지 채권도 목적 달성으로 동시에 소멸하는 관계이므로 실질적으로 선택적 병합 관계 ③ (판례 없으나) 동일 부동산에 대해 주위적으로 매매에 기한 소유권이전등기, 예비적으로 점유취득시효에 기한 소유권이전등기청구를 하는 경우 등도 청구의 크기에 차이가 없어 실질적 선택적 병합으로 봄이 타당</div><div class=\"cs-h\">Ⅳ. 절차와 심판</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소가의 산정과 병합요건의 조사</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소가 산정은 중복청구의 흡수의 법리를 따름 — 병합요건은 법원의 직권조사사항으로 흠이 있을 때에는 분리·심판, 병합요건이 갖추어지면 소송요건을 조사하여 흠이 있으면 소각하판결</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>심리의 공통 - 변론의 분리 불가</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">병합요건과 소송요건이 구비되면 병합된 여러 청구는 같은 절차에서 심판 — 예비적 병합은 어느 하나의 청구에 대한 '변론의 분리'는 허용되지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>종국판결</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>종국판결과 일부판결 가부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 예비적 병합된 청구는 '전부판결'을 함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§198</strong></span></span>) ② 判例: 예비적 병합은 '일부판결'을 할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> ③ 예비적 병합은 일부판결이 허용되지 않으므로 일부판결한 경우 전부판결(판단누락에 준하는 위법)로 취급 → 전부상소·일부상소한 경우는 아래 (2)와 같음[선택 '16]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>상소의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 전부판결에 전부상소한 경우 전부 이심되며 전부 심판대상 ② 전부판결에 일부상소한 경우 상소불가분으로 전부 이심되나 불이익변경금지로 상소한 청구 일부만 심판대상</div><div class=\"cs-h\">Ⅴ. 판단누락(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판단방법</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">예비적 병합의 경우 ① 주위적 청구가 인용될 때에는 예비적 청구에 대해 심판 불요 ② 기각되는 때에는 예비적 청구에 대해 반드시 심판해야 함 ③ 判例: 원고 패소의 제1심판결에 대해 항소심에서 예비적 청구를 추가하면 예비적 청구에 대해 제1심으로 판단해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판단누락(★) - 2개</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 예비적 병합에서 ① 주위적 청구를 먼저 판단하지 않고 예비적 청구를 먼저 판결한 경우 ② 주위적 청구 기각판결을 하고 예비적 청구는 판단하지 않은 경우에 누락시킨 청구부분을 판단누락(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>9호 참조)으로 봄 — 判例(<span class=\"cs-u\"><strong>판단누락설</strong></span>)에 의하면 ① 제1심법원이 추가판결을 할 수 없고 ② 판단누락에 준하는 위법한 전부판결로 보아 상소와 재심을 통해 구제 ③ 예비적 병합에서 판단누락된 부분에 대한 별소제기는 권리보호이익(제소장애사유)이 없어 부적법</div><div class=\"cs-h\">Ⅵ. 주위적 청구 인용판결과 항소의 효력(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① 예비적 병합에서 주위적 청구를 인용한 것에 대해 피고가 항소한 경우 판결 전부에 대해 확정차단·이심 효력 발생 ② 예비적 청구가 항소심 심판대상이 되는지 — 判例: 이 경우에도 예비적 청구가 항소심 심판대상이 됨(항소심에서 주위적 청구가 이유 없다고 인정되면 예비적 청구를 반드시 심판해야 하기 때문) ③ (항소심 심판) 判例: 원고가 제1심에서 선택적으로 구한 두 청구 중 1개가 인용되고 피고가 항소한 후, 원고가 항소심에서 병합형태를 변경하여 제1심에서 심판되지 않은 청구를 주위적 청구로·제1심에서 인용된 청구를 예비적 청구로 구하여 항소심이 주위적 청구를 먼저 심리해 이유 있다고 인정하는 경우, 비록 결론이 제1심판결 주문과 동일하더라도 피고 항소를 기각해서는 안 되고 새로이 청구를 인용하는 주문을 선고해야 함</div><div class=\"cs-h\">Ⅶ. 주위적 청구기각·예비적 청구인용판결에 대해 피고만이 항소한 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① (이심의 범위) 상소불가분으로 주위적 청구에 관한 부분도 확정이 차단되고 항소심에 전부 이심 ② (심판의 범위) 判例: 제1심에서 주위적 청구를 기각하고 예비적 청구를 인용한 판결에 대해 피고만 항소한 때에는 원고로부터 부대항소가 없는 한 항소심 심판대상은 예비적 청구에 국한(불이익변경금지 적용) ③ (★) (청구인낙) 判例: ⅰ) 주위적 청구는 기각하고 예비적 청구만 인용하는 판결에 대해 피고만 항소하더라도 ⅱ) 이심의 효력은 사건 전부에 미쳐 주위적 청구에 관한 부분도 항소심에 이심되므로 ⅲ) 피고가 항소심 변론에서 원고의 주위적 청구를 인낙하여 조서에 기재되면 그 조서는 확정판결과 동일한 효력이 있고 ⅳ) 그 인낙으로 주위적 청구 인용을 해제조건으로 병합심판을 구한 예비적 청구는 심판할 필요 없이 사건이 그대로 종결 → 항소심에서 주위적 청구를 인낙할 수 있음 ④ (비교판례) 다만 判例: 주위적 청구의 당부를 먼저 판단하여 이유가 없을 때에만 원심에서 추가된 예비적 청구를 심리·판단할 수 있고, 추가된 예비적 청구만 분리하여 심리하거나 일부판결을 할 수 없으며, 피고도 추가된 예비적 청구에 관하여만 인낙을 할 수 없고 인낙 취지가 조서에 기재되어도 인낙의 효력이 발생하지 않음</div>", ["★★"], 1, "mp_6"], ["민소046", "청구의 변경", "<div class=\"cs-h\">Ⅰ. 의의[변리사 사례 '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">청구의 변경이란 '법원과 당사자의 동일성을 유지하면서 소송물을 변경하는 경우'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§262</strong></span></span>)</div><div class=\"cs-h\">Ⅱ. 청구변경에 해당 여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>청구취지의 변경</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">청구취지의 변경은 원칙적으로 청구의 변경 — 다만 判例: 소장에서 심판을 구하는 대상이 불분명한 경우 청구취지를 보충·정정하는 것은 청구의 변경에 해당하지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>청구의 확장</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 청구의 확장에는 ⅰ) 수량·금액만을 증가시키는 양적 확장 ⅱ) 상환이행청구를 무조건 이행청구로 바꾸는 질적 확장이 있으며, 청구의 확장은 모두 청구의 추가적 변경으로 봄 ② (★) 양적 확장에서 일부청구의 경우 ⅰ) 명시적 일부청구를 전부청구로 확장하는 것은 소송물이 다르므로 청구의 추가적 변경 ⅱ) 묵시적 일부청구에서 잔부청구로 확장하는 것은 소송물 변동이 없고 이행명령의 상한 변동에 불과하므로 청구변경이 아님<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>청구의 감축(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">청구의 감축이 있는 경우 우선 원고의 의사에 따르되, 그 의사가 불분명한 경우 判例는 원고에게 유리하게 소의 일부취하로 봄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>청구원인의 변경</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例(<span class=\"cs-u\"><strong>구소송물이론</strong></span>)에 의하면 청구원인의 권리·법률관계의 변경을 청구의 변경으로 봄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>공격방법의 변경</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">ⅰ) 말소등기청구에서 말소원인의 변경(원인무효사유를 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§103</strong></span></span>에서 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§108</strong></span></span>로 변경) ⅱ) 부당이득청구에서 법률상 원인 없는 사유의 변경(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§108</strong></span></span> 무효에서 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§109</strong></span></span> 취소로 변경) ⅲ) 사해행위취소청구에서 채권자의 피보전채권 변경(대여금채권→매매대금채권) ⅳ) 계약상 청구를 하면서 유권대리를 표현대리로 변경하는 경우 등은 1개 소송물을 이유 있게 하는 공격방어방법을 바꾸는 것으로 청구변경이 아니라 공격방어방법의 변경에 불과<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 청구변경의 형태와 성질</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>교환적 변경(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 교환적 변경이란 '구청구에 갈음하여 신청구를 제기하는 경우'로, 법적성질에 관해 判例는 구소취하와 신소제기의 결합으로 보는 <span class=\"cs-u\"><strong>결합설</strong></span> ② (피고 동의 불요) 判例: 교환적 변경의 경우 피고 동의가 없어도 '청구기초의 동일성'에 영향이 없으므로 구청구 취하의 효력이 생김(<span class=\"cs-u\"><strong>동의불요설</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>추가적 변경</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">추가적 변경이란 '구청구를 유지하면서 새로운 청구를 추가하는 경우' — 법적성질에 대해 判例는 '소제기와 변론의 병합의 결합'으로 보는 <span class=\"cs-u\"><strong>결합설</strong></span> — 단순병합·선택적 병합·예비적 병합 형태로 소의 추가적 변경이 행해짐</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>변경형태가 불분명한 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">청구변경의 내용이 불명한 때 判例는 변경에 의하여 신청구가 부적법한 경우까지 구청구가 취하되는 교환적 변경이라 할 수는 없다고 하여 추가적 변경으로 봄</div><div class=\"cs-h\">Ⅳ. 적법요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(1) <strong>요건 검토</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">청구변경이 적법하려면 ① 동종절차에 의하여 심리될 수 있을 것 ② 공통관할이 있을 것 ③ 사실심에 계속되고 변론종결 전일 것 ④ 청구기초의 동일성이 있을 것 ⑤ 소송절차를 현저히 지연시키지 않을 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">(2) <strong>항소심에서 청구변경(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">1) 항소심에서 교환적 변경과 재소금지(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 항소심에서의 교환적 변경은 구청구에 대해 본안에 대한 종국판결 후의 소취하가 되어, 그 뒤 소의 변경으로 다시 본래의 구청구를 되살리면 재소금지의 적용을 받아 부적법[선택 '14, '20]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">2) 항소심에서 교환적 변경의 경우 항소심 판결(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">항소심에서 청구가 교환적으로 변경된 경우 구소취하·신소제기의 실질을 가지므로 신청구에 대해 항소심은 제1심으로 심판 → ① '원고의 청구를 인용/기각한다'는 주문을 표시해야 하고 ② '항소를 인용/기각한다'는 주문을 표시해서는 안 됨 ③ 항소심에서 청구가 교환적 변경된 경우 항소각하판결을 할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">3) 항소심에서 교환적 변경과 항소취하(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 제1심판결은 교환적 변경에 의한 소취하로 실효되고 항소심 심판대상은 신청구로 새로운 소송으로 바뀌므로, 그 뒤 항소취하를 해도 항소취하는 대상이 없어 효력이 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">4) 항소심에서 반소변경</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">제1심에서 적법하게 반소를 제기했던 당사자가 항소심에서 반소를 교환적으로 변경하는 경우, 변경된 청구와 종전 청구가 실질적 쟁점이 동일하여 청구의 기초에 변경이 없으면 반소변경도 허용</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">5) 환송심에서 교환적 변경(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 환송심 절차는 환송 전 항소심의 속행이므로 당사자는 새로운 사실·증거 제출은 물론 소의 변경도 할 수 있음 ② 항소심에서의 부당이득반환청구와 환송심에서 교환적 변경된 파산채권확정청구는 실질적으로 목적이 동일하고 실체법상 법적 근거·성질이 동일하며 다만 청구취지만 이행소송에서 확인소송으로 변경한 것으로 양자의 소송물은 실질적으로 동일 → 환송 전 항소심판결 중 초과 부분이 청구기각으로 확정되었으므로 실질적으로 동일한 소송물인 파산채권확정청구에 대해서도 청구기각해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">6) 부대항소(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">제1심에서 전부 승소한 원고가 피고 항소에 편승하여 항소심에서 청구를 변경한 것이 적법한지 — 判例: 원고가 전부 승소하여 항소하지 않고 피고만 항소한 사건에서 청구취지를 확장·변경하여 피고에게 불리하게 된 경우 그 한도에서 '부대항소'를 한 취지로 봄</div><div class=\"cs-h\">Ⅴ. 심판</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소변경의 부적법</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 소의 변경인지 여부와 소 변경의 적법 여부는 법원의 직권조사사항 ② 소변경 신청이 부적법한 경우 법원은 소변경을 허용하지 않는다는 불허결정을 해야 함 ③ 判例: 불허결정은 중간적 재판이어서 독립하여 항고할 수 없고 종국판결에 대한 상소로써만 다툴 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소변경의 적법과 신청구의 심판</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소변경이 적법하다고 인정할 때에는 법원은 따로 소변경을 허가한다는 재판은 요하지 않고 신청구에 대해 심판해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>청구의 변경을 간과한 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>교환적 변경의 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 교환적 변경을 간과하여 신청구를 재판함이 없이 구청구만 판결한 때에는 이미 소 취하된 구청구에 대해 판결한 것이어서, 상급심은 구청구에 대해 소송종료선언을 하고, 누락된 신청구는 원심에 계속 중이므로 원심법원에서 추가판결을 해야 함[선택 '14]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>추가적 변경의 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 추가적 변경으로서 단순병합의 경우 구청구에 대해서만 판결하고 신청구를 판단하지 않은 경우 '재판의 누락'이 되어 신청구는 여전히 원심법원에 소송계속 중이므로 원심법원은 추가판결을 해야 하며, 항소심에서는 구청구에 대한 판단의 당부만 심판 ② 추가적 변경으로서 선택적·예비적 병합의 경우 원심법원이 구청구만 판결하고 신청구를 판단하지 않은 경우 전부판결로서 판단누락에 준하는 위법한 판결이 되므로, 이에 대해 항소하면 전부 이심·전부 심판대상이 되어 항소심은 전부에 대해 판단</div>", ["★★"], 1, "mp_6"], ["민소047", "중간확인의 소", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">중간확인의 소란 '본소송 계속 중 본소 청구의 판단에 전제가 되는 선결적 관계에 있는 법률관계의 존부에 기판력이 생기는 판단을 받기 위하여 추가적으로 제기하는 소'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§264</strong></span></span>)</div><div class=\"cs-h\">Ⅱ. 요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① 중간확인의 소는 ⅰ) 동종의 소송절차일 것 ⅱ) 공통의 관할권일 것 ⅲ) 사실심에 계속 중일 것 ⅳ) 다툼 있는 선결적 법률관계의 확인을 구할 것을 요함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">② (★) 원본채권의 중간확인의 소 등과 같이 선결관계가 본소에 대해 언제까지 존속해야 하는지 문제 — 判例: 재심사유가 인정되지 않아 재심청구를 기각하는 경우 재심절차에서 제기한 중간확인의 소는 각하해야 한다고 하여, 현실적으로 그 중간확인의 소의 판단이 본소송을 좌우할 선결관계에 있어야 한다고 보는 <span class=\"cs-u\"><strong>현실설</strong></span>(본소 청구가 취하·각하·기각될 경우 중간확인의 소는 현실적으로 선결적 관계에 서지 않게 되어 부적법 각하 → 본소의 계속은 중간확인의 소의 제기요건이자 존속요건) — 중간확인의 소를 각하할 경우에도 확인의 소로서의 별도의 확인의 이익이 인정되면 독립의 소로 심리</div>", ["★"], 1, "mp_6"], ["민소048", "반소", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">반소란 '소송계속 중 피고가 본소의 소송절차를 이용하여 원고에 대하여 제기하는 소'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§269</strong></span></span>) — 반소는 본소피고가 제기하는 소송 중의 소로서 청구의 추가적 병합 — 본소원고는 반소피고로, 본소피고는 반소원고로 됨</div><div class=\"cs-h\">Ⅱ. 반소의 법적성질</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>독립의 소 - 반소의 이익(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">반소는 피고의 방어방법과 달리 피고가 제기하는 독립한 소 → 본소의 방어방법(본소 청구기각) 이상의 적극적 내용이 포함되어야 하며, 그렇지 않으면 반소이익이 없어 부적법 각하 — ① 소유권존재확인청구의 본소에 대해 그 부존재확인을 구하는 것 ② 채권에 기한 이행의 본소에 대해 동일 채권에 관한 채무부존재확인의 반소는 본소의 방어방법 이상의 적극적 내용이 없어 반소이익 없어 부적법<span class=\"cs-x\"><strong>(X)</strong></span> / 그러나 ③ 甲의 소유권부존재확인 본소에 대해 乙의 적극적 소유권존재확인 반소 ④ 원고의 채무부존재확인 본소에 대해 피고의 채무이행 반소청구는 본소의 방어방법 이상의 적극적 내용이 포함되어 반소이익 있어 적법<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">⑤ (★) 判例: 적법하게 제기된 본소가 후에 상대방이 제기한 반소로 인하여 소송요건에 흠결이 생겨 다시 부적법하게 되는 것은 아니므로 본소가 부적법하게 된다고 볼 수 없고, 원고가 당초 추구한 기판력을 취득할 수 없는 사태가 발생할 수 있는 점을 고려하면 반소가 제기되었다는 사정만으로 본소청구에 대한 확인의 이익이 소멸한다고 볼 수 없음[선택 '12, '15, '16, '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">⑥ (★) 判例: 소송서류 등이 공시송달로 송달되어 확정된 제1심판결문을 기초로 등기권리자가 소유권이전등기를 마쳤으나 이후 제기된 추후보완항소에서 제1심판결이 취소되고 등기권리자 청구가 기각되었다면, 등기의무자는 이미 등기명의를 이전받은 등기권리자를 상대로 추후보완항소 절차에서 반소를 제기하여 소유권이전등기의 말소등기를 구할 수 있음(반소이익 인정)[사례 '25]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>반소의 당사자 - 본소 피고(반소 원고)가 본소 원고(반소 피고)를 상대로 한 소</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 피고가 원고 이외의 제3자를 추가하여 반소피고로 하는 반소는 원칙적으로 불허<span class=\"cs-x\"><strong>(X)</strong></span> ② (★) 다만 判例: 피고가 제기하려는 반소가 필수적 공동소송이 될 때에는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span>의 필수적 공동소송인 추가의 요건을 갖추면 허용될 수 있음</div><div class=\"cs-h\">Ⅲ. 반소의 모습</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>단순반소</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">단순반소란 '본소청구의 인용·기각 여부와 관계없이 반소청구에 대해 심판을 구하는 반소'</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>예비적 반소(★)</strong><strong>[사례 '24, '25]</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 예비적 반소는 본소청구가 인용될 때를 대비하여 기각·각하될 것을 해제조건으로 반소청구에 대해 심판을 구하는 조건부 반소 ② 본소청구가 각하·취하되면 반소청구는 소멸되며, 본소청구가 기각되면 반소청구에 아무런 판단을 요하지 않음(그럼에도 반소청구에 대해 판결하면 효력 없음) ③ 이 경우 제1심에서 피고는 전부승소하였으므로 그 판결에 대한 피고의 항소는 항소이익이 없어 부적법 ④ (★) 判例: 甲이 乙 상대 매매에 기한 소유권이전등기청구를 제기하자 乙이 본소청구가 인용될 것을 대비하여 매매대금 지급을 구하는 반소를 제기하였고, 제1심이 소의 이익이 없음을 이유로 본소·반소를 모두 각하하였고 제1심판결에 원고만 항소한 사안에서, 예비적 반소도 본소청구와 함께 확정이 차단되고 이심되며 모두 심판대상이 됨(예비적 반소는 본소청구가 인용될 때를 대비하여 심판을 신청하는 것이므로, 항소심에서 제1심에서 각하한 본소가 인용되는 것으로 판단될 때에는 예비적 반소가 심판대상이 될 수 있어야 하기 때문)[선택 '25]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>재반소</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 본소 이혼청구를 기각하고 반소 이혼청구를 인용하는 경우 본소 이혼청구에 병합된 재산분할청구는 피고의 반소청구에 대한 재반소의 실질을 가진다고 보아 재반소 허용</div><div class=\"cs-h\">Ⅳ. 반소의 요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">반소가 적법하려면 ① 반소요건으로 ⅰ) 동종절차에 의할 것 ⅱ) 공통관할이 있을 것 ⅲ) 본소 사실심 변론종결 전일 것 ⅳ) 본소의 청구 또는 방어방법과 상호관련이 있을 것 ⅴ) 본소를 현저히 지연시키지 않을 것 ⅵ) 반소이익이 있을 것을 요하고 ② 소송요건을 갖추어야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>본소가 사실심에 계속 중이고 변론종결 전일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>본소의 소송계속</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 본소의 소송계속은 '단순반소'의 제기요건일 뿐 존속요건은 아니므로 단순반소가 적법하게 제기된 뒤에는 본소가 각하·취하되어 소멸해도 단순반소는 존속 ② 다만 '예비적 반소'는 본소의 기각·각하를 해제조건으로 하는 조건부 반소이므로 본소가 기각·각하·취하되어 소멸하면 예비적 반소도 소멸(본소의 계속이 예비적 반소의 제기요건이자 존속요건)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>항소심 반소(★)</strong><strong>[사례 '25 / 사시 사례]</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">항소심 반소는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§412①</strong></span></span>에 의해 ① 원고의 동의를 받거나 원고가 반소의 본안에 관하여 이의 없이 변론한 경우 ② 원고의 동의나 이의 없는 변론이 없더라도 원고의 심급의 이익을 해할 우려가 없는 경우(ⅰ) 중간확인의 반소 ⅱ) 본소와 청구원인을 같이 하는 반소 ⅲ) 제1심에서 충분히 심리한 쟁점과 관련된 반소 ⅳ) 항소심에서 예비적 반소)에만 허용 — ③ 判例: 항소심에서 원고가 '반소기각의 답변'을 한 것만으로는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§412②</strong></span></span>의 '이의 없이 반소의 본안에 관하여 변론을 한 때'에 해당한다고 볼 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> ④ 判例: ⅰ) '원고의 심급의 이익을 해할 우려가 없는 경우'란 반소청구의 기초를 이루는 실질적 쟁점이 제1심에서 본소의 청구원인 또는 방어방법과 관련하여 충분히 심리되어 상대방에게 제1심에서의 심급의 이익을 잃게 할 염려가 없는 경우 ⅱ) 법정지상권설정등기의 이행을 구하는 항소심 반소는 제1심에서 충분히 심리한 관습상 법정지상권 항변과 관련된 반소로서 '제1심에서 이미 충분히 심리한 쟁점과 관련된 반소'에 해당하여 원고의 심급의 이익을 해할 우려가 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>본소와 반소 사이에 상호관련성이 있을 것(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>상호관련성의 의의와 성질</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 반소청구는 본소의 청구 또는 본소의 방어방법과 서로 관련성이 있어야 함 ② 임의규정이므로 원고가 동의하거나 이의 없이 응소한 경우 상호관련성이 없어도 이의권의 상실에 해당하여 반소는 적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>본소청구와 상호관련성</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 반소청구가 본소청구와 '동일한 법률관계의 형성을 목적'으로 하는 경우 ② 본소와 반소의 '청구원인이 동일'할 때 ③ 청구원인이 동일하지 않더라도 그 '대상·발생원인의 주된 부분'이 법률상·사실상 공통된 경우 상호관련성 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>본소의 방어방법과의 상호관련성(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">반소청구가 본소의 항변사유와 대상이나 발생원인에서 공통성이 있어야 함 → ① 방어방법이 현실적으로 제출되었어야 하고 ② 법률상 허용되어야 함 → ⅰ) 실기한 공격방어방법(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§149</strong></span></span>)으로 각하된 항변에 바탕을 둔 반소 ⅱ) 상계금지채권(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§496</strong></span></span>~<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§498</strong></span></span>)에 기한 피고의 상계항변에 바탕을 둔 반소는 부적법<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>상계초과채권(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">원고의 대여금 본소청구에 대해 피고가 상계항변을 제출하면서 반소로 그 상계초과채권의 지급을 청구하는 반소를 제기한 경우 상호관련성 인정 (★ 상계항변의 경우 ⅰ) 자동채권을 초과하는 부분을 반소로 제기하는 것은 허용되나 ⅱ) 수동채권과 자동채권이 동액인 경우 반소는 본소청구기각을 구하는 것에 불과하여 반소이익 없음)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(5) <strong>점유의 본소와 본권의 반소(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 문제점</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§208②</strong></span></span>에 의해 점유권에 기인한 소는 본권에 관한 이유로 재판하지 못하므로 본권을 항변으로 제출할 수 없는바, 점유회수의 본소에 대하여 본권에 기한 반소제기까지 제기할 수 없는지 문제</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 판례의 입장</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ① 점유권에 기한 본소에 대해 본권자가 본소청구 인용에 대비하여 본권에 기한 예비적 반소를 제기하고 양 청구가 모두 이유 있는 경우, 법원은 점유권에 기한 본소와 본권에 기한 예비적 반소를 모두 인용해야 하고 점유권에 기한 본소를 본권에 관한 이유로 배척할 수 없다고 보아 반소제기 허용 ② 이 법리는 점유를 침탈당한 자가 점유회수의 소를 제기하고 본권자가 그 점유회수의 소가 인용될 것에 대비하여 본권에 기초한 장래이행의 소로서 별소를 제기한 경우에도 동일 적용</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 본소와 반소의 집행</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ① 점유회수의 본소에 대해 본권자가 소유권에 기한 반소를 제기하여 본소와 예비적 반소가 모두 인용·확정되면, 점유자가 본소 확정판결로 집행문을 부여받아 강제집행으로 물건의 점유를 회복할 수 있음 ② 본권자의 소유권에 기한 반소청구는 본소의 의무실현을 정지조건으로 하므로, 본권자는 본소집행 후 집행문을 부여받아 반소 확정판결에 따른 강제집행으로 물건의 점유를 회복할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 본소의 집행에 대한 청구이의의 소 제기 가부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">다만 점유자의 점유회수 집행이 ① 아무런 실익이 없거나 ② 점유회수 집행을 수인하도록 하는 것이 명백히 정의에 반하여 용인할 수 없는 경우 ③ 장기간 강제집행하지 않음으로써 본권자가 강제집행할 수 없게 된다면 ④ 본권자는 본소 확정판결에 대한 청구이의의 소를 통해 강제집행을 저지할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(6) <strong>채권자취소권과 반소와의 관계(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 원고가 매매계약에 기해 소유권을 취득하였음을 전제로 피고 상대 인도청구를 할 때, 피고는 원고의 소유권 취득의 원인이 된 법률행위가 사해행위로 취소되어야 한다고 다투면서 동시에 반소로써 그 법률행위가 사해행위임을 이유로 법률행위의 취소와 원상회복으로 원고의 소유권이전등기 말소절차 등의 이행을 구하는 것도 가능 ② 이 경우 사해행위 취소 여부는 반소의 청구원인임과 동시에 본소 청구에 대한 방어방법이자 본소 청구 인용 여부의 선결문제가 될 수 있음 ③ 법원이 반소청구가 이유 있다고 판단하여 사해행위 취소·원상회복을 명하는 판결을 선고하는 경우, 비록 반소청구에 대한 판결이 확정되지 않았더라도 원고의 소유권 취득의 원인이 된 법률행위가 취소되었음을 전제로 원고의 본소청구를 심리·판단할 수 있음 ④ 그때에는 반소 사해행위취소 판결의 확정을 기다리지 않고 반소 사해행위취소 판결을 이유로 원고의 본소청구를 기각할 수 있음<span class=\"cs-fact-tag\"><strong>[법전협 '22]</strong></span></div><div class=\"cs-h\">Ⅴ. 반소의 절차와 심판</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>반소요건과 일반소송요건의 조사</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">반소가 제기되면 반소요건과 소송요건의 존부를 조사하고 각 요건이 구비되면 본안심리 진행 → ① '반소요건의 흠'이 있는 경우 判例는 부적법한 반소로서 반소를 각하해야 함 ② 반소요건을 갖추었어도 '소송요건의 흠'이 있는 경우에는 판결로써 '반소를 각하'해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>반소의 취하</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 반소의 취하에도 원고의 동의가 필요 — 그러나 본소가 취하된 때에는 원고 동의 없이 반소를 취하할 수 있음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§271</strong></span></span>) ② (★) 判例: <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§271</strong></span></span>은 원고가 본소를 취하해 놓고 그로 인해 유발된 반소만의 유지를 피고에게 강요하는 것은 공평치 못하다는 취지의 규정이므로, 본소가 원고의 의사와 관계없이 부적법하다 하여 각하됨으로써 종료된 경우에까지 유추적용할 수 없다고 보아, 본소가 각하된 때에는 원고의 동의가 있어야 반소를 취하할 수 있음[선택 '25]</div>", ["★★★★"], 1, "mp_6"], ["민소049", "공동소송", "<div class=\"cs-li cs-bul\" style=\"margin-left:0px\">□ 원문 도표전용·PDF 대조 필요: 원본 교재(제211~212면)는 본문 서술 없이 '공동소송의 요건 도해 + 통상공동소송·필수적 공동소송의 형태·심판방법 비교표'로만 구성되어 OCR로 복원되지 않음. 아래는 표준법리로 최소 보정한 요건 골격이며, 통상공동소송의 심판방법은 논점 050, 필수적 공동소송은 논점 051에 상세 서술됨.</div><div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">공동소송이란 '1개의 소송절차에 여러 명의 원고 또는 피고가 관여하는 소송'(소의 주관적 병합)</div><div class=\"cs-h\">Ⅱ. 공동소송의 요건(<span class=\"cs-blue\"><span class=\"cs-u\">§65</span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>주관적 요건(</strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§65</strong></span></span><strong>)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">ⅰ) (권리·의무의 공통) 소송목적이 되는 권리·의무가 여러 사람에게 공통되는 경우 ⅱ) (동일한 사실상·법률상 원인) 소송목적이 되는 권리·의무가 같은 사실상·법률상 원인으로 생긴 경우(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§65</strong></span></span> 전문) ⅲ) (같은 종류의 원인) 소송목적이 되는 권리·의무가 같은 종류의 것이고 사실상·법률상 같은 종류의 원인으로 생긴 경우(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§65</strong></span></span> 후문)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>객관적 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 같은 종류의 소송절차에 의할 것 ② 공통의 관할권이 있을 것 ③ 병합이 법률상 금지되지 않을 것</div><div class=\"cs-h\">Ⅲ. 공동소송의 형태</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>통상의 공동소송</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공동소송인 사이에 합일확정이 필수적이 아닌 공동소송 — 심판방법은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§66</strong></span></span> 공동소송인 독립의 원칙(→ 논점 050)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>필수적 공동소송</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공동소송인 사이에 합일확정을 필수적으로 요하는 공동소송(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67</strong></span></span>) — 고유필수적·유사필수적으로 구분(→ 논점 051)</div>", ["★★★"], 1, "mp_6"], ["민소050", "통상의 공동소송", "<div class=\"cs-h\">Ⅰ. 의의와 공동소송의 형태</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① 통상공동소송이란 '공동소송인 사이에 합일확정이 필수적이 아닌 공동소송' ② 심판방법은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§66</strong></span></span>의 '공동소송인 독립의 원칙'에 의함('통상공동소송에서 각 공동소송인은 다른 공동소송인에 의한 제한을 받지 않고 각자 독립하여 소송수행을 할 수 있는 것')</div><div class=\"cs-h\">Ⅱ. 심판방법 - <span class=\"cs-blue\"><span class=\"cs-u\">§66</span></span> - 공동소송인 독립의 원칙[사례 '14, '18, '22]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송요건의 개별적 조사</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소송요건의 존부는 각 공동소송인마다 개별적으로 심사</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송자료의 독립</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 공동소송인 중 1인의 소송행위는 유리·불리를 막론하고 원칙적으로 다른 공동소송인에 영향을 미치지 않음 → 각 공동소송인은 공격방어방법(주장·증거)을 개별적으로 제출할 수 있고 주장이 서로 달라도 됨 ② 통상공동소송에서 공동소송인 중 1인의 자백은 그 자백을 한 자에게만 효력이 미치고 다른 공동소송인에게는 영향이 없으며 변론 전체의 취지로 참작할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송진행의 독립</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공동소송인 1인에 대한 사항은 다른 공동소송인에게 영향 없음(1인에 대한 중단·중지 사유는 1인에게만 효과, 기일해태의 효과인 쌍불취하·진술간주·자백간주도 불출석한 공동소송인에게만 효과, 상소기간 진행도 개별적)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>재판의 독립</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공동소송인 간 재판통일이 필요 없으며 판결내용이 구구하게 되어도 무방</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>상소의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 전부판결에 전부상소한 경우 전부 이심되며 전부 심판대상 ② (★) 전부판결에 일부상소한 경우 ⅰ) 공동소송인 독립의 원칙이 적용되어 상소불가분의 원칙이 적용되지 않아 일부만 이심되며 ⅱ) 불이익변경금지로 상소한 청구만 일부 심판대상 ③ 통상공동소송은 일부판결이 허용되므로 일부판결한 경우 판결 안 한 부분은 재판의 누락으로 제1심에 계속 중이며 추가판결로 구제 → 판결 안 한 부분에 항소하면 항소대상적격이 없어 부적법하여 항소각하 ④ 判例: 통상공동소송에서 공동당사자 일부만 상고를 제기한 때에는(일부만 이심되고 다른 공동소송인은 분리확정되므로) 피상고인은 상고인인 공동소송인 이외의 다른 공동소송인을 상대방으로 하거나 상대방으로 보태어 부대상고를 제기할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span>[선택 '17, '23]</div><div class=\"cs-h\">Ⅲ. 공동소송인 독립의 원칙의 수정</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>수정의 원리</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공동소송인 독립의 원칙을 일관하면 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§65</strong></span></span> 전문에 해당하는 공동소송의 경우 재판의 모순·저촉이 발생할 우려가 있어 재판의 통일을 위한 수정방안 인정 여부가 문제</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>주장공통의 원칙</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 주장공통의 원칙은 ⅰ) '대립당사자 사이'에서만 적용되고 ⅱ) 통상공동소송은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§66</strong></span></span> '공동소송인 독립의 원칙'이 적용되어 인정할 수 없으며 ⅲ) 이를 인정하면 변론주의의 주장책임을 부정하는 결과가 되므로 주장공통의 원칙 부정<span class=\"cs-x\"><strong>(X)</strong></span>[선택 '12, '14, '17, '18]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>증거공통의 원칙</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 증거공통의 원칙은 ⅰ) '대립당사자' 사이에서만 적용되고 ⅱ) 통상공동소송의 경우 '공동소송인 독립의 원칙'상 인정할 수 없으며 ⅲ) 이를 인정하면 변론주의의 '증거제출책임'에 반하는 결과가 되므로 증거공통의 원칙 부정<span class=\"cs-x\"><strong>(X)</strong></span></div>", ["★★★★"], 1, "mp_6"], ["민소051", "필수적 공동소송", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">공동소송인 사이에 합일확정을 필수적으로 요하는 공동소송(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67</strong></span></span>)</div><div class=\"cs-h\">Ⅱ. 고유필수적 공동소송</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의와 공동소송의 형태</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">고유필수적 공동소송이란 '각 공동소송인 사이에 합일확정의 필요가 있고 공동소송이 법률상 강제되는 공동소송' — '실체법상의 관리처분권이 수인에게 공동으로 귀속'하는 경우이므로 '실체법상의 이유에 의한 필수적 공동소송'</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>형성권의 공동귀속</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>공유물분할청구(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 공유물분할청구의 소는 실체법상 공유물분할청구권이라는 형성권이 수인에게 귀속되는 경우로, 공유자 전부를 공동피고로 하여야 하는 고유필수적 공동소송[선택 '15, '17, '21, '25] ② 공유물분할 소송계속 중 변론종결일 전에 공유자 중 1인 甲의 공유지분 일부가 乙 등에 이전된 사안에서, 변론종결시까지 일부 지분권을 이전받은 자가 소송당사자가 되지 못하는 소송은 전부가 부적법[선택 '18, '23]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>경계확정의 소(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 공유토지의 경계확정청구는 공유자 모두에게 귀속된 공유물의 처분·변경권에 관한 중요사항이므로(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§264</strong></span></span>) 공유자 전원이 나서야 하는 고유필수적 공동소송</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>매매예약완결권의 행사로 가등기에 기한 본등기청구의 소(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 종래판례: 수인의 채권자가 매매예약완결권을 행사하여 가등기에 기한 본등기청구를 하는 경우 반드시 복수채권자 전원이 하여야 하는 고유필수적 공동소송이라는 입장 ② 변경판례: ⅰ) 수인의 채권자가 공동으로 매매예약완결권을 가지는 관계인지(전원이 공동으로 해야 하는 고유필수적 공동소송) ⅱ) 채권자 각자의 지분별로 별개의 독립적 매매예약완결권을 가지는 관계인지(각자 단독으로 이전등기를 할 수 있어 통상공동소송)는 매매예약의 내용에 따라 판단[사례 '16]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>회사관계소송</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 判例: 청산인 해임의 소는 법률관계의 당사자인 회사와 청산인을 공동피고로 해야 하는 고유필수적 공동소송 ② 判例: 주주총회결의 부존재·무효 확인의 소는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>상법§380</strong></span></span>에 의해 준용되는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>상법§190</strong></span></span> 본문에 따라 청구인용판결이 제3자에 대하여도 효력이 있어 공동소송인 사이에 소송법상 합일확정의 필요성이 인정되므로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67</strong></span></span>이 적용되는 필수적 공동소송에 해당</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>공유관계소송(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>원칙 - 통상의 공동소송</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 공유자는 각자 지분을 처분할 수 있고(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§263</strong></span></span>) ② 보존행위는 각자 할 수 있다는 규정(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§265</strong></span></span>단서)을 근거로 공유관계소송을 원칙적으로 통상의 공동소송으로 봄[선택 '12, '14, '16, '21, '23, '24, '25]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>예외 - 고유필수적 공동소송 - 5개</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 공유물 전체에 대한 소유권확인청구, 공동상속인의 다른 공동상속인 상대 상속재산확인의 소 ② 2인이 동업약정에 따라 공동매수한 경우 소유권이전등기청구권을 준합유하는 관계로 고유필수적 공동소송 ③ 2인이 동업약정에 따라 공동예금하였다면 예금청구권을 준합유하는 관계로 고유필수적 공동소송 ④ 공유물분할청구 ⑤ 공유물 경계확정청구는 고유필수적 공동소송[선택 '23, '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>합유관계소송(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>능동소송의 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (합유물의 처분·변경)은 합유자 전원의 동의를 요하고 그 지분의 처분도 전원의 동의를 요하므로(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§272</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§273</strong></span></span>) 실체법상 관리처분권이 합유자 전원에 공동귀속되어 '고유필수적 공동소송' ② (보존행위) 다만 합유물에 관하여 경료된 원인무효의 소유권이전등기 말소를 구하는 소송은 합유물에 관한 보존행위로서 합유자 각자가 할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>수동소송의 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (조합원의 개인적 책임) 判例: 조합채권자가 각 조합원의 개인적 책임에 기하여 채권을 행사하는 경우 통상의 공동소송 ② (조합재산의 공동책임) 判例: 조합재산에 관하여 매매를 원인으로 한 소유권이전등기절차 이행을 구하는 소는 조합원인 피고들 전부를 공동피고로 하여야 하는 고유필수적 공동소송 — 判例: ⅰ) 조합재산은 합유에 속하므로 조합재산에 속하는 채권에 관한 소송은 합유물에 관한 소송으로서 조합원들이 공동으로 제기해야 하는 고유필수적 공동소송 ⅱ) 동업약정에 따라 동업자 공동으로 토지를 매수하였다면 동업자들은 소유권이전등기청구권을 준합유하는 관계로 고유필수적 공동소송이어서 매매계약에 기해 이전등기 이행을 구하는 소를 제기하려면 동업자 전원이 하지 않으면 안 됨[선택 '15, '25] ⅲ) 피고의 합유로 소유권이전등기가 마쳐진 부동산에 대하여 원고의 명의신탁해지로 인한 소유권이전등기이행청구 소송은 합유재산에 관한 소송으로서 고유필수적 공동소송[선택 '17, '21, '24] ⅳ) (★) 조합원이 조합재산을 횡령하여 손해를 입은 주체는 조합재산을 상실한 조합이므로 조합원으로서는 조합관계를 벗어난 개인의 지위에서 손해배상을 구할 수 없고, 그 손해배상채권은 조합원 전원의 준합유에 속하므로 원칙적으로 전 조합원이 고유필수적 공동소송에 의하여만 구할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>총유관계소송(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">비법인사단의 재산관계에 관한 소송은 ① '사단 자체의 명의'로 소송하거나 ② 구성원 '전원'이 당사자로 나서는 고유필수적 공동소송으로 할 수 있으며 ③ 총유물의 '보존행위'에 해당하는 소송도 사단 '명의'로 제소하거나 구성원 '전원'이 당사자가 되어 고유필수적 공동소송 형태로 제소해야 하고 ④ 총유관계소송에서는 구성원들이 개별적으로 소송할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 유사필수적 공동소송</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">유사필수적 공동소송이란 '소송공동이 강제되지 않으나 합일확정의 필요가 있는 공동소송' — 소송법상 판결의 효력이 미치는 자들끼리의 공동소송으로 '소송법상의 이유에 의한 필수적 공동소송'</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판결의 기판력·형성력이 직접 제3자에게 확장되는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 여러 사람이 제기하는 회사설립 무효·취소의 소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>상법§184</strong></span></span>) ② 여러 사람이 제기하는 회사합병무효의 소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>상법§236</strong></span></span>) ③ 주주총회결의 취소·부존재확인의 소(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>상법§376</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§380</strong></span></span>) ④ 복수 채권자에 의한 채권자대위소송 ⑤ 여러 주주에 의한 회사대표소송(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>상법§403</strong></span></span>) 등</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>수인의 채권자들의 대위소송(★) - 유사필수적 공동소송</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 채무자가 채권자대위소송이 제기된 것을 알았을 경우 확정판결의 효력은 채무자에게도 미치므로 채권자대위권에 기하여 공동으로 채무자의 권리를 행사하는 채권자들은 유사필수적 공동소송관계 → ① 대위소송 계속을 채무자가 알았으면 수인의 채권자들도 기판력을 받아 유사필수적 공동소송 ② 채무자가 몰랐으면 통상의 공동소송[사례 '23 / 변리사 사례]</div><div class=\"cs-h\">Ⅳ. 이론상 합일확정소송(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① 이론상 합일확정소송이란 '법률적으로 합일확정의 필요가 없으나 이론적으로 합일확정이 요청되는 공동소송' ② 判例: 수개의 청구가 공통으로 제기되었다 하여 본래부터 자주적 해결권이 다른 공동소송인들 때문에 제한을 받는다는 논리는 생각할 수 없다고 하여 통상공동소송으로 봄 ③ 判例: 순차 경료된 공유등기의 말소청구소송은 필수적 공동소송이 아니라 통상공동소송이며, 통상공동소송에서는 공동당사자들 상호간 공격방어방법의 차이에 따라 모순되는 결론이 발생할 수 있고 이는 변론주의 하에서 부득이한 일로서 판결의 이유모순이라 할 수 없음</div><div class=\"cs-h\">Ⅴ. 심판방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>연합관계</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">필수적 공동소송의 경우 공동소송인 간 '상호연합관계'이며 '합일확정판결'만 허용 → ① 소송자료의 통일 ② 소송진행의 통일 ③ 재판의 통일이 요청</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송요건의 조사와 누락된 고유필수적 공동소송인의 보정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>소송요건의 조사</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소송요건은 각 공동소송인별로 개별적으로 조사 — 공동소송인 중 1인에 소송요건 흠결이 있으면 ① 고유필수적 공동소송은 전부각하 ② 유사필수적 공동소송은 그 공동소송인만 일부각하</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>고유필수적 공동소송인의 당사자적격과 누락 시 보정방법(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 고유필수적 공동소송의 당사자적격</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">고유필수적 공동소송은 전원이 당사자가 되어야 당사자적격이 인정되므로 일부 누락시 당사자적격 흠결로 소는 부적법 각하</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 처음부터 누락된 경우 보정방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 별소제기와 변론의 병합 ② <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span> 필수적 공동소송인의 추가 ③ 공동소송참가(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§83</strong></span></span>) 등이 있으나, ①은 지나치게 우회적이어서 소송경제에 반하고 ③은 누락된 공동소송인 스스로 참가하지 않으면 실효성이 없으므로 ②의 방법이 가장 직접적·용이</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 소송계속 중 누락된 경우 보정방법 - 소송승계</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 공유물분할소송 계속 중 공유자 중 1인의 공유지분이 이전된 경우, 변론종결시까지 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§81</strong></span></span> 승계참가나 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§82</strong></span></span> 인수승계 등으로 지분권을 이전받은 자가 당사자가 되어야 하며 그렇지 못하였으므로 소송 전부가 부적법(소송승계로 보정 가능)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 제소 전 사망한 경우 보정방법 - 표시정정</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ① 공유물분할청구는 고유필수적 공동소송으로 1인에 소송요건 흠이 있으면 전 소송이 부적법 → 고유필수적 공동소송인 중 한 사람이 제소 전에 사망한 경우 사망자는 당사자능력이 없어 부적법하고 이 사건 소 전부는 당사자적격이 없어 부적법 ② 사망자를 피고로 표시하여 소를 제기한 경우 실질적 피고는 사망자의 상속인이므로 상속인으로 표시정정을 할 수 있음(표시정정으로 보정 가능)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송자료의 통일</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>공동소송인 중 한 사람의 소송행위가 다른 공동소송인에게 유리한 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">공동소송인 가운데 한 사람의 소송행위는 모두의 이익을 위하여서만 효력을 가짐(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67①</strong></span></span>) → ① 한 사람이 '출석'하면 전원이 출석한 것이 되어 기일 불출석의 효과(취하간주·진술간주·자백간주)가 생기지 않음 ② 상대방 주장사실을 '다투면'(주장·부인·항변·증거제출) 전원이 다툰 것 ③ 피고 중 한 명이라도 본안에 관하여 '응소'하면 전원이 응소한 것 ④ 답변서를 '제출'하면 전원이 제출한 것이 되어 무변론판결을 할 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>공동소송인 중 한 사람의 소송행위가 다른 공동소송인에게 불리한 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">불리한 행위인 '자백, 청구의 포기·인낙 또는 재판상 화해'는 공동소송인 전원이 함께 하여야 효력이 발생하며 한 사람이 하면 전원에게 효력 없음 → ① 고유필수적 공동소송에서는 '소의 일부취하'도 허용되지 않고 무효 ② 유사필수적 공동소송에서는 '일부취하'가 허용됨[사례 '23]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>상대방의 소송행위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">공동소송인 중 한 사람에 대한 상대방의 소송행위는 이익·불이익을 불문하고 전원에 대하여 효력이 생김(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67②</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송진행의 통일</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>기일의 진행</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 변론 등은 동일기일에 함께 하여야 하며 전부판결을 해야 하고, 판결의 모순·저촉 우려가 있으므로 일부판결을 할 수 없음 → 일부판결한 경우 전부판결로 취급하며 판단누락에 준하는 위법을 이유로 상소·재심으로 취소 가능 ② 공동소송인 중 한 사람에 대해 중단·중지 원인이 있는 경우 전원에게 중단·중지 효과 발생(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67③</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>판결에 대한 상소</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">상소기간은 각 공동소송인별로 개별 진행되나, 전원에 대한 상소기간이 만료되기까지는 당해 판결은 확정되지 않음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>전부판결에 일부 상소의 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 이심의 범위</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">전부판결에 대해 공동소송인 중 일부가 상소를 제기하면 상소불가분으로 전원에 대하여 확정차단되고 상급심에 전부 이심</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 상소하지 않은 당사자의 지위</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 문제점: 한 사람이 상소를 제기하면 전원이 상소심에 이심되는데 상소하지 않은 다른 공동소송인의 상소심에서의 지위가 문제</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 판례의 입장: 判例는 필수적 공동소송에서 상고하지 않은 피고를 단순히 '피고'라고만 표시하고 상고비용을 상고한 피고에게만 부담시킨다고 보아 <span class=\"cs-u\"><strong>단순한 항소심 당사자설</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">다) 단순한 항소심 당사자의 지위: 실제 상소를 제기한 공동소송인만이 ① 상소인지를 붙이고 ② 상소비용도 부담하며 ③ 상소취하도 할 수 있고 ④ 상소심 심판범위도 그에 의해 특정되며, '단순한 상소심 당사자'는 이를 할 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 심판의 범위</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67①</strong></span></span> 합일확정의 필요 때문에 '불이익변경금지원칙'의 적용이 배제되어 공동소송인 전부가 항소심 심판대상이 됨 → 상소심에서 패소하고도 상소하지 않은 당사자에게 유리하게 판결이 변경될 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>재판의 통일 - 일부판결 가부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공동소송인 사이에서 본안에 관한 합일확정판결만 허용되므로 공동소송인 전부에 대해 전부판결을 해야 하고 일부판결을 할 수 없음 → 일부판결한 경우 추가판결은 할 수 없고 전부판결로 취급하며 판단누락에 준하는 위법을 이유로 상소·재심으로 취소 가능</div>", ["★★★★"], 1, "mp_6"], ["민소052", "예비적·선택적 공동소송", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">'공동소송인 가운데 일부의 청구와 다른 공동소송인의 청구가 법률상 양립할 수 없거나(원고 측), 공동소송인 가운데 일부에 대한 청구와 다른 공동소송인에 대한 청구가 법률상 양립할 수 없는 경우(피고 측)에 동시에 심판을 구하는 공동소송'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70</strong></span></span>)</div><div class=\"cs-h\">Ⅱ. 예비적·선택적 공동소송의 형태(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>당사자를 기준으로 한 형태</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>피고를 예비적 공동소송인으로 하는 경우 - 수동형</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§758</strong></span></span> 공작물 하자로 인한 손해배상에 관하여 1차적 피고로 점유자·2차적 피고로 소유자에게 청구하는 경우 ② 유권대리를 이유로 1차적으로 본인을 피고로, 무권대리를 이유로 2차적으로 대리인에게 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§135</strong></span></span> 책임을 묻는 경우 등</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>원고가 예비적 공동소송인이 되는 경우 - 능동형</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1차적으로 채권양수인이 원고가 되어 채무자에게 청구하고, 채권양도가 무효가 될 때를 대비하여 2차적으로 양도인이 원고가 되어 청구하는 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>심판순서를 기준으로 한 형태</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 각 공동소송인 사이에 심판의 순서를 붙여 청구하는 예비적 공동소송 ② 순서를 붙이지 않고 택일적으로 인용될 것을 해제조건으로 다른 사람에 대한 심판을 구하는 선택적 공동소송</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>원시형과 후발형</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① (원시형) 소제기시부터 공동소송으로 제기하는 형태 ② (후발형)(★) 예비적·선택적으로 추가하는 형태 — <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70①</strong></span></span>에서 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span>을 준용하므로 제1심 변론종결시까지 추가 허용 ③ (복합형)(★) 주위적 피고에 대한 주위적·예비적 청구 중 주위적 청구 부분이 받아들여지지 않을 경우 그와 법률상 양립할 수 없는 관계에 있는 예비적 피고에 대한 청구를 받아들여 달라는 취지로, 주위적 피고에 대한 주위적·예비적 청구와 예비적 피고에 대한 청구를 결합하여 소를 제기하는 것도 가능 ④ (★) 判例: 원고 甲이 피고 乙에 대해 주위적으로 명의신탁약정 유효를 전제로 명의신탁 해지를 원인으로 한 소유권이전등기 이행을 구하고, 무효로 주위적 청구가 인용되지 않을 경우 예비적으로 乙에 대해 丙에게 소유권이전등기 말소등기를 이행할 것을 구하며, 동시에 丙에 대해 매매를 원인으로 한 소유권이전등기 이행을 구하는 경우 → 乙에 대한 주위적 청구와 丙에 대한 예비적 청구(주위적 청구 미인용시 丙에 대한 청구 인용)는 주관적·예비적 공동소송관계이고, 乙에 대한 예비적 청구와 丙에 대한 청구는 통상의 공동소송으로 심리·판단해야 함</div><div class=\"cs-h\">Ⅲ. 예비적 공동소송의 요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 공동소송의 요건을 갖출 것 ② 법률상 양립할 수 없는 경우일 것(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>공동소송의 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공동소송의 일종이므로 공동소송의 주관적 요건과 객관적 요건을 갖추어야 함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§65</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§253</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>청구의 법률상 양립불가능</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>법률상 양립불가능할 것(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 동일한 사실관계에 대한 법률적 평가를 달리하여 두 청구 중 어느 한 쪽에 대한 법률효과가 인정되면 다른 쪽에 대한 법률효과가 부정됨으로써 두 청구가 모두 인용될 수는 없는 관계에 있는 경우로 봄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>실체법적·소송법적 양립불가(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 법률상 양립할 수 없으면 '실체법상 양립할 수 없는 경우'뿐 아니라 '소송법상 양립할 수 없는 경우'도 포함[선택 '15, '18, '23]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>사실상 양립불가능한 경우 예비적 공동소송 허부(★)</strong><span class=\"cs-fact-tag\"><strong>[사시 사례]</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">사실상 양립할 수 없는 경우에는 허용되지 않음 — 예: 계약체결의 당사자가 불확실하여 A·B 둘 중 하나라는 사실을 주장하는 경우는 법률상 양립할 수 없는 경우에 해당하지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>법률상 양립가능한 경우 예비적 공동소송 허부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 부진정연대채무의 관계에 있는 채무자들을 공동피고로 한 각 청구는 법률상 양립할 수 없는 것이 아니므로 예비적 공동소송이라 할 수 없음(통상의 공동소송으로 봄)</div><div class=\"cs-h\">Ⅳ. 심판방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송자료의 통일</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>소송자료의 통일 필요 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 예비적 공동소송에서 판결의 모순·저촉을 방지하기 위해 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67①</strong></span></span>을 준용하므로 소송자료의 통일을 위한 규정도 준용됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>원칙 - 1인의 행위(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">주위적·예비적 피고의 소송행위 중 '유리'한 것(다툼·출석·기간준수·답변서 제출)은 전원에 대하여 효력 발생 — 반면 '불리'한 소송행위는 원칙적으로 공동소송인 전원이 함께 하지 않으면 안 됨 — <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67②</strong></span></span> 준용으로 공동소송인의 상대방이 공동소송인을 상대로 한 소송행위는 유리·불리를 떠나 공동소송인 모두에게 효력이 미침</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>예외(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70①</strong></span></span> 단서</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67①</strong></span></span>을 준용하면 청구의 포기·인낙, 화해 및 소의 취하와 같은 소송물에 관한 불리한 처분행위는 공동소송인 중 1인이 할 수 없으나 ② <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70①</strong></span></span> 단서에서는 불리한 행위이지만 각자 청구의 포기·인낙, 화해 및 소의 취하를 할 수 있도록 예외규정을 둠[변리사 '22]</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 1인의 소취하(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">공동소송인 중 일부가 소를 취하하거나 일부 공동소송인에 대한 소를 취하할 수 있고, 이 경우 소를 취하하지 않은 나머지 공동소송인에 관한 청구 부분은 여전히 심판대상[선택 '23]</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 조정 갈음하는 결정(또는 화해권고결정)의 경우 분리확정 가부(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">법원이 원고와 주위적·예비적 피고에 대해 한 조정 갈음 결정(또는 화해권고결정)에 예비적 피고만 이의신청을 한 경우 주위적 청구만 분리확정되는지 문제 — 判例: ① 조정 갈음 결정(또는 화해권고결정)이 확정된 경우 재판상 화해와 동일한 효력이 있으므로 일부 공동소송인이 이의하지 않았다면 원칙적으로 분리확정될 수 있음 ② 다만 그 결정에서 분리확정을 불허하고 있거나, 분리확정을 허용할 경우 형평에 반하고 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70①</strong></span></span> 본문의 입법취지에 반하는 결과가 초래되는 경우에는 분리확정이 허용되지 않음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 일방 자백의 효력 유무(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70①</strong></span></span> 단서에 불리한 행위인 자백을 할 수 있다는 규정이 없으므로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67①</strong></span></span>이 준용됨 → 예비적 공동소송인 1인의 자백이 다른 공동소송인에게 이익이 되면 효력이 있고, 불이익이 되면 효력이 없어 전원이 자백해야 효력이 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송진행의 통일</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67③</strong></span></span><strong>의 준용</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">변론 등 같은 기일에 함께 하여야 하며 원칙적으로 전부판결을 해야 하고 일부판결을 할 수 없음 — 주위적·예비적 피고 중 한 사람에 대해 중단·중지 원인이 발생하면 다른 사람에게도 영향을 미쳐 전체 소송절차 진행이 정지</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>전부판결에 대한 일부항소(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70①</strong></span></span> 본문에서 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67</strong></span></span>을 준용하므로 전부판결에 일부상소한 경우 ① 상소불가분으로 전부 이심 ② 항소하지 않은 당사자는 단순한 항소심 당사자가 됨 ③ 합일확정의 원칙 때문에 불이익변경금지가 배제되어 전부 심판대상 — 判例: 주위적·예비적 공동소송인 중 어느 한 사람에 대해 상소가 제기되면 다른 공동소송인에 대한 청구 부분도 상소심에 이심되어 심판대상이 되고, 이 경우 상소심 심판대상은 합일확정의 필요성을 고려하여 그 심판범위를 판단해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>본안재판의 통일 - 일부판결 허부(★)</strong><strong>[변리사 '22]</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 주위적 피고에 대한 청구를 인용하는 경우에도 예비적 피고에 대한 청구를 판단하여 청구기각판결을 해야 하며(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70②</strong></span></span>) ② 주위적 피고에 대한 청구를 기각하는 경우 예비적 피고에 대해 청구인용 또는 청구기각 판결을 해야 함 → 예비적 공동소송은 일부판결이 허용되지 않으므로 일부판결한 경우 전부판결로 취급되고 판단누락의 위법한 판결로 상소·재심으로 구제 — 判例: 예비적·선택적 공동소송에서는 모든 공동소송인에 관한 청구에 대해 판결하도록 규정하므로, 일부 공동소송인에 관한 청구에 대하여만 판결하는 경우 이는 일부판결이 아닌 흠이 있는 전부판결에 해당하여 상소로써 다투어야 하고, 그 판결에서 누락된 공동소송인은 판단누락을 시정하기 위해 상소를 제기할 이익이 있음[선택 '18, '22, '23]</div>", ["★★★"], 1, "mp_6"], ["민소053", "추가적 공동소송", "<div class=\"cs-h\">Ⅰ. 의의와 형태</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">추가적 공동소송이란 '소송계속 중에 제3자가 스스로 당사자로서 소송에 가입하거나, 종래의 당사자가 제3자에 대한 소를 추가적으로 병합함으로써 공동소송의 형태로 되는 경우'</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 법이 명문으로 추가적 공동소송을 인정하는 경우: ⅰ) 참가승계(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§81</strong></span></span>) ⅱ) 인수승계(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§82</strong></span></span>) ⅲ) 필수적 공동소송인의 추가(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span>) ⅳ) 예비적·선택적 공동소송인의 추가(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70</strong></span></span>에서 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span> 준용) ⅴ) 공동소송참가(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§83</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">② 통상의 공동소송이나 유사필수적 공동소송과 같이 법의 명문 규정이 없는 추가적·주관적 공동소송도 인정할 수 있는지 문제</div><div class=\"cs-h\">Ⅱ. 통상의 공동소송에서 추가적·주관적 공동소송 인정 여부(★) - 3단계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>통상의 공동소송의 경우 </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span><strong>에 의한 추가의 허용 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span>의 필수적 공동소송인 추가의 취지는 고유필수적 공동소송에서 공동소송인이 될 자를 일부 누락하여 당사자적격 흠결로 소가 부적법 각하되는 것을 방지하기 위한 것인데, 통상의 공동소송은 공동소송인을 일부 누락해도 당사자적격 흠결이 생기지 않으므로 추가의 대상이 되지 않음 → <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span>에 의한 추가신청 불가<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>통상의 공동소송의 경우 </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70</strong></span></span><strong>의 추가의 허용 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">예비적·선택적 공동소송은 ① 공동소송의 요건을 갖출 것 ② 법률상 양립할 수 없을 것을 요하는데, 통상의 공동소송은 양립가능하므로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§70</strong></span></span>에 의한 추가신청 불가<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>명문의 규정이 없는 경우 주관적·추가적 공동소송 추가 허부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 필수적 공동소송이 아닌 사건에서 소송 도중에 피고를 추가하는 것은 경위가 어떻든 허용될 수 없다고 하여 명문의 규정이 없는 경우 추가적 공동소송을 불허<span class=\"cs-x\"><strong>(X)</strong></span></div>", ["★"], 1, "mp_6"], ["민소054", "선정당사자", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">선정당사자란 '공동의 이해관계를 가진 다수자가 공동소송인이 되어 소송을 하여야 할 경우에 그 가운데서 모두를 위하여 소송을 수행할 당사자로 선출된 자' — '제3자 소송담당 중 명문의 규정이 있는 임의적 소송담당'으로 대리인과 다름</div><div class=\"cs-h\">Ⅱ. 요건 - <span class=\"cs-blue\"><span class=\"cs-u\">§53</span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">선정당사자제도를 이용하려면 ① 공동소송을 할 여러 사람이 있을 것 ② 여러 사람이 공동의 이해관계를 가질 것 ③ 공동의 이해관계가 있는 자 중에서 선정할 것 ④ 비법인사단이 아닐 것을 갖추어야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공동의 이해관계에 대하여 判例(★): 원칙적으로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§65</strong></span></span> 전문의 경우에만 선정을 허용하나, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§65</strong></span></span> 후문의 경우에도 쟁점 공통의 경우는 '주요한 공격방어방법'이 공통이어서 선정을 허용할 수 있음</div><div class=\"cs-h\">Ⅲ. 선정의 방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>선정의 성질</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>단독소송행위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">선정당사자의 선정행위는 선정자가 소송수행권을 선정당사자에게 부여하는 행위로서 대리권 수여에 유사한 단독적 소송행위 → 소송능력을 요하며 조건을 붙여서는 안 됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>심급 한정의 선정 허용 여부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 선정자는 어느 때라도 선정을 취소할 수 있으며, 선정당사자의 권한남용 방지를 위해 선정자의 의사가 제1심에 한하여 선정한 것이 분명하다면 심급한정 조건은 유효 ② 제1심 한정 문언이 불분명한 경우에는 소송종료시까지 선정의 효력이 있음[선택 '12, '16, '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>선정의 시기</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">선정의 시기는 소송계속의 전후를 불문 — 다만 소송계속 후에 선정한 때에는 선정자는 당연히 소송에서 탈퇴하고(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§53②</strong></span></span>) 선정당사자가 그 지위를 수계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>선정의 방법</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">선정은 각 선정자가 개별적으로 하여야 하며 다수결로 선정할 수 없음 — 전원이 동일인을 선정하여야만 되는 것은 아니고 여러 명의 선정당사자를 선정할 수도 있음</div><div class=\"cs-h\">Ⅳ. 선정의 효과</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>선정당사자의 지위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>당사자 본인으로서의 지위(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 일체의 소송행위와 사법행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 선정당사자는 당사자 본인이고 대리인이 아니므로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§90②</strong></span></span>(특별수권사항)과 같은 제한을 받지 않아 '일체의 소송행위와 사법행위'를 할 수 있음(선정자의 개별적 동의가 필요하지 않으며 선정자에게 효력이 미침) ② 선정당사자가 피고와 한 부제소 합의는 선정당사자가 할 수 있는 소송수행에 필요한 사법상의 행위에 해당하고, 그 효력은 선정자들의 개별적 동의 여부와 관계없이 선정자들 모두에게 미치므로 선정자들이 제소금지합의에 반하여 제기한 소는 권리보호이익이 없어 부적법[선택 '24] ③ 당사자 본인의 지위를 가지므로 선정자와 선정당사자 간 내부적 권한 제한계약을 맺어도 효력이 없고 법원·상대방에게 대항할 수 없음 → 청구의 포기·인낙이나 상대방 주장사실에 대한 자백을 하더라도 그 소송행위는 유효</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 할 수 없는 행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 변호사인 소송대리인과 체결하는 보수약정은 소송수행에 필요한 사법상의 행위라 할 수 없으므로 선정자의 추인이 없는 한 선정자에 대하여 효력이 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>복수의 선정당사자의 지위(★)</strong><strong>[변리사 '13]</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 동일 선정자단에서 수인의 선정당사자가 선정된 경우 수인의 선정당사자는 소송수행권을 합유하는 관계이므로 고유필수적 공동소송 ② 별개의 선정자단에서 각각 수인의 선정당사자가 선정된 경우와 ③ 일부 선정자들이 선출한 선정당사자와 스스로 당사자가 된 자의 소송관계는 원래의 소송이 필수적 공동소송이 아니면 통상공동소송관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>선정당사자의 자격 상실</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 선정당사자의 자격 상실 사유(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 선정당사자의 자격은 ⅰ) 선정당사자의 사망 ⅱ) 선정의 취소에 의하여 상실(선정자는 어느 때나 취소 가능) ② 判例: <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§53</strong></span></span>의 선정당사자는 공동의 이해관계를 가진 사람 중에서 선정되어야 하므로, 선정당사자에 대한 부분의 '소가 취하'되거나 '판결이 확정'되어 공동의 이해관계가 소멸하는 경우에는 선정당사자의 자격을 상실[선택 '16, '17, '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 소멸의 통지</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 대리권 소멸의 경우처럼 상대방에게 선정당사자의 자격상실 통지를 요함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§63②</strong></span></span>) ② 소송진행 중 선정 취소는 통지하지 않으면 선정취소의 효과를 주장할 수 없으며 구 선정당사자가 한 소송행위는 무효로 되지 않음 ③ 다만 법원에 선정취소의 소멸사실이 알려진 뒤에는 선정당사자는 소의 취하, 항소취하, 청구의 포기·인낙, 소송상 화해 등 처분행위를 하지 못함</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 선정당사자의 자격상실과 소송절차의 중단(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 선정당사자 중 일부가 자격상실한 경우라도 절차는 중단되지 않으며 다른 선정당사자가 소송을 속행(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§54</strong></span></span>) ② 선정당사자 전원이 자격을 상실한 경우 선정자가 소송을 수계할 때까지 소송절차 중단(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§237②</strong></span></span>) — 그러나 소송대리인이 있으면 중단되지 않음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§238</strong></span></span>)[선택 '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>선정자의 지위</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>소송탈퇴와 적격유지 여부</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">선정당사자를 선정하면 선정자들은 소송에서 당연히 탈퇴하고 선정당사자만이 당사자로서 소송수행권을 가짐(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§53②</strong></span></span>) — 선정 후 선정자들이 당사자적격을 상실하는가에 관하여 判例는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§53②</strong></span></span>은 선정자의 적격상실을 전제로 한 규정이므로 이를 근거로 <span class=\"cs-u\"><strong>적격상실설</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>판결의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">선정당사자가 받은 판결의 효력은 선정자에게도 미침(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218③</strong></span></span>) — 선정당사자가 이행판결을 받았을 때에는 선정자에 대하여 강제집행을 할 수 있는데 승계집행문이 필요(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민사집행법§31</strong></span></span>)</div><div class=\"cs-h\">Ⅴ. 선정당사자의 자격 흠결의 효과</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송요건, 직권조사사항</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 자격 없는 선정당사자의 소송행위일지라도 선정자가 그 당사자를 선정하여 그 소송행위를 추인할 수 있음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§61</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§60</strong></span></span>) ② 선정행위의 하자 또는 서면에 의한 자격증명이 없는 때에는 보정을 명할 수 있음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§61</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§59</strong></span></span>) ③ 보정·추인이 없는 한 판결로써 소를 각하</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>간과판결</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">선정당사자의 자격이 없음에도 이를 간과하고 본안판결을 하였을 때에는 당사자적격의 흠을 간과한 경우와 같이 판결로서 '무효'이며 선정자에게 효력이 미치지 않으므로, 判例에 의하면 ① 확정 전 상소와 ② 확정 후 재심의 소를 제기할 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>무자격의 선정당사자의 청구인낙의 효력(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 선정당사자 자격의 흠을 간과하여 그를 당사자로 한 판결이 확정된 경우 ① <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>3호의 재심사유에 해당하려면 무권대리인이 대리인으로서 본인을 위해 실질적 소송행위를 하였거나 대리권 흠으로 본인이나 그의 소송대리인이 실질적 소송행위를 할 수 없었던 경우여야 하는데 ② 선정자가 스스로 당해 소송의 공동소송인 중 1인인 선정당사자에게 소송수행권을 수여하는 선정행위를 하였다면 선정자로서는 실질적 소송행위를 할 기회 또는 적법하게 당해 소송에 관여할 기회를 박탈당한 것이 아니므로 ③ 비록 그 선정당사자와 사이에 공동의 이해관계가 없었다 하더라도 그러한 사정은 위 재심사유에 해당하지 않고 ④ 선정당사자가 청구를 인낙하여 인낙조서가 확정된 경우에도 마찬가지</div>", ["★★"], 1, "mp_6"], ["민소055", "통상의 보조참가", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">'타인 간의 소송계속 중 소송결과에 대하여 법률상 이해관계가 있는 제3자가 일방 당사자의 승소를 보조하기 위하여 그 소송에 참가하는 경우'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§71</strong></span></span>) — 참가하는 제3자를 '보조참가인'(종된 당사자), 보조받는 당사자를 '피참가인'(주된 당사자)이라 함</div><div class=\"cs-h\">Ⅱ. 요건 - <span class=\"cs-blue\"><span class=\"cs-u\">§71</span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">보조참가가 적법하려면 ① 타인 사이에 소송이 계속 중일 것 ② 참가인이 피참가인의 소송결과에 대하여 법률상 이해관계가 있을 것 ③ 참가신청이 있을 것 ④ 소송절차를 현저히 지연시키지 않을 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>타인 사이에 소송이 계속 중일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 통상 공동소송의 경우 독립성 때문에 각 공동소송인 간에는 타인 소송이므로 자기의 공동소송인 또는 공동소송인의 상대방을 위하여 보조참가할 수 있음 ② 필수적 공동소송의 경우 자기 소송이므로 공동소송인의 상대방에 참가할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span> ③ 제1심·항소심·상고심 계속 중에 참가 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가이유 - 소송결과에 대한 이해관계</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>소송결과에 대한 이해관계일 것(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 의미</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">소송결과에 이해관계가 있으려면 본 소송 '판결주문'에서 판단되는 소송물인 권리관계의 존부에 의해 직접적으로 영향을 받는 관계에 있을 때(피참가인이 승소하면 참가인의 법률상 지위가 유리, 패소하면 불리하게 될 때)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 판결주문에 대한 이해관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">참가인의 법적 지위가 본소송의 승패에 영향을 받는 경우란 본 소송 '판결주문'에서 판단되는 소송물인 권리관계의 존부에 의해 직접적으로 영향을 받는 관계에 있을 때</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 판결이유에 대한 이해관계(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ① 판결이유에 대한 이해관계만으로 참가이유를 인정하지 않고 판결주문에 의해 영향을 받는 경우로 제한하는 <span class=\"cs-u\"><strong>제한설</strong></span> ② (★) 예외적으로 불법행위로 인한 손해배상책임을 지는 자는 피해자가 다른 공동불법행위자들을 상대로 제기한 손해배상 청구소송의 결과에 대하여 법률상 이해관계를 가지므로 위 소송에 피해자인 원고를 위하여 보조참가를 할 수 있다고 보아, 분쟁의 일회적 해결을 위해 예외적으로 판결이유에만 영향을 받는 경우도 참가이유 인정</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>법률상 이해관계일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 단순한 사실상·경제상·감정상의 이해관계만으로는 참가 불가<span class=\"cs-x\"><strong>(X)</strong></span> ② 법률상 이해관계이면 재산법·가족법·공법상의 관계도 포함 ③ 判例: 당해 소송 판결의 기판력·집행력을 당연히 받는 경우 또는 판결의 효력이 직접 미치지 않더라도 적어도 그 판결을 전제로 보조참가하려는 자의 법률상 지위가 결정되는 관계에 있는 경우를 의미 ④ 判例: 회생채권자가 제기한 채권자취소소송 계속 중 채무자에 대한 회생절차가 개시되어 관리인이 소송을 수계하고 부인의 소로 변경한 경우 소송결과가 채무자 재산 증감에 직접적 영향을 미쳐 회생채권자의 법률상 지위에 영향을 미치므로, 종전에 채권자취소의 소를 제기한 회생채권자는 특별한 사정이 없는 한 소송결과에 이해관계를 갖고 있어 관리인을 돕기 위해 보조참가할 수 있음</div><div class=\"cs-h\">Ⅲ. 보조참가절차</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가의 허부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① '당사자의 이의가 있는 경우'에 참가인은 참가의 이유를 소명해야 함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§73①</strong></span></span>) ② 상대방 당사자가 보조참가를 다투지 않고 본안에 대하여 변론한 경우 '이의신청권을 상실'함이 원칙 ③ 당사자의 이의신청이 없는 경우라도 필요하면 법원은 '직권으로 참가이유를 소명'하도록 명할 수 있고, 참가인은 참가이유를 소명해야 하며 법원은 참가의 허부에 대하여 결정으로 재판 ④ 그 결과 요건 충족시 참가허가 결정, 요건 불비시 불허가 결정</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가의 종료</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">참가인은 어느 때나 참가신청을 취하할 수 있는데, 그 신청이 취하되어도 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§77</strong></span></span>의 참가적 효력을 받음 — 참가인이 한 소송행위는 취하에도 불구하고 효력을 상실하지 않음</div><div class=\"cs-h\">Ⅳ. 참가인의 소송상 지위(★)[사례 '21]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>보조참가인의 종속성</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 보조참가인은 자신의 독자적 청구도 하지 않으며 피참가인의 승소보조자이므로 피참가인과의 관계에서 종속적 지위 ② 보조참가인은 종속적 지위만 있으므로 보조참가인에게 사망 등 소송절차 중단사유가 발생해도 소송이 중단되는 것은 아님 ③ (★) (보조참가인의 상소기간) 判例: 피고 보조참가인은 참가할 때의 소송 진행 정도에 따라 피참가인이 할 수 없는 소송행위를 할 수 없으므로, 피고 보조참가인에 대한 판결정본 송달시로부터 기산하면 상고기간 내라도 이미 피참가인인 피고에 대한 관계에서 상고기간이 경과한 것이라면 피고 보조참가인의 상고도 상고기간 경과 후의 것이 되어 부적법 → 보조참가인의 종속성 때문에 참가인에 의한 상소는 피참가인의 상소기간 내에 해야 함(상고이유서 제출기간도 동일)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>보조참가인의 독립성</strong><strong>[변리사 '20]</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">독자성이 인정되어 당사자에 준하는 절차관여권이 인정됨 → ① 당사자와 별도로 참가인에 대해 '기일통지'·소송서류의 '송달'을 해야 함 ② 피참가인이 기일에 불출석해도 참가인이 '출석'하면 피참가인을 위해 기일을 지킨 것이 됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가인이 할 수 있는 소송행위(★)</strong>[사시 '12]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>원칙 - 독립성</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">참가인은 독립적 지위에서 피참가인의 승소를 위하여 필요한 '일체의 소송행위와 사법행위'를 자기 이름으로 할 수 있음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§76①</strong></span></span>) — 참가인의 소송행위는 피참가인 자신이 행한 것과 동일한 효과 발생</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>제한</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 참가 당시 소송 정도로 보아 피참가인도 할 수 없는 행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">참가 당시 소송 진행 정도에 따라 피참가인이 할 수 없는 행위는 참가인도 할 수 없음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§76①</strong></span></span>단서) → ⅰ) 상고심에서 새로운 사실주장·증거신청 ⅱ) 피참가인의 상소기간 경과 후의 상소제기 등은 보조참가인도 할 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 피참가인의 행위에 어긋나는 행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">참가인의 소송행위가 피참가인의 소송행위에 어긋나는 경우 참가인의 소송행위는 효력이 없음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§76②</strong></span></span>) — 그러나 피참가인의 행위와 명백히 적극적으로 배치되지 않으면 무효로 되지 않음(피참가인이 명백히 다투지 않아 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§150①</strong></span></span>로 자백간주된 사실을 참가인이 다투는 것은 피참가인의 행위와 명백히 적극적으로 배치되는 경우라 할 수 없어 허용)[선택 '20, '23, '24]</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 피참가인에게 불이익한 행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">참가인은 피참가인에게 불리한 행위(청구의 포기·인낙, 재판상 화해, 자백, 상소의 포기·취하 등)를 할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 소송 중의 소제기</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">참가인은 기존 소송을 변경시키는 청구의 변경, 반소, 중간확인의 소의 제기행위 등을 할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">5) 사법상 상계권 행사</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">참가인이 '자신의 사법상의 권리'는 행사할 수 있으나 '피참가인의 사법상의 상계권'은 행사할 수 없음<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅴ. 참가적 효력(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>법적성질</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§77</strong></span></span>은 '참가인에게도 재판의 효력이 미친다'고 하는데, 判例는 기판력과 다른 특수한 효력으로서 피참가인과 상대방 간의 소송(1차 소송)에서 피참가인이 패소한 뒤 피참가인이 참가인 상대의 소송(2차 소송)을 하는 경우 참가인은 1차 소송의 판결내용이 부당하다고 주장할 수 없는 구속력으로 보는 <span class=\"cs-u\"><strong>참가적 효력설</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가적 효력의 발생 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">참가적 효력은 ① 소송판결이 아닌 본안판결이라야 하고 ② 확정될 것을 요하며 ③ 참가인에게 피참가인을 위하여 소송을 수행할 기회가 주어졌을 경우에만 발생 ④ 判例: ⅰ) 전소가 확정판결이 아닌 화해권고결정으로 종료된 경우 확정판결에서와 같은 법원의 사실상·법률상의 본안판단이 이루어졌다고 할 수 없으므로 참가적 효력이 인정되지 않음 ⅱ) 전소가 확정판결이 아닌 조정에 갈음하는 결정으로 종료된 경우에도 참가적 효력이 인정되지 않음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>범위</strong><strong>[선택 '14, '20, '22]</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① (주관적 범위) 참가적 효력은 피참가인과 참가인 사이에만 미치고 상대방과 참가인 사이에서는 미치지 않음 ② (객관적 범위) 참가적 효력은 ⅰ) 판결주문뿐 아니라 ⅱ) 판결이유 중 패소이유가 되었던 사실상·법률상의 판단으로서 참가인이 피참가인과 '공동이익'으로 주장하거나 다툴 수 있었던 사항에도 미침</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가적 효력의 배제</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§76</strong></span></span> 규정에 의해 참가인이 소송행위를 할 수 없었던 경우 ② 참가인의 소송행위가 피참가인의 행위와 어긋나 효력을 잃은 경우 ③ 피참가인이 참가인의 행위를 방해한 경우 ④ 참가인이 할 수 없는 행위를 피참가인이 고의·과실로 하지 않은 경우 참가적 효력 배제</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>기판력과의 차이점</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① (근거와 성질) 기판력은 '법적 안정성'을 위한 것으로 '승패에 불구하고' 생기며 '직권조사사항'이나, 참가적 효력은 피참가인의 패소 '판결기초형성에 대한 책임분담'을 위한 것이어서 '피참가인이 패소'한 경우에만 문제되며 이의가 있어야 고려하는 '항변사항' ② (주관적 범위) 기판력은 원칙적으로 원·피고 당사자 간에만 미치나, 참가적 효력은 피참가인과 보조참가인 사이에서만 미침 ③ (객관적 범위) 기판력은 판결 주문 판단에만 발생하나, 참가적 효력은 판결이유 중의 판단에도 발생 ④ (배제례) 기판력은 배제례가 없으나, 참가적 효력은 배제례가 인정됨(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§77</strong></span></span>)</div>", ["★★"], 1, "mp_6"], ["민소056", "소송고지", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">소송고지란 'ⅰ) 소송계속 중에 ⅱ) 당사자가 ⅲ) 소송참가를 할 이해관계에 있는 제3자에 대하여 ⅳ) 일정한 방식에 따라 소송계속 사실을 통지하는 것'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§84</strong></span></span>) — 고지자가 고지를 함으로써 피고지자에게 참가적 효력을 미칠 수 있게 한다는 점에 취지</div><div class=\"cs-h\">Ⅱ. 소송고지의 요건과 효과</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송고지의 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 소송계속 중일 것 ② 고지자는 계속 중인 소송의 당사자인 원·피고, 보조참가인 및 이들로부터 고지받은 피고지자일 것 ③ 피고지자는 그 소송에 참가할 수 있는 제3자일 것 ④ 고지서를 법원에 제출하고 피고지자와 상대방에게 송달될 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송고지의 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>참가적 효력(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소송고지의 소송법상 효과로 피고지자에게 참가적 효력이 미침 → ① 고지자의 피고지자에 대한 2차 소송에서 피고지자는 1차 소송 판결의 기초가 된 사실상·법률상의 판단과 상반되는 주장을 할 수 없음 ② 2차 소송에서 주장할 수 없는 것은 ⅰ) 피고지자가 참가하였다면 상대방에 대하여 고지자와 '공동이익'으로 주장할 수 있었던 사항에 한하며 ⅱ) 고지자와 피고지자 사이에서 '이해가 대립되는 사항'에 대하여는 참가적 효력이 생기지 않음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>실체법상 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">실체법상 효과로 '<span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§174</strong></span></span>의 시효중단사유로서의 최고'의 효력이 인정됨 — 判例: ⅰ) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§174</strong></span></span>의 6월의 기간은 '소송고지일'부터가 아니라 '당해 소송이 종료된 때'로부터 기산 ⅱ) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§265</strong></span></span>를 유추적용하여 당사자가 소송고지서를 법원에 제출한 때에 시효중단의 효력이 발생</div>", ["★"], 1, "mp_6"], ["민소057", "공동소송적 보조참가", "<div class=\"cs-h\">Ⅰ. 요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">공동소송적 보조참가가 성립하려면 ① 타인 사이의 소송계속 중일 것 ② 당사자적격이 없을 것 ③ 판결의 효력이 미칠 것이 요구됨(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§78</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>당사자적격이 없을 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공동소송적 보조참가인은 타인의 본 소송에 당사자적격이 없어야 하며, 당사자적격이 있으면 공동소송참가를 하게 됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판결의 효력이 미칠 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>기판력이 미치는 경우 - 제3자의 소송담당의 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 제3자 소송담당자 중 '갈음형'은 소송담당자가 받은 판결의 효력이 권리귀속주체에게 미치므로(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218③</strong></span></span>), 당사자적격이 없는 권리귀속주체가 보조참가하면 공동소송적 보조참가로 됨 ② 제3자 소송담당자 중 '함께형(병행형)'의 경우 ⅰ) 채권자대위소송에서 채무자의 참가는 '공동소송적 보조참가' ⅱ) 주주대표소송 중 회사의 참가는 '공동소송참가'</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>형성력이 미치는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">가사소송·회사관계소송·행정소송 등 판결의 형성력이 일반 제3자에게 확장되는 소송에 '당사자적격이 없는' 제3자가 보조참가하면 공동소송적 보조참가로 됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>제소기간을 도과한 후의 참가</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">형성소송은 제소기간의 제한을 두는 경우가 많은바(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>상법§376</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>행정소송법§20</strong></span></span> 등), 판결의 효력을 받고 '당사자적격이 있는' 제3자가 본 소송에 참가할 경우 ⅰ) 제소기간 내에는 당사자적격이 유지되므로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§83</strong></span></span>의 공동소송참가 가능 ⅱ) 기간 경과 후에는 당사자적격을 상실하여 공동소송적 보조참가를 하게 됨</div><div class=\"cs-h\">Ⅱ. 참가인의 소송상 지위와 효과</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가인의 독립적 지위(★) - 통상의 보조참가와 차이점 3개</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 참가인은 피참가인의 행위와 어긋나는 행위를 할 수 있음 ② 참가인의 사망 등 소송절차의 중단·중지 사유가 발생하여 참가인의 이익을 해할 우려가 있으면 소송절차 중단(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67③</strong></span></span> 준용) ③ 참가인의 상소기간은 피참가인의 상소기간에 제한됨이 없이 참가인에 대한 판결정본 송달시로부터 독자적으로 계산 — 判例: 공동소송적 보조참가를 한 참가인이 적법하게 상고를 제기하고 상고이유서 제출기간 내에 상고이유서를 제출하였다면, 상고를 제기하지 않은 피참가인인 피고의 상고이유서 제출기간이 도과하였더라도 그 상고이유서의 제출은 적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가인의 종속적 지위 - 통상의 보조참가와 공통점 4개</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공동소송적 보조참가인도 피참가인의 보조자로 당사자는 아니므로 위 사항을 제외하고는 통상의 보조참가인과 같은 종속적 지위 — 判例: 공동소송적 보조참가인은 당사자가 아니라 보조참가인의 성질을 가지므로 참가할 때의 소송 진행 정도에 따라 피참가인이 할 수 없는 행위를 할 수 없음[선택 '23]</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가인에 미치는 판결의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 피참가인과 참가인 사이에는 본 소송 판결의 효력 중 참가적 효력이 미침 ② 피참가인과 상대방 사이에는 본 소송의 기판력이 참가인에게 미침</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>공동소송적 보조참가에서의 소 취하(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공동소송적 보조참가는 유사필수적 공동소송에 준하는데, 유사필수적 공동소송에서는 원고들 중 일부가 소를 취하하는 경우 다른 공동소송인의 동의를 받을 필요가 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① (항소심에서 피참가인의 소취하) ⅰ) 소 취하는 소가 처음부터 계속되지 않은 것으로 간주되며 본안에 관한 종국판결이 선고된 경우에도 판결 역시 처음부터 존재하지 않은 것으로 간주되므로 ⅱ) 이는 재판의 효력과 직접 관련이 없는 소송행위로서 공동소송적 보조참가인에게 불이익이 된다고 할 것도 아님 ⅲ) 따라서 피참가인이 공동소송적 보조참가인의 동의 없이 소를 취하하였더라도 유효</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">② (재심에서 피참가인의 소취하) ⅰ) 재심의 소를 취하하는 것은 통상의 소취하와 달리 확정된 종국판결에 대한 불복 기회를 상실하게 하여 더 이상 확정판결의 효력을 배제할 수 없게 하는 행위이므로 ⅱ) 재판의 효력과 직접 관련이 있는 소송행위로서 확정판결의 효력이 미치는 공동소송적 보조참가인에게 불리한 행위 ⅲ) 따라서 재심의 소에 공동소송적 보조참가인이 참가한 후에는 피참가인이 재심의 소를 취하하더라도 공동소송적 보조참가인의 동의가 없는 한 효력 없음[선택 '22, '23, '24]</div>", ["★★"], 1, "mp_6"], ["민소058", "공동소송참가", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">'타인 소송계속 중에 당사자적격이 있는 자로서 판결의 효력을 받는 제3자가 원고 또는 피고의 공동소송인으로 참가하는 것'</div><div class=\"cs-h\">Ⅱ. 공동소송참가의 요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">공동소송참가가 성립하려면 ① 타인 사이의 소송계속 중일 것 ② 당사자적격이 있을 것 ③ 합일확정의 경우일 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>타인 사이의 소송계속 중일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">타인의 소송계속 중에 할 수 있고 항소심에서도 참가 가능 — 다만 判例: 공동소송참가는 신소제기의 실질을 가지므로 법률심인 상고심에서는 참가 불가<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>당사자적격이 있을 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공동소송참가를 하는 제3자는 별소 제기 대신 타인의 소송을 이용하여 공동소송인으로 참가하는 것이므로, 제3자도 별소를 제기할 수 있는 당사자적격을 구비해야 참가 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>합일확정의 경우일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>유사필수적 공동소송과 공동소송참가(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 공동소송참가는 판결의 효력이 제3자에게 미치는 경우에 한하여 허용되며, 공동소송참가를 하면 '유사필수적 공동소송'이 됨(이때 판결의 효력은 '기판력'이 미치는 경우) ② 判例: 채권자대위소송 계속 중 다른 채권자가 동일한 채무자를 대위하여 채권자대위권을 행사하면서 공동소송참가신청을 할 경우, 양 청구의 소송물이 동일하다면 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§83①</strong></span></span>이 요구하는 '소송목적이 한쪽 당사자와 제3자에게 합일적으로 확정되어야 할 경우'에 해당하여 참가신청은 적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>고유필수적 공동소송과 공동소송참가(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">고유필수적 공동소송으로 될 경우 통설은 ⅰ) 고유필수적 공동소송도 합일확정소송인 점 ⅱ) 고유필수적 공동소송에서 공동소송인의 일부 누락시 공동소송참가를 인정하여 소를 적법하게 만들 수 있는 점을 근거로 공동소송참가를 할 수 있다고 봄</div><div class=\"cs-h\">Ⅲ. 참가절차와 효과</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">① 참가신청은 소제기의 실질이 있으므로 참가요건은 항변사항이 아니라 직권조사사항 → 요건에 흠결이 있어도 당사자가 이의를 신청할 수 없고, 법원은 직권으로 참가의 적부를 심사하고 요건에 흠이 있을 때에는 종국판결로써 각하해야 함 ② 참가가 적법하다고 인정되면 피참가인과 참가인은 공동소송인이 되고 그 관계는 필수적 공동소송으로 취급되며 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67</strong></span></span>이 적용됨</div><div class=\"cs-h\">Ⅳ. 공동소송적 보조참가와 공동소송참가와의 한계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>채권자대위소송 중에 채무자가 참가하는 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[사례: 채권자대위소송 계속 중 채무자 참가의 형태]</strong></span> 判例: 채권자대위소송에서 채무자가 소송이 제기된 사실을 알고 있어 공동소송적 보조참가 등의 방법으로 채무자의 권리를 보호받을 기회를 부여받은 이상 기판력은 채무자에게도 미친다고 보아 공동소송적 보조참가를 할 수 있음 → (사례해결) 채무자가 채권자 측에 참가한 경우 ① 채무자는 제3채무자에 대해 당사자적격이 있고(병행형) ② 소송담당자인 채권자가 받은 판결의 효력은 피담당자인 채무자에게 미치므로(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218③</strong></span></span>) 공동소송참가에 해당할 수 있으나 ③ 공동소송참가는 동일절차 병합심리되어 판결의 모순·저촉 우려가 없어 중복소제기에 해당하지 않고 ④ 채권자가 대위권을 행사하고 통지 등을 하여 채무자가 대위소송을 알게 되면 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>민법§405②</strong></span></span>에 의해 채무자는 당사자적격을 상실하므로 채무자의 참가는 공동소송적 보조참가</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>회사대표소송 중에 회사가 참가하는 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[사례: 회사대표소송 계속 중 회사 참가의 형태]</strong></span> 判例: ① 회사가 대표소송에 당사자로 참가하는 경우 소송경제가 도모되고 판결의 모순·저촉 가능성도 없는 점과 ② <span class=\"cs-blue\"><span class=\"cs-u\"><strong>상법§404①</strong></span></span>에서 주주의 대표소송의 특성을 살려 회사의 권익을 보호하려 한 입법취지를 함께 고려하면, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>상법§404①</strong></span></span>의 회사의 참가는 공동소송참가를 의미하며 이러한 해석이 중복소제기를 금지하는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§259</strong></span></span>에 반하는 것도 아님[선택 '13, '14, '17, '21] → (사례해결) 회사가 주주 측에 참가한 경우 ① 회사는 대표소송의 당사자적격이 있고(병행형) ② 판결의 효력이 회사에 미치므로 공동소송참가에 해당하며 ③ 동일절차 병합심리로 모순·저촉 우려가 없어 중복소제기 아니고 ④ 상법은 민법과 같은 적격제한 규정이 없으므로 회사의 참가는 공동소송참가</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>채권자대위소송 중에 다른 채권자가 참가하는 경우(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\"><strong>[사례: 채권자대위소송 계속 중 다른 채권자의 공동소송참가신청의 적법 여부]</strong></span> 甲이 乙에 대한 채권으로 채권자대위권을 행사하여 丙에게 피대위채권 95억 중 일부인 20억 지급을 청구하는 소송계속 중, 乙의 다른 채권자 丁이 乙을 대위하여 丙에 대한 95억 채권 중 10억 지급을 청구하며 공동소송참가를 신청한 경우 → ① (적법 여부, 한정 적극) 채권자대위소송 계속 중 다른 채권자가 동일한 채무자를 대위하여 채권자대위권을 행사하며 공동소송참가신청을 할 경우 양 청구의 소송물이 동일하다면 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§83</strong></span></span>의 '소송목적이 한쪽 당사자와 제3자에게 합일적으로 확정되어야 할 경우'에 해당하여 참가신청은 적법 ② (소송물 동일 판단기준) 양 청구의 소송물이 동일한지는 채권자들이 대위행사하는 피대위채권이 동일한지에 따라 결정 ③ (일부청구 명시시, 원칙적 적극) 원고가 일부청구임을 명시하여 피대위채권 일부만 청구한 경우, 참가인의 청구금액이 원고의 청구금액을 초과하지 않는 한 참가인의 청구가 원고의 청구와 소송물이 동일하여 중복되므로 합일확정 필요성이 인정되어 참가신청은 적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>추심소송과 참가(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>채무자의 이행소송에 대한 추심채권자의 소송참가 방식(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 종래판례: 압류·추심명령에 따라 채무자가 상실한 당사자적격이 채권자에게 승계되므로 추심채권자는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§81</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§79</strong></span></span>의 승계참가를 할 수 있었음 ② 변경판례: 채무자가 당사자적격을 상실하지 않아 추심채권자에게 당사자적격이 승계된다고 볼 수 없어 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§81</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§79</strong></span></span>의 승계참가 요건은 충족되기 어렵고, 추심채권자는 채무자가 피압류채권에 관해 제기한 이행소송에 사실심 변론종결시까지 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§83</strong></span></span>에 따라 공동소송참가를 하거나 상고심까지 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§78</strong></span></span>에 따라 공동소송적 보조참가를 할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>추심채권자의 이행소송에 대한 채무자의 소송참가 방식(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 종래판례: 압류·추심명령이 있으면 채무자는 피압류채권에 관해 이행의 소를 제기할 당사자적격을 상실하므로 공동소송참가는 불가하고 공동소송적 보조참가만 가능했음 ② 변경판례: 채무자는 여전히 당사자적격이 있으므로 공동소송적 보조참가뿐 아니라 향후 압류명령 신청 취하 등으로 추심권이 소멸할 경우를 대비하여 공동소송참가도 할 수 있음</div>", ["★★"], 1, "mp_6"], ["민소059", "독립당사자참가", "<div class=\"cs-h\">Ⅰ. 의의 및 구조</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">독립당사자참가란 '타인 간 소송의 계속 중 제3자가 원·피고 양쪽(쌍면참가) 또는 한쪽(편면참가)을 상대방으로 하여 소송목적의 전부나 일부가 자기의 권리라고 주장하거나(권리주장참가), 소송결과에 따라 권리가 침해된다고 주장하면서(사해방지참가) 당사자로서 그 소송절차에 참가하는 것'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§79</strong></span></span>) — 判例는 2당사자 대립구조의 예외로서 원고·피고·참가인 간에 3면의 1개 소송관계가 성립되는 것으로 보는 <span class=\"cs-u\"><strong>3면소송설</strong></span></div><div class=\"cs-h\">Ⅱ. 참가요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>타인 간의 소송이 계속 중일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">본 참가는 제1심·제2심에서도 할 수 있음 — 判例: 독립당사자참가는 실질에 있어 신소제기의 성질을 가지므로 법률심인 상고심에서는 참가 불가<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가이유 - 참가형태</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>권리주장참가</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 의의와 참가인 적격</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">① 제3자가 소송목적의 전부 또는 일부가 자기의 권리임을 주장하며 참가하는 경우 ② 참가인은 본소청구와 '양립할 수 없는 청구'를 주장해야 참가이유를 구비 ③ 참가이유의 판단은 본소청구와 참가인의 청구가 '주장 자체만으로' 양립할 수 없는 관계이면 구비 ④ 따라서 '본안심리결과' 양립된다고 하더라도 독립당사자참가가 부적법하게 되는 것은 아님</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 적법 참가 판례 - 1개의 권리를 본소 원고와 참가인이 서로 주장</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 소유권에 기한 인도청구(★): 소유권에 기한 건물인도청구의 본소에 참가인이 소유자라고 주장하며 원고에 대해 소유권 확인청구를, 피고에 대해 소유권에 기한 건물인도청구를 하는 경우, 일물일권주의상 소유권은 1개이므로 본소청구와 참가는 '양립할 수 없는 관계'여서 참가 적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 채권의 이중양도: 甲이 채권 양수인이라 하여 乙을 피고로 한 양수금청구의 본소에서 丙이 진정한 채권양수인이라며 乙에게 양수금청구를 하며 참가하는 경우, 유효한 채권양수인은 1인뿐이므로 채권적 권리라도 '양립할 수 없는 관계'여서 참가 적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">다) 매매사실이 1개인 경우(★): 判例: 원고의 소유권이전등기청구권과 참가인의 소유권이전등기청구권은 하나의 계약에 기초한 것으로 어느 한쪽의 이전등기청구권이 인정되면 다른 한쪽은 인정될 수 없으므로 서로 양립할 수 없는 관계여서 참가 적법</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">라) 병합된 청구 중 한 청구와 양립불가능한 경우(★): 判例: 본소의 청구가 병합된 경우 어느 하나의 청구라도 참가인의 주장과 양립할 수 없는 관계에 있으면 참가가 허용되고, 양립할 수 없는 본소청구에 관해 본안심리결과 이유가 없는 것으로 판단되더라도 참가신청이 부적법하게 되는 것은 아님</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 부적법 참가 판례 - 2개의 권리를 본소 원고와 참가인이 서로 주장</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">가) 부동산의 이중양도(★): 判例: 참가인은 원고에 대하여 이중매수인의 지위에 있어 소유권이전등기를 마치기 전까지는 서로 소유권을 주장할 수 없는 관계에 있고, 피고의 원고에 대한 소유권이전등기의무와 참가인에 대한 소유권이전등기의무는 양립할 수 있는 법률관계이므로 참가 부적법<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">나) 매매와 점유취득시효에 기한 소유권이전등기 청구(★): 원고의 본소청구인 매매를 원인으로 한 소유권이전등기청구와 참가인의 취득시효완성을 원인으로 한 소유권이전등기청구는 동일한 권리관계에 관한 것이 아니어서 양립될 수 있으므로 독립당사자참가 부적법<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>사해방지참가</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 권리주장참가와 달리 원고의 본소청구와 참가인의 청구가 양립가능한 관계라도 허용됨 ② (★) 判例: 사해방지참가에서 권리침해는 ⅰ) 사해의사가 객관적으로 인정되고 ⅱ) 참가인의 권리가 침해될 염려가 있다고 인정될 경우라고 보아 <span class=\"cs-u\"><strong>사해의사설</strong></span>에 의하며 양자를 별개의 요건으로 봄 ③ (★) 判例: 원고의 피고에 대한 청구의 원인행위가 사해행위라는 이유로 원고에 대해 사해행위취소를 구하며 참가신청을 하는 사안에서, 사해행위취소의 상대적 효력에 의하면 참가신청은 사해방지 목적을 달성할 수 없으므로 '부적법'<span class=\"cs-x\"><strong>(X)</strong></span> ④ 判例: 후순위 근저당권자에게는 원·피고들에 대한 근저당권부존재확인청구라는 참가소송을 통해 후일 발생하게 될 불안·염려를 사전에 차단할 필요가 있고, 이러한 참가소송은 사해판결로 초래될 장애를 방지하기 위한 유효적절한 수단이 됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가취지 - 당사자의 양쪽 또는 한쪽을 상대방으로 한 자기청구일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§79①</strong></span></span>은 「제3자는 당사자의 양쪽 또는 '한쪽'을 상대방으로 하여 당사자로서 소송에 참가할 수 있다」고 규정하여 쌍면참가와 편면참가를 허용</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소의 병합요건을 갖출 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">독립당사자참가는 신소제기의 실질이 있으므로 일반적 소송요건도 갖추어야 함 — 判例: ① 독립당사자참가인의 권리가 원고로부터 부인당하는 경우 독립당사자참가인은 원고를 상대로 자기의 권리의 존재확인을 구해야 하고 ② 제3자에 대한 권리가 부존재한다는 확인을 구하는 것은 자기 권리에 현존하는 위험을 해소시키기 위한 유효적절한 수단이 될 수 없어 확인의 이익이 없음 ③ 독립당사자참가인이 수 개의 청구를 병합하여 독립당사자참가를 하는 경우 각 청구별로 독립당사자참가의 요건을 갖추어야 하고, 편면적 독립당사자참가가 허용된다 하여 참가인이 요건을 갖추지 못한 청구를 추가하는 것을 허용하는 것은 아님</div><div class=\"cs-h\">Ⅲ. 참가절차</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가신청</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">참가신청은 신소제기의 실질을 가지므로 반드시 서면에 의하여야 하며(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§248</strong></span></span>), 그 서면에 참가취지와 이유를 명시하고 자기 청구에 대해 청구취지와 원인을 기재해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>중첩적 참가와 4면소송의 허부(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 이미 독립당사자참가가 있는 소송에 다시 또 다른 제3자가 본소의 당사자를 상대방으로 참가하는 '중첩적 독립당사자참가'를 허용 — 그러나 중첩적 참가의 경우 제1참가인과 제2참가인 간에는 아무런 소송관계가 없으므로 이들 사이에는 어떠한 판결도 할 수 없음(즉 '3면소송의 중첩적 참가'는 허용하되 '4면소송'까지는 허용 불가)</div><div class=\"cs-h\">Ⅳ. 참가심판</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가요건과 소송요건의 조사</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">독립당사자참가요건에 흠이 있는 경우 判例는 참가신청을 부적법 '각하'해야 함(다만 독립당사자참가가 부적법해졌을 때 보조참가로 전환시킬 수 있음) — 참가요건을 갖추면 참가인의 청구에 대한 '소송요건'을 직권으로 조사하고 흠이 있으면 참가신청을 각하</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>본안심판</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>본안심리 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67</strong></span></span><strong>의 규정을 준용</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 원·피고 사이에만 재판상 화해를 하는 것은 3자 간 합일확정의 목적에 반하여 허용되지 않음 — 독립당사자참가인이 화해권고결정에 대해 이의한 경우 이의의 효력이 원·피고 사이에도 미쳐 원고와 참가인의 소송은 화해권고결정 이전의 상태로 돌아감[선택 '14, '17]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>모순 없는 본안판결</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3자 간 모순 없는 해결을 위해 반드시 1개의 '전부판결'을 해야 하며 '일부판결'은 허용되지 않음 → 일부판결한 경우 전부판결로 취급하고 '판단누락'에 준하는 위법을 이유로 상소·재심으로 취소할 수 있고(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§451①</strong></span></span>9호) 원심에서 '추가판결'을 할 수는 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판결에 대한 상소</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>상소의 효력</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 전부판결에 전부상소한 경우 전부 이심되며 전부 심판대상 ② 전부판결에 일부상소한 경우 ⅰ) 상소불가분으로 전부 이심 ⅱ) 항소하지 않은 당사자는 단순한 항소심 당사자가 되고 ⅲ) 합일확정의 원칙 때문에 불이익변경금지가 배제되어 전부 심판대상 ③ 독립당사자참가는 일부판결이 허용되지 않으므로 일부판결한 경우 전부판결(판단누락에 준하는 위법)로 취급 → 전부상소·일부상소한 경우는 위 ①②와 같음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>전부판결에 일부상소한 경우 이심의 범위(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 독립당사자참가는 원고·피고·참가인 3자 간 본안에 관하여 합일확정을 목적으로 하므로 함께 확정되지 않고 먼저 일부만 확정된다면 판결의 모순·저촉 우려가 있어 전부 이심</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>상소하지 않은 당사자의 지위(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: 독립당사자참가인도 항소심에서의 당사자라고 하여 <span class=\"cs-u\"><strong>단순한 상소심 당사자설</strong></span> — 단순한 상소심 당사자는 상소인이 아니므로 ① 인지를 붙일 의무가 없고 ② 상소비용을 부담하지 않으며 ③ 상소취하권이 없고 ④ 상소심 심판범위도 상소인의 불복범위에 국한되며 ⑤ 상소심판결서의 당사자표시에는 단순히 독립당사자참가인으로 표시</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(4) <strong>전부판결에 일부상소한 경우 심판의 범위(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 불이익변경금지원칙의 배제(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 독립당사자참가의 경우 패소하고도 불복상소를 제기하지 않은 당사자의 판결부분이 3자 간 합일확정의 요청 때문에 이익으로 변경될 수 있는 등 불이익변경금지원칙이 배제되어 전부 심판대상이 됨[선택 '13, '17]</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 불이익변경금지 원칙이 배제되는 경우 판결주문 선고와 기판력(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ⅰ) 세 당사자 사이의 결론의 합일확정을 위해 필요한 경우에는 그 한도에서 항소·부대항소를 제기하지 않은 당사자에게 결과적으로 제1심 판결보다 유리한 내용으로 판결이 변경될 수 있으나 ⅱ) 판결의 합일확정을 위해 항소·부대항소를 제기한 적이 없는 당사자의 청구에 대한 제1심 판결을 변경할 필요가 없다면, 그 당사자의 청구가 항소심의 심판대상이 되어 심판해야 하더라도 그 청구에 대한 당부를 반드시 판결 주문에서 선고할 필요는 없음 ⅲ) 이와 같이 항소·부대항소를 제기하지 않은 당사자의 청구에 관하여 항소심에서 판결주문이 선고되지 않고 독립당사자참가소송이 그대로 확정되면 변경되지 않은 제1심 판결의 주문에 대해 기판력이 발생</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 불이익변경금지의 원칙이 배제되지 않는 경우(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: 불이익변경금지가 배제되려면 ⅰ) 참가인의 참가신청이 적법하고 ⅱ) 합일확정의 요청상 필요한 경우에 한함 → 독립당사자참가소송에서 원고의 피고에 대한 청구를 인용하고 참가인의 참가신청을 '부적법' 각하한 제1심판결에 참가인만 항소하고 항소심에서도 참가가 부적법하다는 이유로 항소기각한 경우, 불이익변경금지가 배제되지 않고 적용되므로 항소심 심판범위는 '참가인의 참가신청 부분'만이고 '원고의 본소청구'는 심판대상이 되지 않음</div><div class=\"cs-h\">Ⅴ. 3면소송의 붕괴</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>본소의 취하·각하(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: 본소가 취하·각하된 경우 본소 취하의 효력이 발생하여 독립당사자참가는 원고와 피고를 상대로 한 공동소송으로 변한다고 하여 <span class=\"cs-u\"><strong>공동소송잔존설</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가의 취하·각하</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 독립당사자참가신청의 실질은 소이므로 참가신청도 소의 취하에 준하여 취하할 수 있고 원·피고 쌍방의 동의가 필요 — 참가인의 청구가 취하되면 본소만 잔존(참가인이 쌍면참가를 하였다가 당사자 한쪽만 참가신청을 취하하면 편면참가) ② 참가가 각하된 경우에도 본소만 남음(쌍면참가를 하였다가 당사자 한쪽만 각하되면 편면참가)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송탈퇴</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의와 법적성질(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① (소송종료) 소송탈퇴는 종전 당사자 일방이 자기의 상대방과 참가인 간의 소송결과에 전면적으로 승복할 것을 조건으로 소송에서 물러나는 것으로, 이에 의해 참가인의 상대방에 대한 소송관계만 남고 본소와 참가인·탈퇴자 간의 소송관계는 종료된다고 보는 <span class=\"cs-u\"><strong>조건부 청구의 포기·인낙설</strong></span> ② (<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§80</strong></span></span>에 의해 탈퇴한 당사자에게 판결의 효력이 미치는 근거) 원고가 탈퇴하는 경우는 청구포기를 조건으로, 피고가 탈퇴하는 경우는 청구인낙을 조건으로 탈퇴하는 것이므로 판결의 효력이 미침 ③ (수계신청 불허) 判例(청구포기·인낙설): 甲의 소송탈퇴신청은 효력이 있고 甲의 상속인 丙에게 효력이 미치므로 甲과 丙과 피고 乙 사이의 소송관계는 소송탈퇴로 적법하게 종료되어, 丙의 소송수계신청은 이미 종료된 소송관계에 관한 것이어서 이유 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소송탈퇴가 되려면 ① 제3자의 적법·유효한 참가일 것 ② 본소송의 당사자일 것 ③ 상대방의 승낙을 요함 ④ 권리주장참가에 한하는지에 대하여, 사해방지참가의 경우에도 피고가 소송수행 의욕이 없고 소극적 태도로 일관해 온 때에는 제3자가 소송참가함을 계기로 소송에서 탈퇴할 경우가 있으므로 사해방지참가의 경우에도 탈퇴할 수 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 당사자의 지위상실</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例인 조건부 청구포기·인낙설에 따르면 탈퇴자는 당사자의 지위를 상실하여 소송은 2당사자 소송구조로 환원</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 참가인의 지위 승계 여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">독립당사자참가의 경우 참가인은 원·피고 쌍방과 대립하므로 참가인은 탈퇴자의 소송상 지위를 승계할 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 탈퇴자에 대한 판결의 효력</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§80</strong></span></span>단서의 판결효력의 내용은 <span class=\"cs-u\"><strong>기판력 및 집행력설</strong></span>로 보며, 조건부 청구포기·인낙설에 의할 때 원고 탈퇴는 조건부 청구의 포기이고 피고 탈퇴는 조건부 청구의 인낙이므로 탈퇴자에게 판결의 효력이 미침</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">4) 탈퇴자에 대한 집행권원</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">탈퇴자에게 기판력·집행력이 미치므로, 참가인과 잔존 당사자 사이의 소송에서 승소자의 탈퇴자에 대한 청구가 이행청구인 경우 판결주문에 '탈퇴자에 대한 이행의무의 선고'를 함으로써 이 판결이 '탈퇴자에 대한 집행권원'이 되도록 해야 함</div>", ["★★★★"], 1, "mp_6"], ["민소060", "임의적 당사자변경", "<div class=\"cs-h\">Ⅰ. 의의와 법적성질</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">'소송계속 중 당사자의 의사에 의하여 ⅰ) 종전의 원고나 피고에 갈음(교환적 변경)하여 제3자를 가입시키거나 ⅱ) 종전의 당사자에 추가(추가적 변경)하여 제3자를 가입시키는 것' — 判例는 임의적 당사자변경 중 피고경정에 대해 신당사자에게는 신소의 제기이고 구당사자에게는 구소의 취하라는 두 개의 복합적 소송행위로 보는 <span class=\"cs-u\"><strong>신소제기·구소취하설(복합설)</strong></span></div><div class=\"cs-h\">Ⅱ. 민사소송법상 임의적 당사자변경</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>피고의 경정</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 피고경정이 인정되려면 ① 원고가 피고를 잘못 지정한 것이 분명할 것 ② 제1심 변론종결시까지일 것 ③ 피고가 본안에 대해 응소한 때는 피고의 동의가 있을 것 ④ 교체 전후에 소송물이 동일할 것(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§260</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 判例(★): 피고를 잘못 지정한 것이 분명한 때란 ① 청구취지·청구원인의 기재 내용 자체로 보아 원고가 법률적 평가를 그르치는 등의 이유로 피고 지정이 잘못된 것이 명백하거나 ② 법인격 유무에 관하여 착오를 일으킨 것이 명백한 경우 등을 말하며 ③ 증거조사를 거쳐 사실을 인정하고 그 인정 사실에 터 잡아 법률판단을 하여야 인정할 수 있는 경우에는 '피고를 잘못 지정한 것이 명백한 때'에 해당한다고 볼 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">3) 判例: 권리능력 없는 사단인 부락의 구성원 중 일부가 제기한 소송에서 당사자인 원고의 표시를 부락으로 정정함은 당사자의 동일성을 해하는 것으로 허용되지 않음 → 원고의 변경은 불허<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) ① '피고경정'은 구소취하·신소제기이므로 경정된 피고에 대한 소제기의 효과(시효중단·기간준수)는 경정신청서 제출시 발생(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§265</strong></span></span>) ② 다만 피고의 '표시정정'의 경우에는 최초 소제기에 의한 시효중단·기간준수의 효과가 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 구피고와 신피고는 동일성이 없으므로 구피고의 종전 소송수행의 결과는 신피고에게 원칙적으로 효력이 없음 — 다만 신피고가 구피고의 소송수행 결과를 '원용'하면 신피고에게 효력이 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>필수적 공동소송인의 추가 - </strong><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">필수적 공동소송인의 추가란 '고유필수적 공동소송인 가운데 일부가 누락한 경우 누락된 원고 또는 피고를 추가하는 것'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">추가적 신청이 허용되려면 ① 고유필수적 공동소송인 중 일부가 누락된 경우일 것 ② 제1심 변론종결시까지 신청할 것 ③ 원고 측 추가는 추가될 당사자의 동의가 있을 것 ④ 종전 당사자와 신당사자 간에 공동소송의 요건을 갖출 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">고유필수적 공동소송인의 추가가 허용된 경우 '처음의 소가 제기된 때'에 추가된 당사자와의 사이에 소가 제기된 것으로 봄(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68③</strong></span></span>) → 시효중단·기간준수의 효과는 소제기시에 소급 — 또한 필수적 공동소송인의 추가이므로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67①</strong></span></span>에 의해 종전 공동소송인의 소송수행 결과가 '유리한 소송행위'에 해당하는 경우 추가된 당사자에게도 효력이 미침</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§68</strong></span></span><strong>의 추가가 허용되는 범위에 대한 판례의 입장(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 고유필수적 공동소송의 경우 공동소송인이 될 자를 일부 누락하면 당사자적격 흠결로 소가 부적법 각하되기 때문에 이를 방지하기 위해 추가를 인정할 필요가 있으나 ② 통상의 공동소송이나 유사필수적 공동소송의 경우에는 공동소송인을 일부 누락해도 당사자적격 흠결의 문제가 생기지 않아 추가가 허용되지 않음<span class=\"cs-x\"><strong>(X)</strong></span></div>", ["★"], 1, "mp_6"], ["민소061", "소송승계", "<div class=\"cs-h\">Ⅰ. 의의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">'ⅰ) 소송계속 중에 소송의 목적인 권리관계가 변동함으로써 ⅱ) 새로운 승계인이 종전의 당사자에 갈음하여 당사자가 되고 ⅲ) 그에 따라 당사자적격이 승계되며 당해 소송을 인계받게 되는 것'</div><div class=\"cs-h\">Ⅱ. 당연승계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">당연승계란 'ⅰ) 실체법상 포괄승계원인이 있는 경우 ⅱ) 법률상 당연히 소송당사자가 변경되고 ⅲ) 소송을 인계받게 되는 경우'</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>당연승계의 원인</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 당사자의 사망(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§233</strong></span></span>) ② 법인 등의 합병에 의한 소멸(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§234</strong></span></span>) ③ 당사자인 수탁자의 임무종료(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§236</strong></span></span>) ④ 일정한 자격에 기하여 당사자가 된 자의 자격상실(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§237①</strong></span></span>) ⑤ 선정당사자의 소송 중 선정당사자 전원의 사망 또는 자격상실(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§237②</strong></span></span>) ⑥ 파산의 선고 또는 해지(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§239</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§240</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例: ① 소송계속 중 당사자인 법인이 합병으로 소멸된 때에는 소송절차가 중단되고 합병으로 설립된 법인 또는 합병 후 존속법인이 수계해야 함 — 법인의 권리의무가 법률의 규정에 의해 새로 설립된 법인에 승계되는 경우 특별한 사유가 없는 한 계속 중인 소송에서 그 법인의 법률상 지위도 새로 설립된 법인에 승계되어 새로 설립된 법인이 수계해야 하나, 법률에 법인의 지위를 승계하거나 권리의무가 새로 설립된 법인에 포괄승계된다는 명문 규정이 없는 이상 새로 설립된 법인이 수계할 근거는 없음(포괄승계된 사정이 없다면 권리를 양수받은 이후 승계참가 신청을 해야지 수계 신청을 할 수 없음에 주의) ② 관리비징수업무를 위탁받은 위탁관리업자는 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§237①</strong></span></span>의 '일정한 자격에 의하여 자기의 이름으로 남을 위하여 소송당사자가 된 사람'에 해당 → 위탁관리업자가 구분소유자 등을 상대로 관리비청구 소송을 수행하던 중 관리위탁계약이 종료되어 자격을 잃으면 소송절차가 중단되고 같은 자격을 가진 새로운 위탁관리업자가 수계하거나 새로운 위탁관리업자가 없으면 관리단이나 관리인이 직접 수계해야 함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§237①</strong></span></span>) — 다만 소송대리인이 있으면 관리위탁계약이 종료해도 소송절차가 중단되지 않음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§238</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송상의 취급</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>소송절차가 중단된 경우 - 소송대리인이 없는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 중단과 수계</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">당연승계 원인이 생긴 때에는 당사자의 지위가 승계인에게 이전되므로 승계인이 절차에 관여할 때까지 소송절차가 중단되며, 승계인이 수계신청을 하면 중단이 해소되어 절차가 속행</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 승계인이 아님이 밝혀진 경우 법원의 조치(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">법원은 승계인의 적격을 직권으로 조사하여 적격자가 아님이 밝혀지면 결정으로 당해 수계신청을 '기각'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§243①</strong></span></span>) — 判例: ① 당사자의 사망으로 인한 소송수계신청이 이유 있다고 하여 소송절차를 진행시켰으나 그 후 신청인이 자격 없음이 판명된 경우에는 수계재판을 취소하고 신청을 각하해야 한다는 <span class=\"cs-u\"><strong>신청각하설</strong></span> ② 적법한 소송수계인으로 취급해 절차를 속행한 다음 수계신청인의 청구를 기각한 종국판결 후에 수계신청인이 자격 없음이 판명된 경우에는 원심판결을 파기하고 제1심판결을 취소하며 소송수계신청을 기각한다고 보아 <span class=\"cs-u\"><strong>수계신청기각설</strong></span>로 평석됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>소송절차가 중단되지 않는 경우</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">소송대리인이 있는 경우에는 중단되지 않음(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§238</strong></span></span>)</div><div class=\"cs-h\">Ⅲ. 특정승계 - 소송물의 양도</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">소송물의 양도(특정승계)란 'ⅰ) 소송계속 중에 소송물인 권리관계에 관한 당사자적격이 ⅱ) 특정적으로 제3자에게 이전됨으로써 ⅲ) 소송을 인계받게 되는 경우'</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>소송물양도의 취급</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-blue\"><span class=\"cs-u\"><strong>§81</strong></span></span>·<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§82</strong></span></span>는 승계인을 새로운 당사자로 바꾸고 전주의 소송상 지위를 승계시키는 '소송승계주의'를 채택 → 승계인이 승계절차를 밟지 않으면 종전당사자가 진행하여 받은 판결의 효력은 승계인에게 미치지 않음</div><div class=\"cs-h\">Ⅳ. 참가승계(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가승계의 의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">'ⅰ) 소송계속 중 ⅱ) 소송목적인 권리·의무의 전부나 일부의 승계인이 ⅲ) 독립당사자참가신청의 방식으로 스스로 참가하여 새로운 당사자가 되는 것'(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§81</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가승계의 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>타인 간의 소송이 계속 중일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例: ① 청구이의의 소 계속 중 그 소송에서 집행력 배제를 구하고 있는 채무명의에 표시된 청구권을 양수한 자는 소송의 목적이 된 채무를 승계한 것이므로 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§81</strong></span></span>에 의한 승계참가를 할 수 있고 ② 청구이의의 소가 제기되기 전에 그 채무명의에 표시된 청구권을 양수한 자의 권리승계 참가신청은 부적법 ③ 참가승계신청은 '사실심의 변론종결 전'에 한하며 '상고심'에서는 허용되지 않음[선택 '23]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>소송의 목적인 권리·의무의 승계가 있을 것(★) - 소송물의 양도가 있을 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">判例의 구이론: ① (변론종결 후 승계인과의 관계) <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§81</strong></span></span>의 소송승계인은 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§218①</strong></span></span>의 변론종결 후의 승계인에 준하여 취급 ② (승계인의 범위) ⅰ) '소송물'이 양도된 경우는 당연히 포함하고 ⅱ) '계쟁물'이 양도된 경우도 포함하나, 계쟁물의 승계인의 범위에 대해 채권적 청구권에 기한 소송 중 계쟁물을 취득한 자는 승계인에 포함되지 않지만 물권적 청구권에 기한 소송 중 계쟁물을 양수한 자는 승계인에 포함</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>참가의 방식</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 참가승계의 참가방식은 고유의 독립당사자참가와 같으나, 전주가 승계사실을 다투지 않는 한 대립견제의 소송관계가 성립하지 않음(편면참가) ② 그러나 전주와 승계인 간에 다툼이 있는 경우 승계인은 전주에 대해서도 청구를 해야 하며(쌍면참가) 전주·승계인·피고의 대립관계 소송형태가 됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가승계의 절차</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 참가신청은 소제기에 해당하며 참가요건은 소송요건에 상당하여 요건 구비 여부는 직권조사사항이고 부적법하면 판결로 각하 ② 승계참가신청은 일종의 소제기이고 참가요건은 소송요건에 해당하므로 참가요건에 흠이 있으면 변론을 거쳐 판결로 참가신청을 각하 ③ 참가신청이 있는 경우 승계인에 해당하는지 여부는 본소송의 청구와 참가인의 주장 자체에 의해 판단하고, 본안 심리 결과 승계가 인정되지 않는 때에는 청구기각판결을 해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>참가승계의 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>소송상태 승인의무</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">승계인은 고유의 독립당사자참가와 달리 전주의 소송상 지위를 승계하므로 참가시까지 전주가 한 소송수행의 결과에 구속됨(편면참가) — 다만 '쌍면참가'의 경우 전주와 다툼이 있으므로 전주의 소송수행 결과에 구속되지 않음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>참가 후 소송형태</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (당사자적격 상실) 소송물 양도에 의한 참가승계의 경우 전주인 종전 당사자는 당사자적격이 없어짐 ② (소송탈퇴) 전주는 상대방의 동의를 얻어 탈퇴할 수 있으나 탈퇴에도 불구하고 판결의 효력은 탈퇴한 당사자에게 미침(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§81</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§79</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§80</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>승계의 효력을 다투지 않으나 소송탈퇴·소 취하를 하지 않거나 피고의 부동의로 종전당사자가 탈퇴하지 못하는 경우 소송형태(★)</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (종래 판례 - 통상의 공동소송) 승계참가인이 승계참가신청을 하자 원고가 탈퇴를 신청하였으나 피고들의 부동의로 탈퇴하지 못한 경우 원고의 청구와 승계참가인의 청구는 '통상의 공동소송'으로 봄 ② (변경 판례 - 필수적 공동소송) 判例는 입장을 변경하여 ① 소송탈퇴, ② 소 취하를 하지 않거나 ③ 피고가 부동의하여 원고가 소송에 남아 있는 경우 ⅰ) 원고와 승계참가인의 청구 사이에는 필수적 공동소송에 관한 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§67</strong></span></span>이 적용되며 ⅱ) 근거로 ㉮ 원고와 승계참가인의 청구는 주장 자체로 법률상 양립할 수 없는 관계이고 ㉯ 원고 또는 승계참가인 중 어느 쪽의 청구는 인용되고 다른 쪽은 기각되어 두 청구가 모두 인용될 수 없으므로 ㉰ 필수적 공동소송 규정을 적용하여 두 청구에 대한 판결의 모순·저촉을 방지하고 합일적으로 확정할 필요성이 있기 때문[선택 '21, '23]</div><div class=\"cs-h\">Ⅴ. 인수승계(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>의의</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">인수승계란 'ⅰ) 소송계속 중 소송의 목적인 권리·의무의 전부나 일부의 승계가 있는 때에 ⅱ) 종전당사자의 인수신청에 의하여 승계인인 제3자를 새로운 당사자로 소송에 강제로 끌어들이는 것'</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>인수승계의 요건</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>타인 간의 소송이 계속 중일 것</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>소송의 목적인 권리의무의 승계가 있을 것 - 참가승계와 동일</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">인수승계가 인정되려면 소송의 목적인 권리·의무의 승계, 즉 소송물의 양도가 있을 것을 요함(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§82</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(3) <strong>인수승계의 원인</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">1) 교환적 인수</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">소송인수는 원칙적으로 그 소송의 목적인 채무 자체를 제3자가 승계한 때에 허용하며, 피고적격자가 새 사람으로 이전되어 교환적 인수가 이루어지는 경우로 인수승계 허용</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">2) 추가적 인수(★)</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">判例: ① 소송당사자가 제3자로 하여금 소송을 인수하게 하려면 그 제3자에 대해 인수한 소송의 목적된 채무이행을 구하는 경우에만 허용되고, 그 소송의 목적된 채무와 전혀 별개의 채무의 이행을 구하기 위한 경우에는 허용될 수 없다며 추가적 인수 부정(★ ⅰ) 건물철거청구 중에 피고가 제3자 앞으로 그 건물에 대한 소유권이전등기를 넘길 경우 제3자 명의 등기말소의무의 이행을 구하기 위한 소송인수신청은 허용될 수 없다고 했고 ⅱ) 이전등기청구소송 중 제3자 앞으로 소유권이전등기가 경료되었을 때 그 말소를 구하기 위한 소송의 인수를 불허)[선택 '18, '21] ② 한편 공유물분할 소송계속 중 변론종결일 전에 공유자 중 1인 甲의 공유지분 일부가 乙에게 이전된 사안에서 <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§82</strong></span></span> 인수승계를 할 수 있음(이 경우 인수승계로 당사자 수는 늘어나지만 소송물이 분할되어 이전된 결과일 뿐이므로 추가적 승계가 아니라 교환적 승계에 해당하여 적법)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>인수신청 후 승계인이 아님이 밝혀진 경우 법원의 조치(★)</strong><span class=\"cs-fact-tag\"><strong>[사시 사례]</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">법원이 인수결정 후 본안 심리 중 권리·의무의 승계가 없다고 판명된 때 어떤 재판을 하는지 — 判例: 이행의 소의 당사자적격은 주장 자체로 구비되므로 소 각하하는 것은 타당하지 않고, 청구권이 없다는 이유로 청구기각의 본안판결을 해야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>인수승계의 효과</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(1) <strong>지위의 승계</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① (소송상태승인의무) 인수한 신당사자는 전주의 소송상 지위를 그대로 물려받아 유리·불리를 불문하고 그에 구속됨 ② (소제기의 효과) 당초의 소 제기에 의한 시효중단·기간준수의 효과도 인수인인 신당사자에게 소급적으로 미침(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§82③</strong></span></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(2) <strong>참가 후의 소송형태</strong></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">인수승계에서 교환적 승계의 경우 전주인 종전 당사자는 당사자적격이 없어짐 → 전주는 상대방의 동의를 얻어 탈퇴할 수 있으나 탈퇴에도 불구하고 판결의 효력은 탈퇴한 당사자에게 미침(<span class=\"cs-blue\"><span class=\"cs-u\"><strong>§82③</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§81</strong></span></span>, <span class=\"cs-blue\"><span class=\"cs-u\"><strong>§80</strong></span></span>)</div>", ["★★"], 1, "mp_6"]];
